window.DATA_B1_G=[{"id":"G1","q":"____ a hacer el informe ahora mismo.","o":["Voy ponerme","Voy a ponerme","Voy a poner","Voy poner"],"a":1,"k":"ir a + 동사원형","t":"나는 지금 당장 보고서 작성에 착수할 거야.","e":"'ir a + 동사원형'은 '~할 것이다(가까운 미래)'를 나타내며, 전치사 a를 절대 빼면 안 됩니다. 또 'ponerse a + 동사원형'은 '~하기 시작하다, ~에 착수하다'라는 뜻이라 재귀대명사 se(여기서는 me)가 꼭 필요합니다. 그래서 'Voy a ponerme a hacer'가 됩니다. 예: Me voy a poner a estudiar.(이제 공부를 시작할 거야.)","x":["Voy ponerme: ir 뒤에 전치사 a가 빠져서 틀린 형태입니다 ✗","Voy a ponerme: ir a + ponerse(착수하다) 형태가 모두 갖춰짐 → 정답 ✓","Voy a poner: 재귀대명사가 없어 '~을 놓다'라는 뜻이 되어 '착수하다'가 안 됩니다 ✗","Voy poner: 전치사 a도, 재귀대명사도 빠졌습니다 ✗"]},{"id":"G2","q":"Si no ____ dormir por el ruido, puedes ponerte tapones en los oídos.","o":["pueda","puedes","podrías","puedas"],"a":1,"k":"si 조건문 (현재)","t":"소음 때문에 잠을 잘 수 없으면 귀마개를 끼면 돼.","e":"현실적인 조건을 말하는 'si(만약 ~라면)' 뒤에는 직설법 현재를 씁니다. 주절이 'puedes ponerte(너는 ~할 수 있어)'로 2인칭(tú)이므로 조건절도 2인칭 직설법 현재 'puedes'가 맞습니다. 주의: si 바로 뒤에는 접속법 현재(pueda, puedas)를 쓰지 않습니다.","x":["pueda: 접속법 현재 1·3인칭 단수로, si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","puedes: 직설법 현재 2인칭 단수 → 정답 ✓","podrías: 가능법(~할 수 있을 텐데)으로 현실 조건문의 si절에는 맞지 않습니다 ✗","puedas: 접속법 현재 2인칭으로 si 바로 뒤에는 쓰지 않습니다 ✗"]},{"id":"G3","q":"¿____ habéis terminado los deberes de la escuela?","o":["Ya no","Aún","Todavía","Ya"],"a":3,"k":"ya / todavía","t":"너희들 학교 숙제 벌써 다 했니?","e":"'ya'는 '이미, 벌써'라는 뜻으로 현재완료(habéis terminado)와 함께 '벌써 ~했니?'라고 물을 때 가장 자연스럽습니다. 'todavía/aún'은 '아직'이라는 뜻이라 보통 부정문(todavía no...)에서 '아직 안 했다'를 표현합니다. habéis는 스페인의 vosotros(너희들) 형태이고, 중남미에서는 '¿Ya terminaron?'처럼 ustedes를 씁니다.","x":["Ya no: '더 이상 ~않다'라는 뜻이라 숙제를 끝냈는지 묻는 문장과 맞지 않습니다 ✗","Aún: '아직'이라는 뜻으로 긍정 의문문에서 '아직 끝냈니?'는 어색합니다 ✗","Todavía: '아직'이라는 뜻으로 Aún과 같은 이유로 어색합니다 ✗","Ya: '벌써, 이미' → 정답 ✓"]},{"id":"G4","q":"¿Quién sabe ____ está Jaime?","o":["donde","de dónde","dónde","de donde"],"a":2,"k":"간접의문문 dónde","t":"하이메가 어디에 있는지 누가 알아?","e":"'saber + 의문사'처럼 의문문이 다른 문장 안에 들어간 것을 간접의문문이라고 하는데, 이때도 의문사에는 악센트를 붙입니다(dónde). 위치를 묻는 estar와 함께 '어디에'는 dónde이고, 'de dónde'는 '어디로부터/어디 출신'이라는 뜻입니다.","x":["donde: 악센트가 없으면 관계부사(~하는 곳)라 간접의문문에는 맞지 않습니다 ✗","de dónde: '어디에서부터, 어디 출신'이라는 뜻으로 estar(있다)와 맞지 않습니다 ✗","dónde: 의문사 '어디에' (악센트 있음) → 정답 ✓","de donde: 악센트도 없고 뜻도 '~로부터'라 맞지 않습니다 ✗"]},{"id":"G5","q":"Cuando me duele la cabeza, ____ que se me pase de forma natural.","o":["estoy prefiriendo","prefiera","prefiero","prefiere"],"a":2,"k":"직설법 현재 (습관)","t":"나는 머리가 아플 때 자연스럽게 낫기를 더 좋아한다.","e":"'Cuando me duele la cabeza(머리가 아플 때마다)'는 반복되는 습관을 말하므로 주절은 직설법 현재를 씁니다. 주어는 나(yo)이므로 preferir의 1인칭 'prefiero'가 정답입니다(e→ie 어간 변화). 참고로 'que se me pase'의 pase는 preferir que 뒤라서 접속법입니다.","x":["estoy prefiriendo: preferir 같은 감정·선호 동사는 진행형으로 잘 쓰지 않습니다 ✗","prefiera: 접속법 현재로, 주절 동사에는 맞지 않습니다 ✗","prefiero: 직설법 현재 1인칭(나는 더 좋아한다) → 정답 ✓","prefiere: 3인칭 단수(그/그녀가)라 주어 '나'와 맞지 않습니다 ✗"]},{"id":"G6","q":"Prefiero que ____ en otro momento, estoy ocupado.","o":["hablemos","hablaríamos","hablaremos","hablamos"],"a":0,"k":"preferir que + 접속법","t":"다른 때에 얘기했으면 좋겠어, 나 지금 바빠.","e":"'preferir que(~하는 것을 더 원하다)'처럼 바람·선호를 나타내는 동사 뒤 que절의 주어가 다르면 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)을 씁니다. '우리가 이야기하다'의 접속법 현재는 'hablemos'입니다. 예: Prefiero que vengas mañana.(네가 내일 왔으면 좋겠어.)","x":["hablemos: hablar의 접속법 현재 1인칭 복수 → 정답 ✓","hablaríamos: 가능법(~할 텐데)으로 preferir que 뒤에 쓰지 않습니다 ✗","hablaremos: 직설법 미래라 바람을 나타내는 que절에 맞지 않습니다 ✗","hablamos: 직설법 현재/과거로 접속법이 필요한 자리입니다 ✗"]},{"id":"G7","q":"____ quieran sacar más nota, deben hacer un trabajo extra.","o":["Los cuales","Ellos que","Los que","Que"],"a":2,"k":"관계사 los que","t":"점수를 더 받고 싶은 사람들은 추가 과제를 해야 한다.","e":"'los que'는 '~하는 사람들'이라는 뜻으로, 앞에 꾸밈받는 명사 없이 독립적으로 주어 역할을 합니다. 여기서 quieran이 접속법인 이유는 '(누구든) 원하는 사람이 있다면'처럼 특정되지 않은 사람을 가리키기 때문입니다. 예: Los que lleguen tarde no podrán entrar.(늦게 오는 사람들은 못 들어갑니다.)","x":["Los cuales: 앞에 선행사(명사)가 있을 때만 쓰며 문장 맨 앞 주어로 쓰지 않습니다 ✗","Ellos que: 스페인어에 없는 표현입니다 ✗","Los que: '~하는 사람들' → 정답 ✓","Que: 혼자서는 '~하는 사람들'이라는 주어가 될 수 없습니다 ✗"]},{"id":"G8","q":"La boda de Carlos e Isabel ____ en la iglesia de su barrio.","o":["fue","estuvo","ha estado","estaba"],"a":0,"k":"ser (행사 장소)","t":"카를로스와 이사벨의 결혼식은 그들 동네 성당에서 열렸다.","e":"결혼식·파티·회의 같은 '행사(이벤트)'가 어디서 열리는지 말할 때는 estar가 아니라 ser를 씁니다(ser = 개최되다). 결혼식은 과거에 한 번 끝난 일이므로 단순과거 'fue'가 맞습니다. 예: La fiesta es en mi casa.(파티는 우리 집에서 열려.)","x":["fue: ser의 단순과거, 행사 개최 장소 → 정답 ✓","estuvo: estar는 사물·사람의 위치에 쓰고 행사 개최에는 쓰지 않습니다 ✗","ha estado: estar라서 틀렸고 시제도 맞지 않습니다 ✗","estaba: estar의 불완료과거로 행사 개최에 쓰지 않습니다 ✗"]},{"id":"G9","q":"____ que los medios de transporte tarden mucho.","o":["Fastidian","Me fastidio","Fastidio","Me fastidia"],"a":3,"k":"fastidiar 구문","t":"나는 대중교통이 오래 걸리는 게 짜증 나.","e":"fastidiar(짜증 나게 하다)는 gustar처럼 '짜증 나는 사람'을 간접목적격 대명사(me, te, le…)로 나타냅니다. 짜증 나게 하는 주체는 'que los medios de transporte tarden mucho'라는 절 하나이므로 동사는 3인칭 단수 'fastidia'가 됩니다. 감정 동사 뒤라서 tarden은 접속법입니다.","x":["Fastidian: 3인칭 복수로 주어(que절=단수)와 맞지 않고 대명사도 없습니다 ✗","Me fastidio: 재귀형 '내가 짜증 나다(1인칭)'로 que절을 주어로 받는 구조와 맞지 않습니다 ✗","Fastidio: '내가 ~를 짜증 나게 한다'라는 1인칭 형태입니다 ✗","Me fastidia: '나에게 짜증을 준다' → 정답 ✓"]},{"id":"G10","q":"Rodrigo es ____ más listo de mi clase.","o":["ø","lo","uno","el"],"a":3,"k":"최상급 el más","t":"로드리고는 우리 반에서 제일 똑똑하다.","e":"'~중에서 가장 ~한'이라는 최상급은 '정관사(el/la/los/las) + más + 형용사 + de'로 만듭니다. 로드리고는 남성 단수이므로 'el más listo de mi clase'가 됩니다. 예: Es la más alta de la familia.(그녀는 가족 중 제일 키가 크다.)","x":["ø: 관사가 없으면 '반보다 더 똑똑하다'라는 이상한 비교가 됩니다 ✗","lo: 중성 관사로 'lo más importante(가장 중요한 것)'처럼 사람에게는 쓰지 않습니다 ✗","uno: 'uno de los más listos(가장 똑똑한 사람 중 하나)'처럼 써야 합니다 ✗","el: 남성 단수 정관사, 최상급 → 정답 ✓"]},{"id":"G11","q":"Estáis muy nerviosos. Por favor, ____ pacientes.","o":["son","sois","sed","sean"],"a":2,"k":"명령법 vosotros","t":"너희들 너무 긴장했구나. 제발 좀 참을성을 가져.","e":"vosotros(너희들)에게 하는 긍정 명령은 동사원형의 -r를 -d로 바꿔 만듭니다. ser → sed(~이 되어라). 'Estáis'로 vosotros에게 말하고 있으므로 'sed'가 맞습니다. 중남미에서는 vosotros 대신 ustedes를 써서 'sean pacientes'라고 합니다.","x":["son: 직설법 현재 3인칭 복수(그들은 ~이다)로 명령이 아닙니다 ✗","sois: 직설법 현재 vosotros(너희는 ~이다)로 명령이 아닙니다 ✗","sed: ser의 vosotros 긍정 명령 → 정답 ✓","sean: ustedes 명령형으로 중남미에서는 맞지만, 앞 문장이 vosotros(estáis)라서 맞지 않습니다 ✗"]},{"id":"G12","q":"Este problema matemático no es tan difícil ____ nosotros pensábamos.","o":["como","que","de que","tanto que"],"a":0,"k":"동등비교 tan ~ como","t":"이 수학 문제는 우리가 생각했던 것만큼 어렵지 않다.","e":"'tan + 형용사 + como'는 '~만큼 ~한'이라는 동등비교 표현입니다. 앞에 tan이 있으면 짝꿍은 반드시 como입니다. que는 'más/menos ~ que(~보다 더/덜)'와 짝을 이룹니다. 예: Ana es tan alta como yo.(아나는 나만큼 키가 크다.)","x":["como: tan과 짝을 이루는 '~만큼' → 정답 ✓","que: más/menos와 짝을 이루므로 tan 뒤에는 쓰지 않습니다 ✗","de que: 비교 표현과 맞지 않는 형태입니다 ✗","tanto que: '너무 ~해서 ~하다'라는 뜻으로 tan과 겹쳐 쓸 수 없습니다 ✗"]},{"id":"G13","q":"____ la comida mexicana.","o":["Nosotros encanta","Nos encantan","Nos encanta","Nos encantamos"],"a":2,"k":"encantar 구문","t":"우리는 멕시코 음식을 정말 좋아한다.","e":"encantar(아주 좋아하다)는 gustar처럼 '좋아하는 사람'을 간접목적격 대명사(nos = 우리에게)로 쓰고, 동사는 '좋아하는 대상'에 맞춥니다. 대상 'la comida mexicana'가 단수이므로 'encanta'가 됩니다. 대상이 복수라면 'Nos encantan los tacos.'처럼 씁니다.","x":["Nosotros encanta: 주격 대명사 nosotros는 쓸 수 없고 nos가 필요합니다 ✗","Nos encantan: 3인칭 복수로, 대상(음식)이 단수라 맞지 않습니다 ✗","Nos encanta: 우리에게 + 단수 대상 → 정답 ✓","Nos encantamos: '우리가 서로를 좋아한다'라는 다른 뜻이 됩니다 ✗"]},{"id":"G14","q":"¿Para qué ____ a Julio?","o":["llamases","llames","llamaras","llamaste"],"a":3,"k":"단순과거","t":"너 무엇 때문에 훌리오에게 전화했어?","e":"'para qué(무엇을 위해)'가 들어간 일반 의문문은 직설법을 씁니다. 과거에 한 번 한 행동(전화)을 묻고 있으므로 llamar의 단순과거 2인칭 'llamaste'가 맞습니다. 접속법은 'para que(~하도록)'처럼 접속사로 쓰일 때 필요하며, 의문사 para qué와는 다릅니다.","x":["llamases: 접속법 과거로 일반 의문문에는 쓰지 않습니다 ✗","llames: 접속법 현재로 일반 의문문에 맞지 않습니다 ✗","llamaras: 접속법 과거(-ra형)로 맞지 않습니다 ✗","llamaste: 단순과거 2인칭(너는 전화했다) → 정답 ✓"]},{"id":"G15","q":"Alicia y Carla son mis ____ amigas.","o":["más mejores","mejor","mejores","las mejores"],"a":2,"k":"불규칙 비교급 mejor","t":"알리시아와 카를라는 내 가장 친한 친구들이다.","e":"bueno(좋은)의 비교급·최상급은 'mejor(더 좋은/가장 좋은)'라는 불규칙형이며, 복수 명사 앞에서는 'mejores'가 됩니다. 'mis(내)' 같은 소유형용사가 앞에 있으면 관사 las를 함께 쓰지 않습니다. 'más mejor'처럼 más를 덧붙이는 것도 틀린 표현입니다.","x":["más mejores: mejor 자체가 비교급이라 más를 붙이지 않습니다 ✗","mejor: 단수형이라 복수 명사 amigas와 맞지 않습니다 ✗","mejores: 복수형 → 정답 ✓","las mejores: 소유형용사 mis와 정관사 las를 함께 쓸 수 없습니다 ✗"]},{"id":"G16","q":"¿____ hay un contenedor de basura?","o":["Dónde","Donde","Adónde","Adonde"],"a":0,"k":"의문사 dónde","t":"쓰레기통이 어디에 있나요?","e":"'hay(있다)'와 함께 위치를 물을 때는 의문사 'dónde(어디에)'를 씁니다. 의문문에서는 반드시 악센트를 붙입니다. 'adónde'는 '어디로(방향)'라는 뜻이라 ir 같은 이동 동사와 함께 씁니다. 예: ¿Dónde hay una farmacia?(약국이 어디 있어요?)","x":["Dónde: '어디에' 의문사 → 정답 ✓","Donde: 악센트가 없어 관계부사가 되므로 의문문에 맞지 않습니다 ✗","Adónde: '어디로'(이동 방향)라서 hay와 맞지 않습니다 ✗","Adonde: 악센트가 없는 관계부사이고 방향을 나타냅니다 ✗"]},{"id":"G17","q":"Este ejercicio es más difícil de lo que ____.","o":["parezco","pareces","parezca","parece"],"a":3,"k":"비교 de lo que","t":"이 문제는 보이는 것보다 더 어렵다.","e":"'más + 형용사 + de lo que + 동사'는 '~하는 것보다 더 ~하다'라는 표현입니다. 여기서 비교 대상은 '(이 문제가) 그렇게 보이는 정도'이므로 주어는 este ejercicio(3인칭 단수)이고, 사실을 말하므로 직설법 'parece'를 씁니다.","x":["parezco: 1인칭(내가 ~처럼 보인다)이라 주어와 맞지 않습니다 ✗","pareces: 2인칭(네가 ~처럼 보인다)이라 주어와 맞지 않습니다 ✗","parezca: 접속법 현재로, 사실 비교에는 직설법을 씁니다 ✗","parece: 직설법 3인칭 단수(그것이 ~해 보인다) → 정답 ✓"]},{"id":"G18","q":"Mis padres están muy ____, gracias por preguntar.","o":["buen","bien","buena","buenos"],"a":1,"k":"bien vs bueno","t":"우리 부모님은 아주 잘 지내셔, 물어봐 줘서 고마워.","e":"'estar bien'은 '(건강·상태가) 잘 지내다, 괜찮다'라는 뜻이고, bien은 부사라서 성·수 변화가 없습니다. bueno는 형용사로 사람의 성격(착한)이나 사물의 질(좋은)을 말할 때 주로 ser와 함께 씁니다. 'estar buenos'는 구어에서 '(외모가) 매력적이다'라는 전혀 다른 뜻이 되니 주의하세요.","x":["buen: 남성 단수 명사 앞에서만 쓰는 형태입니다 ✗","bien: 부사 '잘', estar bien = 잘 지내다 → 정답 ✓","buena: 여성 단수 형용사라 부모님(남성 복수)과 맞지 않습니다 ✗","buenos: 형용사라 '잘 지내다'의 뜻이 안 되고 다른 의미가 됩니다 ✗"]},{"id":"G19","q":"¿____ de aquella fiesta?","o":["Acuerdan","Recuerdan","Se acuerdan","Se recuerdan"],"a":2,"k":"acordarse de","t":"그 파티 기억나세요(기억나니)?","e":"'acordarse de + 대상'은 '~을 기억하다'라는 재귀동사 구문으로, se와 전치사 de가 꼭 필요합니다. 반면 recordar는 재귀대명사 없이 바로 목적어를 받습니다(¿Recuerdan aquella fiesta?). 문장에 de가 있으므로 'Se acuerdan'이 맞습니다. ustedes(여러분/너희들) 형태는 중남미에서 '너희들'의 뜻으로도 씁니다.","x":["Acuerdan: acordar(합의하다)라는 다른 뜻이고 se가 빠졌습니다 ✗","Recuerdan: recordar는 de 없이 쓰므로 뒤의 de와 맞지 않습니다 ✗","Se acuerdan: acordarse de(~을 기억하다) → 정답 ✓","Se recuerdan: recordar는 이 뜻으로 재귀형을 쓰지 않습니다 ✗"]},{"id":"G20","q":"Ana es menor de edad, ____ no puede entrar a ese club.","o":["para que","ya que","hasta que","o sea que"],"a":3,"k":"결과 접속사 o sea que","t":"아나는 미성년자야, 그러니까 그 클럽에 들어갈 수 없어.","e":"'o sea que'는 '그러니까, 즉 그래서'라는 뜻으로 앞 내용에서 나오는 결과·결론을 이어 줍니다. '미성년자다 → 그래서 못 들어간다'라는 흐름이므로 결과를 나타내는 o sea que가 맞습니다. 비슷한 표현으로 así que, por lo tanto가 있습니다.","x":["para que: '~하도록(목적)'이라 의미가 맞지 않고 뒤에 접속법이 와야 합니다 ✗","ya que: '~이니까(이유)'라서 이유가 아닌 결과 앞에는 어색합니다 ✗","hasta que: '~할 때까지'라 의미가 맞지 않습니다 ✗","o sea que: '그러니까(결과)' → 정답 ✓"]},{"id":"G21","q":"¿Hay ____ carta para mí?","o":["algún","alguna","algo","ninguna"],"a":1,"k":"부정형용사 alguno","t":"나한테 온 편지 있어요?","e":"'alguno(어떤, 무슨)'는 형용사로 뒤의 명사와 성·수를 맞춥니다. carta(편지)는 여성 단수이므로 'alguna'가 됩니다. 'algún'은 남성 단수 명사 앞에서 쓰는 형태입니다(¿Hay algún mensaje?). 긍정 의문문에서는 ninguna보다 alguna가 자연스럽습니다.","x":["algún: 남성 단수 명사 앞에서 쓰므로 여성 명사 carta와 맞지 않습니다 ✗","alguna: 여성 단수 '어떤' → 정답 ✓","algo: '무언가'라는 대명사로 명사 앞에서 형용사처럼 쓰지 않습니다 ✗","ninguna: '아무 ~도 없는'이라는 부정 의미로 긍정 질문에 어색합니다 ✗"]},{"id":"G22","q":"Cuando llamé a Pilar, me dijo que ____ y que la llamara más tarde.","o":["ha estado comiendo","estaba comiendo","estuvo comiendo","comía"],"a":1,"k":"과거진행 estaba + -ndo","t":"필라르에게 전화했을 때, 그녀는 밥을 먹는 중이라며 나중에 다시 전화해 달라고 했다.","e":"과거의 어느 순간(전화한 순간)에 '진행 중이던 동작'은 'estaba + 현재분사(-ndo)'로 나타냅니다. 'me dijo que' 뒤 간접화법에서도 '지금 먹는 중이야(estoy comiendo)'가 과거로 바뀌어 'estaba comiendo'가 됩니다.","x":["ha estado comiendo: 현재완료 진행형이라 과거 간접화법에 맞지 않습니다 ✗","estaba comiendo: 과거 진행형(~하는 중이었다) → 정답 ✓","estuvo comiendo: 일정 기간 동안 하고 끝난 일을 말해 '그 순간 진행 중'과 맞지 않습니다 ✗","comía: 불완료과거로 가능은 하지만 '그 순간 먹는 중'을 강조하는 진행형이 더 정확합니다 ✗"]},{"id":"G23","q":"Te ayudaré con los deberes en cinco minutos. Ahora ____.","o":["he estado cocinando","cocino","estoy cocinando","he cocinado"],"a":2,"k":"현재진행형","t":"5분 후에 숙제 도와줄게. 지금은 요리하는 중이야.","e":"'Ahora(지금)' 이 순간 진행 중인 동작은 'estar + 현재분사(-ndo)', 즉 현재진행형으로 나타냅니다. 그래서 'estoy cocinando(요리하는 중이다)'가 가장 자연스럽습니다. 단순 현재 cocino는 습관이나 일반적인 사실에 더 어울립니다.","x":["he estado cocinando: '(지금까지) 계속 요리해 왔다'라는 뜻이라 지금 하는 중임을 말하기 어색합니다 ✗","cocino: 단순 현재로 '지금 이 순간 하는 중'을 강조하기엔 부족합니다 ✗","estoy cocinando: 현재진행형(요리하는 중) → 정답 ✓","he cocinado: '요리를 했다(완료)'라는 뜻이라 '지금은 바쁘다'는 흐름과 맞지 않습니다 ✗"]},{"id":"G24","q":"Soy ____ pintora, tengo mi propio estudio de pintura.","o":["una","un","ø","la"],"a":2,"k":"직업 앞 관사 생략","t":"나는 화가야, 내 작업실도 있어.","e":"'ser + 직업'으로 직업을 말할 때는 보통 관사를 쓰지 않습니다(Soy profesor. 나는 선생님이다). 단, 형용사가 붙으면 관사를 씁니다(Soy una pintora famosa. 나는 유명한 화가다). 이 문장은 직업만 말하므로 관사 없이 'Soy pintora'가 맞습니다.","x":["una: 형용사 없이 직업만 말할 때는 관사를 쓰지 않습니다 ✗","un: 남성 관사이고 관사 자체도 필요 없습니다 ✗","ø: 직업 앞 관사 생략 → 정답 ✓","la: 정관사는 '그 화가'처럼 특정할 때만 쓰므로 맞지 않습니다 ✗"]},{"id":"G25","q":"Nos regañaron ____ hacer ruido a altas horas de la noche.","o":["porque","ya que","por","para"],"a":2,"k":"이유 por + 동사원형","t":"우리는 밤늦게 시끄럽게 했다는 이유로 혼났다.","e":"'por + 동사원형'은 '~했기 때문에, ~한 이유로'라는 원인을 나타냅니다. 칭찬하다·혼내다·벌주다 같은 동사 뒤에서 자주 씁니다. porque와 ya que는 '~이기 때문에'라는 뜻은 같지만 뒤에 활용된 동사(주어+동사)가 와야 하므로 동사원형 hacer 앞에는 쓸 수 없습니다.","x":["porque: 뒤에 활용된 동사가 와야 하므로(porque hicimos) 동사원형 앞에 쓸 수 없습니다 ✗","ya que: 뒤에 활용된 동사가 와야 합니다 ✗","por: 원인 por + 동사원형 → 정답 ✓","para: '~하기 위해(목적)'라는 뜻이라 혼난 이유와 맞지 않습니다 ✗"]},{"id":"G26","q":"No voy al teatro ____ invierno pasado.","o":["de","del","desde","desde el"],"a":3,"k":"desde (시작 시점)","t":"나는 지난겨울부터 연극을 보러 가지 않는다.","e":"'desde'는 '~부터(시작 시점)'를 나타내며, 지금까지 이어지는 상황을 말할 때 현재형과 함께 씁니다. 'invierno pasado(지난겨울)'처럼 특정한 시점을 가리킬 때는 정관사 el을 붙여 'desde el invierno pasado'라고 합니다. 예: Vivo aquí desde el año pasado.(나는 작년부터 여기 산다.)","x":["de: '~의, ~에서'라는 뜻으로 시작 시점을 나타내지 못합니다 ✗","del: de + el로 '지난겨울의'가 되어 의미가 맞지 않습니다 ✗","desde: 시작 시점은 맞지만 invierno pasado 앞에 관사 el이 필요합니다 ✗","desde el: '~부터' + 정관사 → 정답 ✓"]},{"id":"G27","q":"No entendí ____. ¿Puede hablar más despacio, por favor?","o":["alguno","nada","nadie","ningún"],"a":1,"k":"부정어 nada","t":"하나도 못 알아들었어요. 좀 더 천천히 말씀해 주시겠어요?","e":"'nada'는 '아무것도(~않다)'라는 뜻으로, 동사 앞에 no가 있어도 함께 쓰는 이중부정이 스페인어에서는 정상입니다. 'No entendí nada'는 '아무것도 이해하지 못했다'가 됩니다. 사람일 때는 nadie(아무도)를 씁니다.","x":["alguno: '어떤 것(하나)'이라는 긍정어로 부정문 no와 맞지 않습니다 ✗","nada: '아무것도' → 정답 ✓","nadie: '아무도(사람)'라서 이해하지 못한 '내용'과 맞지 않습니다 ✗","ningún: 남성 명사 앞에서 쓰는 형용사라 혼자 쓸 수 없습니다 ✗"]},{"id":"G28","q":"Cuidado, no ____ en esa silla, está rota.","o":["te sientas","te sientes","sentarte","siéntate"],"a":1,"k":"부정 명령 (tú)","t":"조심해, 그 의자에 앉지 마, 부서졌어.","e":"tú에게 하는 부정 명령(~하지 마)은 'no + 접속법 현재'로 만들고, 재귀대명사는 동사 앞에 둡니다. sentarse(앉다)의 tú 접속법은 'te sientes'이므로 'no te sientes'가 됩니다. 긍정 명령일 때는 'siéntate(앉아)'처럼 대명사가 뒤에 붙습니다.","x":["te sientas: 직설법 현재로 부정 명령에는 접속법을 써야 합니다 ✗","te sientes: no + 접속법 현재 = 부정 명령 → 정답 ✓","sentarte: 동사원형은 이 자리에서 명령을 나타내지 못합니다 ✗","siéntate: 긍정 명령형이라 no와 함께 쓸 수 없습니다 ✗"]},{"id":"G29","q":"¿Quieres que te ____ más tarde?","o":["llamaría","llame","llamaré","llamo"],"a":1,"k":"querer que + 접속법","t":"내가 나중에 전화해 줄까?","e":"'querer que(~하기를 원하다)'처럼 바람을 나타내는 동사 뒤에서 que절의 주어가 다르면 접속법을 씁니다. 원하는 사람은 tú, 전화하는 사람은 yo이므로 llamar의 접속법 현재 1인칭 'llame'가 맞습니다. '¿Quieres que te + 접속법?'은 '~해 줄까?'라고 제안할 때 자주 씁니다.","x":["llamaría: 가능법으로 querer que 뒤에 쓰지 않습니다 ✗","llame: 접속법 현재 1인칭 → 정답 ✓","llamaré: 직설법 미래로 바람 표현 뒤에 쓰지 않습니다 ✗","llamo: 직설법 현재로 접속법이 필요한 자리입니다 ✗"]},{"id":"G30","q":"Es bueno que ____ de tus problemas con alguien de confianza.","o":["hables","hablases","hablarás","hablas"],"a":0,"k":"es bueno que + 접속법","t":"믿을 만한 사람과 네 문제에 대해 이야기하는 것은 좋은 일이야.","e":"'Es bueno que, Es importante que'처럼 '~하는 것은 ~하다'라는 가치 판단 표현 뒤에는 접속법을 씁니다. 주절이 현재(es)이므로 접속법 현재 'hables'가 맞습니다. 예: Es mejor que descanses.(너는 쉬는 게 좋겠어.)","x":["hables: 접속법 현재 2인칭 → 정답 ✓","hablases: 접속법 과거로, 주절이 현재(es)라서 시제가 맞지 않습니다 ✗","hablarás: 직설법 미래로 가치 판단 표현 뒤에 쓰지 않습니다 ✗","hablas: 직설법 현재로 접속법이 필요한 자리입니다 ✗"]},{"id":"G31","q":"¿Te gustaría ____ actriz?","o":["seas","fueras","ser","eres"],"a":2,"k":"gustaría + 동사원형","t":"너는 배우가 되고 싶니?","e":"'¿Te gustaría + 동사원형?'은 '~하고 싶니?'라는 표현입니다. 하고 싶은 사람과 그 행동을 하는 사람이 같으면(너가 배우가 됨) que 없이 동사원형을 씁니다. 다른 사람이 하기를 바랄 때만 'Me gustaría que fueras actriz(네가 배우가 되면 좋겠어)'처럼 접속법을 씁니다.","x":["seas: 접속법 현재로 que 없이 쓸 수 없습니다 ✗","fueras: 접속법 과거로 que와 다른 주어가 있을 때 씁니다 ✗","ser: 같은 주어이므로 동사원형 → 정답 ✓","eres: 직설법 현재로 gustaría 바로 뒤에 올 수 없습니다 ✗"]},{"id":"G32","q":"Aquí ____ llueve casi nunca.","o":["ni","ø","no","no más"],"a":2,"k":"이중부정 no ~ nunca","t":"여기는 비가 거의 오지 않는다.","e":"'nunca(결코 ~않다)'를 동사 뒤에 두면 동사 앞에 no를 써야 합니다(이중부정). 'No llueve casi nunca'는 '비가 거의 오지 않는다'라는 뜻입니다. nunca를 동사 앞에 두면 no 없이 'Casi nunca llueve'라고 할 수도 있습니다.","x":["ni: '~도 아니다'라는 뜻으로 두 가지를 나열할 때 씁니다 ✗","ø: nunca가 동사 뒤에 오면 앞에 no가 필요합니다 ✗","no: 이중부정 no + 동사 + nunca → 정답 ✓","no más: '~만, 그만'이라는 뜻으로 의미가 맞지 않습니다 ✗"]},{"id":"G33","q":"Si te ____ doliendo la muela, ve al dentista.","o":["sigues","sigue","seguirá","siga"],"a":1,"k":"seguir + 현재분사","t":"이가 계속 아프면 치과에 가.","e":"'seguir + 현재분사(-ndo)'는 '계속 ~하다'라는 뜻입니다. doler(아프다)는 gustar처럼 아픈 부위(la muela)가 주어이므로 3인칭 단수 'sigue'를 씁니다. 현실 조건 si 뒤에는 직설법 현재를 쓰므로 'Si te sigue doliendo'가 됩니다.","x":["sigues: 2인칭 '네가'라서 주어(la muela)와 맞지 않습니다 ✗","sigue: 3인칭 단수 직설법 현재 → 정답 ✓","seguirá: 직설법 미래로 si절에 쓰지 않습니다 ✗","siga: 접속법 현재로 si 바로 뒤에 쓰지 않습니다 ✗"]},{"id":"G34","q":"¡Qué tontería! ¿Quién ha dicho ____?","o":["eso","aquello","esto","estos"],"a":0,"k":"지시대명사 eso","t":"말도 안 돼! 누가 그런 말을 했어?","e":"'eso'는 '그것'이라는 중성 지시대명사로, 방금 상대가 한 말이나 들은 내용을 가리킬 때 씁니다. '¿Quién ha dicho eso?(누가 그런 말을 했어?)'는 매우 자주 쓰는 표현입니다. aquello는 시간·거리상 먼 것, esto는 지금 내가 말하는 가까운 것을 가리킵니다.","x":["eso: 상대방이 말한 내용 '그것' → 정답 ✓","aquello: '저것, 그때 그 일'처럼 멀리 있는 것을 가리켜 어색합니다 ✗","esto: '이것'으로 지금 내가 말하려는 것을 가리킵니다 ✗","estos: 남성 복수 '이것들'로 말한 내용을 가리키지 않습니다 ✗"]},{"id":"G35","q":"Gema se dio una ducha después de ____.","o":["entrena","que entrenó","que entrene","entrenar"],"a":3,"k":"después de + 원형","t":"헤마는 운동을 한 뒤 샤워를 했다.","e":"'después de + 동사원형'은 '~한 후에'라는 뜻이며, 두 동작의 주어가 같을 때 씁니다. 헤마가 운동하고 헤마가 샤워했으므로 'después de entrenar'가 맞습니다. 주어가 다르면 'después de que + 동사'를 씁니다.","x":["entrena: 전치사 de 뒤에는 활용된 동사가 올 수 없습니다 ✗","que entrenó: 주어가 같을 때는 que절보다 동사원형을 씁니다 ✗","que entrene: 접속법 현재로 과거 문장과 시제도 맞지 않습니다 ✗","entrenar: de + 동사원형 → 정답 ✓"]},{"id":"G36","q":"Afortunadamente, me siento ____ que ayer.","o":["mejor","más bien","más mejor","menos bien"],"a":0,"k":"비교급 mejor","t":"다행히 어제보다 몸이 나아졌어.","e":"'sentirse bien(기분·몸 상태가 좋다)'의 비교급은 '더 잘'이라는 뜻의 'mejor'입니다. bien의 비교급은 'más bien'이 아니라 불규칙형 mejor입니다. 'Afortunadamente(다행히)'라는 말로 상태가 좋아졌음을 알 수 있습니다.","x":["mejor: bien의 비교급 '더 좋게' → 정답 ✓","más bien: '오히려, 차라리'라는 다른 뜻의 표현입니다 ✗","más mejor: mejor에 más를 붙이는 것은 틀린 표현입니다 ✗","menos bien: '덜 좋게'로 '다행히'와 의미가 맞지 않습니다 ✗"]},{"id":"G37","q":"Las personas que ____ bien varios idiomas suelen tener más oportunidades profesionales.","o":["están hablando","hablan","estén hablando","habla"],"a":1,"k":"관계절 직설법","t":"여러 언어를 잘하는 사람들은 보통 직업 기회가 더 많다.","e":"관계절의 동사는 선행사(꾸밈받는 명사)에 맞춥니다. 'Las personas(사람들)'는 3인칭 복수이므로 'hablan'입니다. 실제로 그런 사람들에 대한 일반적인 사실이므로 직설법 현재를 씁니다. 능력을 말할 때는 진행형이 아니라 단순 현재가 자연스럽습니다.","x":["están hablando: 진행형은 '지금 말하는 중'이라 능력을 나타내지 않습니다 ✗","hablan: 3인칭 복수 직설법 현재 → 정답 ✓","estén hablando: 접속법 진행형으로 의미가 맞지 않습니다 ✗","habla: 3인칭 단수라 복수 선행사와 맞지 않습니다 ✗"]},{"id":"G38","q":"Nos vemos a las 6 ____ la tarde. ¡Hasta luego!","o":["para","por","de","a"],"a":2,"k":"시간 de la tarde","t":"오후 6시에 보자. 이따 봐!","e":"정확한 시각 뒤에 '오전/오후/밤'을 붙일 때는 전치사 de를 써서 'de la mañana, de la tarde, de la noche'라고 합니다. 시각 없이 '오후에'라고만 할 때는 'por la tarde'(중남미에서는 en la tarde)를 씁니다.","x":["para: '~를 위해, ~까지'라는 뜻으로 시간대 표현에 쓰지 않습니다 ✗","por: 시각 없이 'por la tarde(오후에)'일 때 씁니다 ✗","de: 시각 + de la tarde → 정답 ✓","a: 'a las 6'처럼 시각 앞에 쓰고 시간대 앞에는 쓰지 않습니다 ✗"]},{"id":"G39","q":"La computadora que ____ no funciona bien.","o":["tenga","tengo","estoy teniendo","tendría"],"a":1,"k":"관계절 직설법","t":"내가 가진 컴퓨터는 잘 작동하지 않는다.","e":"관계절이 실제로 존재하는 특정한 것(내 컴퓨터)을 꾸밀 때는 직설법을 씁니다. '내가 가지고 있는'은 tener의 1인칭 현재 'tengo'입니다. 접속법(tenga)은 존재가 확실하지 않거나 찾고 있는 대상을 말할 때 씁니다(Busco una computadora que funcione bien.).","x":["tenga: 접속법으로 특정·실재하는 대상에는 쓰지 않습니다 ✗","tengo: 직설법 현재 1인칭 → 정답 ✓","estoy teniendo: tener(소유)는 보통 진행형으로 쓰지 않습니다 ✗","tendría: 가능법(가질 텐데)으로 의미가 맞지 않습니다 ✗"]},{"id":"G40","q":"La gente ____ ponerse nerviosa antes de hacer un examen importante.","o":["suele","soléis","sueles","suelen"],"a":0,"k":"soler + 동사원형","t":"사람들은 중요한 시험 전에 보통 긴장한다.","e":"'soler + 동사원형'은 '보통 ~하다, ~하곤 하다'라는 습관 표현입니다(o→ue 어간 변화). 'la gente(사람들)'는 의미상 여러 사람이지만 문법적으로는 단수 명사이므로 3인칭 단수 'suele'를 씁니다. 이 점을 자주 헷갈리니 꼭 기억하세요.","x":["suele: la gente는 문법상 단수 → 정답 ✓","soléis: vosotros(너희들) 형태라 주어와 맞지 않습니다 ✗","sueles: tú(너) 형태라 주어와 맞지 않습니다 ✗","suelen: 3인칭 복수로, la gente는 단수 취급하므로 틀립니다 ✗"]},{"id":"G41","q":"No ____ rías de mí.","o":["ø","te","se","os"],"a":1,"k":"재귀동사 reírse","t":"나를 비웃지 마.","e":"'reírse de + 사람'은 '~를 비웃다'라는 뜻의 재귀동사입니다. 부정 명령 'no + 접속법(rías)'은 tú에게 하는 말이므로 재귀대명사도 tú에 맞는 'te'를 동사 앞에 둡니다. 예: No te rías de tu hermano.(동생을 비웃지 마.)","x":["ø: reírse는 재귀대명사가 꼭 필요합니다 ✗","te: tú의 재귀대명사 → 정답 ✓","se: 3인칭/usted 형태라 rías(tú)와 맞지 않습니다 ✗","os: vosotros 형태라 rías(tú)와 맞지 않습니다 ✗"]},{"id":"G42","q":"____ no sabía la respuesta, me copié de un compañero de clase.","o":["Como","Pues","Porque","Así que"],"a":0,"k":"이유 como (문두)","t":"답을 몰라서 반 친구 것을 베꼈다.","e":"'como'가 문장 맨 앞에 오면 '~이니까, ~해서'라는 이유를 나타냅니다. 이유를 먼저 말하고 결과를 뒤에 말하는 구조입니다. 반면 porque는 보통 문장 앞에 두지 않고 결과 뒤에 씁니다(Me copié porque no sabía la respuesta.).","x":["Como: 문두에서 이유를 나타냄 → 정답 ✓","Pues: '그러면, 글쎄'라는 뜻으로 문두에서 이유절을 이끌지 않습니다 ✗","Porque: 이유를 나타내지만 보통 문장 맨 앞에 두지 않습니다 ✗","Así que: '그래서(결과)'라서 이유 앞에 쓰면 의미가 반대가 됩니다 ✗"]},{"id":"G43","q":"¡____ libros hay en tu cuarto!","o":["Cuanta","Cuántos","Cuantos","Cuánto"],"a":1,"k":"감탄문 cuánto","t":"네 방에 책이 정말 많구나!","e":"'¡Cuánto/a/os/as + 명사!'는 '~이 정말 많구나!'라는 감탄문입니다. 감탄문의 의문사에도 악센트를 붙이고, 뒤 명사와 성·수를 맞춥니다. libros는 남성 복수이므로 'Cuántos'가 됩니다.","x":["Cuanta: 악센트가 없고 여성 단수라 libros와 맞지 않습니다 ✗","Cuántos: 남성 복수 감탄사 → 정답 ✓","Cuantos: 성·수는 맞지만 감탄문에는 악센트가 필요합니다 ✗","Cuánto: 남성 단수라 복수 명사 libros와 맞지 않습니다 ✗"]},{"id":"G44","q":"Vos sos una persona ____ paciente.","o":["demasiada","mucha","muy","mucho"],"a":2,"k":"muy + 형용사","t":"너는 정말 참을성이 많은 사람이야.","e":"형용사(paciente) 앞에서 '매우'라는 뜻을 나타낼 때는 부사 'muy'를 씁니다. mucho는 명사나 동사를 꾸밀 때 씁니다(mucha paciencia, trabajar mucho). 'Vos sos'는 아르헨티나·우루과이 등에서 쓰는 voseo(tú 대신 vos를 쓰는 말투)로 'Tú eres'와 같은 뜻입니다.","x":["demasiada: 여성형 형용사로 형용사 앞에서 부사로 쓰지 못합니다 ✗","mucha: 명사를 꾸미는 형용사라 paciente(형용사) 앞에 쓰지 않습니다 ✗","muy: 형용사 앞 '매우' → 정답 ✓","mucho: 형용사 앞에서는 muy를 씁니다 ✗"]},{"id":"G45","q":"El terrorista fue apresado ____ la policía.","o":["por","de","para","a"],"a":0,"k":"수동태 por","t":"그 테러범은 경찰에 의해 체포되었다.","e":"'ser + 과거분사'로 만드는 수동태에서 행위자(~에 의해)는 전치사 'por'로 나타냅니다. 'fue apresado por la policía'는 '경찰에 의해 체포되었다'입니다. 예: El libro fue escrito por Cervantes.(그 책은 세르반테스에 의해 쓰였다.)","x":["por: 수동태 행위자 '~에 의해' → 정답 ✓","de: 수동태의 행위자를 나타내지 않습니다 ✗","para: '~를 위해'라 의미가 맞지 않습니다 ✗","a: 수동태 행위자를 나타내지 않습니다 ✗"]},{"id":"G46","q":"Espero que os ____ nuestra sorpresa.","o":["haya gustado","gustó","gustaba","ha gustado"],"a":0,"k":"접속법 현재완료","t":"너희가 우리 깜짝 선물을 마음에 들어 했기를 바라.","e":"'Espero que(~하기를 바라다)' 뒤에는 접속법을 씁니다. 선물은 이미 주었고 그 결과(마음에 들었는지)를 바라는 것이므로 완료형 접속법 'haya + 과거분사', 즉 'haya gustado'가 맞습니다. 예: Espero que hayas dormido bien.(잘 잤기를 바라.)","x":["haya gustado: 접속법 현재완료 → 정답 ✓","gustó: 직설법 단순과거로 esperar que 뒤에 쓰지 않습니다 ✗","gustaba: 직설법 불완료과거로 접속법이 필요합니다 ✗","ha gustado: 직설법 현재완료로 접속법이 필요합니다 ✗"]},{"id":"G47","q":"Es raro que todavía no hayan llegado los invitados. Igual ____ mucho tráfico.","o":["habría","hubiera","hay","haya"],"a":2,"k":"igual + 직설법","t":"손님들이 아직 안 온 게 이상하네. 아마 차가 많이 막히나 봐.","e":"'igual'은 구어(특히 스페인)에서 '아마, 어쩌면'이라는 뜻으로 쓰이며, 뒤에 보통 직설법이 옵니다. 지금 차가 막히고 있을 가능성을 말하므로 현재형 'hay'가 맞습니다. 비슷한 a lo mejor도 직설법을 쓰지만, quizás·tal vez는 접속법도 쓸 수 있습니다.","x":["habría: 가능법으로 '있었을 텐데'라는 추측이 되어 현재 상황과 맞지 않습니다 ✗","hubiera: 접속법 과거로 igual 뒤에 쓰지 않습니다 ✗","hay: igual + 직설법 현재 → 정답 ✓","haya: 접속법 현재로 igual 뒤에는 보통 직설법을 씁니다 ✗"]},{"id":"G48","q":"Perdone, ¿sabe dónde ____ la ponencia de la señora López?","o":["tiene","hay","está","es"],"a":3,"k":"ser (행사 장소)","t":"실례합니다, 로페스 씨의 발표가 어디서 열리는지 아세요?","e":"강연·발표·회의·파티처럼 '행사가 열리는 장소'를 물을 때는 estar가 아니라 ser를 씁니다. 'ponencia(학회 발표, 강연)'는 행사이므로 '¿Dónde es la ponencia?'가 됩니다. 사물이나 사람의 위치는 estar로 말합니다(¿Dónde está el libro?).","x":["tiene: tener(가지다)는 장소를 묻는 데 쓰지 않습니다 ✗","hay: hay는 정관사(la)가 붙은 특정한 것과 함께 쓰지 않습니다 ✗","está: 사물의 위치에 쓰고 행사 개최 장소에는 쓰지 않습니다 ✗","es: 행사 개최 장소의 ser → 정답 ✓"]},{"id":"G49","q":"¿____ vas vestido así?","o":["Adónde","Donde","Adonde","A donde"],"a":0,"k":"의문사 adónde","t":"너 그렇게 차려입고 어디 가?","e":"'adónde'는 '어디로'라는 뜻의 의문사로, ir(가다) 같은 이동 동사와 함께 목적지를 물을 때 씁니다. 의문문이므로 악센트가 필요합니다. 참고로 'A dónde'처럼 띄어 쓰는 것도 허용되지만, 이 문제의 보기 'A donde'는 악센트가 없어 틀립니다.","x":["Adónde: '어디로' 의문사 → 정답 ✓","Donde: 악센트가 없고 방향(어디로)을 나타내지 않습니다 ✗","Adonde: 악센트가 없어 관계부사가 되므로 의문문에 맞지 않습니다 ✗","A donde: donde에 악센트가 없어 의문문에 맞지 않습니다 ✗"]},{"id":"G50","q":"El vestido que más me gusta ____ todos es el rojo.","o":["de","para","desde","por"],"a":0,"k":"최상급 + de","t":"모든 드레스 중에서 내가 제일 좋아하는 건 빨간색이야.","e":"최상급에서 '~중에서'라는 비교 범위는 전치사 'de'로 나타냅니다. 'el que más me gusta de todos'는 '모든 것 중에서 가장 마음에 드는 것'입니다. 예: Es el más rápido de todos.(모두 중에서 가장 빠르다.)","x":["de: 최상급 범위 '~중에서' → 정답 ✓","para: '~를 위해'라서 비교 범위를 나타내지 않습니다 ✗","desde: '~부터'라서 의미가 맞지 않습니다 ✗","por: 최상급의 범위를 나타내지 않습니다 ✗"]},{"id":"G51","q":"¿Vamos al teatro en coche o prefieres que vayamos ____ pie?","o":["en","a","de","por"],"a":1,"k":"a pie","t":"극장에 차로 갈까, 아니면 걸어가는 게 좋아?","e":"교통수단은 보통 'en + 수단(en coche, en tren, en autobús)'으로 말하지만, '걸어서'는 예외로 'a pie'라고 합니다. 말을 타고 가는 것도 'a caballo'라고 합니다. prefieres que 뒤에 vayamos(접속법)가 쓰인 것도 함께 확인하세요.","x":["en: 'en coche'처럼 탈것에 쓰지만 pie와는 쓰지 않습니다 ✗","a: 'a pie(걸어서)' 고정 표현 → 정답 ✓","de: 'de pie'는 '서 있는 상태로'라는 다른 뜻입니다 ✗","por: 'por pie'라는 표현은 없습니다 ✗"]},{"id":"G52","q":"¡Cuánto ____ este chico desde la última vez que lo vi!","o":["ha crecido","crecería","crecía","está creciendo"],"a":0,"k":"현재완료 (변화)","t":"지난번에 봤을 때 이후로 이 아이 정말 많이 컸구나!","e":"'desde la última vez que lo vi(지난번에 본 뒤로)'처럼 과거의 한 시점부터 지금까지 일어난 변화를 말할 때는 현재완료 'haber + 과거분사'를 씁니다. 그래서 'ha crecido(자랐다)'가 맞습니다. 중남미에서는 단순과거 '¡Cuánto creció!'도 자주 씁니다.","x":["ha crecido: 현재완료(지금까지 자랐다) → 정답 ✓","crecería: 가능법(자랄 텐데)으로 감탄문의 사실 표현에 맞지 않습니다 ✗","crecía: 불완료과거로 과거의 배경 묘사라 '지금까지의 변화'가 안 됩니다 ✗","está creciendo: '지금 자라는 중'이라 지난번 이후의 결과를 감탄하는 문장과 맞지 않습니다 ✗"]},{"id":"G53","q":"¿Necesitas que ____ en algo?","o":["ayudarte","te ayudaré","te ayudo","te ayude"],"a":3,"k":"necesitar que + 접속법","t":"내가 뭐 좀 도와줄까?","e":"'necesitar que(~하는 것이 필요하다)' 뒤에 다른 주어가 오면 접속법을 씁니다. 필요한 사람은 tú, 도와주는 사람은 yo이므로 ayudar의 접속법 현재 1인칭 'ayude'와 목적격 te를 써서 'te ayude'가 됩니다. '¿Necesitas que te ayude?'는 도움을 제안할 때 자주 씁니다.","x":["ayudarte: que 뒤에는 동사원형이 올 수 없습니다 ✗","te ayudaré: 직설법 미래로 접속법이 필요한 자리입니다 ✗","te ayudo: 직설법 현재로 접속법이 필요한 자리입니다 ✗","te ayude: 접속법 현재 1인칭 → 정답 ✓"]},{"id":"G54","q":"Creo que Regina es ____ mejor profesora del instituto.","o":["la","un","una","ø"],"a":0,"k":"최상급 la mejor","t":"나는 레히나가 학교에서 제일 좋은 선생님이라고 생각해.","e":"'정관사 + mejor + 명사 + de'는 '~에서 가장 좋은 ~'이라는 최상급입니다. profesora가 여성 단수이므로 정관사 'la'를 씁니다. 관사가 없거나 부정관사(una)를 쓰면 최상급의 뜻이 되지 않습니다. instituto는 스페인에서 '중·고등학교'를 뜻합니다.","x":["la: 여성 단수 정관사, 최상급 → 정답 ✓","un: 남성 부정관사라 성도 맞지 않고 최상급도 안 됩니다 ✗","una: 부정관사로는 최상급을 만들 수 없습니다 ✗","ø: 관사 없이는 '가장 좋은'이라는 최상급이 안 됩니다 ✗"]},{"id":"G55","q":"¿Están esperando ____ alguien?","o":["por","a","para","de"],"a":1,"k":"사람 목적어 a","t":"누군가를 기다리고 계신가요?","e":"직접목적어가 사람일 때는 앞에 전치사 'a'를 붙입니다(인칭의 a). esperar는 '~를 기다리다'라는 타동사이므로 'esperar a alguien(누군가를 기다리다)'이 됩니다. 사물일 때는 a 없이 씁니다(Espero el autobús. 버스를 기다린다).","x":["por: esperar는 por 없이 바로 목적어를 받습니다 ✗","a: 사람 직접목적어 앞 a → 정답 ✓","para: '~를 위해'라서 '누군가를 기다리다'의 뜻이 안 됩니다 ✗","de: esperar와 함께 쓰지 않습니다 ✗"]},{"id":"G56","q":"Esta carpeta es de Lucía. ¿Puedes ____?","o":["dársela","darse","darle","darla"],"a":0,"k":"이중 목적격 se lo","t":"이 파일은 루시아 거야. 그녀에게 그것을 줄 수 있어?","e":"간접목적격(le, ~에게)과 직접목적격(la, ~을)을 함께 쓰면 le가 'se'로 바뀌어 'se la'가 됩니다. 동사원형 뒤에 붙여 쓰면 'dársela(그녀에게 그것을 주다)'이고, 강세 위치를 지키기 위해 악센트(á)를 붙입니다. la는 carpeta(여성 명사)를 가리킵니다.","x":["dársela: 그녀에게(se) + 그것을(la) → 정답 ✓","darse: 재귀형 '자기 자신에게 주다'로 의미가 맞지 않습니다 ✗","darle: '그녀에게'만 있고 '그것을(carpeta)'이 빠졌습니다 ✗","darla: '그것을'만 있고 '그녀에게'가 빠졌습니다 ✗"]},{"id":"G57","q":"¿Qué ____ pasó a tus amigos? ¿Por qué no vinieron con nosotros?","o":["la","los","les","le"],"a":2,"k":"간접목적격 les","t":"네 친구들에게 무슨 일 있었어? 왜 우리랑 같이 안 왔어?","e":"'pasar a alguien'은 '누군가에게 (일이) 생기다'라는 뜻으로, 일을 겪는 사람을 간접목적격 대명사로 씁니다. 'a tus amigos(네 친구들에게)'는 3인칭 복수이므로 'les'입니다. 예: ¿Qué te pasa?(너 무슨 일 있어?)","x":["la: 직접목적격 여성 단수(그녀를)라 맞지 않습니다 ✗","los: 직접목적격 남성 복수(그들을)라 pasar 구문에 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격 → 정답 ✓","le: 3인칭 단수라 복수인 친구들과 맞지 않습니다 ✗"]},{"id":"G58","q":"Me caí ____ bajar del autobús.","o":["al","cuando","cada vez que","hasta"],"a":0,"k":"al + 동사원형","t":"나는 버스에서 내리다가 넘어졌다.","e":"'al + 동사원형'은 '~할 때, ~하는 순간'이라는 뜻으로, 두 동작이 동시에 일어남을 나타냅니다. 'al bajar del autobús'는 '버스에서 내릴 때'입니다. cuando를 쓰려면 'cuando bajaba'처럼 활용된 동사가 필요합니다.","x":["al: al + 동사원형 '~할 때' → 정답 ✓","cuando: 뒤에 활용된 동사가 와야 하므로 동사원형 앞에 쓸 수 없습니다 ✗","cada vez que: '~할 때마다'로 활용된 동사가 필요하고 의미도 맞지 않습니다 ✗","hasta: '~까지'라서 의미가 맞지 않습니다 ✗"]},{"id":"G59","q":"¿Cuántas habitaciones ____ en este hotel?","o":["están","son","es","hay"],"a":3,"k":"hay (존재)","t":"이 호텔에는 방이 몇 개 있나요?","e":"'~이 있다'는 존재를 나타낼 때는 hay를 씁니다. hay는 단수·복수 모두 형태가 같습니다. 특히 cuántos/as, un, muchos 같은 수량 표현과 함께 '얼마나 있는지'를 말할 때 hay를 씁니다. 예: Hay tres habitaciones libres.(빈방이 세 개 있다.)","x":["están: 특정한 것의 위치를 말할 때 쓰고 수량 질문에는 hay를 씁니다 ✗","son: ser는 '~이다'라서 존재를 묻지 않습니다 ✗","es: 단수형이고 존재를 나타내지 않습니다 ✗","hay: 존재 '있다' → 정답 ✓"]},{"id":"G60","q":"Miguel nos contó que ____ muy contento viviendo en Barcelona.","o":["esté","fue","era","estaba"],"a":3,"k":"간접화법 시제 일치","t":"미겔은 바르셀로나에 살면서 아주 행복하다고 우리에게 말했다.","e":"'contar que(~라고 말하다)'가 과거(contó)일 때, 원래 말한 현재형 'estoy muy contento'는 불완료과거 'estaba'로 바뀝니다. contento(만족한, 기쁜)는 상태를 나타내므로 ser가 아닌 estar를 씁니다.","x":["esté: 접속법이라 사실을 전달하는 간접화법에 맞지 않습니다 ✗","fue: ser이고 단순과거라서 상태 묘사에 맞지 않습니다 ✗","era: ser는 contento(일시적 감정 상태)와 함께 쓰지 않습니다 ✗","estaba: estar 불완료과거, 상태 → 정답 ✓"]},{"id":"G61","q":"Si ____ que te asista, dímelo.","o":["necesitarás","necesitas","necesites","necesitarías"],"a":1,"k":"si 조건문 (현재)","t":"내가 도와주길 원하면 말해.","e":"현실적인 조건 'si(만약 ~라면)' 뒤에는 직설법 현재를 씁니다. 주절이 tú 명령(dímelo, 나에게 말해)이므로 조건절도 2인칭 'necesitas'가 됩니다. 'que te asista'가 접속법인 것은 necesitar que 뒤이기 때문입니다.","x":["necesitarás: 직설법 미래로 si절에 쓰지 않습니다 ✗","necesitas: 직설법 현재 2인칭 → 정답 ✓","necesites: 접속법 현재로 si 바로 뒤에 쓰지 않습니다 ✗","necesitarías: 가능법으로 현실 조건 si절에 쓰지 않습니다 ✗"]},{"id":"G62","q":"No me importa ____ contigo de compras. Al contrario, me gusta la idea.","o":["yendo","que voy","voy","ir"],"a":3,"k":"importar + 동사원형","t":"너랑 쇼핑 가는 거 난 괜찮아. 오히려 그 생각 좋은데.","e":"'No me importa + 동사원형'은 '~하는 것은 상관없다, 괜찮다'라는 뜻입니다. 쇼핑 가는 사람이 '나'(문장의 me와 같은 사람)이므로 que절 없이 동사원형 'ir'를 씁니다. 다른 사람이 하는 경우라면 'No me importa que vengas tarde'처럼 접속법을 씁니다.","x":["yendo: 현재분사는 importar의 주어가 될 수 없습니다 ✗","que voy: importar que 뒤에는 접속법이 와야 하고, 같은 주어라 원형이 맞습니다 ✗","voy: 활용된 동사가 바로 올 수 없습니다 ✗","ir: 같은 주어 → 동사원형 → 정답 ✓"]},{"id":"G63","q":"Luisa es muy cariñosa, ____ me ve me da un abrazo.","o":["cada vez","siempre que","nada más","hasta que"],"a":1,"k":"siempre que","t":"루이사는 정이 많아서, 나를 볼 때마다 안아 준다.","e":"'siempre que'는 '~할 때마다, 언제나 ~하면'이라는 뜻으로 반복되는 습관을 말할 때 뒤에 직설법을 씁니다. 'cada vez que'도 같은 뜻이지만 que가 꼭 필요한데, 보기 'cada vez'에는 que가 없어 틀립니다.","x":["cada vez: 'cada vez que'처럼 que가 있어야 합니다 ✗","siempre que: '~할 때마다' → 정답 ✓","nada más: '~하자마자'는 'nada más + 동사원형'으로 쓰며 반복 의미가 없습니다 ✗","hasta que: '~할 때까지'라서 의미가 맞지 않습니다 ✗"]},{"id":"G64","q":"Vivimos en el ____ del bloque que está ahí enfrente.","o":["tercer","tres","tercero","tercio"],"a":2,"k":"서수 tercero","t":"우리는 저기 맞은편 건물 3층에 산다.","e":"서수 tercero(세 번째)는 남성 단수 명사 바로 앞에서는 o가 빠져 'tercer'가 됩니다(el tercer piso). 하지만 이 문장처럼 뒤에 명사 없이 혼자 쓰이면(piso가 생략됨) 'el tercero'라고 씁니다. primero → primer도 같은 규칙입니다.","x":["tercer: 남성 명사 바로 앞에서만 쓰는 형태라 뒤에 명사가 없으면 안 됩니다 ✗","tres: 기수(셋)라 '세 번째 층'의 뜻이 안 됩니다 ✗","tercero: 명사 없이 쓰는 서수 → 정답 ✓","tercio: '3분의 1'이라는 분수라서 의미가 다릅니다 ✗"]},{"id":"G65","q":"El avión aterrizó una hora después ____ lo estimado.","o":["de","que","a","en"],"a":0,"k":"después de lo","t":"비행기는 예상보다 한 시간 늦게 착륙했다.","e":"'después de'는 '~후에'라는 뜻이고, 'lo estimado'는 '예상된 것(시간)'을 뜻합니다. 그래서 'una hora después de lo estimado'는 '예상보다 한 시간 뒤에'가 됩니다. después는 비교급처럼 que를 쓰지 않고 항상 de와 함께 씁니다.","x":["de: después de '~후에' → 정답 ✓","que: después는 que와 함께 쓰지 않습니다 ✗","a: después와 짝을 이루지 않습니다 ✗","en: después와 짝을 이루지 않습니다 ✗"]},{"id":"G66","q":"¿Me pasas ____ cuchillo? Este no corta bien.","o":["lo otro","otro","la otra","un otro"],"a":1,"k":"otro (관사 없음)","t":"다른 칼 좀 건네줄래? 이건 잘 안 들어.","e":"'otro/a(다른)'는 앞에 부정관사(un/una)를 붙이지 않습니다. 영어 another를 생각해서 'un otro'라고 하기 쉬운데 틀린 표현입니다. cuchillo(칼)는 남성 단수이므로 'otro cuchillo'가 됩니다.","x":["lo otro: 중성형 '다른 것(일)'으로 명사 앞에 쓰지 않습니다 ✗","otro: 관사 없이 '다른' → 정답 ✓","la otra: 여성형이라 남성 명사 cuchillo와 맞지 않습니다 ✗","un otro: otro 앞에 부정관사를 붙이지 않습니다 ✗"]},{"id":"G67","q":"No me importa que ____ un poco tarde, no pasa nada.","o":["vienes","vas a venir","vendrás","vengas"],"a":3,"k":"importar que + 접속법","t":"네가 좀 늦게 와도 나는 상관없어, 괜찮아.","e":"'No me importa que + 다른 주어'는 '~가 ~해도 상관없다'라는 감정·평가 표현이라 접속법을 씁니다. 늦게 오는 사람은 tú이므로 venir의 접속법 현재 'vengas'가 맞습니다. 예: No me importa que llueva.(비가 와도 상관없어.)","x":["vienes: 직설법 현재로 접속법이 필요한 자리입니다 ✗","vas a venir: 직설법 미래 표현이라 맞지 않습니다 ✗","vendrás: 직설법 미래로 맞지 않습니다 ✗","vengas: 접속법 현재 2인칭 → 정답 ✓"]},{"id":"G68","q":"Encontré el calcetín ____ la cama.","o":["bajo de","abajo","debajo de","debajo"],"a":2,"k":"debajo de","t":"양말을 침대 밑에서 찾았다.","e":"'debajo de + 명사'는 '~의 아래에'라는 위치 표현입니다. 뒤에 명사(la cama)가 오므로 de가 꼭 필요합니다. debajo만 쓰면 '아래에'라는 부사가 되어 명사를 바로 받을 수 없습니다. 같은 뜻으로 전치사 bajo를 써서 'bajo la cama'라고 해도 됩니다(bajo de는 틀림).","x":["bajo de: bajo는 전치사라 de를 붙이지 않습니다 ✗","abajo: '아래쪽에(부사)'로 명사를 바로 받지 못합니다 ✗","debajo de: '~의 아래에' → 정답 ✓","debajo: de가 없으면 명사를 받을 수 없습니다 ✗"]},{"id":"G69","q":"Ha empezado ____ llover, vamos a ponernos los chubasqueros.","o":["ø","de","para","a"],"a":3,"k":"empezar a + 원형","t":"비가 오기 시작했어, 우비를 입자.","e":"'empezar a + 동사원형'은 '~하기 시작하다'라는 표현으로 전치사 a가 꼭 필요합니다. 'Ha empezado a llover'는 '비가 오기 시작했다'입니다. comenzar a, ponerse a도 같은 구조입니다. chubasquero는 스페인어로 '우비, 비옷'입니다.","x":["ø: empezar 뒤 동사원형 앞에는 a가 필요합니다 ✗","de: empezar와 함께 쓰지 않습니다(dejar de는 '그만두다') ✗","para: '~하기 위해'라서 의미가 맞지 않습니다 ✗","a: empezar a '~하기 시작하다' → 정답 ✓"]},{"id":"G70","q":"No sé quién te dijo eso. A ____ me dijeron lo contrario.","o":["mí","me","yo","mi"],"a":0,"k":"전치격 대명사 mí","t":"누가 너한테 그 말을 했는지 모르겠어. 나한테는 반대로 말했거든.","e":"전치사(a, para, de 등) 뒤에서 '나'는 'mí'(악센트 있음)를 씁니다. 'A mí me dijeron'처럼 'a mí'를 덧붙이면 '나한테는'이라고 강조·대조하는 효과가 있습니다. 악센트 없는 mi는 '나의'라는 소유형용사입니다.","x":["mí: 전치사 뒤 '나' → 정답 ✓","me: 목적격 대명사로 전치사 뒤에 쓸 수 없습니다 ✗","yo: 주격이라 전치사 뒤에 쓰지 않습니다(entre, según 등 예외 제외) ✗","mi: 악센트가 없으면 '나의'라는 소유형용사입니다 ✗"]},{"id":"G71","q":"No te preocupes, te informaré ____ tenga más datos.","o":["nada más","mientras","al","tan pronto como"],"a":3,"k":"tan pronto como","t":"걱정 마, 자료가 더 생기는 대로 바로 알려 줄게.","e":"'tan pronto como'는 '~하자마자, ~하는 대로'라는 시간 접속사입니다. 미래의 일을 말할 때는 뒤에 접속법을 쓰므로 'tenga'가 왔습니다. 'en cuanto'도 같은 뜻입니다. 예: Te llamo en cuanto llegue.(도착하자마자 전화할게.)","x":["nada más: '~하자마자'라는 뜻일 때는 'nada más + 동사원형'으로 씁니다 ✗","mientras: '~하는 동안'이라서 의미가 맞지 않습니다 ✗","al: 'al + 동사원형'이라 활용된 동사 tenga 앞에 쓸 수 없습니다 ✗","tan pronto como: '~하자마자' → 정답 ✓"]},{"id":"G72","q":"Cuando volví a casa del cole, mi padre ya ____ la comida.","o":["preparó","había preparado","estuvo preparando","ha preparado"],"a":1,"k":"과거완료","t":"내가 학교에서 집에 돌아왔을 때, 아빠는 이미 점심을 차려 놓으셨다.","e":"과거의 어느 시점(집에 돌아왔을 때)보다 더 먼저 끝난 일은 과거완료 'había + 과거분사'로 나타냅니다. 'ya(이미)'와 함께 '이미 ~해 놓았었다'라는 뜻이 됩니다. 'cole'는 colegio(학교)의 구어 표현입니다.","x":["preparó: 단순과거로 '내가 왔을 때 준비했다(그때 시작)'가 되어 ya와 어색합니다 ✗","había preparado: 과거완료(이미 준비해 두었다) → 정답 ✓","estuvo preparando: 일정 기간 진행했다는 뜻이라 맞지 않습니다 ✗","ha preparado: 현재완료라 과거 기준 시점과 맞지 않습니다 ✗"]},{"id":"G73","q":"Supongo que ____ cansada porque no paras de trabajar.","o":["estés","seas","eres","estás"],"a":3,"k":"suponer que + 직설법","t":"네가 일을 쉬지 않고 하니까 피곤하겠구나.","e":"'Supongo que(~라고 생각해/짐작해)'는 긍정문일 때 creo que처럼 뒤에 직설법을 씁니다. cansada(피곤한)는 일시적인 상태이므로 ser가 아니라 estar를 써서 'estás'가 맞습니다. 'no parar de + 원형'은 '쉬지 않고 ~하다'라는 표현입니다.","x":["estés: 접속법으로 긍정 suponer que 뒤에 쓰지 않습니다 ✗","seas: ser 접속법이라 동사와 법 모두 맞지 않습니다 ✗","eres: ser는 피곤함 같은 상태에 쓰지 않습니다 ✗","estás: estar 직설법, 상태 → 정답 ✓"]},{"id":"G74","q":"Anoche Pedro me ____ tres veces.","o":["ha llamado","llamaba","llamó","estaba llamando"],"a":2,"k":"단순과거","t":"어젯밤 페드로가 나에게 세 번 전화했다.","e":"'Anoche(어젯밤)'처럼 끝난 과거 시점에 일어나 완료된 일은 단순과거를 씁니다. 'tres veces(세 번)'처럼 횟수가 정해진 동작도 단순과거로 표현합니다. 그래서 'llamó'가 맞습니다.","x":["ha llamado: 현재완료라 anoche(끝난 과거 시점)와 잘 쓰지 않습니다 ✗","llamaba: 불완료과거로 횟수가 정해진 동작에 쓰지 않습니다 ✗","llamó: 단순과거 3인칭 → 정답 ✓","estaba llamando: 과거진행형이라 '세 번 전화했다'는 완료된 동작과 맞지 않습니다 ✗"]},{"id":"G75","q":"Necesito que alguien me ____ la solución a este problema.","o":["explicará","explicaría","explique","explica"],"a":2,"k":"necesitar que + 접속법","t":"누군가 이 문제의 해답을 나에게 설명해 줬으면 좋겠어.","e":"'Necesito que(~가 ~해 주는 게 필요하다)' 뒤에 다른 주어가 오면 접속법을 씁니다. 주어 alguien(누군가)은 3인칭 단수이므로 explicar의 접속법 현재 'explique'가 맞습니다. 누가 될지 정해지지 않은 사람이라는 점에서도 접속법이 자연스럽습니다.","x":["explicará: 직설법 미래로 necesitar que 뒤에 쓰지 않습니다 ✗","explicaría: 가능법으로 맞지 않습니다 ✗","explique: 접속법 현재 3인칭 → 정답 ✓","explica: 직설법 현재로 접속법이 필요한 자리입니다 ✗"]},{"id":"G76","q":"Habla más despacio para que te ____ todos.","o":["entiendan","entienden","entenderán","entenderían"],"a":0,"k":"para que + 접속법","t":"모두가 네 말을 알아듣도록 더 천천히 말해.","e":"'para que(~하도록, ~하기 위해)'는 목적을 나타내는 접속사로, 뒤에 항상 접속법을 씁니다. 주어는 todos(모두)로 3인칭 복수이므로 entender의 접속법 현재 'entiendan'이 맞습니다(e→ie 어간 변화). 예: Te lo explico para que lo entiendas.(네가 이해하도록 설명해 줄게.)","x":["entiendan: 접속법 현재 3인칭 복수 → 정답 ✓","entienden: 직설법 현재로 para que 뒤에 쓰지 않습니다 ✗","entenderán: 직설법 미래로 para que 뒤에 쓰지 않습니다 ✗","entenderían: 가능법으로 para que 뒤에 쓰지 않습니다 ✗"]},{"id":"G77","q":"¿Adónde ____ el sábado por la noche?","o":["fuisteis","fuesen","fueran","habéis ido"],"a":0,"k":"단순과거 (vosotros)","t":"너희 토요일 밤에 어디 갔었어?","e":"'el sábado por la noche(토요일 밤)'는 이미 끝난 과거 시점이므로 단순과거를 씁니다. ir의 단순과거 vosotros 형태는 'fuisteis'입니다(ser와 형태가 같음). 중남미에서는 ustedes를 써서 '¿Adónde fueron?'이라고 합니다.","x":["fuisteis: ir의 단순과거 vosotros → 정답 ✓","fuesen: 접속법 과거로 일반 의문문에 쓰지 않습니다 ✗","fueran: 접속법 과거로 일반 의문문에 쓰지 않습니다 ✗","habéis ido: 현재완료라 '지난 토요일 밤'이라는 끝난 시점과 잘 맞지 않습니다 ✗"]},{"id":"G78","q":"Óscar está raro últimamente. ____ esté preocupado por algo.","o":["Puede","Puede que","Igual","A lo mejor"],"a":1,"k":"puede que + 접속법","t":"오스카가 요즘 이상해. 뭔가 걱정이 있는지도 몰라.","e":"'Puede que + 접속법'은 '~일지도 모른다'라는 추측 표현으로, que가 꼭 필요하고 뒤에는 항상 접속법을 씁니다. 빈칸 뒤의 'esté'가 접속법이므로 'Puede que'가 맞습니다. 'A lo mejor'와 'Igual'도 '아마'라는 뜻이지만 뒤에 직설법(está)을 씁니다.","x":["Puede: que 없이는 접속법 절을 이끌 수 없습니다 ✗","Puede que: '~일지도 모른다' + 접속법 → 정답 ✓","Igual: '아마'라는 뜻이지만 뒤에 직설법(está)을 씁니다 ✗","A lo mejor: '아마'라는 뜻이지만 뒤에 직설법(está)을 씁니다 ✗"]},{"id":"G79","q":"Como sigas ____ así, la profesora va a echarte de la clase.","o":["a comportarte","comportarte","comportándote","te comportes"],"a":2,"k":"seguir + 현재분사","t":"너 계속 그렇게 행동하면 선생님이 너를 교실에서 내쫓을 거야.","e":"'seguir + 현재분사(-ndo)'는 '계속 ~하다'라는 표현입니다. 재귀동사 comportarse(행동하다)는 현재분사 뒤에 대명사를 붙여 'comportándote'가 되고 악센트가 붙습니다. 문두의 'como + 접속법(sigas)'은 '~하면 (가만 안 둔다)'처럼 경고·위협 조건을 나타냅니다.","x":["a comportarte: seguir는 'a + 동사원형'과 함께 쓰지 않습니다 ✗","comportarte: seguir 뒤에는 동사원형이 아니라 현재분사가 옵니다 ✗","comportándote: seguir + 현재분사 → 정답 ✓","te comportes: 활용된 동사는 seguir 뒤에 바로 올 수 없습니다 ✗"]},{"id":"G80","q":"Si viviera en esa casa, ____ horas en el jardín.","o":["pasaría","pasaré","estaré pasando","pase"],"a":0,"k":"si + 접속법 과거","t":"내가 그 집에 산다면 정원에서 몇 시간이고 보낼 텐데.","e":"현재 사실과 다른 가정을 할 때는 'si + 접속법 과거(viviera), 가능법(pasaría)' 구조를 씁니다. '~라면 ~할 텐데'라는 뜻입니다. 예: Si tuviera dinero, viajaría.(돈이 있다면 여행할 텐데.)","x":["pasaría: 가능법 1인칭(보낼 텐데) → 정답 ✓","pasaré: 직설법 미래로, si + 접속법 과거와 짝이 맞지 않습니다 ✗","estaré pasando: 미래 진행형으로 가정문과 맞지 않습니다 ✗","pase: 접속법 현재로 주절에 쓸 수 없습니다 ✗"]},{"id":"G81","q":"Espero que os ____ el pastel que he preparado.","o":["guste","gustaría","va a gustar","gusta"],"a":0,"k":"esperar que + 접속법","t":"내가 만든 케이크가 너희 마음에 들었으면 좋겠어.","e":"'Espero que(~하기를 바라다)' 뒤 다른 주어의 절에는 접속법을 씁니다. gustar의 주어는 'el pastel(케이크)' 단수이므로 접속법 현재 'guste'가 됩니다. 아직 먹기 전이거나 먹는 중일 때 쓰는 표현입니다(이미 먹은 뒤라면 haya gustado).","x":["guste: 접속법 현재 3인칭 단수 → 정답 ✓","gustaría: 가능법으로 esperar que 뒤에 쓰지 않습니다 ✗","va a gustar: 직설법 미래 표현으로 접속법이 필요합니다 ✗","gusta: 직설법 현재로 접속법이 필요합니다 ✗"]},{"id":"G82","q":"Te recomiendo que ____ con un psicólogo sobre tu problema.","o":["hables","hablas","hablar","hablarías"],"a":0,"k":"recomendar que + 접속법","t":"네 문제에 대해 심리학자와 상담해 보길 권해.","e":"'recomendar que(~하라고 권하다)'처럼 충고·권유를 나타내는 동사 뒤 que절에는 접속법을 씁니다. 상대(tú)에게 권하는 것이므로 hablar의 접속법 현재 2인칭 'hables'가 맞습니다. 비슷한 동사: aconsejar que, sugerir que.","x":["hables: 접속법 현재 2인칭 → 정답 ✓","hablas: 직설법 현재로 접속법이 필요한 자리입니다 ✗","hablar: que 뒤에는 동사원형이 올 수 없습니다 ✗","hablarías: 가능법이라 맞지 않습니다 ✗"]},{"id":"G83","q":"Este equipo de baloncesto es ____ mejor que ese otro.","o":["mucho","tanto","tan","más"],"a":0,"k":"mucho + 비교급","t":"이 농구팀은 저 다른 팀보다 훨씬 낫다.","e":"비교급(mejor, peor, más, menos) 앞에서 '훨씬'이라고 강조할 때는 'mucho'를 씁니다. 'mucho mejor'는 '훨씬 더 좋은'입니다. 'muy mejor'나 'más mejor'는 틀린 표현입니다. 예: Hoy me siento mucho mejor.(오늘은 훨씬 나아.)","x":["mucho: 비교급 강조 '훨씬' → 정답 ✓","tanto: '그만큼'이라는 동등비교 표현이라 mejor와 쓰지 않습니다 ✗","tan: 'tan ~ como'에 쓰며 mejor 앞에 쓰지 않습니다 ✗","más: mejor 자체가 비교급이라 más를 붙이지 않습니다 ✗"]},{"id":"G84","q":"María del Carmen es la mujer ____ viene a ayudarme con las tareas de casa los lunes.","o":["quienes","quien","la que","que"],"a":3,"k":"관계대명사 que","t":"마리아 델 카르멘은 월요일마다 집안일을 도와주러 오는 여자분이다.","e":"쉼표 없이 명사를 바로 꾸미는 관계절(한정적 관계절)에서 주어 역할을 할 때는 'que'를 씁니다. 사람이든 사물이든 que가 기본입니다. quien은 전치사 뒤(la mujer con quien...)나 쉼표가 있는 설명적 관계절에서 씁니다.","x":["quienes: 복수형이라 la mujer(단수)와 맞지 않습니다 ✗","quien: 쉼표 없는 한정적 관계절의 주어로는 쓰지 않습니다 ✗","la que: 전치사 없이 선행사 바로 뒤에서는 쓰지 않습니다 ✗","que: 기본 관계대명사 → 정답 ✓"]},{"id":"G85","q":"No tengo cuchara. ¿Me pasas ____?","o":["un","una","la otra","otra"],"a":1,"k":"부정대명사 una","t":"숟가락이 없어. 하나 건네줄래?","e":"앞에 나온 명사(cuchara)를 반복하지 않고 '하나'라고 받을 때는 부정대명사 'uno/una'를 씁니다. cuchara(숟가락)가 여성 명사이므로 'una'입니다. 남성 명사 앞에서 쓰는 un은 명사 없이 혼자 쓸 수 없습니다(남성일 때는 uno).","x":["un: 명사 앞에서만 쓰는 형태이고 남성형이라 맞지 않습니다 ✗","una: 여성 부정대명사 '하나' → 정답 ✓","la otra: '나머지 하나'라는 뜻이라 숟가락이 없는 상황과 맞지 않습니다 ✗","otra: '또 하나 더'라는 뜻이라 이미 하나 가진 경우에 씁니다 ✗"]},{"id":"G86","q":"Mi madre no se fía ____ los desconocidos.","o":["de","a","en","por"],"a":0,"k":"fiarse de","t":"우리 엄마는 낯선 사람을 믿지 않는다.","e":"'fiarse de + 대상'은 '~를 믿다, 신뢰하다'라는 재귀동사 구문으로 항상 전치사 de와 함께 씁니다. 비슷한 뜻의 'confiar en(~를 신뢰하다)'은 en을 쓰니 함께 외워 두세요. desconocido는 '모르는 사람, 낯선 사람'입니다.","x":["de: fiarse de '~를 믿다' → 정답 ✓","a: fiarse와 함께 쓰지 않습니다 ✗","en: confiar en에서 쓰며 fiarse와는 쓰지 않습니다 ✗","por: fiarse와 함께 쓰지 않습니다 ✗"]},{"id":"G87","q":"¿Sabéis ____ de Mariana? Hace tiempo que no la veo.","o":["alguno","algo","nada","alguna"],"a":1,"k":"saber algo de","t":"너희 마리아나 소식 좀 알아? 그녀를 못 본 지 꽤 됐어.","e":"'saber algo de + 사람'은 '~에 대한 소식을 좀 알다'라는 자주 쓰는 표현입니다. 'algo'는 '무언가'라는 대명사입니다. 긍정 의문문이므로 부정어 nada보다 algo가 자연스럽습니다(No sé nada de ella. 그녀 소식은 전혀 몰라.)","x":["alguno: 사람이나 정해진 것 중 하나를 가리켜 '소식'의 뜻이 안 됩니다 ✗","algo: '무언가(소식)' → 정답 ✓","nada: '아무것도'라는 부정어로 긍정 질문에 어색합니다 ✗","alguna: 여성형 '어떤 하나'라 의미가 맞지 않습니다 ✗"]},{"id":"G88","q":"¿Cuándo ____ la abuela de Jorge?","o":["estuvo falleciendo","fallecía","falleció","ha estado falleciendo"],"a":2,"k":"단순과거","t":"호르헤의 할머니는 언제 돌아가셨어?","e":"'fallecer(돌아가시다, 사망하다)'는 한 순간에 일어나고 끝나는 사건이므로 단순과거 'falleció'를 씁니다. cuándo로 과거의 특정 시점을 묻는 문장에서도 단순과거가 자연스럽습니다. 진행형은 순간적 사건에 쓰지 않습니다.","x":["estuvo falleciendo: 순간적인 사건은 진행형으로 쓰지 않습니다 ✗","fallecía: 불완료과거로 완료된 사건에 맞지 않습니다 ✗","falleció: 단순과거 → 정답 ✓","ha estado falleciendo: 현재완료 진행형으로 의미가 맞지 않습니다 ✗"]},{"id":"G89","q":"Llegué tarde ____ tu culpa.","o":["por","a","para","de"],"a":0,"k":"por (원인)","t":"너 때문에 늦었어.","e":"'por tu culpa'는 '너 때문에, 네 탓으로'라는 고정 표현입니다. por는 원인·이유를 나타냅니다. 예: por mi culpa(내 탓으로), gracias a ti(네 덕분에)도 함께 알아 두세요.","x":["por: 원인 'por tu culpa' → 정답 ✓","a: culpa와 함께 원인을 나타내지 않습니다 ✗","para: '~를 위해'라서 의미가 맞지 않습니다 ✗","de: 'de tu culpa'라는 표현은 없습니다 ✗"]},{"id":"G90","q":"¿Hay ____ leche en el frigorífico?","o":["ø","algo","una","la"],"a":0,"k":"셀 수 없는 명사","t":"냉장고에 우유 있어?","e":"leche(우유)처럼 셀 수 없는 명사가 hay와 함께 쓰여 '(얼마간의) ~이 있다'라고 할 때는 관사를 붙이지 않습니다. 그래서 '¿Hay leche?'가 맞습니다. 또 hay 뒤에는 정관사(la)를 쓰지 않습니다. frigorífico는 스페인어로 냉장고이며 중남미에서는 refrigerador, heladera 등을 씁니다.","x":["ø: 셀 수 없는 명사 앞 관사 생략 → 정답 ✓","algo: 'algo de leche(우유 조금)'처럼 de가 필요합니다 ✗","una: 우유는 셀 수 없어서 부정관사를 쓰지 않습니다 ✗","la: hay 뒤에는 정관사를 쓰지 않습니다 ✗"]},{"id":"G91","q":"Hay una teoría según ____ las personas bilingües tienen mayor capacidad de concentración.","o":["cual","que","el cual","la cual"],"a":3,"k":"전치사 + la cual","t":"이중 언어 사용자가 집중력이 더 뛰어나다는 이론이 있다.","e":"전치사(según, por, con 등) 뒤에서 관계대명사를 쓸 때는 '정관사 + cual' 또는 '정관사 + que'를 씁니다. 선행사 'una teoría'가 여성 단수이므로 'la cual'이 맞습니다. 'según la cual'은 '그것에 따르면'이라는 뜻입니다.","x":["cual: 관계대명사 cual은 반드시 관사와 함께 씁니다 ✗","que: 전치사 según 뒤에서는 관사 없이 que만 쓰기 어렵습니다 ✗","el cual: 남성형이라 여성 명사 teoría와 맞지 않습니다 ✗","la cual: 여성 단수 → 정답 ✓"]},{"id":"G92","q":"No tenemos ____ deudas como vosotros.","o":["tanta","tan","tantas","tantos"],"a":2,"k":"동등비교 tanto","t":"우리는 너희만큼 빚이 많지 않아.","e":"명사 앞에서 '~만큼 많은 ~'이라고 할 때는 'tanto/a/os/as + 명사 + como'를 쓰고, tanto는 뒤 명사의 성·수에 맞춥니다. deudas(빚)는 여성 복수이므로 'tantas'가 됩니다. 형용사·부사 앞에서는 tan을 씁니다(tan rico como).","x":["tanta: 여성 단수라 복수 명사 deudas와 맞지 않습니다 ✗","tan: 형용사·부사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗","tantas: 여성 복수 → 정답 ✓","tantos: 남성 복수라 여성 명사 deudas와 맞지 않습니다 ✗"]},{"id":"G93","q":"A mi hermano le encanta el pescado; a mí, ____, no me gusta nada.","o":["por eso","por tanto","además","en cambio"],"a":3,"k":"대조 en cambio","t":"우리 형은 생선을 아주 좋아해. 반면에 나는 전혀 안 좋아해.","e":"'en cambio'는 '반면에, 그에 반해'라는 뜻으로 두 대상을 대조할 때 씁니다. 형은 좋아하고 나는 싫어한다는 대조 관계이므로 en cambio가 맞습니다. 비슷한 표현으로 'por el contrario'가 있습니다.","x":["por eso: '그래서(결과)'라서 대조 관계와 맞지 않습니다 ✗","por tanto: '따라서(결과)'라서 맞지 않습니다 ✗","además: '게다가(추가)'라서 반대되는 내용과 맞지 않습니다 ✗","en cambio: '반면에(대조)' → 정답 ✓"]},{"id":"G94","q":"Estuvimos charlando ____ amanecer.","o":["hasta","hasta un","hasta el","hasta que"],"a":2,"k":"hasta el + 명사","t":"우리는 새벽까지 수다를 떨었다.","e":"'hasta(~까지)' 뒤에 시간 명사가 오면 관사가 필요합니다. 'el amanecer'는 '새벽, 동틀 녘'이라는 명사(원래 동사 amanecer를 명사로 쓴 것)로, 특정한 그 새벽을 가리키므로 정관사 el을 씁니다. 'hasta que'는 뒤에 활용된 동사가 올 때 씁니다(hasta que amaneció).","x":["hasta: 명사 amanecer 앞에 관사가 필요합니다 ✗","hasta un: 부정관사는 '어느 새벽'이 되어 어색합니다 ✗","hasta el: '~까지' + 정관사 → 정답 ✓","hasta que: 뒤에 활용된 동사가 와야 합니다 ✗"]},{"id":"G95","q":"¿____ qué estabais hablando Regina y tú cuando yo llegué?","o":["Hasta","A","Desde","De"],"a":3,"k":"hablar de","t":"내가 도착했을 때 너랑 레히나는 무슨 얘기를 하고 있었니?","e":"'hablar de + 주제'는 '~에 대해 이야기하다'입니다. 의문문에서는 전치사가 의문사 앞으로 와서 '¿De qué hablabais?(무엇에 대해 이야기했니?)'가 됩니다. estabais는 vosotros 형태로 중남미에서는 '¿De qué estaban hablando?'라고 합니다.","x":["Hasta: '~까지'라서 hablar와 맞지 않습니다 ✗","A: hablar와 함께 주제를 나타내지 않습니다 ✗","Desde: '~부터'라서 의미가 맞지 않습니다 ✗","De: hablar de '~에 대해 말하다' → 정답 ✓"]},{"id":"G96","q":"Es domingo, ____ que los bancos están cerrados.","o":["o sea","por eso","sin embargo","pero"],"a":0,"k":"o sea que","t":"일요일이야, 그러니까 은행들이 문을 닫았다는 거지.","e":"'o sea que'는 '그러니까, 즉 ~라는 거지'라는 뜻으로, 앞 사실에서 나오는 결론을 말할 때 씁니다. 빈칸 뒤에 이미 que가 있으므로 'o sea'를 넣어 'o sea que'를 완성합니다. 'por eso'도 '그래서'라는 뜻이지만 뒤에 que를 붙이지 않습니다.","x":["o sea: o sea que(그러니까) 완성 → 정답 ✓","por eso: '그래서'라는 뜻이지만 'por eso que'라는 형태는 쓰지 않습니다 ✗","sin embargo: '그러나'라서 의미가 반대입니다 ✗","pero: '하지만'이라서 의미가 맞지 않습니다 ✗"]},{"id":"G97","q":"¿Os apetece ____ tomar algo en ese bar?","o":["a","ø","para","de"],"a":1,"k":"apetecer + 원형","t":"너희 저 바에서 뭐 한잔할래?","e":"'apetecer(~하고 싶다, 당기다)'는 gustar처럼 '하고 싶은 사람'을 간접목적격 대명사(os)로 쓰고, 하고 싶은 일은 전치사 없이 동사원형으로 바로 씁니다. '¿Te apetece + 동사원형?'은 스페인에서 '~할래?'라고 제안할 때 자주 씁니다. 중남미에서는 '¿Tienen ganas de...?'를 더 많이 씁니다.","x":["a: apetecer 뒤 동사원형 앞에는 전치사를 쓰지 않습니다 ✗","ø: 전치사 없이 동사원형 → 정답 ✓","para: '~하기 위해'라는 뜻이 되어 맞지 않습니다 ✗","de: apetecer 뒤에는 de를 쓰지 않습니다 ✗"]},{"id":"G98","q":"¿Por qué no ____ entregaste la carta a tus padres?","o":["les","las","lo","le"],"a":0,"k":"간접목적격 les","t":"왜 부모님께 편지를 드리지 않았니?","e":"'entregar algo a alguien(누구에게 무엇을 건네다)'에서 '받는 사람'은 간접목적격 대명사로 씁니다. 'a tus padres(네 부모님께)'는 3인칭 복수이므로 'les'입니다. 스페인어는 'a + 사람'이 있어도 대명사를 함께 쓰는 것이 자연스럽습니다.","x":["les: 3인칭 복수 간접목적격 → 정답 ✓","las: 직접목적격 여성 복수(그것들을)라 맞지 않습니다 ✗","lo: 직접목적격 남성 단수(그것을)라 맞지 않습니다 ✗","le: 3인칭 단수라 복수인 부모님과 맞지 않습니다 ✗"]},{"id":"G99","q":"Estamos ____ contra de esa medida.","o":["en","de","por","a"],"a":0,"k":"estar en contra de","t":"우리는 그 조치에 반대한다.","e":"'estar en contra de + 대상'은 '~에 반대하다'라는 고정 표현입니다. 반대로 '~에 찬성하다'는 'estar a favor de'라고 합니다. 두 표현의 전치사(en contra / a favor)를 함께 외워 두세요.","x":["en: estar en contra de '~에 반대하다' → 정답 ✓","de: 'de contra'라는 표현은 없습니다 ✗","por: 'por contra'는 '반면에'라는 다른 뜻입니다 ✗","a: 'a favor de(찬성)'와 헷갈리기 쉽지만 contra 앞에는 쓰지 않습니다 ✗"]},{"id":"G100","q":"____ frío, fuimos a la playa.","o":["Debido al","A causa del","Por el","A pesar del"],"a":3,"k":"양보 a pesar de","t":"추웠는데도 우리는 해변에 갔다.","e":"'a pesar de + 명사'는 '~에도 불구하고'라는 양보 표현입니다. 추운 날씨와 해변에 간 것은 예상과 반대되는 관계이므로 a pesar del frío가 맞습니다(de + el = del). 'debido a, a causa de, por'는 모두 '~ 때문에'라는 원인 표현이라 의미가 맞지 않습니다.","x":["Debido al: '~ 때문에(원인)'라서 추운데 해변에 간 상황과 맞지 않습니다 ✗","A causa del: '~ 때문에(원인)'라서 맞지 않습니다 ✗","Por el: '~ 때문에'라는 원인이라 맞지 않습니다 ✗","A pesar del: '~에도 불구하고' → 정답 ✓"]},{"id":"G101","q":"¿____ prefieres? ¿Ir al cine o al teatro?","o":["Dónde","Cómo","Cuál","Qué"],"a":3,"k":"의문사 qué","t":"뭐가 더 좋아? 영화관 가는 거, 아니면 극장 가는 거?","e":"선택지가 '동사원형(ir al cine / ir al teatro)'처럼 행동일 때는 '¿Qué prefieres?(무엇을 더 좋아해?)'를 씁니다. cuál은 보통 같은 종류의 명사(물건) 중에서 고를 때 씁니다(¿Cuál prefieres, el rojo o el azul?).","x":["Dónde: '어디에서'라서 preferir의 목적어가 되지 못합니다 ✗","Cómo: '어떻게'라서 의미가 맞지 않습니다 ✗","Cuál: 같은 종류의 명사 중에서 고를 때 쓰며, 행동(동사원형) 선택에는 qué가 자연스럽습니다 ✗","Qué: '무엇을' → 정답 ✓"]},{"id":"G102","q":"Creo que ____ alguien en nuestro jardín.","o":["está","son","es","hay"],"a":3,"k":"hay alguien","t":"우리 정원에 누가 있는 것 같아.","e":"'누군가가 있다'처럼 정해지지 않은 사람·사물의 존재를 말할 때는 hay를 씁니다. alguien(누군가), algo(무언가), un/una 같은 불특정 표현과는 estar가 아니라 hay를 씁니다. estar는 'Juan está en el jardín'처럼 특정한 대상의 위치에 씁니다.","x":["está: 특정한 대상의 위치에 쓰며 alguien과는 hay를 씁니다 ✗","son: ser는 존재를 나타내지 않습니다 ✗","es: ser는 존재를 나타내지 않습니다 ✗","hay: 불특정 대상의 존재 → 정답 ✓"]},{"id":"G103","q":"Si tienes problemas ____ dinero, yo puedo prestarte un poco.","o":["por","para","a","de"],"a":3,"k":"problemas de","t":"돈 문제가 있으면 내가 조금 빌려줄 수 있어.","e":"'problemas de + 명사'는 '~ 문제'라는 뜻으로 문제의 종류를 나타냅니다. 'problemas de dinero(돈 문제)', 'problemas de salud(건강 문제)'처럼 씁니다. 전치사 de가 명사를 꾸며 종류·분야를 나타내는 대표적인 쓰임입니다.","x":["por: '~ 때문에'로 문제의 종류를 나타내지 않습니다 ✗","para: '~를 위한'이라서 의미가 맞지 않습니다 ✗","a: 명사를 꾸며 종류를 나타내지 않습니다 ✗","de: '돈 문제'의 de → 정답 ✓"]},{"id":"G104","q":"____ que fueras más comprensivo conmigo.","o":["Quiero","Querré","He querido","Querría"],"a":3,"k":"querría que + 접속법 과거","t":"네가 나를 좀 더 이해해 주면 좋겠어.","e":"que절에 접속법 과거(fueras)가 오려면 주절이 과거 시제나 가능법이어야 합니다(시제 일치). 'Querría que + 접속법 과거'는 '~해 주면 좋겠는데'라는 부드러운 바람 표현입니다. 주절이 현재(Quiero)라면 'Quiero que seas...'처럼 접속법 현재를 씁니다.","x":["Quiero: 현재형이라 접속법 과거 fueras와 시제가 맞지 않습니다 ✗","Querré: 미래형이라 fueras와 시제가 맞지 않습니다 ✗","He querido: 현재완료라 이 문장의 바람 표현과 맞지 않습니다 ✗","Querría: 가능법 + 접속법 과거 → 정답 ✓"]},{"id":"G105","q":"Comí demasiado en Navidad, por eso estoy ____ dieta.","o":["bajo","a","en","de"],"a":1,"k":"estar a dieta","t":"크리스마스에 너무 많이 먹어서 다이어트 중이야.","e":"'estar a dieta'는 '다이어트 중이다'라는 고정 표현으로 전치사 a를 씁니다. 'ponerse a dieta'는 '다이어트를 시작하다'입니다. 중남미 일부 지역에서는 'estar en dieta'도 쓰지만 표준적으로는 a dieta입니다.","x":["bajo: '~아래'라는 뜻이라 맞지 않습니다 ✗","a: estar a dieta '다이어트 중이다' → 정답 ✓","en: 일부 지역에서 쓰지만 표준 표현은 a dieta입니다 ✗","de: 'estar de dieta'라는 표현은 쓰지 않습니다 ✗"]},{"id":"G106","q":"¿A quién ____ diste mi número de teléfono?","o":["lo","la","les","le"],"a":3,"k":"간접목적격 le","t":"너 누구한테 내 전화번호를 줬어?","e":"'dar algo a alguien(누구에게 무엇을 주다)'에서 받는 사람은 간접목적격 대명사로 씁니다. '¿A quién?(누구에게)'은 단수로 묻는 것이므로 3인칭 단수 'le'가 맞습니다. 직접목적어는 'mi número de teléfono'로 문장에 이미 있습니다.","x":["lo: 직접목적격(그것을)이라 받는 사람을 나타내지 못합니다 ✗","la: 직접목적격 여성(그녀를)이라 맞지 않습니다 ✗","les: 복수형으로, a quién(단수)과 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓"]},{"id":"G107","q":"Chicos, ____ la tarea de la escuela antes de salir a jugar.","o":["haz","haced","hacéis","haces"],"a":1,"k":"명령법 vosotros","t":"얘들아, 놀러 나가기 전에 학교 숙제 해.","e":"'Chicos(얘들아)'처럼 여러 명에게 말할 때 스페인에서는 vosotros 명령을 씁니다. 동사원형의 -r를 -d로 바꿔 hacer → 'haced'가 됩니다. 중남미에서는 ustedes 명령 'hagan'을 씁니다.","x":["haz: tú(한 사람)에게 하는 명령이라 chicos(복수)와 맞지 않습니다 ✗","haced: vosotros 긍정 명령 → 정답 ✓","hacéis: 직설법 현재(너희는 한다)라 명령이 아닙니다 ✗","haces: 직설법 현재(너는 한다)라 명령이 아닙니다 ✗"]},{"id":"G108","q":"Ahora ____. Te llamaré cuando hayamos terminado.","o":["hemos estado almorzando","estamos almorzando","almorcemos","almorzamos"],"a":1,"k":"현재진행형","t":"지금 우리 점심 먹는 중이야. 다 먹고 나서 전화할게.","e":"'Ahora(지금)' 이 순간 하고 있는 일은 현재진행형 'estar + 현재분사'로 말합니다. 'estamos almorzando'는 '점심을 먹고 있는 중이다'입니다. 뒤의 'cuando hayamos terminado(다 끝내면)'는 미래 시점이라 접속법 현재완료를 썼습니다.","x":["hemos estado almorzando: '계속 먹어 왔다'라는 뜻이라 '지금 먹는 중'과 어색합니다 ✗","estamos almorzando: 현재진행형 → 정답 ✓","almorcemos: 접속법 현재(먹자)라 상황 설명에 맞지 않습니다 ✗","almorzamos: 단순 현재로 '지금 이 순간'의 진행을 나타내기에 부족합니다 ✗"]},{"id":"G109","q":"Marcelo nos dijo que ____ en moto.","o":["vendría","estaría viniendo","vaya a venir","venga"],"a":0,"k":"과거 속 미래 (가능법)","t":"마르셀로는 오토바이를 타고 올 거라고 우리에게 말했다.","e":"과거에 말한 '앞으로의 일'을 전할 때는 가능법(조건법)을 씁니다. 원래 말 'Vendré en moto(오토바이로 올게)'가 'nos dijo que'(과거) 뒤에서 'vendría'로 바뀝니다. 이것을 '과거 속의 미래'라고 합니다.","x":["vendría: 가능법, 과거 속 미래 → 정답 ✓","estaría viniendo: 진행형으로 의미가 어색합니다 ✗","vaya a venir: 접속법이라 사실 전달의 decir que 뒤에 맞지 않습니다 ✗","venga: 접속법 현재로 '오라고 말했다(명령 전달)'라는 다른 뜻이 됩니다 ✗"]},{"id":"G110","q":"Freír un huevo es facilísimo, hasta ____ puedo hacerlo.","o":["a mí","me","yo","mí"],"a":2,"k":"hasta yo (~조차)","t":"달걀 프라이는 정말 쉬워, 나조차도 할 수 있어.","e":"여기서 'hasta'는 '~까지'가 아니라 '~조차, ~마저(incluso)'라는 뜻입니다. 이 뜻일 때 hasta는 전치사가 아니라 부사처럼 쓰여서 뒤에 주격 대명사 'yo'가 옵니다. 'puedo(나는 할 수 있다)'의 주어가 yo이기 때문입니다. entre tú y yo, según yo도 비슷한 예외입니다.","x":["a mí: 간접목적어 강조형이라 puedo의 주어가 될 수 없습니다 ✗","me: 목적격 대명사라 주어 자리에 올 수 없습니다 ✗","yo: 주격, '나조차' → 정답 ✓","mí: 전치사 뒤 형태로, 여기서 hasta는 '~조차'라는 뜻이라 주격이 필요합니다 ✗"]},{"id":"G111","q":"Mi padre siempre ____ en esa silla.","o":["se siente","siente","se sienta","sienta"],"a":2,"k":"sentarse vs sentirse","t":"우리 아빠는 늘 저 의자에 앉으신다.","e":"'sentarse(앉다)'와 'sentirse(느끼다)'는 3인칭 형태가 비슷해 헷갈리기 쉽습니다. sentarse → se sienta(앉는다), sentirse → se siente(느낀다). 의자에 앉는 것이므로 'se sienta'가 맞습니다.","x":["se siente: sentirse(~하게 느끼다)라서 의미가 맞지 않습니다 ✗","siente: sentir(느끼다)라서 의미가 맞지 않습니다 ✗","se sienta: sentarse(앉다) 3인칭 단수 → 정답 ✓","sienta: 재귀대명사가 없으면 '앉히다' 또는 '어울리다'라는 다른 뜻이 됩니다 ✗"]},{"id":"G112","q":"Cuando ____ con mis primos, me lo paso genial.","o":["salga","salgo","saldré","salía"],"a":1,"k":"cuando + 직설법 (습관)","t":"사촌들과 놀러 나가면 정말 즐거워.","e":"'cuando'가 반복되는 습관이나 일반적인 사실(~할 때마다)을 말할 때는 직설법 현재를 씁니다. 주절 'me lo paso genial(아주 즐겁게 보낸다)'도 현재형이므로 'salgo'가 맞습니다. 미래의 일을 말할 때만 'Cuando salga...'처럼 접속법을 씁니다.","x":["salga: 접속법은 미래의 일일 때 쓰며, 습관에는 직설법을 씁니다 ✗","salgo: 직설법 현재, 습관 → 정답 ✓","saldré: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","salía: 불완료과거로 현재형 주절과 시제가 맞지 않습니다 ✗"]},{"id":"G113","q":"Hoy ____ domingo, por eso hay tantas tiendas cerradas.","o":["es el","está el","es","está"],"a":2,"k":"ser + 요일","t":"오늘은 일요일이라서 문을 닫은 가게가 많다.","e":"'오늘은 ~요일이다'라고 할 때는 'Hoy es + 요일'로 쓰고, 요일 앞에 관사를 붙이지 않습니다. 반면 '일요일에'처럼 시점을 나타낼 때는 관사를 씁니다(El domingo voy al cine). 스페인에서는 'Hoy estamos a domingo'라는 표현도 있지만 보기의 형태와는 다릅니다.","x":["es el: 'Hoy es + 요일'에는 관사를 쓰지 않습니다 ✗","está el: estar는 이렇게 요일을 말할 때 쓰지 않습니다 ✗","es: Hoy es domingo → 정답 ✓","está: estar로 요일을 말하지 않습니다 ✗"]},{"id":"G114","q":"Ayer me encontraba mal, por eso ____ antes a casa.","o":["me iría","me iba","me fui","me he ido"],"a":2,"k":"단순과거","t":"어제 몸이 안 좋아서 일찍 집에 갔다.","e":"'Ayer(어제)'처럼 끝난 과거 시점에 한 번 일어나 완료된 행동은 단순과거를 씁니다. 'me encontraba mal(몸이 안 좋았다)'은 배경 상태라 불완료과거이고, '집에 갔다'는 그 결과로 일어난 사건이라 'me fui'가 됩니다. irse는 '(어디를) 떠나다, 가 버리다'라는 뜻입니다.","x":["me iría: 가능법(갈 텐데)이라 실제 일어난 일에 맞지 않습니다 ✗","me iba: 불완료과거로 '가려던 참이었다/가곤 했다'가 되어 맞지 않습니다 ✗","me fui: 단순과거, 완료된 사건 → 정답 ✓","me he ido: 현재완료라 ayer와 함께 쓰기 어색합니다 ✗"]},{"id":"G115","q":"Vivo ____ solo dos minutos de mi colegio.","o":["a","desde","de","en"],"a":0,"k":"거리 a","t":"나는 학교에서 겨우 2분 거리에 산다.","e":"'estar/vivir a + 거리·시간 + de'는 '~에서 ~만큼 떨어진 곳에'라는 거리 표현입니다. 'a dos minutos de mi colegio'는 '학교에서 2분 거리에'입니다. 예: Madrid está a 600 km de Barcelona.(마드리드는 바르셀로나에서 600km 떨어져 있다.)","x":["a: 거리 표현 'a + 거리' → 정답 ✓","desde: '~부터'라서 거리 표현과 맞지 않습니다 ✗","de: 출발점(de mi colegio)에 쓰며 거리 앞에는 쓰지 않습니다 ✗","en: '~안에'라서 거리 표현에 쓰지 않습니다 ✗"]},{"id":"G116","q":"No sé nada de ese tema, ____, no puedo informarte.","o":["por tanto","como","ya que","porque"],"a":0,"k":"결과 por tanto","t":"나는 그 주제에 대해 아무것도 몰라, 그러니까 알려 줄 수가 없어.","e":"'por tanto'는 '따라서, 그러므로'라는 뜻으로 앞 내용의 결과를 이어 줍니다. '모른다 → 그래서 알려 줄 수 없다'라는 흐름이므로 por tanto가 맞습니다. 쉼표 사이에 들어가는 연결어라는 점도 단서입니다. 비슷한 말: por lo tanto, así que, por eso.","x":["por tanto: '따라서(결과)' → 정답 ✓","como: 이유를 나타내지만 보통 문장 맨 앞에 옵니다 ✗","ya que: '~이니까(이유)'라서 결과 앞에 쓰면 의미가 뒤바뀝니다 ✗","porque: '왜냐하면(이유)'이라 결과 앞에 쓰면 의미가 뒤바뀝니다 ✗"]},{"id":"G117","q":"No creo que Miguel Ángel ____ más dinero que tú.","o":["tendría","tiene","tenga","está teniendo"],"a":2,"k":"no creer que + 접속법","t":"미겔 앙헬이 너보다 돈이 많을 것 같지 않아.","e":"'creer que(~라고 생각하다)'는 긍정일 때 직설법을 쓰지만, 부정 'No creo que'가 되면 의심을 나타내므로 접속법을 씁니다. tener의 접속법 현재 3인칭은 'tenga'입니다. 비교: Creo que tiene dinero. / No creo que tenga dinero.","x":["tendría: 가능법이라 no creo que 뒤에 맞지 않습니다 ✗","tiene: 직설법으로, 부정 no creo que 뒤에는 접속법이 필요합니다 ✗","tenga: 접속법 현재 3인칭 → 정답 ✓","está teniendo: 진행형이고 직설법이라 맞지 않습니다 ✗"]},{"id":"G118","q":"Toma, Isabel, este regalo es ____ ti.","o":["por","a","hacia","para"],"a":3,"k":"para (수혜자)","t":"자, 이사벨, 이 선물은 너를 위한 거야.","e":"'para'는 '~를 위한, ~에게 주는'이라는 수혜자(받는 사람)를 나타냅니다. 'Este regalo es para ti(이 선물은 너를 위한 거야)'는 아주 자주 쓰는 표현입니다. 전치사 뒤에서 tú는 ti로 바뀌고, ti에는 악센트를 붙이지 않습니다.","x":["por: '~ 때문에, ~를 대신해서'라서 선물 받는 사람에 쓰지 않습니다 ✗","a: 'dar algo a alguien'처럼 동사와 함께 쓰며 ser + 수혜자에는 para를 씁니다 ✗","hacia: '~쪽으로'라는 방향이라 의미가 맞지 않습니다 ✗","para: 수혜자 '~를 위한' → 정답 ✓"]},{"id":"G119","q":"¿Os hace ilusión que ____ vuestros primos en verano?","o":["vienen","vengan","vendrán","vinieran"],"a":1,"k":"hacer ilusión + 접속법","t":"너희는 여름에 사촌들이 오는 게 기대되니?","e":"'hacer ilusión(설레다, 기대되다)'은 gustar처럼 감정을 나타내는 구문으로, 뒤에 다른 주어의 que절이 오면 접속법을 씁니다. 주절이 현재(hace)이므로 접속법 현재 'vengan'이 맞습니다. 스페인에서 자주 쓰는 표현입니다.","x":["vienen: 직설법으로 감정 표현 뒤에 쓰지 않습니다 ✗","vengan: 접속법 현재 3인칭 복수 → 정답 ✓","vendrán: 직설법 미래로 감정 표현 뒤에 쓰지 않습니다 ✗","vinieran: 접속법 과거로, 주절이 현재(hace)라서 시제가 맞지 않습니다 ✗"]},{"id":"G120","q":"¿Te parece normal que nuestra hija ____ tan tarde a casa?","o":["vuelve","está volviendo","volvería","vuelva"],"a":3,"k":"parecer + 형용사 que","t":"우리 딸이 그렇게 늦게 집에 오는 게 정상이라고 생각해?","e":"'Me/Te parece normal(raro, bien...) que'는 평가·판단을 나타내므로 뒤에 접속법을 씁니다. 주어 'nuestra hija'는 3인칭 단수이므로 volver의 접속법 현재 'vuelva'가 맞습니다(o→ue 어간 변화).","x":["vuelve: 직설법으로 평가 표현 뒤에 쓰지 않습니다 ✗","está volviendo: 직설법 진행형이라 맞지 않습니다 ✗","volvería: 가능법이라 맞지 않습니다 ✗","vuelva: 접속법 현재 3인칭 → 정답 ✓"]},{"id":"G121","q":"Si tuviera más tiempo libre, ____ menos estresado.","o":["estuviera","estaría","estoy","estaré"],"a":1,"k":"si + 접속법 과거","t":"자유 시간이 더 있다면 스트레스를 덜 받을 텐데.","e":"현재 사실과 반대되는 가정은 'si + 접속법 과거(tuviera), 가능법(estaría)'으로 만듭니다. '~라면 ~할 텐데'라는 뜻입니다. 주절에 접속법 과거(estuviera)를 쓰는 것은 틀립니다.","x":["estuviera: 접속법 과거는 si절에 쓰고 주절에는 쓰지 않습니다 ✗","estaría: 가능법(~할 텐데) → 정답 ✓","estoy: 직설법 현재로 가정문 주절에 맞지 않습니다 ✗","estaré: 직설법 미래로 si + 접속법 과거와 짝이 맞지 않습니다 ✗"]},{"id":"G122","q":"El lunes pasado ____ una película interesantísima en el cine.","o":["vi","había visto","he visto","veía"],"a":0,"k":"단순과거","t":"지난 월요일에 영화관에서 아주 재미있는 영화를 봤다.","e":"'El lunes pasado(지난 월요일)'처럼 끝난 과거 시점에 완료된 행동은 단순과거를 씁니다. ver의 단순과거 1인칭은 'vi'(악센트 없음)입니다. 'interesantísima'는 interesante에 -ísimo를 붙인 '아주 재미있는'이라는 절대최상급입니다.","x":["vi: 단순과거 1인칭 → 정답 ✓","había visto: 과거완료로 다른 과거 기준 시점이 없어 맞지 않습니다 ✗","he visto: 현재완료라 el lunes pasado와 쓰기 어색합니다 ✗","veía: 불완료과거라 한 번 완료된 일에 맞지 않습니다 ✗"]},{"id":"G123","q":"¡____ llueve! Será mejor que no salgamos todavía.","o":["Cuál","Qué","Como","Cómo"],"a":3,"k":"감탄문 cómo","t":"비가 엄청 오네! 아직 나가지 않는 게 좋겠어.","e":"'¡Cómo + 동사!'는 '정말 ~하구나!'처럼 동작의 정도를 감탄할 때 씁니다. '¡Cómo llueve!'는 '비가 정말 많이 오네!'입니다. '¡Qué + 명사/형용사!'는 '¡Qué lluvia!', '¡Qué bonito!'처럼 동사가 아닌 말 앞에 씁니다.","x":["Cuál: 감탄문에 쓰지 않습니다 ✗","Qué: 명사·형용사 앞에서 감탄할 때 쓰며 동사 바로 앞에는 쓰지 않습니다 ✗","Como: 악센트가 없어 감탄사가 아니라 '~처럼, ~이니까'가 됩니다 ✗","Cómo: 동사 감탄 '정말 ~하구나' → 정답 ✓"]},{"id":"G124","q":"¿Cuándo ____ usted a su marido?","o":["conocía","conoció","estaba conociendo","estuvo conociendo"],"a":1,"k":"conocer 단순과거","t":"남편분을 언제 처음 만나셨어요?","e":"conocer는 단순과거로 쓰면 '(처음) 알게 되다, 만나다'라는 뜻이 됩니다. 처음 만난 것은 한 번 일어난 사건이므로 'conoció'가 맞습니다. 불완료과거 conocía는 '이미 알고 있었다'라는 상태를 나타냅니다.","x":["conocía: 불완료과거로 '알고 있었다(상태)'라는 뜻이 됩니다 ✗","conoció: 단순과거 '처음 만났다' → 정답 ✓","estaba conociendo: 진행형으로 처음 만난 순간에 맞지 않습니다 ✗","estuvo conociendo: 진행형으로 의미가 맞지 않습니다 ✗"]},{"id":"G125","q":"Hay personas que no respetan ____ leyes.","o":["unos","las","ø","los"],"a":1,"k":"정관사 (총칭)","t":"법을 지키지 않는 사람들이 있다.","e":"'las leyes(법)'처럼 어떤 것 전체를 일반적으로 가리킬 때는 정관사를 씁니다. respetar las leyes는 '법을 지키다'라는 자연스러운 표현입니다. ley(법)는 여성 명사이므로 복수는 'las leyes'가 됩니다.","x":["unos: 남성형이고 '몇몇 법'이라는 뜻이 되어 맞지 않습니다 ✗","las: 여성 복수 정관사, 총칭 → 정답 ✓","ø: 일반적인 법 전체를 말할 때는 정관사가 필요합니다 ✗","los: 남성형이라 여성 명사 leyes와 맞지 않습니다 ✗"]},{"id":"G126","q":"¿Cuándo ____ usted y su esposa?","o":["se conocieron","se conocen","se conocían","se habían conocido"],"a":0,"k":"conocerse 단순과거","t":"당신과 부인께서는 언제 처음 만나셨어요?","e":"'conocerse'는 '서로 알게 되다, 처음 만나다'라는 상호적 재귀동사입니다. 처음 만난 일은 과거에 한 번 일어난 사건이므로 단순과거 3인칭 복수 'se conocieron'이 맞습니다. 주어 'usted y su esposa'는 3인칭 복수(ustedes)로 취급합니다.","x":["se conocieron: 단순과거, 처음 만났다 → 정답 ✓","se conocen: 현재형이라 과거 사건을 묻는 질문에 맞지 않습니다 ✗","se conocían: 불완료과거로 '이미 서로 알고 있었다'는 상태가 됩니다 ✗","se habían conocido: 과거완료로 기준이 되는 과거 시점이 없습니다 ✗"]},{"id":"G127","q":"Nunca ____ en ese restaurante. ¿Está buena la comida que hacen?","o":["he comido","comía","estaba comiendo","había comido"],"a":0,"k":"현재완료 (경험)","t":"그 식당에서 한 번도 먹어 본 적이 없어. 거기 음식 맛있어?","e":"'Nunca(한 번도)'와 함께 지금까지의 경험을 말할 때는 현재완료 'he + 과거분사'를 씁니다. 'Nunca he comido...'는 '~를 먹어 본 적이 없다'입니다. 중남미에서는 단순과거 'Nunca comí...'도 자주 씁니다.","x":["he comido: 현재완료, 지금까지의 경험 → 정답 ✓","comía: 불완료과거로 '먹곤 했다'라서 경험 표현에 맞지 않습니다 ✗","estaba comiendo: 과거진행형이라 의미가 맞지 않습니다 ✗","había comido: 과거완료로 과거 기준 시점이 없어 맞지 않습니다 ✗"]},{"id":"G128","q":"Perdona, ¿sabes dónde está la farmacia ____ cercana?","o":["mucho","muy","más","la más"],"a":2,"k":"최상급 (관사+명사+más)","t":"실례지만, 가장 가까운 약국이 어디 있는지 아세요?","e":"최상급은 '정관사 + 명사 + más + 형용사' 순서로 만듭니다. 이미 명사 앞에 정관사 la가 있으므로(la farmacia) 빈칸에는 'más'만 넣으면 됩니다. 관사를 한 번 더 쓰면 틀립니다. 예: el chico más alto(가장 키 큰 남자아이).","x":["mucho: 형용사 앞에 쓰지 않고 '가장'의 뜻도 없습니다 ✗","muy: '매우 가까운 약국'이 되어 최상급이 안 됩니다 ✗","más: la farmacia más cercana(가장 가까운) → 정답 ✓","la más: 정관사 la가 이미 명사 앞에 있어 중복됩니다 ✗"]},{"id":"G129","q":"Si ____ más, sacarás mejores notas.","o":["estudies","estudias","estudiarías","estudiarás"],"a":1,"k":"si 조건문 (현재)","t":"공부를 더 하면 더 좋은 성적을 받을 거야.","e":"현실적인 조건은 'si + 직설법 현재, 주절 미래/현재'로 만듭니다. 주절이 sacarás(받을 것이다)로 2인칭이므로 조건절도 'estudias'입니다. si 바로 뒤에는 미래형이나 접속법 현재를 쓰지 않는다는 점을 꼭 기억하세요.","x":["estudies: 접속법 현재로 si 바로 뒤에 쓰지 않습니다 ✗","estudias: 직설법 현재 2인칭 → 정답 ✓","estudiarías: 가능법으로 si절에 쓰지 않습니다 ✗","estudiarás: 직설법 미래로 si절에 쓰지 않습니다 ✗"]},{"id":"G130","q":"¿____ sirve esta cosa?","o":["A qué","A que","Para qué","Para que"],"a":2,"k":"para qué (용도)","t":"이 물건은 어디에 쓰는 거야?","e":"'servir para + 용도'는 '~에 쓰이다, ~하는 데 도움이 되다'입니다. 용도를 물을 때는 '¿Para qué sirve?(무엇에 쓰여?)'라고 하고, 의문사 qué에는 악센트를 붙입니다. 악센트 없는 'para que'는 '~하도록'이라는 접속사입니다.","x":["A qué: servir와 함께 용도를 묻지 않습니다 ✗","A que: 악센트가 없어 의문문이 되지 않습니다 ✗","Para qué: 용도 '무엇에' → 정답 ✓","Para que: 악센트가 없으면 '~하도록'이라는 접속사입니다 ✗"]},{"id":"G131","q":"Anoche me ____ un dolor de espalda muy molesto.","o":["daba","dio","ha estado dando","ha dado"],"a":1,"k":"단순과거","t":"어젯밤 나는 허리가 아파서 정말 괴로웠다.","e":"'Anoche(어젯밤)'라는 끝난 과거 시점에 일어난 일은 단순과거를 씁니다. 'dar un dolor(통증이 생기다)'에서 주어는 'un dolor'이므로 3인칭 단수 단순과거 'dio'가 맞습니다. 예: Me dio un dolor de cabeza.(두통이 왔다.)","x":["daba: 불완료과거로 반복·배경을 나타내 '어젯밤 생긴 통증'에 어색합니다 ✗","dio: 단순과거 3인칭 단수 → 정답 ✓","ha estado dando: 현재완료 진행형이라 anoche와 맞지 않습니다 ✗","ha dado: 현재완료라 anoche(끝난 과거 시점)와 쓰기 어색합니다 ✗"]},{"id":"G132","q":"Dijiste que ____ con nosotros. ¿Por qué cambiaste de idea después?","o":["vengas","vinieras","vendrías","vienes"],"a":2,"k":"과거 속 미래 (가능법)","t":"너 우리랑 같이 갈 거라고 했잖아. 왜 나중에 마음이 바뀌었어?","e":"과거에 말한 미래의 계획을 전할 때는 가능법을 씁니다. 원래 말 'Vendré con vosotros(너희랑 같이 갈게)'가 'Dijiste que'(과거) 뒤에서 'vendrías'로 바뀝니다. 접속법(vinieras)을 쓰면 '같이 오라고 말했다'라는 명령 전달이 됩니다.","x":["vengas: 접속법 현재로 '오라고 했다(명령)'라는 다른 뜻이 되고 시제도 맞지 않습니다 ✗","vinieras: 접속법 과거로 '오라고 했다(명령)'라는 뜻이 됩니다 ✗","vendrías: 가능법, 과거 속 미래 → 정답 ✓","vienes: 직설법 현재로 과거 간접화법과 시제가 맞지 않습니다 ✗"]},{"id":"G133","q":"¿Cuándo ____ la manifestación de la que nos hablaste?","o":["está","hay","haber","es"],"a":3,"k":"ser (행사 시간)","t":"네가 우리에게 말했던 그 시위는 언제 열려?","e":"시위·파티·회의 같은 '행사'가 언제·어디서 열리는지 말할 때는 ser를 씁니다. 'la manifestación(시위)'은 행사이므로 '¿Cuándo es?'가 됩니다. 'de la que nos hablaste'는 '네가 우리에게 말했던 (그것)'이라는 관계절입니다.","x":["está: estar는 행사 개최 시점에 쓰지 않습니다 ✗","hay: 정관사(la)가 붙은 특정한 대상과 함께 쓰지 않습니다 ✗","haber: 동사원형이라 활용된 동사 자리에 올 수 없습니다 ✗","es: 행사의 ser → 정답 ✓"]},{"id":"G134","q":"Qué raro, son las 3 y Paula no ____ todavía.","o":["llegue","había llegado","ha llegado","llegase"],"a":2,"k":"현재완료 (todavía no)","t":"이상하네, 3시인데 파울라가 아직 안 왔어.","e":"'todavía no(아직 ~않았다)'처럼 지금까지 일어나지 않은 일을 말할 때는 현재완료를 씁니다. 지금(son las 3)을 기준으로 아직 도착하지 않았으므로 'no ha llegado'가 맞습니다. '¡Qué raro!'는 감정 표현이지만 '¡Qué raro que...!'처럼 que가 없으므로 접속법을 쓰지 않습니다.","x":["llegue: 접속법 현재로 que절이 아닌 일반 문장에 쓰지 않습니다 ✗","había llegado: 과거완료라 현재 시점(son las 3)과 맞지 않습니다 ✗","ha llegado: 현재완료 → 정답 ✓","llegase: 접속법 과거라 맞지 않습니다 ✗"]},{"id":"G135","q":"Perdona que no te ____ antes.","o":["haya avisado","he avisado","había avisado","avisaría"],"a":0,"k":"perdonar que + 접속법","t":"더 일찍 알려 주지 못해서 미안해.","e":"'Perdona que(~해서 미안해)'는 감정을 나타내는 표현이라 뒤에 접속법을 씁니다. 알리지 못한 것은 이미 지나간 일이므로 접속법 현재완료 'haya avisado'가 됩니다. 예: Perdona que llegue tarde.(늦어서 미안해 - 지금 일)","x":["haya avisado: 접속법 현재완료 → 정답 ✓","he avisado: 직설법 현재완료로 perdona que 뒤에 쓰지 않습니다 ✗","había avisado: 직설법 과거완료라 맞지 않습니다 ✗","avisaría: 가능법이라 맞지 않습니다 ✗"]},{"id":"G136","q":"____ no sé qué voy a hacer este fin de semana.","o":["Incluso","Mientras","Aun","Todavía"],"a":3,"k":"todavía (아직)","t":"이번 주말에 뭘 할지 아직 모르겠어.","e":"'Todavía no + 동사'는 '아직 ~하지 않다/못하다'라는 뜻입니다. 'Aún no sé'도 같은 뜻이지만, 이때는 반드시 악센트가 있는 'aún'을 써야 합니다. 악센트 없는 'aun'은 '~조차(incluso)'라는 다른 뜻입니다.","x":["Incluso: '~조차, ~까지도'라는 뜻이라 의미가 맞지 않습니다 ✗","Mientras: '~하는 동안'이라 의미가 맞지 않습니다 ✗","Aun: 악센트가 없으면 '~조차'라는 뜻이라 '아직'이 되지 않습니다 ✗","Todavía: '아직' → 정답 ✓"]},{"id":"G137","q":"Voy a darte una pastilla ____ se te pase el dolor de cabeza.","o":["porque","aunque","para","para que"],"a":3,"k":"para que + 접속법","t":"두통이 낫도록 약을 하나 줄게.","e":"뒤에 다른 주어(el dolor)의 활용된 동사(pase, 접속법)가 오므로 목적을 나타내는 접속사 'para que(~하도록)'가 필요합니다. 주어가 같고 동사원형이 오면 para만 씁니다(para dormir mejor). 'pasarse el dolor'는 '통증이 사라지다'입니다.","x":["porque: '~ 때문에'로 이유를 나타내고 접속법과 어울리지 않습니다 ✗","aunque: '비록 ~일지라도'로 의미가 맞지 않습니다 ✗","para: 뒤에 동사원형이 와야 하는데 활용된 동사(pase)가 있습니다 ✗","para que: 목적 + 접속법 → 정답 ✓"]},{"id":"G138","q":"Cuando ____ a Madrid, os llevaremos a un sitio que está genial.","o":["vengáis","vengas","vienen","venís"],"a":0,"k":"cuando + 접속법 (미래)","t":"너희가 마드리드에 오면, 정말 멋진 곳에 데려가 줄게.","e":"'cuando'가 미래의 일(아직 일어나지 않은 일)을 말할 때는 뒤에 접속법을 씁니다. 주절이 'os llevaremos(너희를 데려갈게)'로 vosotros를 가리키므로 venir의 접속법 현재 vosotros 형태 'vengáis'가 맞습니다. 중남미에서는 'Cuando vengan...'이라고 합니다.","x":["vengáis: 접속법 현재 vosotros → 정답 ✓","vengas: 접속법이지만 tú(한 사람) 형태라 os(너희)와 맞지 않습니다 ✗","vienen: 직설법이라 미래의 cuando절에 맞지 않습니다 ✗","venís: 직설법이라 미래의 cuando절에 맞지 않습니다 ✗"]},{"id":"G139","q":"¡Ojalá nos ____ la lotería!","o":["tocaría","toque","tocará","estará tocando"],"a":1,"k":"ojalá + 접속법","t":"우리 복권에 당첨되면 좋겠다!","e":"'¡Ojalá!(~하면 좋겠다)'는 바람을 나타내며 뒤에 항상 접속법을 씁니다. 'tocar la lotería(복권에 당첨되다)'는 gustar처럼 당첨된 사람을 간접목적격(nos)으로, 주어는 la lotería(3인칭 단수)로 씁니다. 그래서 접속법 현재 'toque'가 맞습니다.","x":["tocaría: 가능법으로 ojalá 뒤에 쓰지 않습니다 ✗","toque: 접속법 현재 3인칭 → 정답 ✓","tocará: 직설법 미래로 ojalá 뒤에 쓰지 않습니다 ✗","estará tocando: 미래 진행형으로 맞지 않습니다 ✗"]},{"id":"G140","q":"Es obvio que ____ fotografía es una de sus pasiones.","o":["de la","la","una","ø"],"a":1,"k":"정관사 (주어 총칭)","t":"사진이 그의 열정 중 하나라는 것은 분명하다.","e":"스페인어에서 주어로 쓰이는 명사가 일반적인 개념(사진이라는 분야)을 가리킬 때는 정관사를 붙입니다. 그래서 'la fotografía es...'가 됩니다. 한국어나 영어(Photography is...)와 달리 관사를 빼지 않는다는 점에 주의하세요.","x":["de la: 전치사 de가 붙어 주어가 될 수 없습니다 ✗","la: 일반 개념 주어 앞 정관사 → 정답 ✓","una: '어떤 사진 하나'라는 뜻이 되어 맞지 않습니다 ✗","ø: 주어 자리의 일반 명사에는 정관사가 필요합니다 ✗"]},{"id":"G141","q":"Yo ya ____ de casa cuando llegó mi esposa. Por eso no la vi.","o":["estaba saliendo","salí","había salido","he salido"],"a":2,"k":"과거완료","t":"아내가 도착했을 때 나는 이미 집을 나간 뒤였다. 그래서 아내를 못 봤다.","e":"과거의 한 시점(아내가 도착했을 때)보다 먼저 끝난 일은 과거완료 'había + 과거분사'를 씁니다. 'ya(이미)'와 '그래서 못 봤다'는 내용으로 보아 아내가 오기 전에 이미 나갔음을 알 수 있습니다. 그래서 'había salido'가 맞습니다.","x":["estaba saliendo: '나가는 중이었다'면 아내를 봤을 수도 있어 문맥과 맞지 않습니다 ✗","salí: 단순과거로는 '이미 나간 뒤였다'라는 선후 관계가 드러나지 않습니다 ✗","había salido: 과거완료 → 정답 ✓","he salido: 현재완료라 과거 이야기와 맞지 않습니다 ✗"]},{"id":"G142","q":"Mañana ____ varios eventos en nuestra escuela.","o":["ha habido","habrá","había","habrán"],"a":1,"k":"haber 미래 habrá","t":"내일 우리 학교에서 여러 행사가 열릴 것이다.","e":"'있다'라는 뜻의 hay는 미래에도 단수형 'habrá'만 씁니다. 뒤에 복수 명사(varios eventos)가 와도 'habrán'으로 바꾸지 않습니다. 이 hay(haber)는 주어가 없는 무인칭 동사이기 때문입니다. 'Mañana(내일)'라서 미래형이 필요합니다.","x":["ha habido: 현재완료라 mañana와 맞지 않습니다 ✗","habrá: haber 미래 무인칭 단수 → 정답 ✓","había: 불완료과거라 mañana와 맞지 않습니다 ✗","habrán: 존재의 haber는 복수형을 쓰지 않습니다 ✗"]},{"id":"G143","q":"¿Es verdad que Sabrina y Marcelo ____ la semana que viene?","o":["se casaron","se casen","se están casando","se casan"],"a":3,"k":"현재형 (확정된 미래)","t":"사브리나와 마르셀로가 다음 주에 결혼한다는 게 사실이야?","e":"'Es verdad que(~는 사실이다)'는 사실을 확인하는 표현이라 뒤에 직설법을 씁니다. 또 이미 정해진 가까운 미래의 계획은 현재형으로 말할 수 있으므로 'se casan'이 맞습니다. 참고로 부정 'No es verdad que...' 뒤에서는 접속법을 씁니다.","x":["se casaron: 단순과거라 'la semana que viene(다음 주)'와 맞지 않습니다 ✗","se casen: 접속법으로 긍정 es verdad que 뒤에 쓰지 않습니다 ✗","se están casando: '지금 결혼식 중'이라는 진행 뜻이 되어 어색합니다 ✗","se casan: 직설법 현재, 확정된 미래 → 정답 ✓"]},{"id":"G144","q":"Hacía un día ____ frío que decidimos quedarnos en casa.","o":["tanto que","tanta","tanto","tan"],"a":3,"k":"tan ~ que (결과)","t":"날씨가 너무 추워서 우리는 집에 있기로 했다.","e":"'tan + 형용사 + que'는 '너무 ~해서 ~하다'라는 결과 표현입니다. 여기서 'frío'는 'un día(하루)'를 꾸미는 형용사(추운)이므로 tan을 씁니다. 빈칸 뒤에 이미 que가 있으므로 tan만 넣습니다. 명사 앞이라면 'Hacía tanto frío que...'처럼 tanto를 씁니다.","x":["tanto que: 뒤에 이미 que가 있어서 que가 중복됩니다 ✗","tanta: 여성형으로 frío와 맞지 않고 형용사 앞에 쓰지 않습니다 ✗","tanto: 명사 앞에 쓰며, 여기서 frío는 un día를 꾸미는 형용사입니다 ✗","tan: 형용사 앞 '너무' → 정답 ✓"]},{"id":"G145","q":"Te veo el lunes. ¡Que ____ un buen fin de semana!","o":["pases","pasas","pasarías","pasarás"],"a":0,"k":"Que + 접속법 (기원)","t":"월요일에 봐. 즐거운 주말 보내!","e":"'¡Que + 접속법!'은 '~하길 바라!'라는 기원·인사 표현입니다(앞에 Espero가 생략된 것). 상대(tú)가 주말을 보내는 것이므로 pasar의 접속법 현재 'pases'가 맞습니다. 예: ¡Que te mejores!(빨리 낫길 바라!), ¡Que aproveche!(맛있게 드세요!)","x":["pases: 접속법 현재 2인칭 → 정답 ✓","pasas: 직설법이라 기원 표현에 쓰지 않습니다 ✗","pasarías: 가능법이라 맞지 않습니다 ✗","pasarás: 직설법 미래라 기원 표현에 쓰지 않습니다 ✗"]},{"id":"G146","q":"Este libro no es mío, es ____ Alberto.","o":["desde","de","por","a"],"a":1,"k":"소유 de","t":"이 책은 내 것이 아니야, 알베르토 거야.","e":"'ser de + 사람'은 '~의 것이다'라는 소유 표현입니다. 'Es de Alberto'는 '알베르토의 것이다'입니다. 스페인어에는 영어의 's 같은 소유격이 없으므로 'el libro de Alberto(알베르토의 책)'처럼 항상 de를 씁니다.","x":["desde: '~부터'라서 소유를 나타내지 않습니다 ✗","de: 소유 '~의 것' → 정답 ✓","por: 소유를 나타내지 않습니다 ✗","a: 소유를 나타내지 않습니다 ✗"]},{"id":"G147","q":"No se preocupe, le avisaré ____ tenga los resultados de sus pruebas.","o":["en cuanto","nada más","cuanto","al"],"a":0,"k":"en cuanto + 접속법","t":"걱정 마세요, 검사 결과가 나오는 대로 바로 알려 드릴게요.","e":"'en cuanto'는 '~하자마자, ~하는 대로'라는 시간 접속사로, 미래의 일을 말할 때 뒤에 접속법(tenga)을 씁니다. tan pronto como와 같은 뜻입니다. 'Le avisaré'의 le는 usted(당신에게)를 가리키는 존칭입니다.","x":["en cuanto: '~하자마자' + 접속법 → 정답 ✓","nada más: '~하자마자'일 때 'nada más + 동사원형'으로 씁니다 ✗","cuanto: en 없이 혼자서는 '~하자마자'의 뜻이 되지 않습니다 ✗","al: 'al + 동사원형'으로 써야 하므로 tenga 앞에 쓸 수 없습니다 ✗"]},{"id":"G148","q":"Félix nos dijo que ____ cambiar de trabajo.","o":["estaba queriendo","quiera","estuvo queriendo","quería"],"a":3,"k":"간접화법 불완료과거","t":"펠릭스는 직장을 바꾸고 싶다고 우리에게 말했다.","e":"'nos dijo que(~라고 말했다)' 뒤에서 원래 말의 현재형 'Quiero cambiar de trabajo'는 불완료과거 'quería'로 바뀝니다. querer(원하다)는 마음 상태를 나타내는 동사라 보통 진행형으로 쓰지 않습니다. 'cambiar de + 명사'는 '~를 바꾸다'라는 표현입니다.","x":["estaba queriendo: querer는 보통 진행형으로 쓰지 않습니다 ✗","quiera: 접속법이라 사실 전달의 decir que 뒤에 맞지 않습니다 ✗","estuvo queriendo: 진행형이고 단순과거라 맞지 않습니다 ✗","quería: 불완료과거, 간접화법 → 정답 ✓"]},{"id":"G149","q":"No soporto que mi hermano ____ mi ropa sin pedirme permiso.","o":["se ponen","se pone","se pondría","se ponga"],"a":3,"k":"no soportar que + 접속법","t":"나는 형이 허락도 없이 내 옷을 입는 게 너무 싫어.","e":"'No soporto que(~하는 걸 참을 수 없다)'는 감정 표현이라 다른 주어의 que절에는 접속법을 씁니다. 주어 mi hermano는 3인칭 단수이므로 ponerse(입다)의 접속법 현재 'se ponga'가 맞습니다. 비슷한 표현: Odio que, Me molesta que.","x":["se ponen: 직설법 3인칭 복수라 주어와 법 모두 맞지 않습니다 ✗","se pone: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","se pondría: 가능법이라 맞지 않습니다 ✗","se ponga: 접속법 현재 3인칭 → 정답 ✓"]},{"id":"G150","q":"¿Con ____ países tiene frontera Colombia?","o":["cuál","los qué","que","qué"],"a":3,"k":"의문형용사 qué","t":"콜롬비아는 어떤 나라들과 국경을 맞대고 있나요?","e":"명사 바로 앞에서 '어떤 ~'이라고 물을 때는 'qué + 명사'를 씁니다(¿Qué países?). cuál은 표준적으로 명사 앞에 쓰지 않고, 의문사에는 악센트가 필요합니다. 'tener frontera con'은 '~와 국경을 접하다'입니다. 참고로 일부 중남미 구어에서는 'cuál + 명사'도 들립니다.","x":["cuál: 표준적으로 명사 바로 앞에 쓰지 않으며, 복수라면 cuáles여야 합니다 ✗","los qué: 의문사 앞에 관사를 붙이지 않습니다 ✗","que: 악센트가 없어 의문사가 되지 않습니다 ✗","qué: 명사 앞 의문형용사 '어떤' → 정답 ✓"]},{"id":"G151","q":"No me pongas otro café, ____ tomarme uno en mi casa.","o":["tengo que","acabo de","dejo de","vuelvo a"],"a":1,"k":"acabar de + 동사원형","t":"나한테 커피 한 잔 더 주지 마. 방금 집에서 한 잔 마시고 왔어.","e":"acabar de + 동사원형은 '방금 ~했다'라는 뜻으로, 아주 최근에 끝난 일을 말할 때 씁니다. 커피를 더 주지 말라는 이유로 '방금 집에서 한 잔 마셨다'가 가장 자연스럽습니다. 예: Acabo de comer. (방금 먹었어요.)","x":["tengo que: '~해야 한다'는 의무 표현이라, 커피를 거절하는 이유로 맞지 않습니다 ✗","acabo de: '방금 ~했다'는 뜻으로 문맥에 딱 맞습니다 ✓","dejo de: '~하는 것을 그만두다'라는 뜻이라 '집에서 한 잔 마시는 걸 그만둔다'가 되어 어색합니다 ✗","vuelvo a: '다시 ~하다'라는 뜻이라 거절의 이유가 되지 않습니다 ✗"]},{"id":"G152","q":"Cuando ____ la obra de teatro, los actores salieron a saludar al público.","o":["terminaba","terminó","estuvo terminando","ha terminado"],"a":1,"k":"단순과거 vs 불완료과거","t":"연극이 끝났을 때, 배우들이 관객에게 인사하러 나왔다.","e":"한 번에 끝난 사건(연극이 끝남)과 그 뒤에 이어진 사건(배우들이 나옴)을 순서대로 이야기할 때는 단순과거(pretérito indefinido, 완료된 과거 사건을 나타내는 시제)를 씁니다. 'terminó'는 '끝났다'는 완료된 순간을 나타냅니다. 뒤 문장의 salieron도 단순과거라서 시제가 잘 맞습니다.","x":["terminaba: 불완료과거로 '끝나 가고 있었다'는 배경 묘사라, 끝난 뒤에 인사했다는 순서와 맞지 않습니다 ✗","terminó: 단순과거로 '끝났다'는 완료된 사건 → 정답 ✓","estuvo terminando: '한동안 끝내는 중이었다'는 진행 의미라 어색합니다 ✗","ha terminado: 현재완료라 과거의 이야기(salieron)와 시제가 맞지 않습니다 ✗"]},{"id":"G153","q":"No pude entregar el informe completo ____ falta de tiempo.","o":["para","por","a","de"],"a":1,"k":"전치사 por (원인)","t":"시간이 부족해서 보고서를 완성해서 제출하지 못했다.","e":"por는 '~때문에, ~로 인해'라는 원인·이유를 나타냅니다. 'por falta de tiempo'는 '시간 부족 때문에'라는 아주 자주 쓰는 표현입니다. para는 목적(~하기 위해)이므로 여기서는 쓰지 않습니다. 예: Cerraron por obras. (공사 때문에 문을 닫았다.)","x":["para: 목적·목적지(~을 위해)를 나타내서 원인을 말할 수 없습니다 ✗","por: 원인·이유(~때문에)를 나타냄 → 정답 ✓","a: 방향·대상(~에게, ~로)을 나타내며 원인 표현으로 쓰지 않습니다 ✗","de: 'morirse de hambre'처럼 일부 감정·상태 원인에 쓰지만, 'falta de tiempo' 앞에서는 por를 씁니다 ✗"]},{"id":"G154","q":"No ____ miedo, mi perro no muerde.","o":["ten","tengas","tened","tienes"],"a":1,"k":"부정 명령 (tú)","t":"무서워하지 마, 우리 개는 안 물어.","e":"부정 명령(~하지 마)은 접속법 현재(바람·의심·감정 등을 나타내는 동사 형태)를 씁니다. tener의 tú 접속법 현재는 tengas이므로 'No tengas miedo'가 됩니다. 긍정 명령 ten과 형태가 다르니 주의하세요. 예: No tengas prisa. (서두르지 마.)","x":["ten: tú 긍정 명령(가져, ~해)이라 no와 함께 쓸 수 없습니다 ✗","tengas: tú 부정 명령(접속법 현재) → 정답 ✓","tened: vosotros 긍정 명령이라 no와 함께 쓸 수 없습니다 ✗","tienes: 직설법 현재(너는 가지고 있다)라 명령이 되지 않습니다 ✗"]},{"id":"G155","q":"¿A quién ____ gustaría venir con nosotros a Córdoba?","o":["lo","les","los","le"],"a":3,"k":"gustar 구문 대명사","t":"누가 우리랑 코르도바에 가고 싶어?","e":"gustar(~가 마음에 들다) 구문에서 '좋아하는 사람'은 간접목적격 대명사(~에게에 해당: me, te, le, nos, os, les)로 나타냅니다. '¿A quién?(누구에게?)'는 단수로 묻는 질문이라 3인칭 단수 le를 씁니다. 예: ¿A quién le gusta el fútbol? (누가 축구를 좋아해요?)","x":["lo: 직접목적격(그를/그것을)이라 gustar 구문에 쓰지 않습니다 ✗","les: 3인칭 복수(그들에게)이고, quién은 단수 취급이라 맞지 않습니다 ✗","los: 직접목적격 복수(그들을)라 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격(~에게) → 정답 ✓"]},{"id":"G156","q":"Siento llegar tan tarde. ____ estaba en un atasco.","o":["Porque","Que","Es que","Ya que"],"a":2,"k":"es que (변명·이유)","t":"이렇게 늦게 와서 미안해. 사실은 차가 막혀서 꼼짝 못 했어.","e":"'Es que...'는 회화에서 변명이나 이유를 말할 때 문장 맨 앞에 쓰는 표현으로, '그게 말이야, 사실은 ~해서'라는 느낌입니다. 사과한 뒤 새 문장으로 이유를 설명할 때 아주 자연스럽습니다. porque나 ya que는 보통 앞 문장과 이어서 쓰고, 이렇게 독립된 문장 맨 앞에서 변명할 때는 es que가 가장 적절합니다.","x":["Porque: '왜냐하면'이지만 마침표 뒤 독립 문장 맨 앞에서 변명할 때는 어색합니다 ✗","Que: 단독으로 이유를 나타내기엔 이 문맥에서 부자연스럽습니다 ✗","Es que: 회화에서 변명·이유를 꺼낼 때 쓰는 표현 → 정답 ✓","Ya que: '~이므로'라는 다소 격식 있는 이유 접속사로, 이렇게 따로 떨어진 문장을 시작하지 않습니다 ✗"]},{"id":"G157","q":"No es lógico que ____ tan nerviosa.","o":["te pongas","pongas","te pones","pones"],"a":0,"k":"감정·판단 + 접속법","t":"네가 그렇게 긴장하는 건 말이 안 돼.","e":"'No es lógico que...(~하는 건 논리적이지 않다)'처럼 판단·평가를 나타내는 표현 뒤의 que절에는 접속법을 씁니다. 또 '긴장하다'는 재귀동사 ponerse nervioso/a이므로 재귀대명사 te가 필요합니다. 그래서 'te pongas'가 정답입니다. 예: Es normal que te pongas triste. (네가 슬퍼지는 건 당연해.)","x":["te pongas: 재귀동사 ponerse의 접속법 현재 → 정답 ✓","pongas: 접속법은 맞지만 재귀대명사 te가 빠져 '긴장하다' 뜻이 안 됩니다 ✗","te pones: 직설법이라 판단 표현 뒤 que절에 쓸 수 없습니다 ✗","pones: 직설법인 데다 재귀대명사도 없습니다 ✗"]},{"id":"G158","q":"Nunca he tenido ____ admiradores como tú.","o":["tanto","tantas","tan","tantos"],"a":3,"k":"tanto의 성·수 일치","t":"너만큼 많은 팬을 가져 본 적이 없어.","e":"명사 앞의 tanto(그만큼 많은)는 뒤에 오는 명사와 성·수를 맞춥니다. admiradores(팬들)는 남성 복수이므로 tantos가 됩니다. 'tantos ... como ~'는 '~만큼 많은'이라는 동등 비교입니다. 예: Tengo tantos libros como tú. (나는 너만큼 책이 많다.)","x":["tanto: 남성 단수라 복수 명사 admiradores와 맞지 않습니다 ✗","tantas: 여성 복수라 남성 명사 admiradores와 맞지 않습니다 ✗","tan: 형용사·부사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗","tantos: 남성 복수로 admiradores와 일치 → 정답 ✓"]},{"id":"G159","q":"¿Por qué no vamos ____ otro sitio? El ambiente aquí no es muy bueno.","o":["a","en","de","ø"],"a":0,"k":"ir a + 장소","t":"우리 다른 데 가는 게 어때? 여기 분위기가 별로 좋지 않아.","e":"ir(가다) 같은 이동 동사는 목적지 앞에 전치사 a(~로, ~에)를 씁니다. 그래서 'ir a otro sitio(다른 곳으로 가다)'가 됩니다. en은 '~안에서'라는 위치를 나타내므로 이동 목적지에는 쓰지 않습니다. 예: Vamos a la playa. (해변에 가자.)","x":["a: 이동의 목적지(~로)를 나타냄 → 정답 ✓","en: 위치(~에서)를 나타내서 ir 뒤 목적지로 쓰지 않습니다 ✗","de: 출발점(~에서부터)을 나타내 '다른 곳에서 오다'의 뜻이 됩니다 ✗","ø: ir 뒤에 목적지가 올 때는 전치사 a가 꼭 필요합니다 ✗"]},{"id":"G160","q":"Lo ____ más me gusta de esta región es su belleza natural.","o":["de que","ø","cual","que"],"a":3,"k":"lo que (~하는 것)","t":"이 지역에서 내가 가장 좋아하는 것은 자연의 아름다움이다.","e":"'lo que'는 '~하는 것'이라는 뜻으로, 정해진 명사 없이 어떤 내용 전체를 가리킬 때 씁니다. 'Lo que más me gusta'는 '내가 가장 좋아하는 것'이라는 매우 자주 쓰는 표현입니다. 예: Lo que necesito es dormir. (내가 필요한 건 잠이야.)","x":["de que: 'lo de que'라는 형태는 이 문장에서 쓰지 않습니다 ✗","ø: lo만으로는 뒤의 절과 연결되지 않아 문장이 성립하지 않습니다 ✗","cual: 'lo cual'은 앞 문장 전체를 받는 관계사로, 문장 맨 앞 주어로 쓰지 않습니다 ✗","que: 'lo que'로 '~하는 것'이 됨 → 정답 ✓"]},{"id":"G161","q":"¿Sabes de alguien ____ pueda echarme una mano con la mudanza?","o":["quien","el que","qué","que"],"a":3,"k":"관계대명사 que","t":"이사하는 데 나를 좀 도와줄 수 있는 사람 알고 있니?","e":"앞의 명사(alguien, 누군가)를 꾸며 주는 관계절은 보통 관계대명사 que로 이어 줍니다. quien은 쉼표가 있는 설명절이나 전치사 뒤에서 주로 쓰고, 이렇게 바로 이어지는 제한적 관계절의 주어로는 쓰지 않습니다. 또 아직 누군지 모르는 사람이라 뒤에 접속법 pueda가 왔습니다.","x":["quien: 쉼표 없이 앞 명사를 바로 꾸미는 주어 자리에는 쓰지 않습니다 ✗","el que: 전치사 뒤 등에서 쓰며, 여기서는 어색합니다 ✗","qué: 악센트가 있는 의문사(무엇)라 관계사로 쓸 수 없습니다 ✗","que: 사람·사물 모두 받는 기본 관계대명사 → 정답 ✓"]},{"id":"G162","q":"No sé ____ vamos a ir este fin de semana.","o":["dónde","adonde","de dónde","donde"],"a":0,"k":"간접의문문 dónde","t":"이번 주말에 우리가 어디로 갈지 모르겠어.","e":"'No sé...(모르겠다)' 뒤에 의문 내용이 오면 간접의문문이 되고, 이때도 의문사에 악센트를 붙입니다. 그래서 '어디'를 묻는 dónde를 씁니다. 원래 이동 동사 ir와는 adónde(어디로)가 정확하지만, 실제로는 dónde도 널리 쓰입니다. 보기의 adonde는 악센트가 없어 관계부사가 되므로 틀립니다.","x":["dónde: 악센트 있는 의문사(어디)로 간접의문문에 맞음 → 정답 ✓","adonde: 악센트가 없는 관계부사(~하는 곳으로)라 간접의문문에 쓸 수 없습니다 ✗","de dónde: '어디에서부터'라는 출발점의 뜻이라 문맥에 맞지 않습니다 ✗","donde: 악센트 없는 관계부사(~하는 곳)라 의문의 뜻이 없습니다 ✗"]},{"id":"G163","q":"El abogado ____ contraté es muy bueno.","o":["al que","a que","al quien","cual"],"a":0,"k":"전치사+관계대명사","t":"내가 고용한 변호사는 아주 유능하다.","e":"contratar a alguien(누군가를 고용하다)처럼 사람이 직접목적어일 때는 전치사 a를 붙입니다. 관계절에서도 이 a가 살아 남아 'al que(a + el que)'가 됩니다. abogado가 남성 단수라 el que를 쓰고, a + el이 합쳐져 al que가 됩니다. 물론 그냥 'El abogado que contraté'도 가능합니다.","x":["al que: a + el que로 사람 목적어를 받는 관계사 → 정답 ✓","a que: 관사가 없어 관계사로 성립하지 않습니다 ✗","al quien: quien 앞에는 관사를 붙이지 않으므로 틀린 형태입니다 ✗","cual: 관사 없이 cual 단독으로는 관계사로 쓰지 않습니다 ✗"]},{"id":"G164","q":"A mis amigas ____ parece bien que no quiera casarme.","o":["las","les","le","se"],"a":1,"k":"parecer 구문 대명사","t":"내 친구들은 내가 결혼하고 싶어 하지 않는 걸 괜찮게 생각한다.","e":"parecer bien(~가 좋게 보이다, 괜찮다고 생각하다)은 gustar처럼 '생각하는 사람'을 간접목적격 대명사(~에게에 해당)로 씁니다. 'A mis amigas'는 3인칭 복수이므로 les가 맞습니다. 여성이라도 간접목적격은 성 구별이 없어서 las가 아니라 les를 씁니다.","x":["las: 직접목적격 여성 복수(그녀들을)라 parecer 구문에 쓰지 않습니다 ✗","les: 3인칭 복수 간접목적격(그들/그녀들에게) → 정답 ✓","le: 3인칭 단수라 복수인 amigas와 맞지 않습니다 ✗","se: 재귀대명사라 이 구문에 맞지 않습니다 ✗"]},{"id":"G165","q":"¿____ prefieres? ¿El bolso marrón o el negro?","o":["Cuánto","Quién","Cuándo","Cuál"],"a":3,"k":"의문사 cuál","t":"어느 걸 더 좋아해? 갈색 가방, 아니면 검은 가방?","e":"정해진 몇 가지 중에서 '어느 것'을 고르게 할 때는 cuál을 씁니다. 여기서는 갈색 가방과 검은 가방 둘 중 하나를 고르는 상황이라 cuál이 맞습니다. 예: ¿Cuál quieres, este o ese? (이거랑 그거 중 어느 걸 원해?)","x":["Cuánto: '얼마나(양·가격)'를 묻는 말이라 선택 질문에 맞지 않습니다 ✗","Quién: '누구'를 묻는 말이라 가방에 쓸 수 없습니다 ✗","Cuándo: '언제'를 묻는 말이라 문맥과 무관합니다 ✗","Cuál: 여러 개 중 '어느 것'을 묻는 의문사 → 정답 ✓"]},{"id":"G166","q":"Señoras, ¿____ importaría esperar un momento?","o":["le","se","os","les"],"a":3,"k":"importar 구문 (ustedes)","t":"여러분(부인들), 잠시만 기다려 주시겠어요?","e":"'¿Le/Les importaría...?(~해 주시겠어요?)'는 정중한 부탁 표현입니다. importar도 gustar처럼 간접목적격 대명사를 씁니다. 'Señoras(부인들)'에게 존칭으로 말하므로 ustedes에 해당하는 les를 씁니다. 중남미에서는 친한 사이에도 복수는 항상 ustedes(les)를 씁니다.","x":["le: usted 한 명에게 쓰는 형태라 복수 señoras와 맞지 않습니다 ✗","se: 재귀대명사라 importar 구문의 대상으로 쓰지 않습니다 ✗","os: vosotros(너희)에게 쓰는 친근한 형태라 존칭 señoras와 맞지 않습니다 ✗","les: ustedes(여러분)에 해당하는 간접목적격 → 정답 ✓"]},{"id":"G167","q":"Qué ganas de llegar a casa y acostarme. ¡Me muero ____ sueño!","o":["de","en","con","a"],"a":0,"k":"morirse de (관용)","t":"빨리 집에 가서 눕고 싶다. 졸려 죽겠어!","e":"'morirse de + 명사'는 '~해서 죽겠다'라는 과장 표현으로, 원인을 나타내는 전치사 de를 씁니다. 'Me muero de sueño(졸려 죽겠다)', 'Me muero de hambre(배고파 죽겠다)'처럼 자주 씁니다. 참고로 'morirse por + 동사원형'은 '~하고 싶어 죽겠다'라는 뜻입니다.","x":["de: 원인(~때문에)을 나타내 morirse de sueño가 됨 → 정답 ✓","en: 위치를 나타내는 전치사라 이 관용 표현에 쓰지 않습니다 ✗","con: '~와 함께'라는 뜻이라 맞지 않습니다 ✗","a: 방향을 나타내는 전치사라 맞지 않습니다 ✗"]},{"id":"G168","q":"No quiere saber ____ de su expareja.","o":["nada","ninguna","ninguno","algo"],"a":0,"k":"부정어 nada","t":"그는 전 애인에 대해서는 아무것도 알고 싶어 하지 않는다.","e":"스페인어는 동사 앞에 no가 있으면 뒤에도 부정어(nada, nadie, ninguno 등)를 쓰는 이중 부정이 정상입니다. '아무것도'는 nada입니다. 'No quiero saber nada de...'는 '~에 대해선 아무것도 알고 싶지 않다'는 자주 쓰는 표현입니다.","x":["nada: '아무것도'라는 부정 대명사 → 정답 ✓","ninguna: '어떤 ~도 (아닌)'이라는 여성형으로, 가리키는 명사가 없어 맞지 않습니다 ✗","ninguno: '아무도/어느 것도'라는 뜻으로 특정 무리를 가리킬 때 써서 어색합니다 ✗","algo: '무언가'라는 긍정어라 no와 함께 쓰지 않습니다 ✗"]},{"id":"G169","q":"Nunca he usado una máquina ____ escribir.","o":["sobre","a","por","de"],"a":3,"k":"명사 + de + 동사원형","t":"나는 타자기를 한 번도 써 본 적이 없다.","e":"'máquina de escribir'는 '타자기'라는 고정된 표현입니다. 이처럼 '명사 + de + 동사원형'은 용도를 나타내는 복합 명사를 만듭니다. 예: máquina de coser(재봉틀), goma de borrar(지우개).","x":["sobre: '~위에, ~에 관해'라는 뜻이라 맞지 않습니다 ✗","a: 'olla a presión'처럼 일부 표현에 쓰지만 타자기는 de를 씁니다 ✗","por: 원인·경로를 나타내 맞지 않습니다 ✗","de: máquina de escribir(타자기) → 정답 ✓"]},{"id":"G170","q":"¿De dónde ____ tus colegas?","o":["estén","sean","son","están"],"a":2,"k":"ser de (출신)","t":"네 동료들은 어디 출신이야?","e":"출신이나 국적은 'ser de + 장소'로 말합니다. 그래서 '¿De dónde son?(어디 출신이에요?)'가 됩니다. estar de는 출신이 아니라 일시적인 상태(estar de vacaciones 휴가 중이다)에 씁니다. 그냥 묻는 질문이므로 직설법을 씁니다.","x":["estén: estar의 접속법이라 일반 의문문에 맞지 않고, 출신에도 쓰지 않습니다 ✗","sean: ser의 접속법이라 일반 의문문에 쓰지 않습니다 ✗","son: ser 직설법 현재로 출신을 물음 → 정답 ✓","están: estar는 위치·상태를 나타내 출신을 묻는 데 쓰지 않습니다 ✗"]},{"id":"G171","q":"¿Cuándo ____ los resultados del test?","o":["sepas","supiste","estabas sabiendo","estuviste sabiendo"],"a":1,"k":"saber 단순과거","t":"시험 결과는 언제 알게 됐어?","e":"saber는 단순과거(supe, supiste...)로 쓰면 '알게 되었다'라는 순간의 의미가 됩니다. '언제' 결과를 알게 됐는지 과거의 한 시점을 묻는 질문이므로 supiste가 맞습니다. 예: Lo supe ayer. (어제 그걸 알게 됐어.)","x":["sepas: 접속법 현재라 일반 의문문에 쓰지 않습니다 ✗","supiste: 단순과거로 '알게 되었다'는 순간 → 정답 ✓","estabas sabiendo: saber는 진행형으로 거의 쓰지 않아 부자연스럽습니다 ✗","estuviste sabiendo: 마찬가지로 saber의 진행형은 어색합니다 ✗"]},{"id":"G172","q":"¿____ a ordenar esta habitación?","o":["Ayudarme","Me ayudas","Ayuda me","Ayúdame"],"a":1,"k":"부탁 표현 (현재형)","t":"이 방 정리하는 거 도와줄래?","e":"회화에서 '¿Me ayudas...?'처럼 현재형 의문문은 '~해 줄래?'라는 가벼운 부탁 표현입니다. 물음표가 있는 의문문이므로 명령형(Ayúdame)보다 현재형이 맞습니다. 목적격 대명사 me는 활용된 동사 앞에 둡니다.","x":["Ayudarme: 동사원형이라 주어가 없어 의문문으로 성립하지 않습니다 ✗","Me ayudas: 현재형 의문문으로 '도와줄래?' → 정답 ✓","Ayuda me: 명령형 뒤 대명사는 붙여 써야 해서(ayúdame) 틀린 형태입니다 ✗","Ayúdame: 명령형(도와줘)이라 의문문 형태와 맞지 않습니다 ✗"]},{"id":"G173","q":"Estoy harto ____ que me critiquen por todo.","o":["por","de","a","con"],"a":1,"k":"estar harto de","t":"모든 일로 사람들이 나를 비난하는 데 진절머리가 나.","e":"'estar harto/a de ~'는 '~에 질리다, 넌더리가 나다'라는 표현으로 항상 전치사 de와 함께 씁니다. 뒤에 절이 오면 'de que + 접속법'이 됩니다. 예: Estoy harta de esperar. (기다리는 데 지쳤어.)","x":["por: harto와 함께 쓰지 않습니다 ✗","de: estar harto de(~에 질리다) → 정답 ✓","a: harto 뒤에 쓰지 않습니다 ✗","con: 'harto con'은 표준 표현이 아닙니다 ✗"]},{"id":"G174","q":"¿Qué ____ ahora mismo si te tocara la lotería?","o":["hicieras","harías","haces","harás"],"a":1,"k":"가정문 (조건법)","t":"만약 복권에 당첨된다면 지금 당장 뭘 할 거야?","e":"현재 사실과 다르거나 가능성이 낮은 가정은 'si + 접속법 과거, 조건법(~할 텐데)'으로 말합니다. si절에 tocara(접속법 과거)가 있으므로 주절에는 조건법 harías가 와야 합니다. 예: Si tuviera tiempo, viajaría. (시간이 있다면 여행할 텐데.)","x":["hicieras: 접속법 과거는 si절에 쓰는 형태라 주절에 쓰지 않습니다 ✗","harías: 조건법(~할 텐데)으로 가정문 주절에 맞음 → 정답 ✓","haces: 직설법 현재라 접속법 과거 가정과 어울리지 않습니다 ✗","harás: 미래형은 'si + 현재' 조건문에 쓰며 tocara와 맞지 않습니다 ✗"]},{"id":"G175","q":"¿A qué ____ usted?","o":["dedicas","se dedica","te dedicas","dedica"],"a":1,"k":"dedicarse (usted)","t":"무슨 일을 하세요?","e":"'¿A qué se dedica?'는 직업을 묻는 표현으로, 재귀동사 dedicarse(~에 종사하다)를 씁니다. usted(당신)는 3인칭 단수 동사를 쓰고 재귀대명사도 se를 씁니다. 친구에게는 '¿A qué te dedicas?'라고 묻습니다.","x":["dedicas: tú 형태이고 재귀대명사도 없어 usted와 맞지 않습니다 ✗","se dedica: usted에 맞는 3인칭 재귀 형태 → 정답 ✓","te dedicas: tú(너)에게 쓰는 형태라 usted와 맞지 않습니다 ✗","dedica: 재귀대명사 se가 빠져 '종사하다' 뜻이 되지 않습니다 ✗"]},{"id":"G176","q":"Estos zapatos me ____, no son de mi número.","o":["molesto","molesta","molestan","molestáis"],"a":2,"k":"molestar 구문","t":"이 신발 때문에 발이 불편해. 내 사이즈가 아니야.","e":"molestar(불편하게 하다, 성가시게 하다)는 gustar처럼 '불편함을 주는 것'이 주어가 되고, 불편한 사람은 간접목적격 대명사(me)로 씁니다. 주어가 estos zapatos(이 신발들, 복수)이므로 동사는 3인칭 복수 molestan이 됩니다.","x":["molesto: 1인칭 단수(내가 귀찮게 하다)라 주어 zapatos와 맞지 않습니다 ✗","molesta: 3인칭 단수라 복수 주어 zapatos와 맞지 않습니다 ✗","molestan: 3인칭 복수로 zapatos와 일치 → 정답 ✓","molestáis: vosotros 형태라 주어와 맞지 않습니다 ✗"]},{"id":"G177","q":"Elsa no suele ____ antes de las 8.","o":["levantar","levantarse","se levantar","se levanta"],"a":1,"k":"soler + 재귀동사원형","t":"엘사는 보통 8시 전에는 일어나지 않는다.","e":"soler(보통 ~하다) 뒤에는 동사원형이 옵니다. '일어나다'는 재귀동사 levantarse이므로 동사원형에 se를 붙인 levantarse를 씁니다. 재귀대명사는 'se suele levantar'처럼 soler 앞에 두거나 'suele levantarse'처럼 원형 뒤에 붙입니다.","x":["levantar: '들어 올리다'라는 타동사라 재귀대명사 없이 '일어나다'가 되지 않습니다 ✗","levantarse: 재귀동사원형으로 soler 뒤에 맞음 → 정답 ✓","se levantar: 재귀대명사를 동사원형 앞에 따로 둘 수 없습니다 ✗","se levanta: 활용형이라 soler 뒤에 올 수 없습니다 ✗"]},{"id":"G178","q":"¿Por qué no te gustó ____ final de la película?","o":["ø","un","lo","el"],"a":3,"k":"정관사 el","t":"영화 결말이 왜 마음에 안 들었어?","e":"gustar 구문의 주어로 특정한 것(이 영화의 결말)을 가리킬 때는 정관사를 씁니다. final(결말)은 남성 명사이므로 el final이 됩니다. 'el final de la película'는 '그 영화의 결말'이라는 정해진 대상입니다.","x":["ø: 특정한 결말을 가리키는 주어라 관사가 필요합니다 ✗","un: 부정관사(어떤 하나의)라 '그 영화의 결말'이라는 특정 대상과 맞지 않습니다 ✗","lo: 중성 관사로 명사 앞에 쓰지 않습니다 ✗","el: 남성 단수 정관사로 특정 결말을 가리킴 → 정답 ✓"]},{"id":"G179","q":"¿Qué te gustaría ____ de mayor?","o":["que seas","serás","que serías","ser"],"a":3,"k":"gustar + 동사원형","t":"커서 뭐가 되고 싶어?","e":"'gustaría + 동사원형'은 '~하고 싶다'는 뜻입니다. 주어가 같을 때(내가 ~하고 싶다)는 que절이 아니라 동사원형을 씁니다. 'de mayor'는 '어른이 되면, 커서'라는 표현입니다. 예: Me gustaría ser médico. (의사가 되고 싶어요.)","x":["que seas: 다른 사람에게 바랄 때 쓰는 형태로, 같은 사람이 원하는 이 문장에는 맞지 않습니다 ✗","serás: 미래형 활용이라 gustaría 뒤에 바로 올 수 없습니다 ✗","que serías: 조건법은 que절에 이렇게 쓰지 않습니다 ✗","ser: 동사원형으로 gustaría 뒤에 맞음 → 정답 ✓"]},{"id":"G180","q":"Oiga, ____ de la sala. Aquí no puede estar.","o":["salga","sal","sale","saldes"],"a":0,"k":"usted 명령형","t":"저기요, 방에서 나가세요. 여기 계시면 안 됩니다.","e":"'Oiga(저기요)'와 'puede(당신은 ~할 수 있다)'로 보아 상대를 usted로 부르고 있습니다. usted에 대한 긍정 명령은 접속법 현재 형태를 쓰므로 salir는 salga가 됩니다. tú에게는 sal을 씁니다.","x":["salga: usted 명령형(나가세요) → 정답 ✓","sal: tú 명령형(나가)이라 usted와 맞지 않습니다 ✗","sale: 직설법 현재(그/당신은 나간다)라 명령이 아닙니다 ✗","saldes: 존재하지 않는 형태입니다 ✗"]},{"id":"G181","q":"Ayer ____ viendo la tele hasta las tantas.","o":["estuve","había estado","estaba","he estado"],"a":0,"k":"단순과거 진행형","t":"어제 밤늦게까지 TV를 봤다.","e":"'ayer(어제)'처럼 끝난 시간을 나타내는 말과 함께, 일정 기간 계속된 행동을 말할 때는 'estar 단순과거 + 현재분사'를 씁니다. 'hasta las tantas'는 '아주 늦은 시간까지'라는 관용 표현입니다. 행동이 그 기간 동안 이어지고 끝났음을 나타내므로 estuve가 맞습니다.","x":["estuve: 단순과거로 끝난 기간의 진행 행동 → 정답 ✓","había estado: 과거완료로 다른 과거보다 앞선 일을 말할 때 쓰므로 맞지 않습니다 ✗","estaba: 불완료과거는 배경 묘사라 '언제까지 했다'는 완료된 기간과 어울리지 않습니다 ✗","he estado: 현재완료는 ayer와 함께 쓰지 않습니다 ✗"]},{"id":"G182","q":"¿Qué sueles hacer en tu día ____ día?","o":["en","por","a","de"],"a":2,"k":"관용 표현 día a día","t":"평소 일상에서 보통 뭐 해?","e":"'el día a día'는 '일상, 하루하루의 생활'이라는 표현으로 전치사 a를 씁니다. 'en tu día a día'는 '네 일상에서'라는 뜻입니다. 비슷한 구조로 'poco a poco(조금씩)', 'paso a paso(한 걸음씩)'가 있습니다.","x":["en: 'día en día'라는 표현은 없습니다 ✗","por: 'día por día'는 일상이라는 뜻의 관용 표현이 아닙니다 ✗","a: el día a día(일상) → 정답 ✓","de: 'de día'는 '낮에'라는 뜻으로 이 구조에 맞지 않습니다 ✗"]},{"id":"G183","q":"Deben responder ____ al menos siete de las diez preguntas.","o":["correctamente","correctos","correcta","correcto"],"a":0,"k":"부사 -mente","t":"10문제 중 적어도 7문제는 정확하게 답해야 합니다.","e":"동사 responder(답하다)를 꾸미는 말이므로 부사가 필요합니다. 형용사 여성형에 -mente를 붙이면 부사가 됩니다: correcta → correctamente(정확하게). 형용사(correcto, correcta)는 명사를 꾸밉니다.","x":["correctamente: 동사를 꾸미는 부사(정확하게) → 정답 ✓","correctos: 남성 복수 형용사라 동사를 꾸밀 수 없습니다 ✗","correcta: 여성 단수 형용사라 동사를 꾸밀 수 없습니다 ✗","correcto: 남성 단수 형용사라 동사를 꾸밀 수 없습니다 ✗"]},{"id":"G184","q":"Mi hijo, cuando vemos la tele, siempre se sienta ____ su papá y yo.","o":["delante","encima","detrás","entre"],"a":3,"k":"위치 표현 entre","t":"우리 아들은 TV를 볼 때 항상 아빠와 나 사이에 앉는다.","e":"entre는 '~사이에'라는 뜻으로, 두 사람이나 사물 사이의 위치를 말합니다. 'entre su papá y yo(아빠와 나 사이에)'처럼 'entre A y B'로 씁니다. 참고로 entre 뒤에는 yo, tú를 그대로 씁니다(mí, ti가 아님).","x":["delante: '앞에'인데 delante de가 필요하고, 두 사람을 연결하는 y와 맞지 않습니다 ✗","encima: '위에'인데 encima de가 필요하고 문맥에도 맞지 않습니다 ✗","detrás: '뒤에'인데 detrás de가 필요하고 'A y B' 구조와 맞지 않습니다 ✗","entre: 'A와 B 사이에' → 정답 ✓"]},{"id":"G185","q":"¿Todavía no ____ la redacción?","o":["terminabais","terminéis","terminasteis","habéis terminado"],"a":3,"k":"현재완료 + todavía","t":"너희 아직 작문 다 안 끝냈어?","e":"'todavía no(아직 ~안 했다)'는 지금까지의 상황을 묻기 때문에 스페인에서는 현재완료(haber + 과거분사)를 씁니다. vosotros(너희)의 현재완료는 habéis terminado입니다. 중남미에서는 '¿Todavía no terminaron?'처럼 단순과거를 쓰는 경우가 많습니다.","x":["terminabais: 불완료과거로 과거의 습관·배경이라 맞지 않습니다 ✗","terminéis: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","terminasteis: 단순과거로 스페인에서는 todavía no와 잘 쓰지 않습니다 ✗","habéis terminado: 현재완료로 지금까지의 상태를 물음 → 정답 ✓"]},{"id":"G186","q":"En el coche ____ alquilamos cabían cinco personas.","o":["que lo","el cual","el que","que"],"a":3,"k":"관계대명사 que","t":"우리가 빌린 차에는 다섯 명이 탈 수 있었다.","e":"앞의 명사(coche)를 꾸미는 관계절에 전치사가 없을 때는 기본적으로 que를 씁니다. 'el cual'이나 'el que'는 전치사 뒤나 쉼표가 있는 설명절에서 씁니다. 또 관계절 안에서 목적어를 다시 lo로 쓰면 중복이 되어 틀립니다.","x":["que lo: 관계사가 이미 목적어 역할을 하므로 lo를 또 쓰면 틀립니다 ✗","el cual: 전치사 없는 제한적 관계절에서는 쓰지 않습니다 ✗","el que: 전치사 없이 앞 명사를 바로 꾸밀 때는 쓰지 않습니다 ✗","que: 기본 관계대명사 → 정답 ✓"]},{"id":"G187","q":"Se nota que tus suegros te ____ mucho.","o":["quieran","quieres","están queriendo","quieren"],"a":3,"k":"se nota que + 직설법","t":"시부모님(장인·장모님)이 너를 많이 아끼시는 게 보여.","e":"'Se nota que...(~인 게 보인다, 티가 난다)'는 사실을 확인하는 표현이라 뒤에 직설법을 씁니다. 주어가 tus suegros(3인칭 복수)이고 목적어가 te(너를)이므로 quieren이 맞습니다. querer a alguien은 '누군가를 사랑하다, 아끼다'라는 뜻입니다.","x":["quieran: 접속법이라 사실을 나타내는 se nota que 뒤에 쓰지 않습니다 ✗","quieres: tú 형태라 주어 suegros와 맞지 않습니다 ✗","están queriendo: querer는 감정 동사라 진행형으로 쓰지 않습니다 ✗","quieren: 직설법 3인칭 복수 → 정답 ✓"]},{"id":"G188","q":"Espero que tu abuela ____ mejor de salud.","o":["esté","está","es","sea"],"a":0,"k":"esperar que + 접속법","t":"너희 할머니 건강이 좋아지셨으면 좋겠다.","e":"'Espero que...(~하기를 바란다)'처럼 바람을 나타내는 표현 뒤에는 접속법을 씁니다. 또 건강 상태는 일시적인 상태이므로 ser가 아니라 estar를 씁니다. 그래서 estar의 접속법 현재 esté가 정답입니다. 예: Espero que estés bien. (잘 지내길 바라.)","x":["esté: estar 접속법 현재로 바람 + 상태 → 정답 ✓","está: 직설법이라 esperar que 뒤에 쓰지 않습니다 ✗","es: ser 직설법이라 상태와 바람 모두에 맞지 않습니다 ✗","sea: ser는 일시적인 건강 상태에 쓰지 않습니다 ✗"]},{"id":"G189","q":"No me importa ____ lo que digan de mí.","o":["algo","nada","alguno","nadie"],"a":1,"k":"부정어 nada","t":"사람들이 나에 대해 뭐라고 하든 전혀 신경 안 써.","e":"'No me importa nada'는 '전혀 상관없다'라는 뜻으로, no와 함께 부정어 nada를 써서 강조합니다. 스페인어는 이중 부정이 정상 문법입니다. 여기서 nada는 '전혀, 조금도'라는 부사적 의미입니다.","x":["algo: '조금, 무언가'라는 긍정어라 no와 함께 쓰지 않습니다 ✗","nada: '전혀'라는 부정어로 no와 함께 씀 → 정답 ✓","alguno: '어떤 것'이라는 긍정 한정사라 맞지 않습니다 ✗","nadie: '아무도'라는 사람을 가리키는 말이라 맞지 않습니다 ✗"]},{"id":"G190","q":"¿____ sabe dónde está Fernando?","o":["Alguien","Algo","Algún","Algunos"],"a":0,"k":"부정대명사 alguien","t":"페르난도가 어디 있는지 아는 사람 있어?","e":"alguien은 '누군가'라는 뜻으로, 사람을 가리키는 부정대명사입니다. 동사 sabe(알다)의 주어가 될 사람이 필요하므로 alguien이 맞습니다. algo는 '무언가(사물)'를 가리킵니다.","x":["Alguien: '누군가'로 사람을 가리키는 주어 → 정답 ✓","Algo: '무언가'라는 사물이라 '아는' 주어가 될 수 없습니다 ✗","Algún: 남성 명사 앞에만 오는 형용사라 혼자 쓸 수 없습니다 ✗","Algunos: 복수인데 동사 sabe가 단수라 맞지 않습니다 ✗"]},{"id":"G191","q":"Debemos ____ pensar también en los demás, no solo en nosotros mismos.","o":["a","de","por","ø"],"a":3,"k":"deber + 동사원형","t":"우리는 우리 자신만이 아니라 다른 사람들도 생각해야 한다.","e":"deber(~해야 한다) 뒤에는 전치사 없이 바로 동사원형이 옵니다. 'deber de + 동사원형'은 '~임에 틀림없다'라는 추측의 뜻이라 의무와 다릅니다. 예: Debes descansar. (너는 쉬어야 해.)","x":["a: deber 뒤에 a를 쓰지 않습니다 ✗","de: deber de는 추측(~일 것이다)의 의미라 의무 문장에 맞지 않습니다 ✗","por: deber 뒤에 쓰지 않습니다 ✗","ø: deber + 동사원형 바로 연결 → 정답 ✓"]},{"id":"G192","q":"¿Cuántos idiomas ____ en vuestro colegio?","o":["enseñarse","se enseñar","se enseña","se enseñan"],"a":3,"k":"수동의 se","t":"너희 학교에서는 몇 개 언어를 가르쳐?","e":"'se + 3인칭 동사'는 행위자를 밝히지 않는 수동 표현입니다(수동의 se, ~되다). 이때 동사는 뒤의 명사와 수를 맞춥니다. idiomas(언어들)가 복수이므로 se enseñan이 맞습니다. 예: Se venden pisos. (아파트 팝니다.)","x":["enseñarse: 동사원형이라 문장의 동사가 될 수 없습니다 ✗","se enseñar: 활용되지 않은 형태라 틀립니다 ✗","se enseña: 단수라 복수 명사 idiomas와 맞지 않습니다 ✗","se enseñan: 복수 idiomas와 일치하는 수동의 se → 정답 ✓"]},{"id":"G193","q":"Ismael habla exactamente igual ____ su padre.","o":["que","de","de que","como"],"a":0,"k":"igual que (비교)","t":"이스마엘은 자기 아빠와 똑같이 말한다.","e":"'igual que ~'는 '~와 똑같이'라는 동등 비교 표현입니다. 'exactamente igual que su padre'는 '아빠와 정확히 똑같이'라는 뜻입니다. 중남미 일부 지역에서는 'igual a'나 'igual como'도 들리지만, 표준적인 형태는 igual que입니다.","x":["que: igual que(~와 똑같이) → 정답 ✓","de: 'igual de + 형용사'는 '똑같이 ~한'이란 구조로 여기에 맞지 않습니다 ✗","de que: 절을 이끄는 형태라 명사 앞에 쓸 수 없습니다 ✗","como: 'igual como'는 비표준적이라 정답이 아닙니다 ✗"]},{"id":"G194","q":"La chica ____ jersey azul se llama Mónica.","o":["por el","del","en el","al"],"a":1,"k":"de (특징·옷차림)","t":"파란 스웨터를 입은 여자아이 이름은 모니카야.","e":"사람의 옷차림이나 특징을 말할 때 'de + 정관사 + 명사'를 써서 '~을 입은/가진'을 나타냅니다. de + el = del이므로 'la chica del jersey azul(파란 스웨터를 입은 여자아이)'이 됩니다. jersey는 스페인에서 쓰는 말이고, 중남미에서는 suéter를 많이 씁니다.","x":["por el: 경로·원인을 나타내 옷차림 표현에 쓰지 않습니다 ✗","del: de + el로 '~을 입은' 특징 표현 → 정답 ✓","en el: '~안에'라는 위치라 맞지 않습니다 ✗","al: a + el로 방향을 나타내 맞지 않습니다 ✗"]},{"id":"G195","q":"No vi a Carolina porque se fue antes de que yo ____.","o":["llegara","llegué","llegue","llegaba"],"a":0,"k":"antes de que+접속법 과거","t":"카롤리나는 내가 도착하기 전에 가 버려서 그녀를 못 봤다.","e":"'antes de que(~하기 전에)'는 항상 접속법을 씁니다. 주절이 과거(se fue)이므로 접속법 과거 llegara를 씁니다. 현재 시점이라면 'antes de que llegue'가 됩니다.","x":["llegara: 접속법 과거로 과거 문장의 antes de que 뒤에 맞음 → 정답 ✓","llegué: 직설법이라 antes de que 뒤에 쓸 수 없습니다 ✗","llegue: 접속법 현재라 과거 주절(se fue)과 시제가 맞지 않습니다 ✗","llegaba: 직설법 불완료과거라 antes de que 뒤에 쓸 수 없습니다 ✗"]},{"id":"G196","q":"Le llamo para que me ____ sobre un asunto.","o":["informas","informe","informa","informes"],"a":1,"k":"para que + 접속법","t":"어떤 일에 대해 알려 주십사 전화드렸습니다.","e":"'para que(~하도록)'는 목적을 나타내며 항상 접속법을 씁니다. 'Le llamo(당신께 전화드립니다)'에서 상대가 usted이므로 3인칭 단수 접속법 informe가 맞습니다.","x":["informas: 직설법 tú 형태라 맞지 않습니다 ✗","informe: usted에 맞는 접속법 현재 → 정답 ✓","informa: 직설법이라 para que 뒤에 쓸 수 없습니다 ✗","informes: 접속법이지만 tú 형태라 usted(le)와 맞지 않습니다 ✗"]},{"id":"G197","q":"Pienso que Miguel ____ un hombre educado y muy amable.","o":["esté","es","está","sea"],"a":1,"k":"pensar que + 직설법","t":"내 생각에 미겔은 예의 바르고 아주 친절한 사람이야.","e":"'Pienso que / Creo que(~라고 생각한다)'처럼 긍정문으로 의견을 말할 때는 뒤에 직설법을 씁니다. 부정문(No pienso que...)일 때 접속법이 됩니다. 또 '~한 사람이다'처럼 성격·정체를 말할 때는 ser를 쓰므로 es가 맞습니다.","x":["esté: 접속법이고 estar라 이중으로 맞지 않습니다 ✗","es: ser 직설법으로 성격·정체 표현 → 정답 ✓","está: estar는 'un hombre(한 남자)' 같은 명사와 함께 쓰지 않습니다 ✗","sea: 긍정 pensar que 뒤에는 접속법을 쓰지 않습니다 ✗"]},{"id":"G198","q":"Creo que el color azul ____ muy bien.","o":["te sienta","te sientas","te sientes","te siente"],"a":0,"k":"sentar bien (어울리다)","t":"내 생각엔 파란색이 너한테 정말 잘 어울려.","e":"'sentarle bien a alguien'은 '(옷·색 등이) ~에게 잘 어울리다'라는 뜻입니다. gustar처럼 사람은 간접목적격(te)으로, 어울리는 것(el color azul)이 주어가 됩니다. 주어가 3인칭 단수이고 creo que 뒤라 직설법 sienta가 맞습니다.","x":["te sienta: sentar의 3인칭 단수 직설법 → 정답 ✓","te sientas: sentarse(앉다)의 tú 형태라 뜻이 달라집니다 ✗","te sientes: sentirse(느끼다)의 tú 형태라 뜻이 맞지 않습니다 ✗","te siente: 접속법이라 긍정 creo que 뒤에 쓰지 않습니다 ✗"]},{"id":"G199","q":"Perdone, ¿me ____ qué hora es?","o":["dices","dicen","dice","diga"],"a":2,"k":"usted 의문 부탁","t":"실례합니다, 지금 몇 시인지 알려 주시겠어요?","e":"'Perdone(실례합니다)'은 usted에게 쓰는 표현이므로 동사도 usted 형태(3인칭 단수)로 맞춥니다. '¿Me dice...?'는 현재형 의문문으로 '~를 말해 주시겠어요?'라는 정중한 부탁입니다. tú라면 'Perdona, ¿me dices...?'가 됩니다.","x":["dices: tú 형태라 Perdone(usted)과 맞지 않습니다 ✗","dicen: ustedes(여러분) 형태라 한 사람에게 말하는 상황과 맞지 않습니다 ✗","dice: usted 형태 현재형 의문 부탁 → 정답 ✓","diga: 접속법·명령형이라 의문문 부탁에 맞지 않습니다 ✗"]},{"id":"G200","q":"Me gustaría hablar con ____ gerente de la empresa.","o":["ø","le","al","el"],"a":3,"k":"정관사 el","t":"회사 지배인(매니저)과 이야기하고 싶습니다.","e":"'hablar con(~와 이야기하다)' 뒤에 특정한 사람(그 회사의 매니저)이 오므로 정관사가 필요합니다. gerente는 남성·여성이 같은 형태이고, 여기서는 el gerente(남성)를 씁니다. con 뒤에 전치사 a가 또 올 수는 없으므로 al은 틀립니다.","x":["ø: 특정 직책의 사람을 가리켜 관사가 필요합니다 ✗","le: 대명사라 명사 앞에 올 수 없습니다 ✗","al: a + el인데 con 뒤에 a를 또 쓸 수 없습니다 ✗","el: 특정 인물을 가리키는 정관사 → 정답 ✓"]},{"id":"G201","q":"Irene es tan alta ____ su madre.","o":["como","de","que","igual de"],"a":0,"k":"tan ... como (동등비교)","t":"이레네는 엄마만큼 키가 크다.","e":"'tan + 형용사/부사 + como ~'는 '~만큼 ...하다'라는 동등 비교입니다. tan과 짝을 이루는 말은 항상 como입니다. 예: Soy tan alto como mi hermano. (나는 형만큼 키가 크다.)","x":["como: tan과 짝을 이루는 동등 비교 → 정답 ✓","de: tan 뒤에 짝으로 쓰지 않습니다 ✗","que: 'más/menos ... que'에서 쓰며 tan과는 쓰지 않습니다 ✗","igual de: 'igual de alta que'처럼 쓰는 다른 구조라 tan과 함께 쓸 수 없습니다 ✗"]},{"id":"G202","q":"____ problemas se resuelven fácilmente.","o":["Algunas","Unas","Algunos","Unos"],"a":2,"k":"algunos (성·수 일치)","t":"어떤 문제들은 쉽게 해결된다.","e":"algunos/algunas는 '몇몇의, 어떤'이라는 뜻으로 뒤의 명사와 성·수를 맞춥니다. problema는 -a로 끝나지만 남성 명사(el problema)이므로 남성 복수 algunos가 맞습니다. 그리스어에서 온 -ma 명사(el tema, el sistema, el idioma)는 대부분 남성입니다.","x":["Algunas: 여성형이라 남성 명사 problemas와 맞지 않습니다 ✗","Unas: 여성형이라 맞지 않습니다 ✗","Algunos: 남성 복수로 '몇몇 문제들' → 정답 ✓","Unos: 남성 복수지만 '몇몇 문제는 (다른 건 몰라도)'라는 일부를 가리키는 의미로는 algunos가 더 자연스럽습니다 ✗"]},{"id":"G203","q":"Si conoces a ____ que pueda ayudarme con el inglés, dímelo, por favor.","o":["nadie","algún","algunos","alguien"],"a":3,"k":"부정대명사 alguien","t":"내 영어 공부를 도와줄 수 있는 사람을 알면 나한테 말해 줘.","e":"alguien은 '누군가'라는 사람을 가리키는 대명사입니다. 긍정문(Si conoces...)이므로 nadie(아무도)가 아니라 alguien을 씁니다. 사람이 직접목적어라 앞에 전치사 a가 붙습니다(conocer a alguien).","x":["nadie: '아무도'라는 부정어라 긍정 조건문과 맞지 않습니다 ✗","algún: 명사 앞에만 쓰는 형용사라 혼자 쓸 수 없습니다 ✗","algunos: 복수인데 뒤의 동사 pueda가 단수라 맞지 않습니다 ✗","alguien: '누군가'라는 사람 대명사 → 정답 ✓"]},{"id":"G204","q":"No sé ____ decirte. Tú sabes mejor que nadie lo que debes hacer.","o":["qué","que","cuál","cual"],"a":0,"k":"간접의문문 qué","t":"너한테 뭐라고 말해야 할지 모르겠어. 네가 해야 할 일은 누구보다 네가 잘 알잖아.","e":"'No sé + 의문사 + 동사원형'은 '무엇을/어떻게 ~해야 할지 모르겠다'라는 간접의문문입니다. '무엇'을 뜻하는 의문사이므로 악센트가 있는 qué를 씁니다. 악센트 없는 que는 접속사·관계사입니다. 예: No sé qué hacer. (뭘 해야 할지 모르겠어.)","x":["qué: 악센트 있는 의문사(무엇) → 정답 ✓","que: 악센트가 없는 접속사라 '무엇'의 뜻이 없습니다 ✗","cuál: '어느 것'이라 정해진 선택지가 없는 이 문맥에 맞지 않습니다 ✗","cual: 악센트 없는 관계사라 의문 의미가 없습니다 ✗"]},{"id":"G205","q":"¿Puedes pasarme ese ____ libro, por favor?","o":["el","ø","un","lo"],"a":1,"k":"지시사 + 명사 (관사 없음)","t":"그 책 좀 건네줄래?","e":"지시형용사(este, ese, aquel)는 그 자체로 명사를 한정하므로 관사를 함께 쓰지 않습니다. 그래서 'ese libro(그 책)'로 충분하고, 'ese el libro'나 'ese un libro'는 틀립니다.","x":["el: 지시사와 정관사를 겹쳐 쓸 수 없습니다 ✗","ø: 지시사 ese만으로 명사를 한정 → 정답 ✓","un: 지시사와 부정관사를 함께 쓸 수 없습니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗"]},{"id":"G206","q":"____ salir de clase, me fui al gimnasio.","o":["Cuando","Al","En cuanto","Después"],"a":1,"k":"al + 동사원형","t":"수업이 끝나고 나와서 나는 헬스장에 갔다.","e":"'al + 동사원형'은 '~할 때, ~하자마자'라는 뜻으로 동시성이나 바로 이어진 동작을 나타냅니다. 뒤에 바로 동사원형(salir)이 오므로 al이 맞습니다. cuando, en cuanto는 뒤에 활용된 동사가 와야 하고, después는 de가 필요합니다(después de salir).","x":["Cuando: 뒤에 활용 동사가 와야 해서(cuando salí) 동사원형과 쓸 수 없습니다 ✗","Al: al + 동사원형(~할 때) → 정답 ✓","En cuanto: '~하자마자'지만 활용 동사가 필요합니다 ✗","Después: 'después de salir'처럼 de가 있어야 합니다 ✗"]},{"id":"G207","q":"Cierra bien la ventana ____ no entre el frío.","o":["porque","a que","para que","ya que"],"a":2,"k":"para que + 접속법","t":"추위가 들어오지 않도록 창문을 꼭 닫아.","e":"'para que(~하도록, ~하지 않도록)'는 목적을 나타내고 뒤에 접속법(entre)이 옵니다. 문장에서 entre가 접속법이므로 목적을 나타내는 para que가 맞습니다. porque나 ya que는 이유를 나타내며 보통 직설법과 씁니다.","x":["porque: 이유(왜냐하면)라 뒤에 직설법이 오며 목적의 뜻이 아닙니다 ✗","a que: 일부 동사 뒤(ayudar a que 등)에 쓰는 형태라 여기서는 맞지 않습니다 ✗","para que: 목적(~하도록) + 접속법 → 정답 ✓","ya que: '~이므로'라는 이유 표현이라 맞지 않습니다 ✗"]},{"id":"G208","q":"¿Les diste las gracias a tus amigos ____ los regalos que te han hecho?","o":["de","ante","para","por"],"a":3,"k":"dar las gracias por","t":"친구들이 준 선물에 대해 고맙다고 인사했니?","e":"'dar las gracias por ~'는 '~에 대해 감사하다'라는 표현으로, 감사의 이유를 por로 나타냅니다. 'Gracias por todo(모든 것에 감사해요)'처럼 por는 원인·이유를 나타냅니다.","x":["de: 감사의 이유에는 쓰지 않습니다 ✗","ante: '~앞에서'라는 뜻이라 맞지 않습니다 ✗","para: 목적(~을 위해)이라 감사의 이유에 쓰지 않습니다 ✗","por: 감사의 이유(~에 대해) → 정답 ✓"]},{"id":"G209","q":"Voy a ir al supermercado. Estaré ____ vuelta en veinte minutos.","o":["para","a","de","ø"],"a":2,"k":"estar de vuelta","t":"마트에 갔다 올게. 20분 안에 돌아올 거야.","e":"'estar de vuelta'는 '돌아와 있다, 돌아오다'라는 관용 표현으로 전치사 de를 씁니다. 'Estaré de vuelta en veinte minutos'는 '20분 뒤에 돌아와 있을게'라는 뜻입니다. 비슷하게 'estar de viaje(여행 중이다)', 'estar de vacaciones(휴가 중이다)'가 있습니다.","x":["para: 'estar para'는 '~할 참이다'라는 다른 뜻입니다 ✗","a: 'estar a vuelta'라는 표현은 없습니다 ✗","de: estar de vuelta(돌아와 있다) → 정답 ✓","ø: 'estar vuelta'는 성립하지 않습니다 ✗"]},{"id":"G210","q":"En cuanto ____ la noticia, hablé con Martín.","o":["estuve sabiendo","sabía","sabría","supe"],"a":3,"k":"en cuanto + 단순과거","t":"그 소식을 알게 되자마자 마르틴과 이야기했다.","e":"'en cuanto(~하자마자)'가 과거에 실제로 일어난 일을 말할 때는 직설법 과거를 씁니다. saber의 단순과거 supe는 '알게 되었다'라는 순간을 나타냅니다. 미래의 일이라면 'En cuanto sepa...'처럼 접속법을 씁니다.","x":["estuve sabiendo: saber는 진행형으로 거의 쓰지 않아 어색합니다 ✗","sabía: 불완료과거로 '알고 있었다'는 상태라 '알게 되자마자'와 맞지 않습니다 ✗","sabría: 조건법이라 실제 일어난 과거 사건에 쓰지 않습니다 ✗","supe: 단순과거로 '알게 되었다' → 정답 ✓"]},{"id":"G211","q":"____ contentísimo. ¡Me han ascendido en la empresa!","o":["Es","Estoy","Soy","Esté"],"a":1,"k":"estar + 감정 상태","t":"나 너무 기뻐. 회사에서 승진했어!","e":"감정이나 기분처럼 일시적인 상태를 말할 때는 estar를 씁니다. contento(기쁜)는 항상 estar와 함께 씁니다. -ísimo는 '아주 ~한'이라는 최상급 강조 어미입니다(contentísimo = 아주 기쁜).","x":["Es: ser는 감정 상태(contento)와 함께 쓰지 않습니다 ✗","Estoy: estar로 일시적인 기분 → 정답 ✓","Soy: ser라 감정 상태에 쓰지 않습니다 ✗","Esté: 접속법이라 단순한 평서문에 쓰지 않습니다 ✗"]},{"id":"G212","q":"Eso no es ____, así que debes devolverlo.","o":["la tuya","el tuyo","tuyo","tuya"],"a":2,"k":"소유사 (중성 eso)","t":"그건 네 것이 아니니까 돌려줘야 해.","e":"ser 뒤에 소유사가 와서 '~의 것이다'라고 할 때는 보통 관사 없이 씁니다(Es mío, Es tuyo). 주어 eso는 중성 대명사라서 남성형 tuyo로 맞춥니다. 'el tuyo'는 '네 것'이라는 명사 역할로, 다른 것과 비교해 고를 때 씁니다.","x":["la tuya: 여성형인 데다 관사도 있어 eso와 맞지 않습니다 ✗","el tuyo: '(여럿 중) 네 것'이라는 뜻이라 소유 여부를 말하는 이 문장에 맞지 않습니다 ✗","tuyo: ser 뒤 관사 없이 '네 것이다' → 정답 ✓","tuya: 여성형이라 중성 eso와 맞지 않습니다 ✗"]},{"id":"G213","q":"¿____ lo bien que nos lo pasábamos en el cole?","o":["Acuerdas de","Te recuerdas","Recuerdas","Acuerdas"],"a":2,"k":"recordar vs acordarse","t":"학교 다닐 때 우리가 얼마나 재밌게 놀았는지 기억나?","e":"recordar(기억하다)는 재귀대명사나 전치사 없이 바로 목적어를 받습니다. 반면 acordarse는 재귀동사라 'te acuerdas de ~'처럼 te와 de가 둘 다 필요합니다. 'el cole'는 'el colegio(학교)'의 구어체입니다.","x":["Acuerdas de: 재귀대명사 te가 빠져 틀립니다(¿Te acuerdas de...?) ✗","Te recuerdas: recordar는 재귀동사로 쓰지 않습니다 ✗","Recuerdas: recordar + 목적어 바로 연결 → 정답 ✓","Acuerdas: te와 de가 모두 빠져 틀립니다 ✗"]},{"id":"G214","q":"Alquilaremos ____ coche para recorrer Portugal.","o":["una","un","uno","ø"],"a":1,"k":"부정관사 un","t":"포르투갈을 여행하기 위해 차 한 대를 빌릴 거야.","e":"처음 언급하는, 특정하지 않은 '차 한 대'이므로 부정관사를 씁니다. coche는 남성 명사이므로 un coche가 됩니다. uno는 명사 없이 혼자 쓸 때(Quiero uno. 하나 원해요.) 쓰는 형태입니다.","x":["una: 여성형이라 남성 명사 coche와 맞지 않습니다 ✗","un: 남성 명사 앞 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄어듭니다 ✗","ø: 셀 수 있는 단수 명사라 관사가 필요합니다 ✗"]},{"id":"G215","q":"¿____ han hecho ese trabajo tan bueno?","o":["Quien","Quienes","Quién","Quiénes"],"a":3,"k":"의문사 quiénes","t":"그렇게 훌륭한 작업을 한 사람들이 누구야?","e":"의문사 quién은 사람이 여러 명일 때 quiénes(누구들)로 씁니다. 동사 han hecho가 3인칭 복수이므로 복수형 quiénes가 맞습니다. 의문문이므로 악센트가 반드시 있어야 합니다.","x":["Quien: 악센트가 없어 관계사가 되고, 단수라 동사와도 맞지 않습니다 ✗","Quienes: 악센트가 없어 의문사가 아닙니다 ✗","Quién: 단수형이라 복수 동사 han과 맞지 않습니다 ✗","Quiénes: 악센트 있는 복수 의문사 → 정답 ✓"]},{"id":"G216","q":"¿Puedes llevarle ____ plato a tu abuelita?","o":["este","eso","esta","esto"],"a":0,"k":"지시형용사 este","t":"이 접시 좀 할머니께 가져다드릴 수 있니?","e":"명사 앞에서 '이 ~'라고 할 때는 지시형용사를 쓰고 명사와 성·수를 맞춥니다. plato(접시)는 남성 단수라 este를 씁니다. eso, esto는 중성 대명사로 명사 앞에 쓰지 않습니다.","x":["este: 남성 단수 지시형용사(이) → 정답 ✓","eso: 중성 대명사(그것)라 명사 앞에 쓸 수 없습니다 ✗","esta: 여성형이라 남성 명사 plato와 맞지 않습니다 ✗","esto: 중성 대명사(이것)라 명사 앞에 쓸 수 없습니다 ✗"]},{"id":"G217","q":"¿Dónde están ____ pantalones que uso para correr?","o":["unas","unos","los","las"],"a":2,"k":"정관사 los","t":"내가 달리기할 때 입는 바지 어디 있어?","e":"'내가 달리기할 때 입는'이라는 관계절로 특정한 바지를 가리키므로 정관사를 씁니다. pantalones(바지)는 남성 복수 명사라 los를 씁니다. 스페인어에서 바지는 보통 복수형으로 씁니다.","x":["unas: 여성 부정관사라 맞지 않습니다 ✗","unos: 부정관사라 특정한 바지를 가리킬 수 없습니다 ✗","los: 남성 복수 정관사로 특정한 바지 → 정답 ✓","las: 여성형이라 남성 명사 pantalones와 맞지 않습니다 ✗"]},{"id":"G218","q":"Alberto todavía ____ enfermo.","o":["sea","está","es","esté"],"a":1,"k":"estar enfermo","t":"알베르토는 아직 아프다.","e":"'아프다'처럼 건강 상태는 일시적인 상태이므로 estar를 씁니다. 'todavía(아직)'도 지금 이어지는 상태라는 것을 보여 줍니다. 평서문이라 접속법이 아닌 직설법 está를 씁니다.","x":["sea: ser의 접속법이라 상태와 평서문 모두에 맞지 않습니다 ✗","está: estar 직설법으로 일시적 상태 → 정답 ✓","es: ser는 일시적인 병의 상태에 잘 쓰지 않습니다 ✗","esté: 접속법이라 평서문에 쓰지 않습니다 ✗"]},{"id":"G219","q":"¡Llevo media hora ____! ¿Dónde estabas?","o":["esperarte","en esperarte","esperando a ti","esperándote"],"a":3,"k":"llevar + 현재분사","t":"나 너 30분째 기다리고 있었어! 어디 있었어?","e":"'llevar + 시간 + 현재분사(-ando/-iendo)'는 '~동안 계속 ~하고 있다'라는 뜻입니다. 대명사 te(너를)는 현재분사 뒤에 붙여 쓰고, 이때 악센트가 생깁니다: esperando + te = esperándote. 예: Llevo dos años estudiando español. (스페인어를 2년째 공부하고 있다.)","x":["esperarte: 동사원형이라 llevar 구문에 맞지 않습니다 ✗","en esperarte: 전치사와 동사원형은 이 구문에 쓰지 않습니다 ✗","esperando a ti: 대명사는 'a ti'만 쓰지 않고 te를 붙여야 합니다 ✗","esperándote: 현재분사 + te(악센트 포함) → 정답 ✓"]},{"id":"G220","q":"____ Ángel y yo no hay nada más que una buena amistad.","o":["Sobre","Con","En","Entre"],"a":3,"k":"entre (사이·관계)","t":"앙헬과 나 사이에는 좋은 우정 이상은 아무것도 없어.","e":"entre는 '~사이에'라는 뜻으로 두 사람 사이의 관계를 말할 때도 씁니다. 'Entre A y B no hay nada'는 'A와 B 사이에는 아무것도 없다'라는 표현입니다. entre 뒤에서는 mí가 아니라 yo를 그대로 씁니다.","x":["Sobre: '~위에, ~에 관해'라 두 사람의 관계에 맞지 않습니다 ✗","Con: '~와 함께'라 'A y yo' 구조와 맞지 않습니다 ✗","En: '~안에'라 맞지 않습니다 ✗","Entre: 'A와 B 사이에' → 정답 ✓"]},{"id":"G221","q":"No quiero que ____ tan tarde, me preocupo por ti.","o":["volvéis","vuelvas","vuelves","volverás"],"a":1,"k":"querer que + 접속법","t":"너무 늦게 돌아오지 않았으면 좋겠어. 네가 걱정되거든.","e":"'Quiero que...(~하기를 원한다)'처럼 다른 사람에게 바라는 내용에는 접속법을 씁니다. 뒤 문장 'por ti'로 보아 상대는 tú이므로 volver의 tú 접속법 현재 vuelvas가 맞습니다.","x":["volvéis: 직설법 vosotros 형태라 맞지 않습니다 ✗","vuelvas: tú 접속법 현재 → 정답 ✓","vuelves: 직설법이라 querer que 뒤에 쓰지 않습니다 ✗","volverás: 미래형 직설법이라 맞지 않습니다 ✗"]},{"id":"G222","q":"¿A qué hora ____ fuisteis de la biblioteca?","o":["te","se","ø","os"],"a":3,"k":"irse (재귀 vosotros)","t":"너희 몇 시에 도서관에서 나갔어?","e":"irse는 '(어떤 장소를) 떠나다'라는 재귀동사입니다. 동사 fuisteis가 vosotros 형태이므로 재귀대명사도 os를 씁니다. 'irse de + 장소'는 '~에서 떠나다'입니다. 중남미에서는 '¿A qué hora se fueron?'(ustedes)이라고 합니다.","x":["te: tú의 재귀대명사라 fuisteis와 맞지 않습니다 ✗","se: 3인칭·ustedes의 재귀대명사라 fuisteis와 맞지 않습니다 ✗","ø: 'ir de la biblioteca'는 '떠나다' 뜻이 되지 않습니다 ✗","os: vosotros의 재귀대명사 → 정답 ✓"]},{"id":"G223","q":"Estoy intentando ____ descansar. ¿Te importa hacer menos ruido?","o":["ø","a","por","de"],"a":0,"k":"intentar + 동사원형","t":"나 쉬려고 하는 중이야. 좀 덜 시끄럽게 해 줄래?","e":"intentar(~하려고 하다, 시도하다) 뒤에는 전치사 없이 바로 동사원형이 옵니다. 'tratar de + 동사원형'도 같은 뜻이지만 de가 필요하니 헷갈리지 마세요. 예: Intento dormir. (자려고 해.)","x":["ø: intentar + 동사원형 바로 연결 → 정답 ✓","a: intentar 뒤에 a를 쓰지 않습니다 ✗","por: intentar 뒤에 por를 쓰지 않습니다 ✗","de: tratar de에는 쓰지만 intentar에는 쓰지 않습니다 ✗"]},{"id":"G224","q":"¿Te acuerdas ____ Beatriz? La vi el otro día en el supermercado.","o":["para","por","a","de"],"a":3,"k":"acordarse de","t":"베아트리스 기억나? 며칠 전에 마트에서 봤어.","e":"acordarse(기억하다)는 재귀동사로, 기억하는 대상 앞에 항상 전치사 de를 씁니다. '¿Te acuerdas de ~?'는 '~ 기억나?'라는 아주 흔한 표현입니다. recordar를 쓰면 'Recuerdas a Beatriz?'처럼 de 없이 씁니다.","x":["para: acordarse와 함께 쓰지 않습니다 ✗","por: acordarse와 함께 쓰지 않습니다 ✗","a: 사람 목적어 앞의 a는 recordar에 쓰고 acordarse에는 쓰지 않습니다 ✗","de: acordarse de(~을 기억하다) → 정답 ✓"]},{"id":"G225","q":"En México hay muchos más habitantes ____ España.","o":["que en","como en","de","que"],"a":0,"k":"más ... que en","t":"멕시코에는 스페인보다 인구가 훨씬 많다.","e":"우등 비교는 'más ... que'를 씁니다. 비교하는 대상이 장소(en México vs en España)이므로 같은 전치사 en을 반복해 'que en España'가 됩니다. 수량 앞이 아니라 비교 대상 앞이라 de가 아니라 que입니다.","x":["que en: 비교의 que + 장소의 en → 정답 ✓","como en: como는 동등 비교(tan ... como)에 쓰므로 más와 맞지 않습니다 ✗","de: 'más de + 숫자'처럼 수량 앞에서만 씁니다 ✗","que: 비교 대상이 장소라 en이 빠지면 '멕시코에 스페인보다'가 아니라 어색한 비교가 됩니다 ✗"]},{"id":"G226","q":"Es increíble que ____ tantos idiomas a un nivel tan avanzado.","o":["habla","hablaría","está hablando","hable"],"a":3,"k":"감정·평가 + 접속법","t":"그가 그렇게 많은 언어를 그렇게 높은 수준으로 구사하다니 놀랍다.","e":"'Es increíble que...(~하다니 놀랍다)'처럼 감정이나 평가를 나타내는 표현 뒤 que절에는 접속법을 씁니다. hablar의 3인칭 단수 접속법 현재는 hable입니다. 예: Es increíble que no lo sepas. (네가 그걸 모르다니 믿을 수 없어.)","x":["habla: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","hablaría: 조건법이라 맞지 않습니다 ✗","está hablando: 직설법 진행형이라 맞지 않습니다 ✗","hable: 접속법 현재 → 정답 ✓"]},{"id":"G227","q":"Esta ropa está limpia, no ____ metas en la lavadora.","o":["le","lo","la","las"],"a":2,"k":"직접목적격 la","t":"이 옷은 깨끗해. 세탁기에 넣지 마.","e":"'그것을 넣지 마'에서 '그것'은 앞의 la ropa(옷, 여성 단수)를 가리키므로 직접목적격 대명사(~을/를에 해당) la를 씁니다. 부정 명령에서는 대명사를 동사 앞에 둡니다: no la metas. ropa는 '옷 전체'를 뜻하는 단수 명사입니다.","x":["le: 간접목적격(~에게)이라 '옷을'을 받을 수 없습니다 ✗","lo: 남성형이라 여성 명사 ropa와 맞지 않습니다 ✗","la: 여성 단수 직접목적격(그것을) → 정답 ✓","las: 복수형인데 ropa는 단수입니다 ✗"]},{"id":"G228","q":"La habitación ____ limpié ayer, por eso está perfecta.","o":["le","la","ø","lo"],"a":1,"k":"목적어 앞 강조와 대명사","t":"방은 어제 내가 청소했어. 그래서 완벽하지.","e":"직접목적어(la habitación)를 문장 맨 앞으로 내세우면 동사 앞에 그것을 다시 받는 대명사를 꼭 써야 합니다. habitación은 여성 단수이므로 la를 씁니다: 'La habitación la limpié ayer.' 한국어의 '방은 (그걸) 내가 청소했어'와 비슷한 구조입니다.","x":["le: 간접목적격이라 '방을'을 받을 수 없습니다 ✗","la: 여성 단수 직접목적격으로 앞의 목적어를 다시 받음 → 정답 ✓","ø: 목적어가 동사 앞에 나오면 대명사를 생략할 수 없습니다 ✗","lo: 남성형이라 여성 명사 habitación과 맞지 않습니다 ✗"]},{"id":"G229","q":"Deberíamos ____ más empatía con las personas discapacitadas","o":["teniendo","a tener","de tener","tener"],"a":3,"k":"deber + 동사원형","t":"우리는 장애가 있는 사람들에게 더 많이 공감해야 한다.","e":"deber(~해야 한다)는 조건법 deberíamos로 쓰면 '~하는 게 좋겠다, ~해야 할 것이다'라는 부드러운 조언이 됩니다. 뒤에는 전치사 없이 동사원형이 옵니다. 'tener empatía con ~'은 '~에게 공감하다'라는 뜻입니다.","x":["teniendo: 현재분사라 deber 뒤에 올 수 없습니다 ✗","a tener: deber 뒤에 a를 쓰지 않습니다 ✗","de tener: deber de는 추측(~일 것이다)의 뜻이 되어 맞지 않습니다 ✗","tener: deber + 동사원형 → 정답 ✓"]},{"id":"G230","q":"¿Había ____ gente en el estreno de la película?","o":["mucho","muchos","muchas","mucha"],"a":3,"k":"mucho의 성·수 일치","t":"영화 시사회에 사람이 많았어?","e":"명사 앞의 mucho(많은)는 명사와 성·수를 맞춥니다. gente(사람들)는 뜻은 여러 사람이지만 문법적으로 여성 단수 명사입니다. 그래서 mucha gente가 맞습니다. 동사도 단수로 씁니다: La gente es amable.","x":["mucho: 남성 단수라 여성 명사 gente와 맞지 않습니다 ✗","muchos: 남성 복수라 맞지 않습니다 ✗","muchas: gente는 단수 명사라 복수형을 쓰지 않습니다 ✗","mucha: 여성 단수로 gente와 일치 → 정답 ✓"]},{"id":"G231","q":"____ sigas portándote mal, te voy a castigar.","o":["Si","Para que","Aunque","Como"],"a":3,"k":"como + 접속법 (경고)","t":"계속 말 안 들으면 벌 줄 거야.","e":"'como + 접속법'은 '만약 ~하면'이라는 조건을 나타내는데, 주로 경고나 위협을 할 때 씁니다. 뒤에 sigas(접속법)가 있으므로 como가 맞습니다. si는 같은 뜻이지만 현재 접속법과 함께 쓰지 않습니다(Si sigues...). 예: Como llegues tarde, me enfado. (늦게 오면 화낼 거야.)","x":["Si: si 뒤에는 접속법 현재(sigas)를 쓸 수 없고 sigues가 와야 합니다 ✗","Para que: 목적(~하도록)이라 문맥에 맞지 않습니다 ✗","Aunque: '~하더라도'라 벌을 준다는 경고와 맞지 않습니다 ✗","Como: 'como + 접속법'의 경고 조건 → 정답 ✓"]},{"id":"G232","q":"No me gusta ____ de esos cantantes.","o":["ningún","algún","ninguno","uno"],"a":2,"k":"ninguno (대명사)","t":"나는 그 가수들 중 아무도 좋아하지 않아.","e":"ninguno는 '(여럿 중) 아무도/어느 것도'라는 뜻의 대명사로, 'ninguno de + 복수 명사' 형태로 씁니다. ningún은 명사 바로 앞에서만 쓰는 줄임형이라 'de' 앞에는 ninguno를 씁니다. 주어가 단수(ninguno)라 동사도 gusta입니다.","x":["ningún: 남성 명사 바로 앞에서만 쓰는 형태라 de 앞에 쓸 수 없습니다 ✗","algún: 긍정어인 데다 명사 바로 앞에만 쓰는 형태입니다 ✗","ninguno: 'ninguno de ~(~중 아무도)' → 정답 ✓","uno: '그중 한 명은 좋아하지 않는다'가 되어 이중 부정 문맥과 맞지 않습니다 ✗"]},{"id":"G233","q":"Lucía, con ____ me une una buena amistad, vive en Canadá.","o":["cual","quien","ella","que"],"a":1,"k":"전치사 + quien","t":"나와 좋은 우정으로 이어져 있는 루시아는 캐나다에 산다.","e":"사람을 가리키는 관계절에서 전치사(con) 뒤에는 quien을 쓸 수 있습니다. 'con quien me une una buena amistad'는 '나와 좋은 우정으로 연결된 (사람)'이라는 뜻입니다. 'con la que'도 가능하지만 'con que'처럼 관사 없는 que는 사람에게 잘 쓰지 않습니다.","x":["cual: 관사 없이 cual 단독으로 관계사가 되지 않습니다(con la cual은 가능) ✗","quien: 전치사 뒤 사람을 받는 관계사 → 정답 ✓","ella: 인칭대명사라 문장을 관계절로 이어 주지 못합니다 ✗","que: 전치사 뒤에서 사람을 받을 때는 관사가 필요합니다 ✗"]},{"id":"G234","q":"Yo tengo más obligaciones ____.","o":["que tú","de ti","de tú","que ti"],"a":0,"k":"비교 que + 주격","t":"내가 너보다 의무(해야 할 일)가 더 많아.","e":"'más ... que'로 비교할 때 que 뒤의 인칭대명사는 주격(yo, tú)을 씁니다. 그래서 'más que tú'가 맞고 'que ti'는 틀립니다. ti는 전치사 뒤에서만 쓰는데 que는 전치사가 아니기 때문입니다.","x":["que tú: 비교의 que + 주격 tú → 정답 ✓","de ti: 비교 대상 앞에는 de가 아니라 que를 씁니다 ✗","de tú: de 뒤에는 tú를 쓸 수 없고, 비교 구문에도 맞지 않습니다 ✗","que ti: que 뒤에는 전치격 ti가 아니라 tú를 씁니다 ✗"]},{"id":"G235","q":"Aquí está mi paraguas. ¿Dónde está ____?","o":["los tuyos","tuyo","el tuyo","la tuya"],"a":2,"k":"소유대명사 el tuyo","t":"여기 내 우산이 있어. 네 건 어디 있어?","e":"명사를 반복하지 않고 '네 것'이라고 할 때는 '정관사 + 소유사(el tuyo, la tuya...)'를 씁니다. paraguas(우산)는 -s로 끝나지만 남성 단수 명사(el paraguas)이므로 el tuyo가 맞습니다. 동사 está도 단수입니다.","x":["los tuyos: 복수형이라 단수 동사 está와 맞지 않습니다 ✗","tuyo: 관사가 없어 '네 것'이라는 대명사 역할을 못 합니다 ✗","el tuyo: 남성 단수 소유대명사(네 것) → 정답 ✓","la tuya: 여성형이라 남성 명사 paraguas와 맞지 않습니다 ✗"]},{"id":"G236","q":"Ojalá ____ vivir en una casa como esa.","o":["puedo","podría","pudiera","podré"],"a":2,"k":"ojalá + 접속법 과거","t":"저런 집에서 살 수 있으면 얼마나 좋을까.","e":"ojalá(~이면 좋겠다)는 항상 접속법과 함께 씁니다. 실현 가능성이 낮거나 현실과 다른 소원일 때는 접속법 과거(pudiera)를 씁니다. 가능성이 있는 바람이라면 접속법 현재(Ojalá pueda...)를 씁니다.","x":["puedo: 직설법이라 ojalá 뒤에 쓰지 않습니다 ✗","podría: 조건법이라 ojalá 뒤에 쓰지 않습니다 ✗","pudiera: 접속법 과거로 이루기 어려운 소원 → 정답 ✓","podré: 미래형 직설법이라 쓰지 않습니다 ✗"]},{"id":"G237","q":"Tengo ____ ropa que tú.","o":["casi tanta","menos","tan","tanta"],"a":1,"k":"menos ... que","t":"나는 너보다 옷이 적다.","e":"뒤에 'que tú'가 있으므로 우등·열등 비교(más/menos ... que)가 필요합니다. menos는 형태가 변하지 않아 명사 ropa 앞에 그대로 씁니다. tanta(그만큼 많은)는 como와 짝을 이루므로 que와 함께 쓸 수 없습니다.","x":["casi tanta: tanta는 como와 짝을 이뤄 que와 쓸 수 없습니다 ✗","menos: 'menos ... que(~보다 적은)' → 정답 ✓","tan: 명사 앞에 쓰지 않고, como와 짝을 이룹니다 ✗","tanta: 동등 비교라 como가 필요합니다 ✗"]},{"id":"G238","q":"No ____ la esperanza, todavía puedes alcanzar tu objetivo.","o":["perded","pierdas","pierdes","perdéis"],"a":1,"k":"부정 명령 (tú)","t":"희망을 잃지 마. 아직 목표를 이룰 수 있어.","e":"tú에게 하는 부정 명령(~하지 마)은 접속법 현재를 씁니다. perder(잃다)는 e→ie로 바뀌는 불규칙 동사라 pierdas가 됩니다. 뒤 문장 'puedes'로 보아 상대가 tú라는 것을 알 수 있습니다.","x":["perded: vosotros 긍정 명령이라 no와 쓸 수 없습니다 ✗","pierdas: tú 부정 명령(접속법 현재) → 정답 ✓","pierdes: 직설법이라 명령이 되지 않습니다 ✗","perdéis: 직설법 vosotros 형태라 맞지 않습니다 ✗"]},{"id":"G239","q":"No ____ triste, cariño, todo tiene solución.","o":["estáis","estás","estés","está"],"a":2,"k":"부정 명령 estar","t":"슬퍼하지 마, 자기야. 모든 일엔 해결책이 있어.","e":"부정 명령은 접속법 현재를 씁니다. 상대가 cariño(자기야)라고 부르는 한 사람(tú)이므로 estar의 tú 접속법 estés를 씁니다. 'No estés triste'는 '슬퍼하지 마'라는 위로 표현입니다.","x":["estáis: 직설법 vosotros라 명령이 되지 않습니다 ✗","estás: 직설법이라 부정 명령으로 쓸 수 없습니다 ✗","estés: tú 접속법 현재로 부정 명령 → 정답 ✓","está: 직설법 3인칭이라 맞지 않습니다 ✗"]},{"id":"G240","q":"¿Qué es la felicidad para ____?","o":["tú","te","ti","a ti"],"a":2,"k":"전치격 대명사 ti","t":"너에게 행복이란 뭐야?","e":"전치사(para, de, sin 등) 뒤에서는 tú가 아니라 전치격 대명사 ti를 씁니다. 그래서 'para ti(너에게, 너한테 있어)'가 됩니다. 단, con은 contigo로 합쳐집니다.","x":["tú: 주격이라 전치사 para 뒤에 쓸 수 없습니다 ✗","te: 목적격 대명사라 전치사 뒤에 쓸 수 없습니다 ✗","ti: 전치사 뒤에 쓰는 형태 → 정답 ✓","a ti: 전치사가 두 번(para a) 겹쳐 틀립니다 ✗"]},{"id":"G241","q":"Me gustaría que mis hijos ____ más en las tareas domésticas.","o":["colaboren","colaborarían","colaboraran","colaborarán"],"a":2,"k":"gustaría que + 접속법 과거","t":"우리 아이들이 집안일에 더 협조해 주면 좋겠어.","e":"주절이 조건법(me gustaría)이면 que절에는 접속법 과거를 씁니다. 그래서 colaborar의 3인칭 복수 접속법 과거 colaboraran이 맞습니다. 주절이 현재(me gusta que)라면 접속법 현재 colaboren이 됩니다.","x":["colaboren: 접속법 현재라 조건법 gustaría와 시제가 맞지 않습니다 ✗","colaborarían: 조건법이라 que절에 쓰지 않습니다 ✗","colaboraran: 접속법 과거로 gustaría와 시제 일치 → 정답 ✓","colaborarán: 미래형 직설법이라 맞지 않습니다 ✗"]},{"id":"G242","q":"¿A qué hora ____ el domingo pasado?","o":["os levantasteis","os estabais levantando","os habéis levantado","os levantabais"],"a":0,"k":"단순과거 (재귀)","t":"너희 지난 일요일에 몇 시에 일어났어?","e":"'el domingo pasado(지난 일요일)'처럼 끝난 과거 시점의 한 번의 행동은 단순과거로 씁니다. levantarse의 vosotros 단순과거는 os levantasteis입니다. 중남미에서는 ustedes를 써서 '¿A qué hora se levantaron?'이라고 합니다.","x":["os levantasteis: 단순과거로 지난 일요일 한 번의 행동 → 정답 ✓","os estabais levantando: 진행형 과거라 '일어나는 중이었다'가 되어 맞지 않습니다 ✗","os habéis levantado: 현재완료라 'el domingo pasado'와 쓰지 않습니다 ✗","os levantabais: 불완료과거로 습관을 나타내 한 번의 일요일과 맞지 않습니다 ✗"]},{"id":"G243","q":"¿Cómo la pasaste el día de ____ cumpleaños?","o":["tus","tuyo","tuyos","tu"],"a":3,"k":"소유형용사 tu","t":"네 생일에 어떻게 보냈어?","e":"명사 앞에 오는 소유형용사는 짧은 형태(mi, tu, su)를 씁니다. cumpleaños는 -s로 끝나지만 단수 명사(el cumpleaños)이므로 tu를 씁니다. '¿Cómo la pasaste?'는 중남미에서 많이 쓰는 표현이고, 스페인에서는 '¿Cómo lo pasaste?'라고 합니다.","x":["tus: 복수형인데 이 문장의 cumpleaños는 단수입니다 ✗","tuyo: 명사 뒤나 ser 뒤에 쓰는 형태라 명사 앞에 쓸 수 없습니다 ✗","tuyos: 명사 뒤에 쓰는 복수형이라 맞지 않습니다 ✗","tu: 명사 앞 단수 소유형용사 → 정답 ✓"]},{"id":"G244","q":"No me interrumpas, por favor, ____.","o":["he estado estudiando","estoy estudiando","estudio","he estudiado"],"a":1,"k":"현재진행형","t":"방해하지 말아 줘, 나 공부하는 중이야.","e":"말하는 바로 그 순간에 하고 있는 행동은 'estar + 현재분사'의 현재진행형으로 말합니다. 방해하지 말라는 이유가 '지금 공부 중'이기 때문에 estoy estudiando가 가장 자연스럽습니다.","x":["he estado estudiando: '지금까지 공부해 왔다'는 뜻이라 지금 하는 중이라는 이유로 약합니다 ✗","estoy estudiando: 지금 진행 중인 행동 → 정답 ✓","estudio: 일반 현재(공부한다)라 지금 이 순간의 진행을 강조하지 못합니다 ✗","he estudiado: '공부를 했다(끝냄)'라 방해하지 말라는 이유가 되지 않습니다 ✗"]},{"id":"G245","q":"No pude responder a la pregunta porque me quedé completamente ____ blanco.","o":["en","de","entre","sobre"],"a":0,"k":"quedarse en blanco","t":"머릿속이 완전히 하얘져서 질문에 대답하지 못했다.","e":"'quedarse en blanco'는 '머릿속이 하얘지다, 아무 생각이 안 나다'라는 관용 표현으로 전치사 en을 씁니다. 시험이나 발표 때 긴장해서 말문이 막히는 상황에 자주 씁니다.","x":["en: quedarse en blanco(머릿속이 하얘지다) → 정답 ✓","de: 'de blanco'는 '흰옷을 입고'라는 뜻이라 맞지 않습니다 ✗","entre: 이 관용 표현에 쓰지 않습니다 ✗","sobre: 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"G246","q":"¿Cuál es el animal más rápido ____ mundo?","o":["al","del","de","en"],"a":1,"k":"최상급 + de","t":"세계에서 가장 빠른 동물은 뭐야?","e":"최상급(el más ~)에서 범위(~중에서, ~에서)는 전치사 de로 나타냅니다. mundo(세계) 앞에 정관사 el이 필요하므로 de + el = del이 됩니다. 영어처럼 en을 쓰지 않도록 주의하세요. 예: el chico más alto de la clase (반에서 가장 키 큰 남자아이)","x":["al: a + el로 방향을 나타내 맞지 않습니다 ✗","del: de + el로 최상급의 범위 → 정답 ✓","de: 관사가 빠져 'de mundo'는 틀립니다 ✗","en: 최상급의 범위에는 en이 아니라 de를 씁니다 ✗"]},{"id":"G247","q":"En Barcelona hay más ____ un millón de habitantes.","o":["con","que","a","de"],"a":3,"k":"más de + 수량","t":"바르셀로나에는 인구가 100만 명이 넘는다.","e":"숫자나 수량 앞에서 '~이상, ~넘게'라고 할 때는 'más de + 숫자'를 씁니다. 'más que'는 두 대상을 비교할 때 씁니다. 예: Tengo más de veinte años. (나는 스무 살이 넘었다.)","x":["con: 비교 구문에 쓰지 않습니다 ✗","que: 숫자 앞에서는 que가 아니라 de를 씁니다 ✗","a: 비교 구문에 쓰지 않습니다 ✗","de: más de + 수량(~이상) → 정답 ✓"]},{"id":"G248","q":"No confío ____ casi nadie.","o":["en","de","a","con"],"a":0,"k":"confiar en","t":"나는 거의 아무도 믿지 않는다.","e":"confiar(믿다, 신뢰하다)는 믿는 대상 앞에 전치사 en을 씁니다. 'confiar en alguien(누군가를 믿다)'로 외워 두세요. 'casi nadie'는 '거의 아무도 (아니다)'라는 뜻입니다.","x":["en: confiar en(~을 믿다) → 정답 ✓","de: confiar와 함께 쓰지 않습니다 ✗","a: confiar 뒤 대상 앞에 쓰지 않습니다 ✗","con: confiar와 함께 쓰지 않습니다 ✗"]},{"id":"G249","q":"Tuvimos que tomar ____ taxi para ir al hospital.","o":["el","ø","en","un"],"a":3,"k":"부정관사 un","t":"병원에 가려고 우리는 택시를 타야 했다.","e":"처음 언급하는, 특정하지 않은 택시 한 대를 탔으므로 부정관사 un을 씁니다. taxi는 남성 명사입니다. 'tomar un taxi'는 '택시를 타다'라는 아주 흔한 표현이고, 스페인에서는 'coger un taxi'라고도 합니다.","x":["el: 특정한 그 택시를 가리키게 되어 이 문맥에 어색합니다 ✗","ø: 셀 수 있는 단수 명사라 관사가 필요합니다 ✗","en: 'tomar en taxi'는 틀린 표현입니다('ir en taxi'는 가능) ✗","un: 특정하지 않은 택시 한 대 → 정답 ✓"]},{"id":"G250","q":"____ días en la universidad fueron muy aburridos.","o":["Las primeras","Primeros","Primeras","Los primeros"],"a":3,"k":"서수의 성·수 일치","t":"대학에서의 처음 며칠은 매우 지루했다.","e":"서수(primero 첫 번째 등)도 형용사라서 명사와 성·수를 맞춥니다. días는 -a로 끝나지만 남성 명사(el día)이므로 남성 복수 primeros를 씁니다. 문장의 주어이고 특정 기간을 가리키므로 정관사 los도 필요합니다.","x":["Las primeras: 여성형이라 남성 명사 días와 맞지 않습니다 ✗","Primeros: 주어 자리라 관사가 필요합니다 ✗","Primeras: 여성형이고 관사도 없습니다 ✗","Los primeros: 남성 복수 + 정관사 → 정답 ✓"]},{"id":"G251","q":"¿Te gustaría ir ____ Valencia?","o":["en","entre","de","a"],"a":3,"k":"ir a + 장소","t":"발렌시아에 가 보고 싶어?","e":"ir(가다)처럼 이동을 나타내는 동사는 목적지 앞에 전치사 a를 씁니다. 'ir a Valencia'는 '발렌시아에 가다'입니다. en은 'ir en tren(기차로 가다)'처럼 교통수단에 씁니다.","x":["en: 교통수단이나 위치에 쓰고 목적지에는 쓰지 않습니다 ✗","entre: '~사이에'라 맞지 않습니다 ✗","de: 출발점(~에서)을 나타내 맞지 않습니다 ✗","a: 이동의 목적지(~로) → 정답 ✓"]},{"id":"G252","q":"Se enfadó ____ nadie le dijo que habían cancelado el evento.","o":["como","por","porque","pese a que"],"a":2,"k":"porque (이유)","t":"아무도 그에게 행사가 취소됐다고 말해 주지 않아서 그는 화가 났다.","e":"porque(~때문에, 왜냐하면)는 주절 뒤에서 이유를 설명합니다. '화가 났다' 뒤에 그 이유가 이어지므로 porque가 맞습니다. como(~이니까)도 이유를 나타내지만 항상 문장 맨 앞에 옵니다.","x":["como: 이유의 como는 문장 맨 앞에서만 씁니다 ✗","por: 전치사라 뒤에 절(활용 동사)이 바로 올 수 없습니다 ✗","porque: 주절 뒤 이유 접속사 → 정답 ✓","pese a que: '~에도 불구하고'라 의미가 반대가 됩니다 ✗"]},{"id":"G253","q":"Si quieres saber lo que te pasa, ____ hablar con tu doctora.","o":["deberías","debe","deberías a","debas"],"a":0,"k":"deber 조건법 (조언)","t":"너한테 무슨 문제가 있는지 알고 싶으면 의사 선생님과 이야기해 보는 게 좋겠어.","e":"deber의 조건법 deberías는 '~하는 게 좋겠다'라는 부드러운 조언입니다. si절의 quieres로 보아 상대가 tú이므로 tú 형태를 씁니다. deber 뒤에는 전치사 없이 바로 동사원형이 옵니다.","x":["deberías: tú 조건법으로 부드러운 조언 → 정답 ✓","debe: usted/3인칭 형태라 tú(quieres)와 맞지 않습니다 ✗","deberías a: deber 뒤에 a를 쓰지 않습니다 ✗","debas: 접속법이라 주절에 쓰지 않습니다 ✗"]},{"id":"G254","q":"Te ____ a la cita médica si no tengo que trabajar ese día.","o":["acompañe","estoy acompañando","acompañaré","acompañase"],"a":2,"k":"조건문 si + 현재, 미래","t":"그날 일하지 않아도 되면 병원 진료에 같이 가 줄게.","e":"현실적으로 가능한 조건은 'si + 직설법 현재, 주절은 미래형'으로 말합니다. si절에 tengo(현재)가 있으므로 주절은 미래형 acompañaré가 자연스럽습니다. 예: Si llueve, me quedaré en casa. (비가 오면 집에 있을 거야.)","x":["acompañe: 접속법이라 주절에 쓰지 않습니다 ✗","estoy acompañando: 현재진행형이라 미래 약속의 의미가 되지 않습니다 ✗","acompañaré: 미래형으로 조건이 이뤄질 때의 행동 → 정답 ✓","acompañase: 접속법 과거라 주절에 쓰지 않습니다 ✗"]},{"id":"G255","q":"Hace ____ par de semanas que no veo a mis amigas.","o":["el","una","uno","un"],"a":3,"k":"un par de","t":"친구들을 못 본 지 2주쯤 됐다.","e":"'un par de ~'는 '두어 개의, 한 쌍의'라는 뜻으로, par는 남성 명사라 부정관사 un을 씁니다. 'Hace + 시간 + que ~'는 '~한 지 (시간)이 되었다'라는 표현입니다. 예: Hace un par de días que no duermo bien. (며칠째 잠을 잘 못 자고 있어.)","x":["el: 'el par'는 특정한 한 쌍이라 '두어 주' 뜻에 맞지 않습니다 ✗","una: par는 남성 명사라 여성 관사를 쓰지 않습니다 ✗","uno: 명사 앞에서는 un으로 줄어듭니다 ✗","un: un par de(두어 개의) → 정답 ✓"]},{"id":"G256","q":"Todos estamos de acuerdo ____.","o":["con ti","con te","con tú","contigo"],"a":3,"k":"contigo","t":"우리 모두 너와 같은 생각이야.","e":"전치사 con과 ti가 합쳐지면 특별한 형태 contigo(너와 함께)가 됩니다. 마찬가지로 con + mí = conmigo입니다. 'estar de acuerdo con ~'은 '~에게 동의하다'라는 표현입니다.","x":["con ti: con + ti는 반드시 contigo로 합쳐야 합니다 ✗","con te: te는 목적격이라 전치사 뒤에 쓸 수 없습니다 ✗","con tú: 주격 tú는 전치사 뒤에 쓸 수 없습니다 ✗","contigo: con + ti의 특별한 형태 → 정답 ✓"]},{"id":"G257","q":"Me alegra que sigas ____ español.","o":["a estudiar","estudiado","estudiar","estudiando"],"a":3,"k":"seguir + 현재분사","t":"네가 계속 스페인어를 공부하고 있다니 기뻐.","e":"'seguir + 현재분사(-ando/-iendo)'는 '계속 ~하다'라는 뜻입니다. 그래서 'sigas estudiando(계속 공부하다)'가 됩니다. sigas가 접속법인 것은 'Me alegra que(~해서 기쁘다)'라는 감정 표현 뒤이기 때문입니다.","x":["a estudiar: seguir 뒤에는 'a + 동사원형'을 쓰지 않습니다 ✗","estudiado: 과거분사라 seguir 진행 구문에 맞지 않습니다 ✗","estudiar: 동사원형은 seguir 뒤에 쓰지 않습니다 ✗","estudiando: seguir + 현재분사(계속 ~하다) → 정답 ✓"]},{"id":"G258","q":"Si vas a la playa, no ____ ponerte protección solar.","o":["te olvides","olvide","olvidas","olvides"],"a":3,"k":"olvidar 부정 명령","t":"해변에 가면 선크림 바르는 거 잊지 마.","e":"tú에게 하는 부정 명령은 접속법 현재이므로 'no olvides'가 됩니다. olvidar는 바로 동사원형을 목적어로 받을 수 있습니다(olvidar ponerse). 재귀형 olvidarse를 쓰려면 de가 필요해서 'no te olvides de ponerte'가 됩니다.","x":["te olvides: 재귀형이라 뒤에 de가 있어야 합니다(te olvides de ponerte) ✗","olvide: usted 형태라 tú(vas)와 맞지 않습니다 ✗","olvidas: 직설법이라 명령이 되지 않습니다 ✗","olvides: tú 부정 명령 + 동사원형 바로 연결 → 정답 ✓"]},{"id":"G259","q":"Hizo el ejercicio una y otra vez ____ le salió bien.","o":["antes de que","en cuanto","hasta que","desde que"],"a":2,"k":"hasta que (~할 때까지)","t":"그는 제대로 될 때까지 그 연습 문제를 몇 번이고 풀었다.","e":"'hasta que(~할 때까지)'는 어떤 행동이 계속되다 끝나는 시점을 나타냅니다. 실제로 일어난 과거 사건이므로 뒤에 직설법(salió)이 왔습니다. 'una y otra vez'는 '몇 번이고, 반복해서'라는 뜻입니다. 'salir bien'은 '(일이) 잘되다'입니다.","x":["antes de que: '~하기 전에'라는 뜻이며 뒤에 접속법이 와야 합니다 ✗","en cuanto: '~하자마자'라 반복하다가 성공했다는 의미와 맞지 않습니다 ✗","hasta que: '~할 때까지' → 정답 ✓","desde que: '~한 이후로'라 의미가 맞지 않습니다 ✗"]},{"id":"G260","q":"Hoy tengo que trabajar ____ las 6, así que no podemos vernos antes.","o":["hasta","de","hacia","para"],"a":0,"k":"hasta (시간)","t":"오늘은 6시까지 일해야 해서 그 전에는 만날 수 없어.","e":"hasta는 '~까지'라는 뜻으로 행동이 끝나는 시간을 나타냅니다. '6시까지 일해야 해서 그 전에는 못 만난다'는 흐름이므로 hasta가 맞습니다. 'de 9 a 6(9시부터 6시까지)'처럼 쓰는 de와 구별하세요.","x":["hasta: 끝나는 시점(~까지) → 정답 ✓","de: 시작 시점(~부터)이라 문맥과 맞지 않습니다 ✗","hacia: '~무렵에, ~쪽으로'라 끝나는 시간을 나타내지 않습니다 ✗","para: 기한(~까지 완료)을 나타내 '6시까지 계속 일한다'는 의미와 다릅니다 ✗"]},{"id":"G261","q":"Os doy las gracias ____ todo lo que habéis hecho.","o":["para","por","hasta","hacia"],"a":1,"k":"dar las gracias por","t":"너희가 해 준 모든 것에 고마워.","e":"감사하는 이유는 전치사 por로 나타냅니다. 'dar las gracias por ~', 'gracias por ~'는 '~에 대해 고맙다'는 뜻입니다. 'os'는 vosotros(너희)에게 쓰는 간접목적격 대명사입니다.","x":["para: 목적을 나타내 감사의 이유에 쓰지 않습니다 ✗","por: 감사의 이유(~에 대해) → 정답 ✓","hasta: '~까지'라 맞지 않습니다 ✗","hacia: '~쪽으로'라 맞지 않습니다 ✗"]},{"id":"G262","q":"Alguien ____ llamar al fontanero, se ha roto la cisterna del baño.","o":["debo","tengo que","hay que","tiene que"],"a":3,"k":"tener que (주어 일치)","t":"누가 배관공을 불러야 해. 화장실 물탱크가 고장 났어.","e":"tener que + 동사원형은 '~해야 한다'라는 의무입니다. 주어가 alguien(누군가, 3인칭 단수)이므로 tiene que가 맞습니다. hay que도 '~해야 한다'지만 주어가 없는 무인칭 표현이라 alguien과 함께 쓸 수 없습니다.","x":["debo: 1인칭(나는)이라 주어 alguien과 맞지 않습니다 ✗","tengo que: 1인칭이라 alguien과 맞지 않습니다 ✗","hay que: 주어 없는 무인칭 표현이라 alguien을 주어로 받을 수 없습니다 ✗","tiene que: 3인칭 단수로 alguien과 일치 → 정답 ✓"]},{"id":"G263","q":"¿____ cuándo viven aquí?","o":["Entre","Sobre","De","Desde"],"a":3,"k":"desde cuándo","t":"여기 언제부터 살고 있어요?","e":"'¿Desde cuándo...?'는 '언제부터 ~?'라는 뜻으로, 어떤 상태가 시작된 시점을 묻습니다. 지금도 계속되는 일이라 동사는 현재형(viven)을 씁니다. 예: ¿Desde cuándo estudias español? (언제부터 스페인어 공부해?)","x":["Entre: '~사이에'라 시점을 묻지 않습니다 ✗","Sobre: '대략 ~쯤'이라는 뜻이지만 의문문으로는 어색합니다 ✗","De: 'de cuándo'는 '언제 것인지(시기)'를 묻는 말이라 맞지 않습니다 ✗","Desde: desde cuándo(언제부터) → 정답 ✓"]},{"id":"G264","q":"Estuve trabajando sin ____ hasta la medianoche.","o":["parado","paro","parando","parar"],"a":3,"k":"sin + 동사원형","t":"자정까지 쉬지 않고 일했다.","e":"전치사(sin, para, de 등) 뒤에 동사가 올 때는 항상 동사원형을 씁니다. 'sin parar'는 '멈추지 않고, 쉬지 않고'라는 자주 쓰는 표현입니다. 한국어로 '~하지 않고'를 현재분사로 쓰지 않도록 주의하세요.","x":["parado: 과거분사라 전치사 뒤에 쓰지 않습니다 ✗","paro: '실업, 정지'라는 명사이거나 1인칭 현재라 맞지 않습니다 ✗","parando: 현재분사는 전치사 sin 뒤에 쓰지 않습니다 ✗","parar: 전치사 뒤 동사원형 → 정답 ✓"]},{"id":"G265","q":"Dicen que nuestro antiguo colegio va a ser ____.","o":["derrumbado","derrumbo","derrumbó","derrumbando"],"a":0,"k":"수동태 ser + 과거분사","t":"우리 옛날 학교가 철거될 거라고들 한다.","e":"'ser + 과거분사'는 '~되다'라는 수동태입니다. 학교가 '철거하는' 게 아니라 '철거되는' 것이므로 과거분사 derrumbado를 씁니다. 과거분사는 주어(colegio, 남성 단수)와 성·수를 맞춥니다. 'ir a ser'는 '~될 것이다'라는 가까운 미래입니다.","x":["derrumbado: 과거분사로 수동태(철거되다) → 정답 ✓","derrumbo: 1인칭 현재(나는 무너뜨린다)라 맞지 않습니다 ✗","derrumbó: 단순과거 활용형이라 ser 뒤에 올 수 없습니다 ✗","derrumbando: 현재분사라 ser와 수동태를 만들지 못합니다 ✗"]},{"id":"G266","q":"¿Cuántos años llevan ____ tus padres?","o":["casándose","casados","casando","casado"],"a":1,"k":"llevar + 과거분사","t":"너희 부모님은 결혼하신 지 몇 년 되셨어?","e":"'llevar + 시간 + 과거분사(형용사)'는 '~한 상태로 (시간이) 되다'라는 뜻입니다. casados(결혼한)는 상태를 나타내는 형용사로, 주어 tus padres(남성 복수)에 맞춰 casados가 됩니다. 예: Llevo dos horas sentado. (두 시간째 앉아 있다.)","x":["casándose: '결혼식을 올리는 중'이라는 진행 동작이라 맞지 않습니다 ✗","casados: 결혼한 상태 + 복수 일치 → 정답 ✓","casando: '결혼시키는 중'이라는 뜻이라 맞지 않습니다 ✗","casado: 단수형이라 복수 주어 padres와 맞지 않습니다 ✗"]},{"id":"G267","q":"Ahora no me pasa, pero antes me ____ vergüenza hablar en público.","o":["daba","estaba dando","había dado","dio"],"a":0,"k":"불완료과거 (과거 습관)","t":"지금은 안 그런데, 예전에는 사람들 앞에서 말하는 게 부끄러웠어.","e":"'antes(예전에)'처럼 과거에 반복되던 일이나 계속되던 상태는 불완료과거(pretérito imperfecto, 과거의 습관·배경을 나타내는 시제)로 말합니다. 'dar vergüenza'는 '부끄럽게 하다'라는 뜻으로 gustar처럼 me를 씁니다. 그래서 'me daba vergüenza'가 됩니다.","x":["daba: 불완료과거로 예전의 반복된 감정 → 정답 ✓","estaba dando: 진행형이라 과거 습관을 나타내지 않습니다 ✗","había dado: 과거완료라 다른 과거보다 이전 일을 말할 때 씁니다 ✗","dio: 단순과거로 한 번 일어난 일이라 '예전에 늘'이라는 뜻과 맞지 않습니다 ✗"]},{"id":"G268","q":"Aquí fue ____ conocí a mi esposo.","o":["cuando","como","cuanto","donde"],"a":3,"k":"관계부사 donde","t":"내가 남편을 만난 곳이 바로 여기야.","e":"'Aquí fue donde...'는 '~한 곳은 바로 여기였다'라는 강조 구문입니다. 장소(aquí)를 강조할 때는 관계부사 donde를 씁니다. 시간을 강조하면 cuando, 방법을 강조하면 como를 씁니다.","x":["cuando: 시간을 강조할 때 쓰므로 장소 aquí와 맞지 않습니다 ✗","como: 방법을 강조할 때 쓰므로 맞지 않습니다 ✗","cuanto: '~하는 만큼'이라 맞지 않습니다 ✗","donde: 장소를 강조하는 관계부사 → 정답 ✓"]},{"id":"G269","q":"¿____ es la isla más grande de Canarias?","o":["Qué","Quién","Cuál","Cuánta"],"a":2,"k":"cuál + ser","t":"카나리아 제도에서 가장 큰 섬은 어디야?","e":"ser 동사 앞에서 여러 개 중 하나를 특정하라고 물을 때는 qué가 아니라 cuál을 씁니다. '¿Cuál es...?'는 '~은 무엇/어느 것인가요?'라는 뜻입니다. 예: ¿Cuál es tu nombre? (네 이름이 뭐야?)","x":["Qué: ser 앞에서 하나를 특정할 때는 qué를 쓰지 않습니다(정의를 물을 때만 씀) ✗","Quién: 사람을 묻는 말이라 섬에 쓸 수 없습니다 ✗","Cuál: 여러 섬 중 하나를 특정 → 정답 ✓","Cuánta: '얼마나 많은'이라 맞지 않습니다 ✗"]},{"id":"G270","q":"Mis padres no me dejan ____ después de las doce de la noche.","o":["saliendo","salir","que salgo","a salir"],"a":1,"k":"dejar + 동사원형","t":"우리 부모님은 밤 12시 이후에 외출하는 것을 허락하지 않으셔.","e":"dejar가 '허락하다, ~하게 두다'라는 뜻일 때는 바로 동사원형이 옵니다. 'dejar a alguien + 동사원형'은 '누가 ~하도록 허락하다'입니다. que절을 쓴다면 'que salga'처럼 접속법이 필요합니다.","x":["saliendo: 현재분사라 dejar 뒤에 쓰지 않습니다 ✗","salir: dejar + 동사원형(~하게 허락하다) → 정답 ✓","que salgo: que절이면 접속법(salga)이 와야 합니다 ✗","a salir: dejar 뒤에 a를 쓰지 않습니다 ✗"]},{"id":"G271","q":"¿Te has fijado ____ los zapatos de esa señora?","o":["en","a","sobre","por"],"a":0,"k":"fijarse en","t":"저 아주머니 신발 봤어?","e":"fijarse(주목하다, 눈여겨보다)는 대상 앞에 전치사 en을 씁니다. '¿Te has fijado en ~?'는 '~ 눈여겨봤어?, ~ 봤어?'라는 표현입니다. 예: Fíjate en este detalle. (이 부분을 잘 봐.)","x":["en: fijarse en(~을 눈여겨보다) → 정답 ✓","a: fijarse와 함께 쓰지 않습니다 ✗","sobre: fijarse와 함께 쓰지 않습니다 ✗","por: fijarse와 함께 쓰지 않습니다 ✗"]},{"id":"G272","q":"Si ____ con nosotros, seguro que te lo pasas genial.","o":["vendrás","vendrías","vienes","vengas"],"a":2,"k":"조건문 si + 현재","t":"우리랑 같이 오면 분명 엄청 재밌게 보낼 거야.","e":"가능성이 있는 현실적인 조건은 'si + 직설법 현재'로 씁니다. 주절도 현재형(te lo pasas)으로 쓸 수 있습니다. si 뒤에는 미래형이나 조건법, 접속법 현재를 쓰지 않습니다.","x":["vendrás: 미래형은 조건의 si 뒤에 쓰지 않습니다 ✗","vendrías: 조건법은 si 뒤에 쓰지 않습니다 ✗","vienes: si + 직설법 현재 → 정답 ✓","vengas: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G273","q":"El hijo de Ana y José Manuel nació ____ 2 de octubre.","o":["el","del","la","al"],"a":0,"k":"날짜 앞 정관사 el","t":"아나와 호세 마누엘의 아들은 10월 2일에 태어났다.","e":"스페인어에서 날짜를 말할 때는 '~일에'를 전치사 없이 정관사 el로 나타냅니다. 'el 2 de octubre(10월 2일에)'처럼 씁니다. 요일도 마찬가지입니다: el lunes(월요일에).","x":["el: 날짜 앞 정관사(~일에) → 정답 ✓","del: de + el로 날짜 앞에 쓰지 않습니다 ✗","la: 여성형이라 날짜(día, 남성)에 맞지 않습니다 ✗","al: a + el로 날짜 앞에 쓰지 않습니다 ✗"]},{"id":"G274","q":"Estos ejercicios no son muy ____.","o":["faciles","fácil","fáciles","facil"],"a":2,"k":"형용사 복수·악센트","t":"이 연습 문제들은 그리 쉽지 않다.","e":"형용사는 주어(ejercicios, 복수)와 수를 맞추므로 복수형이 필요합니다. fácil은 끝에서 두 번째 음절에 강세가 있는 단어라 악센트가 있고, 복수 fáciles에서도 같은 음절에 강세가 있으므로 악센트를 유지합니다.","x":["faciles: 악센트가 빠져 철자가 틀립니다 ✗","fácil: 단수형이라 복수 주어와 맞지 않습니다 ✗","fáciles: 복수 + 올바른 악센트 → 정답 ✓","facil: 단수형인 데다 악센트도 빠졌습니다 ✗"]},{"id":"G275","q":"¿____ son esas chicas que están allí sentadas?","o":["Cuáles","Quién","Quiénes","Cuál"],"a":2,"k":"의문사 quiénes","t":"저기 앉아 있는 여자애들은 누구야?","e":"사람이 누구인지 물을 때는 quién을 쓰고, 여러 명이면 quiénes로 씁니다. 'esas chicas(그 여자애들)'가 복수이고 동사도 son이므로 quiénes가 맞습니다. cuál은 사람이 누구인지(정체)를 물을 때가 아니라 여럿 중 고를 때 씁니다.","x":["Cuáles: '어느 것들'이라 사람의 정체를 묻는 질문에 맞지 않습니다 ✗","Quién: 단수형이라 복수 son, chicas와 맞지 않습니다 ✗","Quiénes: 사람 복수 의문사 → 정답 ✓","Cuál: 단수인 데다 정체를 묻는 질문에 맞지 않습니다 ✗"]},{"id":"G276","q":"¿Cómo te fue en ____ entrevista que te hicieron ayer?","o":["el","una","ø","la"],"a":3,"k":"정관사 la","t":"어제 본 면접은 어떻게 됐어?","e":"'어제 너한테 한 그 면접'이라는 관계절로 특정한 면접을 가리키므로 정관사를 씁니다. entrevista(면접, 인터뷰)는 여성 명사라 la를 씁니다. '¿Cómo te fue en ~?'는 '~은 어떻게 됐어?'라는 자주 쓰는 표현입니다.","x":["el: 남성형이라 여성 명사 entrevista와 맞지 않습니다 ✗","una: 부정관사라 '어제의 그 면접'이라는 특정 대상과 맞지 않습니다 ✗","ø: 특정한 면접을 가리키므로 관사가 필요합니다 ✗","la: 여성 단수 정관사로 특정 면접 → 정답 ✓"]},{"id":"G277","q":"Vive desde hace cuatro años en Irlanda; ____, todavía le cuesta mucho hablar bien inglés.","o":["en cambio","pero","sin embargo","aunque"],"a":2,"k":"sin embargo (역접)","t":"그는 4년 전부터 아일랜드에 살고 있다. 그런데도 영어를 잘하는 게 여전히 아주 힘들다.","e":"sin embargo는 '그럼에도 불구하고, 그런데도'라는 역접 연결어로, 세미콜론(;)이나 마침표 뒤에 오고 뒤에 쉼표를 찍습니다. 4년을 살았는데도(기대) 영어가 어렵다(예상과 반대)는 흐름에 딱 맞습니다. pero는 보통 뒤에 쉼표를 찍지 않습니다.","x":["en cambio: '반면에'라는 대조로, 두 대상을 비교할 때 써서 이 흐름과 맞지 않습니다 ✗","pero: 뜻은 비슷하지만 ; 뒤에서 쉼표와 함께 쓰는 형태로는 어색합니다 ✗","sin embargo: '그런데도' 역접 연결어 → 정답 ✓","aunque: '~이지만'이라는 접속사로 이 문장 부호 구조에 맞지 않습니다 ✗"]},{"id":"G278","q":"¿____ quieres un auto tan grande?","o":["De qué","A qué","Para qué","En qué"],"a":2,"k":"para qué (목적)","t":"그렇게 큰 차가 왜(뭐 하려고) 필요해?","e":"'¿Para qué...?'는 '무엇을 위해, 뭐 하려고?'라는 목적을 묻는 질문입니다. 큰 차를 원하는 목적을 묻는 문맥이라 para qué가 맞습니다. '¿Por qué?'는 이유를 묻습니다. auto는 중남미에서 '자동차'로 많이 쓰고, 스페인에서는 coche를 씁니다.","x":["De qué: '무엇에 대해/무엇으로 된'이라 목적을 묻지 않습니다 ✗","A qué: '무엇에/몇 시에'라 맞지 않습니다 ✗","Para qué: 목적(뭐 하려고) → 정답 ✓","En qué: '무엇에서/무엇으로'라 맞지 않습니다 ✗"]},{"id":"G279","q":"____ no tenía suficiente dinero para comprar dos refrescos, compré solo uno.","o":["Que","Porque","Es que","Como"],"a":3,"k":"como (이유, 문두)","t":"음료수 두 개를 살 돈이 충분하지 않아서 하나만 샀다.","e":"como가 문장 맨 앞에 오면 '~이니까, ~해서'라는 이유를 나타냅니다. 이유절이 먼저 나오고 쉼표 뒤에 결과가 이어지는 구조에서는 porque가 아니라 como를 씁니다. porque는 보통 주절 뒤에 옵니다.","x":["Que: 문장 맨 앞에서 이유를 나타내지 않습니다 ✗","Porque: 이유절을 문장 맨 앞에 둘 때는 보통 쓰지 않습니다 ✗","Es que: 회화체 변명 표현이라 이런 복문 구조에 맞지 않습니다 ✗","Como: 문두에서 이유(~해서) → 정답 ✓"]},{"id":"G280","q":"¿Conoces a alguien que ____ ayudarme con las tareas de casa?","o":["puede","puedan","pueda","podía"],"a":2,"k":"미지의 선행사 + 접속법","t":"집안일을 도와줄 수 있는 사람 알아?","e":"있는지 없는지 모르는 사람(alguien)을 찾는 관계절에서는 접속법을 씁니다. alguien은 3인칭 단수이므로 pueda가 맞습니다. 이미 아는 사람이라면 직설법을 씁니다: Conozco a alguien que puede ayudarte.","x":["puede: 직설법이라 존재가 확실한 사람에게 씁니다 ✗","puedan: 복수형이라 단수 alguien과 맞지 않습니다 ✗","pueda: 접속법 현재 단수 → 정답 ✓","podía: 직설법 과거라 현재 질문과 맞지 않습니다 ✗"]},{"id":"G281","q":"¿____ os pareció la propuesta de Carla?","o":["Por qué","Cuál","Cuándo","Qué"],"a":3,"k":"qué + parecer","t":"카를라의 제안 어땠어?","e":"'¿Qué te/os parece...?'는 '~ 어때?, ~ 어떻게 생각해?'라는 의견을 묻는 표현입니다. 과거형으로 '¿Qué os pareció?'는 '어땠어?'가 됩니다. 한국어 '어떻게'에 끌려 cómo를 생각하기 쉽지만 parecer와는 qué를 씁니다.","x":["Por qué: 이유를 묻는 말이라 의견을 묻는 표현과 맞지 않습니다 ✗","Cuál: parecer와 함께 의견을 묻는 데 쓰지 않습니다 ✗","Cuándo: '언제'라 맞지 않습니다 ✗","Qué: ¿Qué os pareció?(어땠어?) → 정답 ✓"]},{"id":"G282","q":"Aurelia y Felipe ____ llevan muy bien, por eso trabajan juntos.","o":["le","se lo","se","es"],"a":2,"k":"llevarse bien","t":"아우렐리아와 펠리페는 사이가 아주 좋아서 함께 일한다.","e":"'llevarse bien/mal'은 '사이가 좋다/나쁘다'라는 재귀동사 표현입니다. 주어가 두 사람(3인칭 복수)이므로 재귀대명사 se를 씁니다. 이 표현에서 se는 '서로'라는 상호의 의미도 있습니다.","x":["le: 간접목적격이라 재귀 표현이 되지 않습니다 ✗","se lo: lo가 더해지면 '그것을 가져가다'라는 다른 뜻이 됩니다 ✗","se: llevarse bien(사이가 좋다) → 정답 ✓","es: ser 동사라 문장 구조가 성립하지 않습니다 ✗"]},{"id":"G283","q":"Llegué al aeropuerto tan pronto ____ pude.","o":["cuanto","que","cual","como"],"a":3,"k":"tan pronto como","t":"나는 최대한 빨리 공항에 도착했다.","e":"'tan pronto como ~'는 '~하자마자, 가능한 한 빨리'라는 뜻의 표현입니다. 'tan pronto como pude'는 '할 수 있는 한 빨리'입니다. tan과 짝을 이루는 말은 항상 como입니다.","x":["cuanto: 'en cuanto(~하자마자)'에 쓰지만 tan pronto 뒤에는 쓰지 않습니다 ✗","que: tan과 짝을 이루지 않습니다 ✗","cual: tan과 짝을 이루지 않습니다 ✗","como: tan pronto como(~하자마자) → 정답 ✓"]},{"id":"G284","q":"Cada vez que ____ a ese parque, veo a Luisa con su perro.","o":["voy","iré","iría","vaya"],"a":0,"k":"cada vez que + 직설법","t":"그 공원에 갈 때마다 강아지와 함께 있는 루이사를 본다.","e":"'cada vez que(~할 때마다)'가 실제로 반복되는 습관을 말할 때는 직설법 현재를 씁니다. 주절 veo도 현재형이라 voy가 맞습니다. 미래의 일이라면 접속법(Cada vez que vaya...)을 씁니다.","x":["voy: 직설법 현재로 반복되는 습관 → 정답 ✓","iré: 미래형은 cada vez que 뒤에 쓰지 않습니다 ✗","iría: 조건법이라 맞지 않습니다 ✗","vaya: 접속법은 미래의 일일 때 쓰고 현재 습관에는 쓰지 않습니다 ✗"]},{"id":"G285","q":"No voy a parar de llamar a Pepe hasta que ____ al teléfono.","o":["responderá","va a responder","responde","responda"],"a":3,"k":"hasta que + 접속법","t":"페페가 전화를 받을 때까지 계속 전화할 거야.","e":"'hasta que(~할 때까지)'가 아직 일어나지 않은 미래의 일을 가리킬 때는 접속법을 씁니다. 페페가 전화를 받는 건 아직 일어나지 않은 일이므로 접속법 현재 responda가 맞습니다.","x":["responderá: 미래형은 hasta que 뒤에 쓰지 않습니다 ✗","va a responder: 직설법 미래 표현이라 쓰지 않습니다 ✗","responde: 직설법 현재라 미래의 일에 쓰지 않습니다 ✗","responda: 접속법 현재로 아직 일어나지 않은 일 → 정답 ✓"]},{"id":"G286","q":"Soy contable, pero estoy ____ camarero en un conocido restaurante.","o":["a","por","para","de"],"a":3,"k":"estar de + 직업","t":"나는 회계사인데, 지금은 유명한 식당에서 웨이터로 일하고 있다.","e":"'ser + 직업'은 본래 직업을, 'estar de + 직업'은 '임시로 ~로 일하고 있다'를 나타냅니다. 원래는 회계사(soy contable)지만 지금은 임시로 웨이터 일을 한다는 대조이므로 estar de가 맞습니다. 중남미에서는 contable 대신 contador를 많이 씁니다.","x":["a: estar 뒤 직업에 쓰지 않습니다 ✗","por: estar por는 '~할 참이다'라는 다른 뜻입니다 ✗","para: estar para도 '~할 참이다'라는 뜻이라 맞지 않습니다 ✗","de: estar de + 직업(임시로 ~로 일하다) → 정답 ✓"]},{"id":"G287","q":"El segundo episodio de esta serie no es ____ interesante.","o":["algo","nadie","algún","nada"],"a":3,"k":"no ... nada (전혀)","t":"이 드라마 2화는 전혀 재미없다.","e":"'no ... nada + 형용사'는 '전혀 ~하지 않다'라는 강한 부정입니다. nada는 여기서 '전혀'라는 부사로 쓰이며 형태가 변하지 않습니다. 'No es nada interesante'는 '전혀 흥미롭지 않다'입니다.","x":["algo: '약간'이라는 긍정 표현이라 no와 함께 쓰지 않습니다 ✗","nadie: '아무도'라는 사람 대명사라 형용사 앞에 쓰지 않습니다 ✗","algún: 명사 앞에만 쓰는 형용사라 맞지 않습니다 ✗","nada: no와 함께 '전혀' → 정답 ✓"]},{"id":"G288","q":"No podré quedar contigo ____ la tarde, tengo que trabajar.","o":["por","de","para","entre"],"a":0,"k":"por la tarde","t":"오후에는 너랑 만날 수 없을 거야. 일해야 하거든.","e":"하루의 시간대를 말할 때 스페인에서는 'por la mañana/tarde/noche(아침/오후/밤에)'처럼 por를 씁니다. 중남미에서는 'en la tarde'나 'a la tarde'도 많이 씁니다. 'de la tarde'는 'a las cinco de la tarde(오후 5시)'처럼 정확한 시각 뒤에 씁니다.","x":["por: 하루 중 시간대(~에) → 정답 ✓","de: 정확한 시각 뒤에만 쓰고 단독으로는 쓰지 않습니다 ✗","para: 기한·목적을 나타내 시간대 표현이 되지 않습니다 ✗","entre: '~사이에'라 맞지 않습니다 ✗"]},{"id":"G289","q":"Ayer me compré ____ par de camisetas de deporte.","o":["la","una","un","el"],"a":2,"k":"un par de","t":"어제 운동용 티셔츠 두어 장을 샀다.","e":"'un par de ~'는 '한 쌍의, 두어 개의'라는 뜻입니다. par는 남성 명사이므로 un을 씁니다. 처음 언급하는 특정하지 않은 물건이므로 정관사(el)가 아니라 부정관사가 자연스럽습니다.","x":["la: 여성형이라 남성 명사 par와 맞지 않습니다 ✗","una: 여성형이라 맞지 않습니다 ✗","un: un par de(두어 개의) → 정답 ✓","el: 정관사라 '특정한 그 한 쌍'이 되어 어색합니다 ✗"]},{"id":"G290","q":"¿Quién ____ ha dicho eso a mi hijo?","o":["le lo","le","se","lo"],"a":1,"k":"중복 간접목적격 le","t":"누가 우리 아들한테 그런 말을 했어?","e":"스페인어에서는 간접목적어(a mi hijo)가 있어도 동사 앞에 간접목적격 대명사 le를 함께 쓰는 것이 자연스럽습니다. 직접목적어 eso는 이미 명사로 나와 있으므로 lo를 또 쓰지 않습니다. 대명사 두 개를 쓸 때 le lo는 se lo로 바뀝니다.","x":["le lo: le와 lo가 함께 올 때는 se lo로 바뀌고, eso가 있어 lo도 필요 없습니다 ✗","le: a mi hijo를 받는 간접목적격 → 정답 ✓","se: 간접목적격 단독으로는 le를 써야 합니다 ✗","lo: 직접목적격이라 '아들에게'를 받을 수 없습니다 ✗"]},{"id":"G291","q":"Jero no habla tanto ____ su hermano.","o":["como","que","cómo","de"],"a":0,"k":"tanto como (동등비교)","t":"헤로는 자기 형만큼 말이 많지 않다.","e":"동사 뒤에서 '~만큼 (많이)'라고 할 때는 'tanto como'를 씁니다. tanto와 짝을 이루는 말은 항상 como입니다. 'No habla tanto como su hermano'는 '형만큼 많이 말하지 않는다'라는 뜻입니다.","x":["como: tanto와 짝을 이루는 동등 비교 → 정답 ✓","que: más/menos와 짝을 이루며 tanto와는 쓰지 않습니다 ✗","cómo: 악센트 있는 의문사(어떻게)라 비교 구문에 쓰지 않습니다 ✗","de: tanto와 짝을 이루지 않습니다 ✗"]},{"id":"G292","q":"¿Por qué ____ a Pedro de su anterior trabajo?","o":["despedían","despidieron","se despedían","se despidieron"],"a":1,"k":"despedir vs despedirse","t":"왜 페드로를 이전 직장에서 해고했어?","e":"despedir a alguien은 '누군가를 해고하다'라는 타동사입니다. 재귀형 despedirse는 '작별 인사를 하다'라는 다른 뜻이 됩니다. 과거에 한 번 일어난 해고이므로 단순과거 despidieron(그들이 해고했다)을 씁니다. 주어를 밝히지 않는 3인칭 복수는 '누군가가'라는 무인칭 의미입니다.","x":["despedían: 불완료과거라 한 번의 해고 사건과 맞지 않습니다 ✗","despidieron: 단순과거로 해고한 사건 → 정답 ✓","se despedían: '작별 인사를 하곤 했다'라는 뜻이 됩니다 ✗","se despidieron: '작별 인사를 했다'라는 뜻이 됩니다 ✗"]},{"id":"G293","q":"¿Por qué se suspendió el último partido ____ fútbol?","o":["en","a","de","sobre"],"a":2,"k":"명사 + de + 명사","t":"지난 축구 경기는 왜 취소됐어?","e":"'partido de fútbol(축구 경기)'처럼 종류를 나타낼 때는 'de + 명사'로 연결합니다. 관사 없이 de만 씁니다. 예: clase de español(스페인어 수업), libro de cocina(요리책).","x":["en: 종류를 나타내는 연결에 쓰지 않습니다 ✗","a: 종류를 나타내는 연결에 쓰지 않습니다 ✗","de: partido de fútbol(축구 경기) → 정답 ✓","sobre: '~에 관한'이라 경기 종류에 쓰지 않습니다 ✗"]},{"id":"G294","q":"Como el domingo pasado ____ todo el día, decidí quedarme en casa.","o":["lloviera","llovería","llovía","estuvo lloviendo"],"a":3,"k":"단순과거 진행형","t":"지난 일요일 하루 종일 비가 와서 집에 있기로 했다.","e":"'el domingo pasado(지난 일요일)', 'todo el día(하루 종일)'처럼 끝난 기간 동안 계속된 행동은 'estar 단순과거 + 현재분사'로 표현할 수 있습니다. estuvo lloviendo는 '(그 하루 동안) 계속 비가 왔다'는 뜻으로, 끝난 기간의 지속을 강조합니다. como가 문두에서 이유를 나타내므로 직설법이 와야 합니다.","x":["lloviera: 접속법이라 이유의 como 뒤에 쓰지 않습니다 ✗","llovería: 조건법이라 실제 일어난 과거에 쓰지 않습니다 ✗","llovía: 배경 묘사로 쓸 수는 있지만, 끝난 기간(todo el día)의 지속을 나타내는 데는 단순과거 진행형이 더 적절합니다 ✗","estuvo lloviendo: 끝난 기간 동안 계속된 행동 → 정답 ✓"]},{"id":"G295","q":"Es demasiado tarde, ____ será mejor hacer la llamada mañana.","o":["aunque","así que","porque","como"],"a":1,"k":"así que (결과)","t":"너무 늦었으니까 전화는 내일 하는 게 좋겠어.","e":"así que는 '그래서, 그러니까'라는 결과를 나타내는 접속사로, 앞에 이유가 오고 뒤에 결과가 옵니다. '너무 늦었다(이유) → 내일 전화하는 게 낫다(결과)'라는 흐름이므로 así que가 맞습니다.","x":["aunque: '~이지만'이라 역접이 되어 흐름과 맞지 않습니다 ✗","así que: 결과(그래서) → 정답 ✓","porque: 이유(왜냐하면)를 이끌어 인과 순서가 반대가 됩니다 ✗","como: 이유의 como는 문장 맨 앞에 오므로 여기서는 쓸 수 없습니다 ✗"]},{"id":"G296","q":"¿Puedes decirme qué pone en ese cartel? No ____ veo bien.","o":["la","lo","les","las"],"a":1,"k":"중성 직접목적격 lo","t":"저 표지판에 뭐라고 쓰여 있는지 말해 줄래? 잘 안 보여.","e":"'qué pone(뭐라고 쓰여 있는지)'처럼 내용 전체를 가리킬 때는 중성 직접목적격 대명사 lo를 씁니다. 'No lo veo bien'은 '그게 잘 안 보인다'입니다. 'pone'는 스페인에서 '(글이) 쓰여 있다'는 뜻으로 쓰고, 중남미에서는 dice를 씁니다.","x":["la: 여성 명사를 받는 대명사라 내용 전체를 가리키지 못합니다 ✗","lo: 중성 직접목적격(그것을) → 정답 ✓","les: 간접목적격 복수(그들에게)라 맞지 않습니다 ✗","las: 여성 복수 직접목적격이라 맞지 않습니다 ✗"]},{"id":"G297","q":"Somos hermanos, ____ nos parecemos tanto.","o":["porque","por eso","ya que","a causa de que"],"a":1,"k":"por eso (결과)","t":"우리는 형제야. 그래서 이렇게 많이 닮았어.","e":"por eso는 '그래서, 그 때문에'라는 결과를 나타냅니다. '형제다(이유) → 닮았다(결과)'라는 순서이므로 por eso가 맞습니다. porque, ya que, a causa de que는 모두 이유를 이끄는 말이라 인과 순서가 반대가 됩니다.","x":["porque: '왜냐하면'으로 '닮았기 때문에 형제다'가 되어 어색합니다 ✗","por eso: 결과(그래서) → 정답 ✓","ya que: '~이므로'라는 이유 접속사라 순서가 맞지 않습니다 ✗","a causa de que: '~때문에'라는 이유 표현이라 순서가 맞지 않습니다 ✗"]},{"id":"G298","q":"Si ____ más ejercicio físico, te encontrarías mejor.","o":["hicieras","hagas","harías","harás"],"a":0,"k":"가정문 si + 접속법 과거","t":"운동을 더 하면 몸이 더 좋아질 텐데.","e":"주절이 조건법(te encontrarías)이면 si절에는 접속법 과거를 씁니다. hacer의 tú 접속법 과거는 hicieras입니다. 'si + 접속법 과거, 조건법'은 현재 사실과 다르거나 가정적인 상황을 말합니다.","x":["hicieras: 접속법 과거로 조건법 주절과 짝 → 정답 ✓","hagas: 접속법 현재는 si 뒤에 쓰지 않습니다 ✗","harías: 조건법은 si절에 쓰지 않습니다 ✗","harás: 미래형은 si절에 쓰지 않습니다 ✗"]},{"id":"G299","q":"Ojalá pudiera bailar como ____.","o":["vos","te","ti","a ti"],"a":0,"k":"como + 주격 (vos)","t":"너처럼 춤출 수 있으면 좋겠어.","e":"비교의 como 뒤에는 주격 대명사(yo, tú, vos)를 씁니다. como는 전치사가 아니므로 ti를 쓰지 않습니다. 이 문제에서는 tú 대신 아르헨티나·우루과이 등에서 쓰는 vos(너)가 정답으로 제시되었습니다. 스페인이나 대부분의 지역에서는 'como tú'라고 합니다.","x":["vos: 중남미 일부 지역의 주격 '너' → 정답 ✓","te: 목적격이라 como 뒤에 쓸 수 없습니다 ✗","ti: 전치사 뒤에 쓰는 형태라 como 뒤에는 쓰지 않습니다 ✗","a ti: 전치사 a가 붙어 '너에게'가 되므로 맞지 않습니다 ✗"]},{"id":"G300","q":"El concierto fue un éxito. Fue ____ montón de gente.","o":["uno","un","el","ø"],"a":1,"k":"un montón de","t":"콘서트는 대성공이었어. 엄청 많은 사람들이 왔어.","e":"'un montón de ~'는 '엄청 많은 ~'이라는 회화 표현입니다. montón은 남성 명사라 un을 씁니다. 여기서 fue는 ser가 아니라 ir(가다)의 단순과거로, 'Fue un montón de gente'는 '사람들이 엄청 많이 갔다(왔다)'는 뜻입니다.","x":["uno: 명사 앞에서는 un으로 줄어듭니다 ✗","un: un montón de(엄청 많은) → 정답 ✓","el: 정관사를 쓰면 관용 표현이 되지 않습니다 ✗","ø: montón은 관사 없이 쓰지 않습니다 ✗"]},{"id":"G301","q":"Los niños están viendo ____ la televisión.","o":["de","a","ø","en"],"a":2,"k":"ver + 직접목적어","t":"아이들이 텔레비전을 보고 있다.","e":"ver(보다)는 타동사라서 '무엇을 보는지'를 전치사 없이 바로 씁니다. 'la televisión'은 사물이므로 전치사 a도 필요 없습니다. 예: Veo la película. (나는 영화를 본다.)","x":["de: '~의/~에서'라는 뜻으로 ver 뒤에 목적어를 연결하지 않습니다 ✗","a: 사람 직접목적어 앞에 쓰는 전치사인데 텔레비전은 사물이라 ✗","ø: 사물 직접목적어는 전치사 없이 바로 씁니다 → 정답 ✓","en: '~안에서'로, 'ver en la televisión'은 'TV에서 (무언가를) 보다'라는 다른 뜻이라 ✗"]},{"id":"G302","q":"Me gustaría saludar ____ todos los invitados.","o":["por","a","de","ø"],"a":1,"k":"인칭 전치사 a","t":"모든 손님들께 인사드리고 싶습니다.","e":"직접목적어(~을/를)가 사람이면 그 앞에 전치사 a를 넣는데, 이를 '인칭 a'라고 합니다. saludar(인사하다)의 대상인 'todos los invitados(모든 손님)'가 사람이므로 a가 필요합니다. 예: Saludé a mi profesor. (나는 선생님께 인사했다.)","x":["por: 이유·경로를 나타내며 saludar의 대상을 표시하지 않습니다 ✗","a: 사람 직접목적어 앞의 인칭 a → 정답 ✓","de: '~의/~로부터'라는 뜻으로 맞지 않습니다 ✗","ø: 대상이 사람이므로 a를 생략할 수 없습니다 ✗"]},{"id":"G303","q":"Hasta el domingo pasado yo nunca ____ ningún plato típico de Polonia.","o":["había probado","he probado","probaba","estaba probando"],"a":0,"k":"과거완료","t":"지난 일요일까지 나는 폴란드 전통 요리를 한 번도 먹어 본 적이 없었다.","e":"'Hasta el domingo pasado(지난 일요일까지)'처럼 과거의 한 시점을 기준으로 그 이전의 경험을 말할 때는 과거완료(había + 과거분사, '~했었다')를 씁니다. 기준점이 과거이므로 현재완료(he probado)는 쓸 수 없습니다. 예: Nunca había visto el mar. (나는 바다를 본 적이 없었다.)","x":["había probado: 과거 기준점 이전의 경험을 나타내는 과거완료 → 정답 ✓","he probado: 현재완료로, 현재까지의 경험을 말할 때 쓰므로 과거 기준점과 맞지 않습니다 ✗","probaba: 불완료과거(과거의 습관·배경)로 '한 번도 ~해 본 적 없었다'는 경험 의미를 못 냅니다 ✗","estaba probando: 과거진행(~하고 있었다)으로 경험을 말하는 문맥과 맞지 않습니다 ✗"]},{"id":"G304","q":"¿Han leído ____ obra de Cortázar?","o":["alguna","ninguna","algún","ningún"],"a":0,"k":"alguno/ninguno","t":"코르타사르의 작품을 읽어 본 적 있으세요?","e":"긍정 의문문에서 '어떤 ~라도'를 물을 때는 alguno를 씁니다. obra(작품)는 여성 명사이므로 여성형 alguna가 됩니다. ninguno는 부정문에서 '하나도 ~않다'라는 뜻으로 씁니다. 예: ¿Tienes alguna pregunta? (질문 있니?)","x":["alguna: 여성 단수 명사 obra 앞의 '어떤' → 정답 ✓","ninguna: '하나도 (없다)'라는 부정 의미라 긍정 의문문과 맞지 않습니다 ✗","algún: 남성 단수 명사 앞 형태라 여성 명사 obra와 맞지 않습니다 ✗","ningún: 남성형이면서 부정 의미라 두 가지 모두 맞지 않습니다 ✗"]},{"id":"G305","q":"Una amiga ____ está viviendo en China.","o":["de mí","de mía","mi","mía"],"a":3,"k":"강세형 소유사","t":"내 친구 한 명이 중국에 살고 있다.","e":"'una amiga mía'는 '내 친구들 중 한 명'이라는 뜻으로, 명사 뒤에 오는 강세형 소유사(mío, mía, míos, mías)를 씁니다. amiga가 여성 단수이므로 mía가 됩니다. 'mi amiga'는 명사 앞에만 올 수 있어서 'una amiga mi'는 틀립니다.","x":["de mí: 스페인어에서 '나의'를 de mí로 표현하지 않습니다 ✗","de mía: 소유사 앞에 de를 붙이지 않습니다 ✗","mi: 단축형 소유사는 명사 앞에만 쓰므로 명사 뒤에 올 수 없습니다 ✗","mía: 명사 뒤에 오는 여성 단수 강세형 소유사 → 정답 ✓"]},{"id":"G306","q":"Disculpa la tardanza, es que ____ el autobús.","o":["estaba perdiendo","he perdido","estuve perdiendo","perdía"],"a":1,"k":"현재완료","t":"늦어서 미안해, 버스를 놓쳤거든.","e":"방금 일어나 현재(늦게 도착한 상황)와 직접 연결된 일을 말할 때 스페인에서는 현재완료(he + 과거분사)를 주로 씁니다. 'es que ~'는 '실은 ~해서'라고 변명이나 이유를 말할 때 쓰는 표현입니다. 참고로 중남미에서는 'perdí el autobús'처럼 단순과거를 더 많이 씁니다.","x":["estaba perdiendo: 과거진행으로 '놓치고 있었다'가 되어 어색합니다 ✗","he perdido: 현재와 이어지는 방금 끝난 일을 나타내는 현재완료 → 정답 ✓","estuve perdiendo: 일정 기간 계속된 행동에 쓰는 형태로, 한순간의 '놓치다'와 맞지 않습니다 ✗","perdía: 불완료과거로 반복·습관 의미가 되어 맞지 않습니다 ✗"]},{"id":"G307","q":"Pensé que ____ enojada conmigo, por eso te pedí que habláramos.","o":["estuviste","has estado","estuvieras","estabas"],"a":3,"k":"불완료과거","t":"네가 나한테 화가 나 있다고 생각했어, 그래서 이야기하자고 한 거야.","e":"'Pensé que ~(~라고 생각했다)'처럼 과거에 생각한 내용 안에서 그때의 상태를 말할 때는 불완료과거(estabas)를 씁니다. pensar que가 긍정이면 뒤에 직설법이 오므로 접속법 estuvieras는 쓰지 않습니다. 예: Creí que estabas en casa. (네가 집에 있는 줄 알았어.)","x":["estuviste: 단순과거로 끝난 일을 말할 때 쓰며, 그때의 지속 상태 묘사에는 어색합니다 ✗","has estado: 현재완료로 과거 시점의 생각 안에 넣기 어렵습니다 ✗","estuvieras: 접속법 과거로, 긍정의 pensar que 뒤에는 직설법을 씁니다 ✗","estabas: 과거의 상태를 묘사하는 불완료과거 → 정답 ✓"]},{"id":"G308","q":"Tengo cita con mi médico mañana ____ la mañana.","o":["para","entre","por","de"],"a":2,"k":"por la mañana","t":"나는 내일 오전에 의사와 진료 예약이 있다.","e":"하루의 시간대를 말할 때 '오전에, 오후에, 밤에'는 'por la mañana, por la tarde, por la noche'라고 합니다. 반면 시각과 함께 쓸 때는 de를 씁니다(a las 9 de la mañana). 중남미 일부 지역에서는 'en la mañana'도 많이 씁니다.","x":["para: 목적·기한을 나타내며 시간대 표현에 쓰지 않습니다 ✗","entre: '~사이에'라는 뜻으로 맞지 않습니다 ✗","por: 'por la mañana(오전에)' 고정 표현 → 정답 ✓","de: 'de la mañana'는 시각 뒤에서만 씁니다(a las 10 de la mañana) ✗"]},{"id":"G309","q":"____ que hayas dejado de fumar.","o":["Me alegras","Me alegra","Me alegran","Me alegro"],"a":1,"k":"alegrar 구문","t":"네가 담배를 끊어서 기쁘다.","e":"'Me alegra que ~'는 gustar처럼 'que 이하의 일이 나를 기쁘게 한다'는 구조라서 동사는 3인칭 단수 alegra가 됩니다. 감정을 나타내므로 que 뒤에는 접속법(hayas dejado)이 옵니다. 재귀동사로 쓰면 'Me alegro de que ~'처럼 de가 꼭 필요합니다.","x":["Me alegras: '네가 나를 기쁘게 한다'로, 주어가 que절이라는 구조와 맞지 않습니다 ✗","Me alegra: que절을 주어로 하는 3인칭 단수 → 정답 ✓","Me alegran: 3인칭 복수로, 주어(que절)가 단수 취급이라 ✗","Me alegro: 재귀형이면 'Me alegro de que'처럼 de가 필요해서 ✗"]},{"id":"G310","q":"Amelia ____ la hermana de mi amigo Ramón.","o":["eres","es","está","estás"],"a":1,"k":"ser vs estar","t":"아멜리아는 내 친구 라몬의 여동생(누나)이다.","e":"신분·관계(누구인지)를 말할 때는 ser를 씁니다. 주어 Amelia는 3인칭 단수이므로 es가 됩니다. estar는 위치나 일시적 상태에 씁니다. 예: Ella es mi prima. (그녀는 내 사촌이다.)","x":["eres: ser의 2인칭 단수(너는 ~이다)라 주어와 맞지 않습니다 ✗","es: 관계·신분을 나타내는 ser의 3인칭 단수 → 정답 ✓","está: estar는 위치·상태에 쓰므로 가족 관계에는 쓰지 않습니다 ✗","estás: estar의 2인칭 형태이며 의미도 맞지 않습니다 ✗"]},{"id":"G311","q":"Estoy preocupado ____ la salud de mi madre.","o":["a","por","para","de"],"a":1,"k":"preocupado por","t":"나는 어머니의 건강이 걱정된다.","e":"'estar preocupado por ~'는 '~에 대해 걱정하다'라는 고정 표현입니다. por가 걱정의 원인이나 대상을 나타냅니다. 예: Estamos preocupados por el examen. (우리는 시험이 걱정이다.)","x":["a: preocupado와 함께 쓰지 않는 전치사입니다 ✗","por: 걱정의 원인·대상을 나타내는 preocupado por → 정답 ✓","para: 목적을 나타내어 '건강을 위해 걱정한다'라는 어색한 뜻이 됩니다 ✗","de: preocupado de는 일반적인 표현이 아닙니다 ✗"]},{"id":"G312","q":"Yo nací antes que Rafaela, así que soy ____.","o":["mayor","de su edad","más","menor"],"a":0,"k":"mayor/menor","t":"나는 라파엘라보다 먼저 태어났으니까 내가 언니(누나)다.","e":"나이가 더 많은 것은 mayor(더 나이 많은), 더 어린 것은 menor(더 어린)로 표현합니다. 라파엘라보다 먼저 태어났으므로 나이가 더 많아 mayor가 맞습니다. 예: Mi hermano mayor tiene 20 años. (우리 형은 20살이다.)","x":["mayor: '나이가 더 많은'이라는 뜻 → 정답 ✓","de su edad: '그녀 또래의'라는 뜻이라 먼저 태어났다는 내용과 맞지 않습니다 ✗","más: 혼자서는 '더'라는 뜻일 뿐 무엇이 더한지 나타내지 못합니다 ✗","menor: '더 어린'이라는 뜻이라 반대입니다 ✗"]},{"id":"G313","q":"Hija mía, deberías ____ ya.","o":["acostarse","acostar","acostarte","te acostar"],"a":2,"k":"재귀동사 부정사","t":"딸아, 이제 그만 자러 가야지.","e":"acostarse(잠자리에 들다)는 재귀동사(자기 자신에게 동작이 돌아오는 동사)이고, 부정사로 쓸 때는 대명사를 끝에 붙입니다. 말하는 상대가 tú(너)이므로 acostarte가 됩니다. 'te debes acostar'처럼 활용 동사 앞에 둘 수도 있지만, 부정사 바로 앞에는 둘 수 없습니다.","x":["acostarse: 3인칭(그/그녀) 형태라 '너'에게 말하는 문장과 맞지 않습니다 ✗","acostar: 재귀대명사가 없으면 '(누군가를) 눕히다'라는 뜻이 됩니다 ✗","acostarte: 2인칭 재귀대명사 te를 부정사 끝에 붙인 형태 → 정답 ✓","te acostar: 대명사를 부정사 앞에 따로 둘 수 없습니다 ✗"]},{"id":"G314","q":"Nos fuimos de la playa ____ empezó a llover.","o":["al","en cuanto","después de","cuanto"],"a":1,"k":"en cuanto","t":"비가 오기 시작하자마자 우리는 해변을 떠났다.","e":"en cuanto는 '~하자마자'라는 뜻의 접속사로, 뒤에 활용된 동사(empezó)가 옵니다. 과거에 실제 일어난 일이므로 직설법을 씁니다. 'al'이나 'después de'는 뒤에 동사원형이 와야 합니다.","x":["al: 'al + 동사원형' 형태라 활용 동사 empezó와 쓸 수 없습니다 ✗","en cuanto: '~하자마자', 뒤에 활용 동사가 오는 접속사 → 정답 ✓","después de: 뒤에 동사원형이 와야 하므로 ✗(después de que라면 가능)","cuanto: 혼자서는 '~만큼'이라는 뜻으로 시간 접속사가 아닙니다 ✗"]},{"id":"G315","q":"Prefiero ____ aquí hasta que deje de llover.","o":["me quedar","que me quede","me quedo","quedarme"],"a":3,"k":"preferir + 부정사","t":"비가 그칠 때까지 여기 있는 게 좋겠어.","e":"preferir(선호하다) 뒤에 주어가 같은 행동이 오면 동사원형을 씁니다. quedarse(머무르다)는 재귀동사라 대명사를 끝에 붙여 quedarme가 됩니다. 주어가 다를 때만 'Prefiero que te quedes(네가 남았으면 해)'처럼 que + 접속법을 씁니다.","x":["me quedar: 대명사를 부정사 앞에 따로 둘 수 없습니다 ✗","que me quede: 주어가 같은데 que절을 쓰는 것은 부자연스럽습니다 ✗","me quedo: 활용 동사 두 개를 연달아 쓸 수 없습니다 ✗","quedarme: preferir + 동사원형, 대명사를 끝에 붙인 형태 → 정답 ✓"]},{"id":"G316","q":"____ nosotros no hay ningún problema.","o":["Sobre","Hacia","Entre","A"],"a":2,"k":"전치사 entre","t":"우리 사이에는 아무 문제도 없어.","e":"entre는 '~사이에'라는 뜻으로, 사람들 사이의 관계를 말할 때 씁니다. 'Entre nosotros'는 '우리 사이에'라는 뜻입니다. entre 뒤에는 mí, ti가 아니라 yo, tú를 쓴다는 점도 기억하세요(entre tú y yo).","x":["Sobre: '~위에/~에 대해'라는 뜻으로 맞지 않습니다 ✗","Hacia: '~쪽으로'라는 방향을 나타내 맞지 않습니다 ✗","Entre: '~사이에' → 정답 ✓","A: '~에게/~로'로 의미가 통하지 않습니다 ✗"]},{"id":"G317","q":"¿A qué ____ tu mal humor?","o":["se debe","deberse","deber","debe"],"a":0,"k":"deberse a","t":"네 기분이 안 좋은 건 무엇 때문이니?","e":"'deberse a ~'는 '~때문이다, ~에 기인하다'라는 뜻의 재귀 표현입니다. 주어가 'tu mal humor(너의 나쁜 기분)'으로 3인칭 단수이므로 se debe가 됩니다. 예: El retraso se debe a la lluvia. (지연은 비 때문이다.)","x":["se debe: '~때문이다'인 deberse a의 3인칭 단수 → 정답 ✓","deberse: 동사원형은 문장의 본동사로 쓸 수 없습니다 ✗","deber: 원형이고 재귀대명사도 없어 ✗","debe: se 없이 쓰면 '~해야 한다/빚지다'라는 뜻이 되어 ✗"]},{"id":"G318","q":"Mis amigos no son españoles, ____ hablan muy bien español.","o":["pero","por eso","así que","dado que"],"a":0,"k":"접속사 pero","t":"내 친구들은 스페인 사람이 아니지만, 스페인어를 아주 잘한다.","e":"앞 내용(스페인 사람이 아니다)과 뒷 내용(스페인어를 잘한다)이 서로 대조되므로 '하지만'을 뜻하는 pero를 씁니다. 다른 보기들은 모두 원인이나 결과를 나타내서 흐름이 맞지 않습니다.","x":["pero: '하지만', 대조를 나타냄 → 정답 ✓","por eso: '그래서'라는 결과 표현이라 논리가 맞지 않습니다 ✗","así que: '그러니까'라는 결과 표현이라 ✗","dado que: '~이므로'라는 이유 표현이라 ✗"]},{"id":"G319","q":"Estoy acostumbrado a cenar a las 8 ____ noche.","o":["a la","para la","desde la","de la"],"a":3,"k":"de la noche","t":"나는 밤 8시에 저녁을 먹는 데 익숙하다.","e":"구체적인 시각 뒤에 시간대를 붙일 때는 de를 씁니다: a las 8 de la noche(밤 8시), a las 10 de la mañana(오전 10시). 시각 없이 시간대만 말할 때는 por la noche(밤에)를 씁니다.","x":["a la: 시각 뒤 시간대에 a를 쓰지 않습니다 ✗","para la: 목적·기한의 para는 여기서 맞지 않습니다 ✗","desde la: '~부터'라는 뜻이라 ✗","de la: 시각 + de la noche → 정답 ✓"]},{"id":"G320","q":"El concierto ____ a causa del mal tiempo.","o":["estuvo cancelado","fue cancelado","ha cancelado","canceló"],"a":1,"k":"수동태 ser + 과거분사","t":"콘서트는 악천후 때문에 취소되었다.","e":"'취소되었다'처럼 주어가 행동을 당하는 수동태는 'ser + 과거분사'로 만듭니다. 과거에 한 번 일어난 일이므로 ser의 단순과거 fue를 써서 fue cancelado가 됩니다. 'se canceló'라고 해도 같은 뜻입니다.","x":["estuvo cancelado: estar + 과거분사는 상태를 말하며 '취소되었다'는 사건을 나타내지 못합니다 ✗","fue cancelado: ser 단순과거 + 과거분사의 수동태 → 정답 ✓","ha cancelado: '(누가) 취소했다'라는 능동 형태라 콘서트가 주어인 문장과 맞지 않습니다 ✗","canceló: 능동형이라 '콘서트가 (무엇을) 취소했다'가 됩니다 ✗"]},{"id":"G321","q":"La playa está justo ____ hotel en el que nos alojaremos.","o":["delante","delante de","delante al","delante del"],"a":3,"k":"delante de","t":"해변은 우리가 묵을 호텔 바로 앞에 있다.","e":"'~앞에'는 'delante de'로 씁니다. 뒤에 남성 정관사 el이 오면 de + el이 축약되어 del이 됩니다. 그래서 'delante del hotel'이 됩니다.","x":["delante: 혼자서는 '앞에'라는 부사라 뒤에 명사를 바로 붙일 수 없습니다 ✗","delante de: de 뒤에 el이 와야 하는데 관사가 빠져 있습니다 ✗","delante al: delante는 a가 아니라 de와 함께 씁니다 ✗","delante del: de + el의 축약형 → 정답 ✓"]},{"id":"G322","q":"____ algo personal.","o":["Te quiero contar","Quiero contar a ti","Quiero te contar","Quiero contar te"],"a":0,"k":"목적격 대명사 위치","t":"너한테 개인적인 이야기를 하나 해 주고 싶어.","e":"목적격 대명사(te: 너에게)는 활용 동사 앞에 두거나(Te quiero contar) 동사원형 끝에 붙입니다(Quiero contarte). 대명사를 동사원형 앞에 따로 두거나 띄어 쓸 수는 없습니다.","x":["Te quiero contar: 대명사를 활용 동사 quiero 앞에 둔 올바른 형태 → 정답 ✓","Quiero contar a ti: 대명사 te 없이 'a ti'만 쓰는 것은 부자연스럽습니다 ✗","Quiero te contar: 대명사를 동사원형 앞에 둘 수 없습니다 ✗","Quiero contar te: 동사원형에 붙일 때는 contarte처럼 붙여 써야 합니다 ✗"]},{"id":"G323","q":"____ de vosotras ha mentido.","o":["Un","Unas","Una","Unos"],"a":2,"k":"una de + 복수","t":"너희 중 한 명이 거짓말을 했다.","e":"'~중 하나'는 'uno/una de + 복수'로 표현합니다. vosotras는 여성 복수(너희 여자들)이므로 una가 맞습니다. 이때 동사는 '한 명'에 맞춰 단수(ha mentido)를 씁니다. 참고로 vosotras는 스페인에서 쓰며, 중남미에서는 ustedes를 씁니다.","x":["Un: 명사 앞 단축형이라 단독으로 '하나'를 뜻하지 않습니다 ✗","Unas: 복수라 단수 동사 ha mentido와 맞지 않습니다 ✗","Una: 여성 단수 '한 명' → 정답 ✓","Unos: 남성 복수라 성·수 모두 맞지 않습니다 ✗"]},{"id":"G324","q":"Todos me felicitaron por el premio ____ Ignacio.","o":["aunque","pero","no","excepto"],"a":3,"k":"excepto","t":"이그나시오만 빼고 모두가 상에 대해 나를 축하해 주었다.","e":"excepto는 '~을 제외하고'라는 뜻으로 todos(모두) 중에서 예외를 말할 때 씁니다. 비슷한 말로 menos, salvo가 있습니다. 예: Todos vinieron excepto Ana. (아나만 빼고 모두 왔다.)","x":["aunque: '비록 ~일지라도'라는 양보 접속사라 뒤에 문장이 와야 합니다 ✗","pero: '하지만'으로 뒤에 이름만 오면 문장이 완성되지 않습니다 ✗","no: 부정어 no는 이 위치에서 예외를 나타내지 못합니다 ✗","excepto: '~을 제외하고' → 정답 ✓"]},{"id":"G325","q":"No estoy segura de que Carmen ____ unirse a nosotros.","o":["puede","ha podido","pueda","había podido"],"a":2,"k":"의심 + 접속법","t":"카르멘이 우리와 함께할 수 있을지 확실하지 않다.","e":"'No estoy seguro/a de que ~'처럼 확신이 없거나 의심을 나타낼 때는 que 뒤에 접속법(바람·의심·감정을 나타낼 때 쓰는 동사 형태)을 씁니다. poder의 접속법 현재 3인칭 단수는 pueda입니다. 반대로 'Estoy segura de que puede'처럼 확신하면 직설법을 씁니다.","x":["puede: 직설법이라 의심을 나타내는 no estoy segura de que 뒤에 쓰지 않습니다 ✗","ha podido: 직설법 현재완료라 ✗","pueda: 의심 뒤에 오는 접속법 현재 → 정답 ✓","había podido: 직설법 과거완료라 ✗"]},{"id":"G326","q":"¿____ qué se dedica tu padre?","o":["En","De","Para","A"],"a":3,"k":"dedicarse a","t":"너희 아버지는 무슨 일을 하시니?","e":"'dedicarse a ~'는 '~에 종사하다, ~을 직업으로 하다'라는 뜻입니다. 의문문에서는 전치사가 의문사 앞으로 나와 '¿A qué se dedica?(무슨 일을 하세요?)'가 됩니다. 직업을 묻는 아주 흔한 표현입니다.","x":["En: dedicarse는 en과 함께 쓰지 않습니다 ✗","De: dedicarse de는 틀린 형태입니다 ✗","Para: '무엇을 위해'라는 목적이 되어 ✗","A: dedicarse a의 전치사 → 정답 ✓"]},{"id":"G327","q":"____ cuando llamaron por teléfono.","o":["He estado duchándome","Estaba duchándome","Estuve duchándome","Me duchaba"],"a":1,"k":"과거진행","t":"전화가 왔을 때 나는 샤워를 하고 있었다.","e":"과거에 어떤 행동이 진행되던 중에 다른 일이 끼어들 때, 진행 중이던 행동은 과거진행(estaba + 현재분사)으로, 끼어든 사건은 단순과거(llamaron)로 씁니다. '샤워하던 중'이라는 진행의 의미를 가장 분명하게 나타내는 것이 estaba duchándome입니다.","x":["He estado duchándome: 현재완료진행이라 과거 사건 llamaron과 시제가 맞지 않습니다 ✗","Estaba duchándome: 과거에 진행 중이던 행동 → 정답 ✓","Estuve duchándome: 단순과거 진행은 끝난 기간 전체를 말할 때 써서 끼어드는 상황에 맞지 않습니다 ✗","Me duchaba: 불완료과거로 문법적으로는 가능하지만, 교재는 진행 중임을 강조하는 과거진행을 정답으로 봅니다 ✗"]},{"id":"G328","q":"Cuando ____ 20 años me fui a vivir a Suecia.","o":["estaba teniendo","tenía","tuve","había tenido"],"a":1,"k":"불완료과거 (나이)","t":"스무 살이었을 때 나는 스웨덴으로 이사 갔다.","e":"과거에 '몇 살이었는지' 같은 배경 상태는 불완료과거로 표현합니다. tener의 불완료과거 1인칭 단수는 tenía입니다. 이사 간 사건 자체는 단순과거(me fui)로 씁니다.","x":["estaba teniendo: tener(나이)는 진행형으로 쓰지 않습니다 ✗","tenía: 과거 배경(나이)을 나타내는 불완료과거 → 정답 ✓","tuve: 단순과거는 '스무 살이 되었다'는 뉘앙스가 되어 배경 묘사로 어색합니다 ✗","había tenido: 과거완료라 시간 순서가 맞지 않습니다 ✗"]},{"id":"G329","q":"Ayer ____ todo el día en el campo.","o":["estuvimos","habíamos estado","hemos estado","estábamos"],"a":0,"k":"단순과거","t":"어제 우리는 하루 종일 시골에 있었다.","e":"ayer(어제)처럼 끝난 과거 시점과 'todo el día(하루 종일)'처럼 기간이 정해진 행동은 단순과거로 씁니다. estar의 단순과거 1인칭 복수는 estuvimos입니다.","x":["estuvimos: 끝난 과거의 일정 기간을 나타내는 단순과거 → 정답 ✓","habíamos estado: 과거완료는 다른 과거 시점보다 앞선 일에 씁니다 ✗","hemos estado: 현재완료는 ayer 같은 끝난 시간 표현과 잘 쓰지 않습니다 ✗","estábamos: 불완료과거는 배경 묘사용이라 '하루 종일 있었다'는 완결된 사실에 맞지 않습니다 ✗"]},{"id":"G330","q":"El documental duró más ____ lo que pensaba.","o":["a","por","que","de"],"a":3,"k":"más de lo que","t":"그 다큐멘터리는 내가 생각했던 것보다 길었다.","e":"비교 대상이 '명사'가 아니라 문장(lo que pensaba: 내가 생각한 것)일 때는 'más de lo que'를 씁니다. 'más que'는 명사나 대명사를 비교할 때 씁니다(Es más alto que yo). 예: Es más difícil de lo que parece. (보기보다 어렵다.)","x":["a: 비교 표현에 쓰지 않습니다 ✗","por: 비교 표현에 쓰지 않습니다 ✗","que: lo que 앞에서는 que가 아니라 de를 씁니다 ✗","de: 문장과 비교하는 más de lo que → 정답 ✓"]},{"id":"G331","q":"No quiero ser el ____ en entrar. ¿Puedes entrar tú antes?","o":["primer","primero","lo primer","lo primero"],"a":1,"k":"primero/primer","t":"나는 첫 번째로 들어가고 싶지 않아. 네가 먼저 들어갈래?","e":"서수 primero(첫 번째)는 남성 단수 명사 앞에서만 primer로 줄어듭니다. 여기서는 'el primero'로 뒤에 명사 없이 '첫 번째 사람'이라는 뜻으로 쓰였으므로 원래 형태 primero를 씁니다. 예: el primer día(첫날) / Soy el primero.(내가 첫 번째다)","x":["primer: 뒤에 남성 명사가 있을 때만 쓰는 단축형이라 ✗","primero: 명사 없이 쓰인 '첫 번째(사람)' → 정답 ✓","lo primer: lo와 primer는 함께 쓰지 않습니다 ✗","lo primero: '가장 먼저 할 일'이라는 중성 표현이고, 이미 el이 있어 ✗"]},{"id":"G332","q":"Esos señores son ____.","o":["japoneses","japonés","de japoneses","japonesas"],"a":0,"k":"국적 형용사 일치","t":"저 신사분들은 일본 사람들이다.","e":"국적 형용사는 주어의 성·수에 맞춥니다. señores(신사들)는 남성 복수이므로 japonés의 남성 복수형 japoneses를 씁니다. 복수가 되면 악센트가 사라진다는 점에 주의하세요(japonés → japoneses).","x":["japoneses: 남성 복수형 → 정답 ✓","japonés: 단수라 복수 주어와 맞지 않습니다 ✗","de japoneses: '일본인들의'라는 뜻이 되어 ✗","japonesas: 여성 복수라 señores와 성이 맞지 않습니다 ✗"]},{"id":"G333","q":"Estudia ____ siempre saca la mejor nota de la clase.","o":["tanto que","tan que","tanta que","tantos que"],"a":0,"k":"tanto que","t":"그는 공부를 아주 많이 해서 항상 반에서 최고 점수를 받는다.","e":"'너무 ~해서 …하다'라는 결과를 나타낼 때 동사 뒤에서는 'tanto que'를 씁니다(동사를 꾸미는 tanto는 형태가 변하지 않음). 형용사·부사 앞에서는 tan을 씁니다(Es tan listo que...). 예: Comió tanto que se sintió mal. (너무 많이 먹어서 속이 안 좋았다.)","x":["tanto que: 동사(estudia)를 꾸미는 '아주 많이 ~해서' → 정답 ✓","tan que: tan은 형용사·부사 앞에서만 쓰고 바로 que가 올 수 없습니다 ✗","tanta que: 여성 명사를 꾸미는 형태라 동사 뒤에 쓰지 않습니다 ✗","tantos que: 남성 복수 명사를 꾸미는 형태라 ✗"]},{"id":"G334","q":"Incluso ____, que soy tan despistada, recuerdo la fecha de tu onomástica.","o":["yo","mí","a mí","me"],"a":0,"k":"주격 대명사","t":"그렇게 덜렁대는 나조차도 네 영명축일을 기억하고 있어.","e":"incluso(~조차)는 뒤에 오는 말을 강조할 뿐 전치사가 아니므로, 주어 자리에는 주격 대명사 yo를 씁니다. 동사 recuerdo(내가 기억한다)의 주어이기 때문입니다. onomástica는 자기 이름과 같은 성인의 축일로, 스페인 문화에서 생일처럼 축하하기도 합니다.","x":["yo: 동사 recuerdo의 주어인 주격 대명사 → 정답 ✓","mí: 전치사 뒤에서만 쓰는 형태라 ✗","a mí: '나에게'라는 간접목적 표현이라 주어가 될 수 없습니다 ✗","me: 목적격 대명사라 주어로 쓸 수 없습니다 ✗"]},{"id":"G335","q":"Los estudiantes ____ saquen mejor nota podrán pedir una beca.","o":["quienes","los que","quien","que"],"a":3,"k":"관계대명사 que","t":"더 좋은 점수를 받는 학생들은 장학금을 신청할 수 있다.","e":"선행사(los estudiantes) 바로 뒤에 쉼표 없이 오는 제한적 관계절에서는 que를 씁니다. quien(es)은 쉼표가 있는 설명적 관계절이나 전치사 뒤에서 씁니다. saquen이 접속법인 이유는 '아직 누가 될지 정해지지 않은 학생들'을 말하기 때문입니다.","x":["quienes: 쉼표 없는 제한적 관계절에서 주어로 쓰지 않습니다 ✗","los que: 이미 선행사 los estudiantes가 있어 관사가 중복됩니다 ✗","quien: 단수인 데다 같은 이유로 ✗","que: 제한적 관계절의 기본 관계대명사 → 정답 ✓"]},{"id":"G336","q":"La mitad ____ los trabajadores de mi empresa son mayores de cuarenta años.","o":["de","ø","a","que"],"a":0,"k":"la mitad de","t":"우리 회사 직원의 절반은 40세 이상이다.","e":"'~의 절반'은 'la mitad de ~'로 표현합니다. 뒤에 복수 명사가 오면 동사는 의미상 복수(son)를 쓰는 경우가 많습니다. 예: La mitad de la clase está enferma. (반의 절반이 아프다.)","x":["de: '~의 절반'을 만드는 전치사 → 정답 ✓","ø: mitad와 명사 사이에 de가 꼭 필요합니다 ✗","a: mitad 뒤에 a를 쓰지 않습니다 ✗","que: 비교 표현이 아니므로 ✗"]},{"id":"G337","q":"¿Por qué estás ____ enojado?","o":["tanto","tantos","tanta","tan"],"a":3,"k":"tan + 형용사","t":"너는 왜 그렇게 화가 나 있니?","e":"형용사(enojado)나 부사 앞에서 '그렇게, 그토록'을 말할 때는 tan을 씁니다. tanto/tanta/tantos는 명사 앞이나 동사 뒤에서 씁니다. enojado는 중남미에서 많이 쓰고, 스페인에서는 enfadado를 더 자주 씁니다.","x":["tanto: 동사 뒤나 남성 단수 명사 앞에서 쓰는 형태라 ✗","tantos: 남성 복수 명사 앞에 쓰는 형태라 ✗","tanta: 여성 단수 명사 앞에 쓰는 형태라 ✗","tan: 형용사 앞의 '그렇게' → 정답 ✓"]},{"id":"G338","q":"No importa que ____ frío, voy a dar un paseo.","o":["hace","haría","haga","hiciera"],"a":2,"k":"no importa que","t":"추워도 상관없어, 나는 산책하러 갈 거야.","e":"'No importa que ~(~해도 상관없다)'는 감정·가치 판단을 나타내는 표현이라 뒤에 접속법이 옵니다. 현재·미래 상황이므로 hacer의 접속법 현재 haga를 씁니다. 날씨 표현은 'hace frío(춥다)'처럼 hacer를 씁니다.","x":["hace: 직설법이라 no importa que 뒤에 쓰지 않습니다 ✗","haría: 조건법이라 ✗","haga: 접속법 현재 → 정답 ✓","hiciera: 접속법 과거로 주절 importa(현재)와 시제가 맞지 않습니다 ✗"]},{"id":"G339","q":"Este vaso está roto, será ____ que lo tires.","o":["buen","mejor","bien","la mejor"],"a":1,"k":"será mejor que","t":"이 컵은 깨졌으니 버리는 게 좋겠다.","e":"'Es/Será mejor que + 접속법'은 '~하는 편이 낫다'라는 충고 표현입니다. 여기서 mejor는 bueno의 비교급 '더 좋은'이라는 뜻입니다. será(미래형)는 '아마 ~일 것이다'라는 부드러운 느낌을 줍니다.","x":["buen: 남성 명사 앞에서만 쓰는 형태라 ✗","mejor: '~하는 편이 낫다'의 mejor → 정답 ✓","bien: 부사라 ser 뒤에서 이 구문을 만들지 않습니다 ✗","la mejor: '가장 좋은 것(여성)'이라는 뜻이 되어 ✗"]},{"id":"G340","q":"No voy a salir este sábado, ____ quedarme en casa estudiando.","o":["tengo que","tengo","hay que","tiene que"],"a":0,"k":"tener que","t":"나는 이번 토요일에 나가지 않을 거야, 집에서 공부해야 하거든.","e":"'tener que + 동사원형'은 '(내가) ~해야 한다'라는 개인적 의무를 나타냅니다. 주어가 yo이므로 tengo que가 됩니다. 'hay que'는 주어 없이 '(일반적으로) ~해야 한다'라는 뜻이라 나 개인의 계획을 말할 때는 맞지 않습니다.","x":["tengo que: 1인칭 '나는 ~해야 한다' → 정답 ✓","tengo: que가 없으면 '가지고 있다'라는 뜻이 되어 ✗","hay que: 무인칭 의무 표현이라 개인 상황에 어색합니다 ✗","tiene que: 3인칭이라 주어(나)와 맞지 않습니다 ✗"]},{"id":"G341","q":"Dijiste que ____ antes de las 2. ¿Por qué has llamado después?","o":["estabas llamando","llamaras","llamarías","llamarás"],"a":2,"k":"과거 속 미래(조건법)","t":"너 2시 전에 전화하겠다고 했잖아. 왜 그 뒤에 전화했어?","e":"과거에 '~하겠다'고 말한 내용을 전할 때(간접화법)는 미래 대신 조건법(llamarías)을 씁니다. 이를 '과거에서 본 미래'라고 합니다. 예: Dijo que vendría. (그는 오겠다고 말했다.)","x":["estabas llamando: 과거진행이라 '전화하고 있었다'가 되어 ✗","llamaras: 접속법 과거로, decir가 '전달'의 뜻일 때는 쓰지 않습니다 ✗","llamarías: 과거 시점에서 본 미래를 나타내는 조건법 → 정답 ✓","llamarás: 단순미래로 주절 dijiste(과거)와 시제가 맞지 않습니다 ✗"]},{"id":"G342","q":"El servicio ____ habitación de este hotel es bastante bueno.","o":["para","a","de","sobre"],"a":2,"k":"명사 + de + 명사","t":"이 호텔의 룸서비스는 꽤 좋다.","e":"'servicio de habitación(룸서비스)'처럼 명사가 다른 명사를 꾸밀 때는 de로 연결합니다. 한국어로는 '~용, ~의'에 가깝습니다. 예: tarjeta de crédito(신용카드), clase de español(스페인어 수업)","x":["para: '~을 위한'이라는 뜻이지만 이 고정 표현에는 쓰지 않습니다 ✗","a: 명사끼리 연결하는 이 표현에 쓰지 않습니다 ✗","de: servicio de habitación 고정 표현 → 정답 ✓","sobre: '~에 대한'이라는 뜻이라 ✗"]},{"id":"G343","q":"Vivimos en el ____ piso y nuestro hijo en el cuarto.","o":["tres","tercero","tercera","tercer"],"a":3,"k":"서수 tercer","t":"우리는 3층에 살고 우리 아들은 4층에 산다.","e":"tercero(세 번째)는 남성 단수 명사 앞에서 o가 떨어져 tercer가 됩니다. piso(층)는 남성 명사이므로 'el tercer piso'가 맞습니다. primero → primer도 같은 규칙입니다.","x":["tres: 기수(셋)라 '몇 번째'를 나타내지 못합니다 ✗","tercero: 남성 명사 앞에서는 tercer로 줄여야 합니다 ✗","tercera: 여성형이라 남성 명사 piso와 맞지 않습니다 ✗","tercer: 남성 단수 명사 앞 단축형 → 정답 ✓"]},{"id":"G344","q":"¿Para qué ____ esas tijeras?","o":["estás queriendo","queráis","quieres","quieras"],"a":2,"k":"직설법 의문문","t":"그 가위는 뭐 하려고 원하는 거야?","e":"직접 묻는 일반 의문문에서는 직설법을 씁니다. 상대가 tú이므로 querer의 현재 2인칭 단수 quieres가 됩니다. 'tijeras(가위)'는 항상 복수로 쓰는 명사라 esas가 붙었습니다.","x":["estás queriendo: querer는 보통 진행형으로 쓰지 않습니다 ✗","queráis: 접속법이고 vosotros 형태라 ✗","quieres: 직설법 현재 2인칭 단수 → 정답 ✓","quieras: 접속법이라 일반 의문문에 쓰지 않습니다 ✗"]},{"id":"G345","q":"No veo películas de acción ____ no me gustan.","o":["por qué","porque","porqué","por que"],"a":1,"k":"porque/por qué","t":"나는 액션 영화를 좋아하지 않아서 보지 않는다.","e":"이유를 설명하는 '왜냐하면, ~때문에'는 붙여 쓴 porque입니다. 의문사 '왜'는 por qué(띄어 쓰고 악센트), 명사 '이유'는 el porqué입니다. 예: No vine porque estaba enfermo. (아파서 안 왔어.)","x":["por qué: 의문사 '왜'라서 이유를 설명하는 자리에 맞지 않습니다 ✗","porque: 이유 접속사 '~때문에' → 정답 ✓","porqué: 명사 '이유'로 보통 el porqué로 씁니다 ✗","por que: 'por + 관계사 que' 형태로 이 문장에 맞지 않습니다 ✗"]},{"id":"G346","q":"Tengo que ____ hacer este ejercicio. Mi profe dice que está mal.","o":["empezar a","volver a","dejar de","acabar de"],"a":1,"k":"volver a + 원형","t":"이 문제를 다시 풀어야 해. 선생님이 틀렸다고 하셔.","e":"'volver a + 동사원형'은 '다시 ~하다'라는 뜻입니다. 선생님이 틀렸다고 했으니 다시 해야 한다는 문맥에 맞습니다. 예: Vuelve a llamar más tarde. (나중에 다시 전화해.)","x":["empezar a: '~하기 시작하다'라서 이미 한 문제와 맞지 않습니다 ✗","volver a: '다시 ~하다' → 정답 ✓","dejar de: '~하는 것을 그만두다'라서 ✗","acabar de: '방금 ~했다'라서 tener que와 의미가 맞지 않습니다 ✗"]},{"id":"G347","q":"Perdone, ¿nos ____ la cuenta?","o":["trae","traiga","traigas","traes"],"a":0,"k":"정중한 요청 (usted)","t":"실례합니다, 계산서 좀 가져다주시겠어요?","e":"식당에서 정중하게 부탁할 때 '¿Nos trae ~?'처럼 usted에 맞춘 직설법 현재 의문문을 씁니다. Perdone가 usted 형태이므로 trae(3인칭 단수)가 맞습니다. 명령형으로 말하면 'Tráiganos la cuenta'가 됩니다.","x":["trae: usted에 맞춘 직설법 현재 의문문 → 정답 ✓","traiga: 접속법이라 의문문에 쓰지 않습니다 ✗","traigas: 접속법 tú 형태라 ✗","traes: tú 형태라 Perdone(usted)와 맞지 않습니다 ✗"]},{"id":"G348","q":"Solo Luisa y yo nos quedamos en la fiesta ____ el final. Los demás se fueron antes.","o":["hasta","en","por","hacia"],"a":0,"k":"hasta el final","t":"루이사와 나만 파티에 끝까지 남았다. 나머지 사람들은 먼저 갔다.","e":"hasta는 '~까지'라는 뜻으로 시간이나 장소의 끝점을 나타냅니다. 'hasta el final'은 '끝까지'라는 자주 쓰는 표현입니다. 예: Te espero hasta las cinco. (5시까지 기다릴게.)","x":["hasta: '~까지' → 정답 ✓","en: 'en el final'은 '끝에'라는 위치 의미라 머무른 기간을 나타내지 못합니다 ✗","por: 이유·경로를 나타내어 ✗","hacia: '~쪽으로/~무렵'이라 ✗"]},{"id":"G349","q":"No quiero que mis padres ____ que he suspendido varias asignaturas.","o":["sabrán","sepan","saben","van a saber"],"a":1,"k":"querer que + 접속법","t":"나는 부모님이 내가 여러 과목에서 낙제한 것을 아는 걸 원하지 않는다.","e":"'querer que ~'처럼 바람을 나타내고 주절과 종속절의 주어가 다를 때, que 뒤에 접속법을 씁니다. saber의 접속법 현재 3인칭 복수는 sepan입니다. suspender는 스페인에서 '(시험에) 떨어지다'라는 뜻입니다.","x":["sabrán: 직설법 미래라 querer que 뒤에 쓰지 않습니다 ✗","sepan: 접속법 현재 3인칭 복수 → 정답 ✓","saben: 직설법 현재라 ✗","van a saber: 직설법 미래 표현이라 ✗"]},{"id":"G350","q":"Necesito una nueva máquina ____ afeitar.","o":["por","a","de","sobre"],"a":2,"k":"용도 de + 원형","t":"새 면도기가 필요하다.","e":"'máquina de afeitar(면도기)'처럼 '~하는 용도의 기계/도구'는 'de + 동사원형'으로 표현합니다. 예: máquina de coser(재봉틀), goma de borrar(지우개)","x":["por: 용도 표현에 쓰지 않습니다 ✗","a: 'a + 원형'은 이런 도구 이름에 쓰지 않습니다 ✗","de: 용도를 나타내는 de → 정답 ✓","sobre: '~에 대해'라서 ✗"]},{"id":"G351","q":"Cuando tengo estrés, ____ a caminar con mi perro y me calmo.","o":["sale","saldré","salió","salgo"],"a":3,"k":"직설법 현재 (습관)","t":"스트레스를 받으면 나는 개와 함께 산책하러 나가고, 그러면 마음이 진정된다.","e":"'Cuando tengo estrés(스트레스 받을 때면)'처럼 반복되는 습관을 말할 때는 직설법 현재를 씁니다. 주어가 yo이므로 salir의 1인칭 단수 salgo입니다(불규칙: salir → salgo). 뒤의 me calmo도 1인칭 현재입니다.","x":["sale: 3인칭 단수라 주어(나)와 맞지 않습니다 ✗","saldré: 미래형이라 습관을 나타내지 못합니다 ✗","salió: 3인칭 단순과거라 ✗","salgo: 1인칭 현재, 습관 → 정답 ✓"]},{"id":"G352","q":"Hice todo lo que pude por salvar al animal herido, pero fue ____ vano.","o":["en","por","a","de"],"a":0,"k":"en vano","t":"다친 동물을 살리려고 할 수 있는 건 다 했지만, 헛수고였다.","e":"'en vano'는 '헛되이, 소용없이'라는 뜻의 고정 표현입니다. 'fue en vano'는 '헛수고였다'라는 뜻입니다. 예: Lo intentó en vano. (그는 헛되이 시도했다.)","x":["en: 'en vano' 고정 표현 → 정답 ✓","por: 'por vano'라는 표현은 없습니다 ✗","a: 'a vano'라는 표현은 없습니다 ✗","de: 'de vano'라는 표현은 없습니다 ✗"]},{"id":"G353","q":"¿____ motos has tenido en los últimos veinte años?","o":["Cuántos","Cuánta","Cuántas","Cuánto"],"a":2,"k":"cuánto 일치","t":"지난 20년 동안 오토바이를 몇 대 가져 봤니?","e":"의문사 cuánto(얼마나 많은)는 뒤의 명사와 성·수를 맞춥니다. moto(오토바이)는 -o로 끝나지만 motocicleta의 줄임말이라 여성 명사입니다. 그래서 여성 복수 cuántas가 됩니다.","x":["Cuántos: 남성 복수라 여성 명사 motos와 맞지 않습니다 ✗","Cuánta: 단수라 복수 명사와 맞지 않습니다 ✗","Cuántas: 여성 복수 → 정답 ✓","Cuánto: 남성 단수라 ✗"]},{"id":"G354","q":"¡Muchas gracias ____ todo!","o":["por","a","de","para"],"a":0,"k":"gracias por","t":"모든 것에 정말 감사해요!","e":"감사의 이유를 말할 때는 'gracias por ~'를 씁니다. por가 '~때문에, ~에 대해'라는 원인을 나타냅니다. 예: Gracias por tu ayuda. (도와줘서 고마워.)","x":["por: 감사의 이유를 나타내는 por → 정답 ✓","a: 'gracias a ~'는 '~덕분에'라는 뜻으로 감사 인사 대상에 쓰지 않습니다 ✗","de: gracias de는 일반적인 표현이 아닙니다 ✗","para: 목적을 나타내어 ✗"]},{"id":"G355","q":"Me molesta que la gente ____ cuando habla por teléfono.","o":["grita","está gritando","grite","gritaría"],"a":2,"k":"감정 + 접속법","t":"사람들이 통화할 때 소리 지르는 게 거슬린다.","e":"'Me molesta que ~(~가 거슬린다)'처럼 감정을 나타내는 표현 뒤 que절에는 접속법을 씁니다. gritar의 접속법 현재 3인칭 단수는 grite입니다. la gente는 의미상 여러 사람이지만 문법적으로 단수입니다.","x":["grita: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","está gritando: 직설법 진행형이라 ✗","grite: 접속법 현재 → 정답 ✓","gritaría: 조건법이라 ✗"]},{"id":"G356","q":"José Antonio vive en ____ segundo piso de ese bloque.","o":["el","ø","un","lo"],"a":0,"k":"서수 앞 정관사","t":"호세 안토니오는 그 건물 2층에 산다.","e":"특정한 층을 말할 때는 정관사를 써서 'el segundo piso'라고 합니다. 건물에는 2층이 하나뿐이므로 특정한 것을 가리키는 el이 맞습니다. 참고로 스페인에서 piso는 '아파트'를 뜻하기도 합니다.","x":["el: 특정한 층을 가리키는 정관사 → 정답 ✓","ø: 서수 앞에는 보통 관사가 필요합니다 ✗","un: '어떤 2층'이라는 뜻이 되어 어색합니다 ✗","lo: 중성 관사라 남성 명사 piso 앞에 쓰지 않습니다 ✗"]},{"id":"G357","q":"Confío ____ ti.","o":["en","por","de","a"],"a":0,"k":"confiar en","t":"나는 너를 믿어.","e":"'confiar en ~'은 '~을 믿다, 신뢰하다'라는 고정 표현입니다. 전치사 en 뒤에는 ti(전치격 대명사)가 옵니다. 예: Confío en ella. (나는 그녀를 믿는다.)","x":["en: confiar en 고정 표현 → 정답 ✓","por: confiar와 함께 쓰지 않습니다 ✗","de: 'fiarse de'와 헷갈리기 쉽지만 confiar는 en을 씁니다 ✗","a: confiar a는 '~에게 맡기다'라는 다른 뜻이라 ✗"]},{"id":"G358","q":"Toma, este es el libro ____ que te hablé el otro día.","o":["para el","en el","al","del"],"a":3,"k":"hablar de + 관계사","t":"자, 이게 내가 저번에 너한테 말했던 그 책이야.","e":"'hablar de ~(~에 대해 말하다)'의 전치사 de가 관계대명사 앞으로 옵니다. de + el que가 축약되어 'del que'가 됩니다. 예: la chica de la que te hablé(내가 말한 그 여자애)","x":["para el: hablar para는 '~을 위해 말하다'라 맞지 않습니다 ✗","en el: hablar en은 '~에서/~(언어)로 말하다'라 ✗","al: hablar a는 '~에게 말하다'라 책과 맞지 않습니다 ✗","del: hablar de의 de + el que → 정답 ✓"]},{"id":"G359","q":"Si vamos ____ metro, llegaremos mucho antes.","o":["en","de","por","con"],"a":0,"k":"교통수단 en","t":"지하철로 가면 훨씬 빨리 도착할 거야.","e":"교통수단을 탈 때 '~로(타고)'는 en을 씁니다: en metro, en coche, en avión. 단, '걸어서'는 'a pie', '말을 타고'는 'a caballo'입니다.","x":["en: 교통수단을 나타내는 en → 정답 ✓","de: 교통수단 표현에 쓰지 않습니다 ✗","por: 'por metro'는 일반적이지 않습니다 ✗","con: '~와 함께'라서 교통수단에 쓰지 않습니다 ✗"]},{"id":"G360","q":"Fue en 1999 ____ conocí a Jimena.","o":["cuando","como","donde","desde cuando"],"a":0,"k":"강조 구문 fue ~ cuando","t":"내가 히메나를 만난 건 1999년이었다.","e":"'Fue en + 시간 + cuando ~'는 시간을 강조하는 구문(바로 ~때였다)입니다. 강조하는 요소가 시간이면 cuando, 장소면 donde, 방법이면 como를 씁니다. 예: Fue en Madrid donde nos conocimos. (우리가 만난 건 마드리드에서였다.)","x":["cuando: 시간을 강조하는 구문 → 정답 ✓","como: 방법을 강조할 때 씁니다 ✗","donde: 장소를 강조할 때 씁니다 ✗","desde cuando: '언제부터'라서 ✗"]},{"id":"G361","q":"El viaje duró más ____ lo que pensábamos.","o":["a","que","sobre","de"],"a":3,"k":"más de lo que","t":"여행은 우리가 생각했던 것보다 오래 걸렸다.","e":"문장 전체(lo que pensábamos: 우리가 생각했던 것)와 비교할 때는 'más de lo que'를 씁니다. 'más que'는 명사·대명사와 직접 비교할 때 씁니다. 예: Cuesta más de lo que esperaba. (예상보다 비싸다.)","x":["a: 비교 표현에 쓰지 않습니다 ✗","que: lo que 앞에서는 de를 써야 합니다 ✗","sobre: 비교 표현이 아닙니다 ✗","de: más de lo que → 정답 ✓"]},{"id":"G362","q":"¿Todavía tienes el balón de Pablito? ¿Por qué no ____ lo has devuelto?","o":["le","se","les","la"],"a":1,"k":"le → se 변화","t":"아직 파블리토의 공을 가지고 있니? 왜 그에게 돌려주지 않았어?","e":"간접목적격(le: 그에게)과 직접목적격(lo: 그것을)이 함께 오면 le가 se로 바뀝니다(le lo → se lo). 여기서는 '파블리토에게 그것(공)을'이므로 se lo가 됩니다. 예: Se lo di ayer. (어제 그에게 그것을 줬어.)","x":["le: lo 앞에서 le는 se로 바뀌어야 합니다 ✗","se: le lo가 바뀐 se lo → 정답 ✓","les: 복수인 데다 역시 se로 바뀌어야 합니다 ✗","la: 직접목적격이라 lo와 겹칩니다 ✗"]},{"id":"G363","q":"____ llovía intensamente, suspendieron el acto.","o":["Porque","Por","A causa de","Como"],"a":3,"k":"como (이유)","t":"비가 세차게 내려서 행사가 취소되었다.","e":"이유를 문장 맨 앞에 둘 때는 porque 대신 como를 씁니다. porque는 보통 주절 뒤에 옵니다(Suspendieron el acto porque llovía). 'a causa de'와 por는 뒤에 명사가 와야 합니다.","x":["Porque: 문장 맨 앞에서 이유를 말할 때는 보통 como를 씁니다 ✗","Por: 뒤에 명사나 동사원형이 와야 합니다 ✗","A causa de: 뒤에 명사가 와야 해서 활용 동사 llovía와 맞지 않습니다 ✗","Como: 문장 앞에서 '~이므로' → 정답 ✓"]},{"id":"G364","q":"____ el tren cuando me di cuenta de que no había comprado el billete.","o":["Estuve esperando","Esperé","Estaba esperando","He esperado"],"a":2,"k":"과거진행 + 단순과거","t":"표를 사지 않았다는 걸 알았을 때 나는 기차를 기다리고 있었다.","e":"과거에 진행 중이던 배경 행동(기다리고 있었다)은 과거진행 estaba esperando로, 그 도중에 일어난 사건(알아차렸다)은 단순과거 me di cuenta로 씁니다. '~하고 있을 때 ~했다' 구조를 기억하세요.","x":["Estuve esperando: 끝난 기간 전체를 말하는 형태라 도중에 일어난 일과 맞지 않습니다 ✗","Esperé: 단순과거라 '기다리는 중'이라는 배경을 나타내지 못합니다 ✗","Estaba esperando: 진행 중이던 과거 행동 → 정답 ✓","He esperado: 현재완료라 과거 사건과 시제가 맞지 않습니다 ✗"]},{"id":"G365","q":"Hasta el domingo pasado, yo nunca ____ la nieve en persona.","o":["había visto","veía","he visto","vi"],"a":0,"k":"과거완료 (경험)","t":"지난 일요일까지 나는 눈을 직접 본 적이 한 번도 없었다.","e":"'Hasta el domingo pasado'라는 과거 기준점까지의 경험을 말하므로 과거완료(había visto)를 씁니다. ver의 과거분사는 불규칙형 visto입니다. 'en persona'는 '직접, 실제로'라는 뜻입니다.","x":["había visto: 과거 기준점 이전의 경험 → 정답 ✓","veía: 불완료과거로 경험을 나타내지 못합니다 ✗","he visto: 현재완료라 과거 기준점과 맞지 않습니다 ✗","vi: 단순과거로 '그때까지 한 번도'라는 의미를 나타내기 어렵습니다 ✗"]},{"id":"G366","q":"Mario no ____ bien, por eso se ha ido a su casa.","o":["sentirse","siente","se sienta","se siente"],"a":3,"k":"sentirse 재귀","t":"마리오는 몸이 좋지 않아서 집에 갔다.","e":"'몸 상태나 기분이 ~하다'는 재귀동사 sentirse로 표현합니다(Me siento bien: 나는 기분이 좋다). 주어 Mario는 3인칭 단수, 직설법 현재이므로 se siente입니다. sentir(e→ie)는 어간이 바뀌는 동사입니다.","x":["sentirse: 동사원형이라 본동사로 쓸 수 없습니다 ✗","siente: se가 없으면 '(무엇을) 느끼다'라는 뜻이 되어 ✗","se sienta: 접속법(또는 sentarse '앉다'의 직설법)이라 ✗","se siente: 재귀동사 sentirse의 3인칭 현재 → 정답 ✓"]},{"id":"G367","q":"____ en ese hotel. ¡Es fabuloso!","o":["Acabaremos de quedarnos","Dejaremos de quedarnos","Volveremos a quedarnos","Llevamos quedándonos"],"a":2,"k":"volver a + 원형","t":"우리 그 호텔에 또 묵을 거야. 정말 멋져!","e":"'volver a + 동사원형'은 '다시 ~하다'라는 뜻입니다. 호텔이 멋지다고 했으므로 '다시 묵을 것이다'가 자연스럽습니다. quedarse en은 '~에 머물다, 묵다'라는 뜻입니다.","x":["Acabaremos de quedarnos: acabar de(방금 ~하다)는 미래형으로 쓰면 어색합니다 ✗","Dejaremos de quedarnos: '그만 묵을 것이다'라서 '멋지다'와 맞지 않습니다 ✗","Volveremos a quedarnos: '다시 묵을 것이다' → 정답 ✓","Llevamos quedándonos: '~째 묵고 있다'로 기간 표현이 필요하고 문맥에 맞지 않습니다 ✗"]},{"id":"G368","q":"Diego Rivera fue ____ famoso pintor mexicano.","o":["ø","unos","un","uno"],"a":2,"k":"부정관사 + 형용사","t":"디에고 리베라는 유명한 멕시코 화가였다.","e":"원래 직업 앞에는 관사를 생략하지만(Es pintor), 형용사(famoso)가 붙어 사람을 설명하면 부정관사가 필요합니다. pintor는 남성 단수이므로 un을 씁니다. 디에고 리베라는 프리다 칼로의 남편이기도 한 벽화가입니다.","x":["ø: 형용사가 붙은 명사 앞에서는 관사가 필요합니다 ✗","unos: 복수라 ✗","un: 남성 단수 부정관사 → 정답 ✓","uno: 명사 앞에서는 un으로 줄여야 합니다 ✗"]},{"id":"G369","q":"No te enojes con ellos, solo estaban ____ broma.","o":["por","de","con","a"],"a":1,"k":"de broma","t":"그들에게 화내지 마, 그냥 장난이었어.","e":"'estar de broma'는 '농담하다, 장난치다'라는 고정 표현입니다. de가 '~하는 상태로'라는 뜻을 나타냅니다. 비슷한 표현: estar de vacaciones(휴가 중이다), estar de viaje(여행 중이다)","x":["por: 'por broma'는 '장난으로'라는 뜻이지만 estar와 함께 쓰지 않습니다 ✗","de: estar de broma 고정 표현 → 정답 ✓","con: estar와 broma를 연결하지 않습니다 ✗","a: 'a broma'라는 표현은 없습니다 ✗"]},{"id":"G370","q":"Me sorprendió ____ que se habían casado.","o":["saber","sabiendo","cuando saber","de saber"],"a":0,"k":"부정사 주어","t":"그들이 결혼했다는 걸 알고 나는 놀랐다.","e":"'Me sorprendió ~'는 gustar형 구문으로, '나를 놀라게 한 것'이 주어입니다. 동사가 주어가 될 때는 동사원형을 씁니다. 그래서 'saber que se habían casado(그들이 결혼했다는 것을 아는 것)'가 주어가 됩니다.","x":["saber: 주어 역할을 하는 동사원형 → 정답 ✓","sabiendo: 현재분사는 주어로 쓸 수 없습니다 ✗","cuando saber: cuando 뒤에는 활용 동사가 와야 합니다 ✗","de saber: 주어 앞에 전치사를 붙일 수 없습니다 ✗"]},{"id":"G371","q":"En nuestra casa ____ a eso de las 9.","o":["se cenan","se cena","cenar","cenarse"],"a":1,"k":"무인칭 se","t":"우리 집에서는 9시쯤 저녁을 먹는다.","e":"'일반적으로 ~한다'라고 주어를 특정하지 않을 때 'se + 3인칭 단수 동사'(무인칭 se)를 씁니다. 목적어가 없으므로 단수 cena가 됩니다. 'a eso de las 9'는 '9시쯤'이라는 뜻입니다.","x":["se cenan: 복수 주어가 없으므로 복수형을 쓰지 않습니다 ✗","se cena: 무인칭 se + 3인칭 단수 → 정답 ✓","cenar: 동사원형이라 본동사가 될 수 없습니다 ✗","cenarse: 동사원형이고 이런 재귀형은 쓰지 않습니다 ✗"]},{"id":"G372","q":"Estoy ____ mejor, gracias por preguntar.","o":["muy","mucha","más","mucho"],"a":3,"k":"mucho mejor","t":"훨씬 좋아졌어, 물어봐 줘서 고마워.","e":"비교급(mejor, peor, más, menos) 앞에서 '훨씬'이라고 강조할 때는 mucho를 씁니다. muy는 비교급 앞에 쓸 수 없습니다. 예: Esta casa es mucho más grande. (이 집이 훨씬 크다.)","x":["muy: 비교급 mejor 앞에는 쓰지 않습니다 ✗","mucha: 여성형으로 부사 역할을 할 수 없습니다 ✗","más: mejor 자체가 비교급이라 más mejor는 틀린 표현입니다 ✗","mucho: 비교급을 강조하는 '훨씬' → 정답 ✓"]},{"id":"G373","q":"Cuando salí de la oficina, ____ cuenta de que hacía mucho frío.","o":["me estaba dando","me di","me daba","me dio cuenta"],"a":1,"k":"darse cuenta","t":"사무실을 나왔을 때 나는 날씨가 아주 춥다는 걸 알아차렸다.","e":"'darse cuenta de ~'는 '~을 깨닫다, 알아차리다'라는 표현입니다. 과거의 한순간에 일어난 일이므로 단순과거를 쓰고, 주어가 yo이니 me di cuenta가 됩니다. 문장에 이미 cuenta가 있어 빈칸에는 me di만 들어갑니다.","x":["me estaba dando: 과거진행이라 한순간의 깨달음에 어색합니다 ✗","me di: 1인칭 단순과거 → 정답 ✓","me daba: 불완료과거라 반복·배경이 되어 ✗","me dio cuenta: 3인칭 동사인 데다 cuenta가 중복됩니다 ✗"]},{"id":"G374","q":"Se me ha ocurrido ____ idea buenísima.","o":["ø","un","una","la"],"a":2,"k":"부정관사 una","t":"정말 좋은 생각이 떠올랐어.","e":"처음 언급하는 '어떤 하나의' 것은 부정관사를 씁니다. idea(생각)는 -a로 끝나는 여성 명사이므로 una를 씁니다. 'ocurrirse'는 '(생각이) 떠오르다'라는 뜻으로 'Se me ocurrió...'처럼 씁니다.","x":["ø: 단수 가산명사 앞에 관사가 필요합니다 ✗","un: 남성형이라 여성 명사 idea와 맞지 않습니다 ✗","una: 여성 단수 부정관사 → 정답 ✓","la: 정관사는 이미 알고 있는 특정한 생각에 쓰므로 ✗"]},{"id":"G375","q":"Creo que esos vasos no ____ de vidrio.","o":["son","estén","están","sean"],"a":0,"k":"ser de (재료)","t":"내 생각에 저 컵들은 유리로 만든 게 아닌 것 같아.","e":"재료(~로 만들어졌다)를 말할 때는 'ser de'를 씁니다. 'Creo que ~(~라고 생각한다)'는 긍정이므로 뒤에 직설법이 옵니다. 'No creo que sean de vidrio'처럼 creer가 부정일 때만 접속법을 씁니다.","x":["son: 재료를 나타내는 ser, 직설법 → 정답 ✓","estén: estar 접속법이라 재료 표현과 맞지 않습니다 ✗","están: estar는 재료를 나타내지 않습니다 ✗","sean: 접속법이라 긍정 creo que 뒤에 쓰지 않습니다 ✗"]},{"id":"G376","q":"No sé nada ____ informática, así que no puedo ayudarte.","o":["con","para","por","de"],"a":3,"k":"saber de","t":"나는 컴퓨터에 대해서 아무것도 몰라서 너를 도와줄 수 없어.","e":"'saber de ~'는 '~에 대해 알다, ~에 관한 지식이 있다'라는 뜻입니다. 'No sé nada de ~'는 '~에 대해 하나도 모른다'라는 자주 쓰는 표현입니다. informática는 '컴퓨터공학, 정보 기술'입니다.","x":["con: saber와 함께 이 뜻으로 쓰지 않습니다 ✗","para: 목적을 나타내어 ✗","por: 이유·경로를 나타내어 ✗","de: '~에 대해' → 정답 ✓"]},{"id":"G377","q":"Somos ____ Colombia, ¿y ustedes?","o":["de","del","a","en"],"a":0,"k":"ser de (출신)","t":"우리는 콜롬비아 출신이에요, 여러분은요?","e":"출신지는 'ser de + 장소'로 표현합니다. 대부분의 나라 이름 앞에는 관사를 쓰지 않으므로 'de Colombia'가 됩니다. ustedes는 중남미에서 '너희들'과 '여러분' 모두에 씁니다.","x":["de: 출신을 나타내는 de → 정답 ✓","del: de + el인데 Colombia 앞에는 관사가 없습니다 ✗","a: 방향을 나타내어 ✗","en: 위치를 나타내어 ser와 출신 표현이 되지 않습니다 ✗"]},{"id":"G378","q":"No te fíes de Sergio. Es capaz ____ hacer cualquier cosa con tal de conseguir sus objetivos.","o":["para","de","en","a"],"a":1,"k":"capaz de","t":"세르히오를 믿지 마. 그는 목표를 이루기 위해서라면 무슨 짓이든 할 수 있는 사람이야.","e":"'ser capaz de + 동사원형'은 '~할 수 있다, ~할 능력(배짱)이 있다'라는 고정 표현입니다. 'con tal de ~'는 '~하기 위해서라면'이라는 뜻입니다. 예: Es capaz de correr 10 km. (그는 10km를 달릴 수 있다.)","x":["para: capaz와 함께 쓰지 않습니다 ✗","de: capaz de 고정 표현 → 정답 ✓","en: capaz와 함께 쓰지 않습니다 ✗","a: capaz와 함께 쓰지 않습니다 ✗"]},{"id":"G379","q":"¿Cuánto ____ el partido de baloncesto?","o":["estaba durando","estuvo durando","duraba","duró"],"a":3,"k":"단순과거 (기간)","t":"농구 경기는 얼마나 걸렸어?","e":"이미 끝난 일의 전체 길이를 물을 때는 단순과거를 씁니다. durar(지속되다)의 단순과거 3인칭 단수는 duró입니다. 예: La película duró dos horas. (영화는 두 시간이었다.)","x":["estaba durando: durar는 보통 진행형으로 쓰지 않습니다 ✗","estuvo durando: 같은 이유로 어색합니다 ✗","duraba: 불완료과거라 끝난 경기의 전체 길이를 말하기에 맞지 않습니다 ✗","duró: 끝난 일의 지속 시간 → 정답 ✓"]},{"id":"G380","q":"____ tú friegas los platos, yo barro el suelo, ¿vale?","o":["Al","Después","Antes","Mientras"],"a":3,"k":"mientras","t":"네가 설거지하는 동안 내가 바닥을 쓸게, 알았지?","e":"mientras는 '~하는 동안'이라는 뜻으로 두 행동이 동시에 일어날 때 씁니다. 뒤에 활용 동사(friegas)가 옵니다. ¿vale?는 스페인에서 '알았지?, 괜찮지?'라는 뜻으로 자주 씁니다.","x":["Al: 'al + 동사원형'이라 활용 동사 friegas와 쓸 수 없습니다 ✗","Después: 'después de que'가 되어야 하고 의미도 맞지 않습니다 ✗","Antes: 'antes de que'가 필요하고 의미도 다릅니다 ✗","Mientras: '~하는 동안' → 정답 ✓"]},{"id":"G381","q":"Luis dice que se pasará por nuestra tienda cuando ____ tiempo.","o":["tuviera","tenga","tendrá","tendría"],"a":1,"k":"cuando + 접속법","t":"루이스는 시간이 될 때 우리 가게에 들르겠다고 한다.","e":"cuando가 미래의 일을 가리킬 때는 뒤에 접속법 현재를 씁니다. 한국어로는 '~하게 되면'에 가깝습니다. 주절 dice(현재)와 se pasará(미래)에 맞춰 tener의 접속법 현재 tenga를 씁니다.","x":["tuviera: 접속법 과거라 현재·미래 문맥과 맞지 않습니다 ✗","tenga: 미래를 가리키는 cuando 뒤 접속법 현재 → 정답 ✓","tendrá: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","tendría: 조건법이라 ✗"]},{"id":"G382","q":"Conozco a un músico ____ toca varios instrumentos a la perfección.","o":["quien","que","el que","al que"],"a":1,"k":"관계대명사 que","t":"나는 여러 악기를 완벽하게 연주하는 음악가를 한 명 안다.","e":"쉼표 없이 선행사(un músico)를 바로 꾸미는 관계절에서 주어 역할을 할 때는 que를 씁니다. quien은 전치사 뒤나 쉼표가 있는 관계절에서 씁니다. 예: Tengo un amigo que vive en Perú. (페루에 사는 친구가 있다.)","x":["quien: 쉼표 없는 제한적 관계절의 주어로 쓰지 않습니다 ✗","que: 기본 관계대명사 → 정답 ✓","el que: 전치사 없이 이 자리에 쓰면 어색합니다 ✗","al que: '그를'이라는 목적어가 되어 문장 구조와 맞지 않습니다 ✗"]},{"id":"G383","q":"Nos veremos ____ las 12 del mediodía.","o":["de","sobre","antes","en"],"a":1,"k":"sobre (대략)","t":"낮 12시쯤 보자.","e":"sobre가 시각 앞에 오면 '~쯤, 대략'이라는 뜻이 됩니다. 비슷한 표현으로 'a eso de las 12', 'alrededor de las 12'가 있습니다. 정확한 시각이라면 'a las 12'라고 합니다.","x":["de: 시각 앞에 de를 쓰면 '12시부터'처럼 되어 어색합니다 ✗","sobre: '~쯤' → 정답 ✓","antes: 'antes de las 12'처럼 de가 필요합니다 ✗","en: 시각 앞에 en을 쓰지 않습니다 ✗"]},{"id":"G384","q":"En serio, ____ entendí nada de lo que me dijo.","o":["ni","ø","no","sí"],"a":2,"k":"이중 부정","t":"진짜야, 그가 한 말을 하나도 이해 못 했어.","e":"스페인어에서는 nada(아무것도)가 동사 뒤에 오면 동사 앞에 no를 꼭 넣어야 합니다(이중 부정). 'No entendí nada'는 '하나도 이해하지 못했다'라는 뜻입니다. nada가 동사 앞에 오면 no를 쓰지 않습니다(Nada entendí).","x":["ni: '~도 아닌'이라는 뜻으로 여기서는 no가 필요합니다 ✗","ø: 동사 뒤에 nada가 있으면 no를 생략할 수 없습니다 ✗","no: 이중 부정의 no → 정답 ✓","sí: 긍정어라 nada와 함께 쓰면 모순됩니다 ✗"]},{"id":"G385","q":"Os informaré en cuanto ____ algo.","o":["supiera","sepa","sé","sabré"],"a":1,"k":"en cuanto + 접속법","t":"뭔가 알게 되면 바로 너희에게 알려 줄게.","e":"en cuanto(~하자마자)가 미래의 일을 가리키면 뒤에 접속법 현재를 씁니다. saber의 접속법 현재 1인칭 단수는 sepa입니다. 주절 informaré가 미래형인 것도 힌트입니다.","x":["supiera: 접속법 과거라 미래 문맥과 맞지 않습니다 ✗","sepa: 미래를 가리키는 en cuanto 뒤 접속법 현재 → 정답 ✓","sé: 직설법 현재라 미래의 일을 나타내지 못합니다 ✗","sabré: 시간 접속사 뒤에는 미래형을 쓰지 않습니다 ✗"]},{"id":"G386","q":"____ estás aquí, ayúdame a preparar la cena.","o":["Pues","Así que","Porque","Ya que"],"a":3,"k":"ya que","t":"여기 왔으니까 저녁 준비하는 것 좀 도와줘.","e":"ya que는 '~이니까, ~인 이상'이라는 뜻으로, 듣는 사람도 아는 이유를 문장 앞에 둘 때 씁니다. como와 비슷하게 쓰입니다. porque는 보통 문장 앞에 두지 않습니다.","x":["Pues: '그러면, 음'이라는 뜻으로 이유절을 이끌지 않습니다 ✗","Así que: '그래서'라는 결과 표현이라 ✗","Porque: 이유절이 문장 앞에 올 때는 보통 쓰지 않습니다 ✗","Ya que: '~이니까' → 정답 ✓"]},{"id":"G387","q":"Has traído más bebidas ____ las que necesitamos.","o":["de","para","a","que"],"a":0,"k":"más de las que","t":"너는 우리가 필요한 것보다 음료를 더 많이 가져왔다.","e":"비교 대상이 명사를 받는 관계절(las que necesitamos: 우리가 필요한 것들)일 때는 'más de + 관사 + que'를 씁니다. bebidas가 여성 복수라서 las que가 되었습니다. 예: Compré más libros de los que puedo leer. (읽을 수 있는 것보다 책을 더 샀다.)","x":["de: más de las que → 정답 ✓","para: 비교 표현에 쓰지 않습니다 ✗","a: 비교 표현에 쓰지 않습니다 ✗","que: 관계절 las que 앞에서는 de를 씁니다 ✗"]},{"id":"G388","q":"Quienes se esfuercen más, serán ____.","o":["recompensados","recompensado","recompensando","recompensar"],"a":0,"k":"수동태 분사 일치","t":"더 노력하는 사람들은 보상을 받을 것이다.","e":"'ser + 과거분사' 수동태에서 과거분사는 주어의 성·수에 맞춥니다. 주어 Quienes(~하는 사람들)는 복수이므로 recompensados가 됩니다. quienes se esfuercen의 접속법은 '누가 될지 아직 모르는 사람들'을 나타냅니다.","x":["recompensados: 복수 주어에 일치한 과거분사 → 정답 ✓","recompensado: 단수라 복수 주어와 맞지 않습니다 ✗","recompensando: 현재분사라 수동태를 만들지 못합니다 ✗","recompensar: 동사원형이라 ✗"]},{"id":"G389","q":"No quiero que ____ des tanta comida al perro. ¡Está muy gordo!","o":["se","lo","la","le"],"a":3,"k":"간접목적격 le","t":"개한테 먹이를 그렇게 많이 주지 마. 너무 뚱뚱하잖아!","e":"dar(주다)는 '누구에게(간접목적어)'와 '무엇을(직접목적어)'을 가집니다. 여기서 '개에게'는 간접목적어이므로 le를 씁니다. 'al perro'와 le를 함께 쓰는 것은 스페인어에서 자연스럽습니다.","x":["se: 직접목적격 대명사가 함께 올 때만 le가 se로 바뀝니다 ✗","lo: 직접목적격(그것을)이라 '개에게'를 나타내지 못합니다 ✗","la: 직접목적격 여성형이라 ✗","le: 간접목적격 '그(개)에게' → 정답 ✓"]},{"id":"G390","q":"Estoy seguro de que había más ____ doscientas personas en la presentación del libro.","o":["que","sobre","a","de"],"a":3,"k":"más de + 숫자","t":"책 발표회에 200명이 넘는 사람이 있었던 게 확실해.","e":"숫자 앞에서 '~이상, ~넘게'라고 할 때는 'más de + 숫자'를 씁니다. 'más que'는 숫자 앞에 쓰지 않습니다(부정문 'no ~ más que'는 '~밖에 없다'라는 다른 뜻). 예: Tiene más de 30 años. (그는 서른이 넘었다.)","x":["que: 숫자 앞에서 '~넘게'를 나타낼 때는 de를 씁니다 ✗","sobre: '~쯤'이라는 뜻이라 más와 함께 쓰지 않습니다 ✗","a: 비교 표현에 쓰지 않습니다 ✗","de: más de + 숫자 → 정답 ✓"]},{"id":"G391","q":"Intenté ____ arreglar la lavadora sin éxito.","o":["a","por","de","ø"],"a":3,"k":"intentar + 원형","t":"세탁기를 고쳐 보려고 했지만 실패했다.","e":"intentar(시도하다)는 전치사 없이 바로 동사원형을 씁니다. 'tratar de + 원형'도 같은 뜻인데, 이때는 de가 필요하니 헷갈리지 마세요. 'sin éxito'는 '성공하지 못하고'라는 뜻입니다.","x":["a: intentar 뒤에 a를 쓰지 않습니다 ✗","por: intentar 뒤에 por를 쓰지 않습니다 ✗","de: de는 tratar de에 쓰는 전치사라 ✗","ø: intentar + 동사원형 → 정답 ✓"]},{"id":"G392","q":"Voy a darte una noticia, pero no ____ la cuentes a nadie todavía.","o":["se","te","le","les"],"a":0,"k":"le → se 변화","t":"너에게 소식 하나 알려 줄 테니, 아직 아무에게도 말하지 마.","e":"'누구에게(a nadie)'와 '그것을(la noticia → la)'이 함께 오면, 간접목적격 le가 se로 바뀌어 'se la'가 됩니다. 부정 명령이라 대명사는 동사 앞에 둡니다. nadie를 받는 간접목적격도 le(→se)를 씁니다.","x":["se: 직접목적격 la 앞에서 le가 바뀐 se → 정답 ✓","te: '너에게'라서 '아무에게도'와 맞지 않습니다 ✗","le: la 앞에서는 se로 바꿔야 합니다 ✗","les: 복수인 데다 역시 se로 바꿔야 합니다 ✗"]},{"id":"G393","q":"Ni Pedro ____ Juan saben lo que ha ocurrido.","o":["tampoco","no","y","ni"],"a":3,"k":"ni ~ ni","t":"페드로도 후안도 무슨 일이 일어났는지 모른다.","e":"'Ni A ni B'는 'A도 B도 ~ 아니다'라는 표현입니다. 두 사람 모두를 부정하므로 동사는 복수(saben)를 씁니다. ni가 동사 앞에 오면 no를 따로 쓰지 않습니다.","x":["tampoco: '~도 아니다'라는 부사로 ni ~ ni 짝을 만들지 못합니다 ✗","no: ni와 짝을 이루지 않습니다 ✗","y: '그리고'라서 부정 의미가 사라집니다 ✗","ni: ni ~ ni 구문 → 정답 ✓"]},{"id":"G394","q":"____ atleta que ganó es brasileña.","o":["ø","La","Un","El"],"a":1,"k":"atleta 성 구별","t":"우승한 선수는 브라질 여성이다.","e":"atleta(운동선수)는 -a로 끝나지만 남녀 형태가 같은 명사로, 관사로 성별을 구별합니다(el atleta / la atleta). brasileña가 여성형이므로 la atleta가 됩니다. '우승한' 특정한 선수이므로 정관사를 씁니다.","x":["ø: 주어 자리의 특정한 사람 앞에는 관사가 필요합니다 ✗","La: 여성 정관사, 특정 선수 → 정답 ✓","Un: 남성 부정관사라 brasileña와 맞지 않습니다 ✗","El: 남성형이라 brasileña와 맞지 않습니다 ✗"]},{"id":"G395","q":"____ diez minutos llegaremos a nuestro destino.","o":["Antes","Para","A","En"],"a":3,"k":"en + 시간","t":"10분 뒤에 우리는 목적지에 도착할 것이다.","e":"'en + 시간'은 '~후에, ~만에'라는 뜻으로 미래에 얼마 뒤 일이 일어나는지 나타냅니다. 예: Vuelvo en cinco minutos. (5분 뒤에 돌아올게.) '~전에'는 'antes de'이고 'dentro de diez minutos'도 같은 뜻입니다.","x":["Antes: 'antes de'가 필요하고 '10분 전에'라는 다른 뜻입니다 ✗","Para: 기한(~까지)을 나타내어 어색합니다 ✗","A: 'a los diez minutos'처럼 쓰면 과거 '10분 뒤'가 되지만 이 형태는 틀립니다 ✗","En: '~후에' → 정답 ✓"]},{"id":"G396","q":"Te noto siempre baja de energía. Yo ____ trabajaría menos.","o":["que ti","que tú","a ti","tú"],"a":1,"k":"yo que tú","t":"너 늘 기운이 없어 보여. 내가 너라면 일을 덜 하겠어.","e":"'Yo que tú ~'는 '내가 너라면'이라는 충고 표현으로, 뒤에 조건법(trabajaría)이 옵니다. 비교의 que 뒤처럼 주격 tú를 씁니다. 같은 뜻으로 'Yo en tu lugar ~'도 있습니다.","x":["que ti: que 뒤에는 ti가 아니라 tú를 씁니다 ✗","que tú: '내가 너라면' → 정답 ✓","a ti: '너에게'라서 의미가 맞지 않습니다 ✗","tú: que가 빠지면 '나 너 일을 덜…'처럼 문장이 성립하지 않습니다 ✗"]},{"id":"G397","q":"Llegamos con el tiempo justo al aeropuerto. De hecho, los pasajeros ____ habían empezado a embarcar.","o":["aún","todavía","mientras","ya"],"a":3,"k":"ya (이미)","t":"우리는 아슬아슬하게 공항에 도착했다. 사실 승객들은 이미 탑승을 시작한 상태였다.","e":"ya는 '이미, 벌써'라는 뜻으로, 기대보다 일찍 어떤 일이 일어났음을 나타냅니다. 우리가 도착했을 때 탑승이 이미 시작되어 있었으므로 ya가 맞습니다. 반대로 aún/todavía는 '아직'입니다.","x":["aún: '아직'이라서 '시작했다'는 긍정문과 맞지 않습니다 ✗","todavía: aún과 같은 '아직'이라 ✗","mientras: '~하는 동안'이라는 접속사라 이 자리에 맞지 않습니다 ✗","ya: '이미' → 정답 ✓"]},{"id":"G398","q":"Hijo, ____ aquí un momento, quiero preguntarte algo.","o":["venga","ven","venid","vienes"],"a":1,"k":"tú 명령형","t":"아들아, 잠깐 이리 와 봐, 뭐 좀 물어보고 싶어.","e":"아들(tú)에게 하는 긍정 명령이므로 venir의 tú 명령형 ven을 씁니다. venir는 명령형이 불규칙입니다(ven, venga, venid, vengan). 참고로 아르헨티나 등 vos를 쓰는 지역에서는 'vení'라고 합니다.","x":["venga: usted에게 하는 명령형이라 ✗","ven: tú 긍정 명령 → 정답 ✓","venid: vosotros(너희)에게 하는 명령형이라 ✗","vienes: 직설법 현재(너는 온다)라 명령이 아닙니다 ✗"]},{"id":"G399","q":"____ sepa la respuesta a esta pregunta, que levante la mano.","o":["Quien","Los que","Que","Quienes"],"a":0,"k":"관계사 quien","t":"이 질문의 답을 아는 사람은 손을 드세요.","e":"선행사 없이 '~하는 사람'이라는 뜻으로 quien을 쓸 수 있습니다. 동사 sepa가 단수이므로 단수 quien이 맞습니다. '누군지 모르는 사람'이라 접속법 sepa를 씁니다.","x":["Quien: '~하는 사람(단수)' → 정답 ✓","Los que: 복수라 단수 동사 sepa와 맞지 않습니다 ✗","Que: 선행사 없이 단독으로 '~하는 사람'이 될 수 없습니다 ✗","Quienes: 복수라 sepa와 맞지 않습니다 ✗"]},{"id":"G400","q":"Necesito que me ____ su opinión sobre esto.","o":["das","de","dé","da"],"a":2,"k":"necesitar que + 접속법","t":"이것에 대한 당신의 의견을 저에게 말씀해 주셨으면 합니다.","e":"'Necesito que ~'처럼 필요·요청을 나타내고 주어가 다를 때는 접속법을 씁니다. su opinión이므로 상대는 usted이고, dar의 접속법 현재 3인칭 단수는 dé입니다. 전치사 de와 구별하기 위해 악센트를 꼭 붙입니다.","x":["das: 직설법 tú 형태라 ✗","de: 악센트 없는 de는 전치사(~의)입니다 ✗","dé: dar의 접속법 현재 3인칭(usted) → 정답 ✓","da: 직설법이라 necesitar que 뒤에 쓰지 않습니다 ✗"]},{"id":"G401","q":"____ esta ventana hay una vista maravillosa.","o":["De","Sobre","Desde","Bajo"],"a":2,"k":"전치사 desde","t":"이 창문에서는 멋진 경치가 보인다.","e":"desde는 '~에서(부터)'라는 출발점을 나타냅니다. 경치를 보는 '시작점'이 창문이므로 desde가 맞습니다. 예: Desde mi casa se ve el mar. (우리 집에서 바다가 보인다.)","x":["De: 출신·소유를 나타내어 보는 지점으로는 어색합니다 ✗","Sobre: '창문 위에'가 되어 ✗","Desde: 보는 출발점 '~에서' → 정답 ✓","Bajo: '창문 아래에'가 되어 ✗"]},{"id":"G402","q":"¡Ojalá ____ el examen!","o":["apruebes","aprobarás","aprobarías","apruebas"],"a":0,"k":"ojalá + 접속법","t":"네가 시험에 합격하길 바라!","e":"ojalá(~이면 좋겠다)는 바람을 나타내므로 항상 접속법을 씁니다. 실현 가능성이 있는 미래의 바람이므로 접속법 현재 apruebes를 씁니다. aprobar(합격하다)는 o→ue로 바뀌는 동사입니다.","x":["apruebes: 접속법 현재 → 정답 ✓","aprobarás: 직설법 미래라 ojalá 뒤에 쓰지 않습니다 ✗","aprobarías: 조건법이라 ✗","apruebas: 직설법 현재라 ✗"]},{"id":"G403","q":"Belén es menor ____ que su hermana Cristina.","o":["de","ø","con","a"],"a":1,"k":"menor que","t":"벨렌은 언니 크리스티나보다 어리다.","e":"menor(더 어린), mayor(더 나이 많은)는 그 자체가 비교급이라 뒤에 바로 que를 씁니다. 빈칸 뒤에 이미 que가 있으므로 아무것도 넣지 않습니다. 예: Soy mayor que tú. (내가 너보다 나이가 많다.)","x":["de: menor de que라는 형태는 없습니다 ✗","ø: menor que 그대로 → 정답 ✓","con: 비교 표현에 쓰지 않습니다 ✗","a: 비교 표현에 쓰지 않습니다 ✗"]},{"id":"G404","q":"____ en Córdoba hasta 1999.","o":["Estuve viviendo","Vivo","He vivido","He estado viviendo"],"a":0,"k":"단순과거 진행","t":"나는 1999년까지 코르도바에 살았다.","e":"'hasta 1999(1999년까지)'처럼 과거에 끝난 기간 동안 계속된 행동은 'estar 단순과거 + 현재분사'(estuve viviendo)로 쓸 수 있습니다. 'viví'라고 해도 됩니다. 현재와 이어지지 않으므로 현재완료는 쓰지 않습니다.","x":["Estuve viviendo: 과거에 끝난 기간 동안의 지속 → 정답 ✓","Vivo: 현재형이라 과거 기간과 맞지 않습니다 ✗","He vivido: 현재완료는 현재와 이어진 일에 써서 1999년에 끝난 일과 맞지 않습니다 ✗","He estado viviendo: 같은 이유로 ✗"]},{"id":"G405","q":"No me apetece ____ salir, voy a quedarme en casa.","o":["algo","muy","poco","mucho"],"a":3,"k":"부정문 mucho","t":"별로 나가고 싶지 않아, 집에 있을래.","e":"'No me apetece mucho ~'는 '별로 ~하고 싶지 않다'라는 뜻으로, 동사를 꾸미는 부사 mucho를 씁니다. apetecer는 스페인에서 '~이 당기다, ~하고 싶다'라는 뜻으로 gustar처럼 씁니다. 중남미에서는 'No tengo muchas ganas de salir'를 더 자주 씁니다.","x":["algo: 부정문에서 '별로'라는 뜻으로 쓰지 않습니다 ✗","muy: 동사나 동사원형을 꾸미지 않습니다 ✗","poco: no와 함께 쓰면 '조금도 아니게'라는 어색한 이중 의미가 됩니다 ✗","mucho: '별로 (~않다)' → 정답 ✓"]},{"id":"G406","q":"Estuve varios días sin salir de casa ____ estaba enfermo.","o":["porque","por","como","así que"],"a":0,"k":"porque (이유)","t":"나는 아파서 며칠 동안 집 밖에 나가지 않았다.","e":"주절 뒤에서 이유를 설명할 때는 porque(~때문에)를 씁니다. 뒤에 활용 동사 estaba가 오므로 접속사가 필요합니다. como는 이유를 말할 때 문장 맨 앞에 둡니다.","x":["porque: 주절 뒤 이유 접속사 → 정답 ✓","por: 전치사라 뒤에 명사나 동사원형이 와야 합니다 ✗","como: 이유의 como는 문장 맨 앞에 옵니다 ✗","así que: '그래서'라는 결과 표현이라 ✗"]},{"id":"G407","q":"No estoy de acuerdo ____ lo que dices.","o":["a","con","para","de"],"a":1,"k":"estar de acuerdo con","t":"나는 네 말에 동의하지 않아.","e":"'estar de acuerdo con ~'은 '~에 동의하다'라는 고정 표현입니다. 동의하는 대상(사람이나 의견) 앞에 con을 씁니다. 예: Estoy de acuerdo contigo. (나는 너에게 동의해.)","x":["a: 이 표현에 a를 쓰지 않습니다 ✗","con: estar de acuerdo con → 정답 ✓","para: 이 표현에 쓰지 않습니다 ✗","de: 'de acuerdo de'라는 표현은 없습니다 ✗"]},{"id":"G408","q":"Es un secreto, así que no ____ cuentes a nadie.","o":["se","les","le lo","se lo"],"a":3,"k":"se lo","t":"비밀이니까 아무에게도 말하지 마.","e":"'누구에게(a nadie)'와 '그것을(el secreto → lo)'이 함께 오면 le lo가 se lo로 바뀝니다. 부정 명령이므로 대명사는 동사 앞에 둡니다. 순서는 항상 '간접(se) + 직접(lo)'입니다.","x":["se: 직접목적격 lo(비밀을)가 빠져 있습니다 ✗","les: 직접목적격이 없고 se로 바꿔야 합니다 ✗","le lo: 함께 쓸 때 le는 se로 바뀌어야 합니다 ✗","se lo: 간접 + 직접 목적격 → 정답 ✓"]},{"id":"G409","q":"Yo nací dos años antes que David, soy ____ que él.","o":["menor","mayor","el menor","el mayor"],"a":1,"k":"mayor que","t":"나는 다비드보다 2년 먼저 태어났으니 그보다 나이가 많다.","e":"먼저 태어난 사람이 '더 나이 많은' 사람이므로 mayor를 씁니다. 뒤에 'que él'이 오는 비교 구문이므로 관사 없는 mayor가 맞습니다. 'el mayor'는 '가장 나이 많은'이라는 최상급이라 que와 함께 쓰지 않습니다.","x":["menor: '더 어린'이라 반대입니다 ✗","mayor: '더 나이 많은' → 정답 ✓","el menor: 최상급인 데다 뜻도 반대입니다 ✗","el mayor: 최상급이라 'que él'과 함께 쓰지 않습니다 ✗"]},{"id":"G410","q":"____ levantarme, sentí un mareo.","o":["En cuanto","Cuando","Tan pronto como","Al"],"a":3,"k":"al + 원형","t":"일어나자 어지러움을 느꼈다.","e":"'al + 동사원형'은 '~할 때, ~하자'라는 뜻으로 두 행동이 거의 동시에 일어날 때 씁니다. 빈칸 뒤가 동사원형 levantarme이므로 al만 가능합니다. 예: Al llegar a casa, me duché. (집에 도착하자 샤워했다.)","x":["En cuanto: 뒤에 활용 동사가 와야 합니다(en cuanto me levanté) ✗","Cuando: 뒤에 활용 동사가 와야 합니다 ✗","Tan pronto como: 뒤에 활용 동사가 와야 합니다 ✗","Al: al + 동사원형 → 정답 ✓"]},{"id":"G411","q":"No me interesa ____ a esa exposición de arte.","o":["iré","yendo","que voy","ir"],"a":3,"k":"부정사 주어","t":"나는 그 미술 전시회에 가는 데 관심이 없다.","e":"interesar(관심을 끌다)는 gustar처럼 '관심 대상'이 주어입니다. 주어가 행동일 때는 동사원형을 쓰므로 'ir a esa exposición'이 됩니다. 예: Me interesa aprender idiomas. (나는 언어 배우는 데 관심이 있다.)","x":["iré: 활용 동사라 주어 자리에 올 수 없습니다 ✗","yendo: 현재분사는 주어가 될 수 없습니다 ✗","que voy: que절이라면 접속법이 필요하고, 주어가 같을 때는 원형을 씁니다 ✗","ir: 주어 역할의 동사원형 → 정답 ✓"]},{"id":"G412","q":"Nunca hemos comido ____ un restaurante japonés.","o":["por","para","a","en"],"a":3,"k":"전치사 en (장소)","t":"우리는 일본 식당에서 한 번도 먹어 본 적이 없다.","e":"어떤 장소 '안에서' 무언가를 할 때는 en을 씁니다. 'comer en un restaurante'는 '식당에서 먹다'입니다. 방향(~로 가다)이라면 a를 씁니다(ir a un restaurante).","x":["por: '~근처/~을 지나'라는 뜻이라 ✗","para: 목적·대상을 나타내어 ✗","a: 방향을 나타내어 comer와 맞지 않습니다 ✗","en: 장소 '~에서' → 정답 ✓"]},{"id":"G413","q":"¿____ qué cama prefieres dormir tú?","o":["Por","Desde","A","En"],"a":3,"k":"전치사 + 의문사","t":"너는 어느 침대에서 자는 게 더 좋아?","e":"'dormir en una cama(침대에서 자다)'의 en이 의문문에서 의문사 앞으로 나옵니다. 스페인어는 전치사를 문장 끝에 두지 않고 반드시 의문사 앞에 둡니다. 예: ¿Con quién vas? (누구랑 가?)","x":["Por: 침대를 '지나서'라는 뜻이 되어 ✗","Desde: '~에서부터'라서 ✗","A: 방향을 나타내어 dormir와 맞지 않습니다 ✗","En: dormir en의 en → 정답 ✓"]},{"id":"G414","q":"Deberías ____ fumar. ¡Es malo para tu salud!","o":["dejar de","acabar de","volver a","estar a punto de"],"a":0,"k":"dejar de + 원형","t":"담배를 끊어야 해. 건강에 나쁘다고!","e":"'dejar de + 동사원형'은 '~하는 것을 그만두다, 끊다'라는 뜻입니다. 담배가 건강에 나쁘다고 했으니 '끊다'가 맞습니다. 예: Dejé de beber café. (나는 커피를 끊었다.)","x":["dejar de: '~을 그만두다' → 정답 ✓","acabar de: '방금 ~했다'라서 ✗","volver a: '다시 ~하다'라서 반대 의미입니다 ✗","estar a punto de: '막 ~하려는 참이다'라서 ✗"]},{"id":"G415","q":"Espero que sepas ____ estás haciendo.","o":["lo que","la que","que","el que"],"a":0,"k":"중성 관계사 lo que","t":"네가 뭘 하고 있는지 알고 있길 바란다.","e":"lo que는 '~하는 것'이라는 뜻으로, 특정 명사가 아닌 막연한 내용을 가리킵니다. 'lo que estás haciendo'는 '네가 하고 있는 것'입니다. 'Espero que'는 바람이라 뒤에 접속법 sepas가 왔습니다.","x":["lo que: 막연한 내용 '~하는 것' → 정답 ✓","la que: 여성 명사를 가리킬 때만 씁니다 ✗","que: 선행사 없이 단독으로 '~하는 것'이 될 수 없습니다 ✗","el que: 남성 명사를 가리킬 때 씁니다 ✗"]},{"id":"G416","q":"¿Qué ____ tú si te pasara algo así?","o":["harías","habías hecho","hacías","hiciste"],"a":0,"k":"가정문 조건법","t":"너라면 그런 일이 생기면 어떻게 하겠니?","e":"'si + 접속법 과거(pasara)' 가정문에서 주절에는 조건법(~할 텐데)을 씁니다. hacer의 조건법 2인칭 단수는 harías입니다(불규칙). 현실이 아닌 가상의 상황을 말하는 구조입니다.","x":["harías: 가정문 주절의 조건법 → 정답 ✓","habías hecho: 과거완료라 가정문 주절에 맞지 않습니다 ✗","hacías: 불완료과거라 ✗","hiciste: 단순과거라 ✗"]},{"id":"G417","q":"No sé dónde está el gato. ____ está en el jardín.","o":["Es probable que","Es posible que","Puede que","A lo mejor"],"a":3,"k":"a lo mejor + 직설법","t":"고양이가 어디 있는지 모르겠어. 아마 정원에 있을 거야.","e":"'아마 ~일 것이다'를 나타내는 표현 중 'a lo mejor'는 뒤에 직설법을 씁니다. 반면 'es probable que, es posible que, puede que'는 접속법을 씁니다. 빈칸 뒤가 직설법 está이므로 a lo mejor만 맞습니다.","x":["Es probable que: 뒤에 접속법(esté)이 와야 합니다 ✗","Es posible que: 뒤에 접속법이 와야 합니다 ✗","Puede que: 뒤에 접속법이 와야 합니다 ✗","A lo mejor: 직설법과 함께 쓰는 '아마' → 정답 ✓"]},{"id":"G418","q":"Nunca ____ hemos estado en Islandia, pero nos encantaría ir.","o":["ya","no","ø","aún"],"a":2,"k":"nunca 단독 부정","t":"우리는 아이슬란드에 한 번도 가 본 적이 없지만, 정말 가 보고 싶다.","e":"nunca(결코, 한 번도)가 동사 앞에 오면 no를 따로 쓰지 않습니다. 동사 뒤에 올 때만 no가 필요합니다(No hemos estado nunca). 그래서 빈칸에는 아무것도 넣지 않습니다.","x":["ya: '이미'라는 뜻이라 nunca와 모순됩니다 ✗","no: nunca가 동사 앞에 있을 때는 no를 쓰지 않습니다 ✗","ø: nunca 단독으로 부정 → 정답 ✓","aún: '아직'이라 이 자리에서 어색합니다 ✗"]},{"id":"G419","q":"¿Cuánto tiempo ____ con Inés?","o":["sigues saliendo","vas saliendo","estás saliendo","llevas saliendo"],"a":3,"k":"llevar + 현재분사","t":"너는 이네스와 사귄 지 얼마나 됐니?","e":"'llevar + 기간 + 현재분사'는 '~째 ~하고 있다'라는 뜻으로, 어떤 일을 얼마나 계속해 왔는지 말합니다. '¿Cuánto tiempo llevas + 현재분사?'는 기간을 묻는 대표적 표현입니다. salir con은 '~와 사귀다'라는 뜻입니다.","x":["sigues saliendo: '여전히 사귀고 있다'라서 기간 질문과 맞지 않습니다 ✗","vas saliendo: ir + 현재분사는 '점점 ~해 가다'라서 ✗","estás saliendo: 진행 중임을 말할 뿐 기간을 묻지 못합니다 ✗","llevas saliendo: '~째 사귀고 있다' → 정답 ✓"]},{"id":"G420","q":"Hoy tenemos clase en el aula 12; ____ otras aulas no están disponibles.","o":["las","unas","unos","los"],"a":0,"k":"정관사 las","t":"오늘은 12호 강의실에서 수업이 있어. 다른 강의실들은 사용할 수 없거든.","e":"aula(강의실)는 여성 명사이고, 여기서는 '나머지 특정한 강의실들'을 가리키므로 정관사 las를 씁니다. 참고로 aula는 강세 있는 a-로 시작해 단수에서는 'el aula'라고 하지만 복수는 'las aulas'입니다.","x":["las: 여성 복수 정관사, 나머지 특정한 강의실들 → 정답 ✓","unas: '어떤 강의실들'이라 '다른 강의실 전부'의 뜻이 되지 않습니다 ✗","unos: 남성형이라 여성 명사 aulas와 맞지 않습니다 ✗","los: 남성형이라 ✗"]},{"id":"G421","q":"Voy a recoger la ropa tendida antes de que ____ a llover.","o":["empiece","empieza","empezase","empezará"],"a":0,"k":"antes de que + 접속법","t":"비가 오기 시작하기 전에 널어 둔 빨래를 걷을게.","e":"'antes de que ~(~하기 전에)'는 항상 접속법을 씁니다. 주절이 현재·미래이므로 접속법 현재 empiece(empezar, e→ie, z→c)가 됩니다. 'empezar a + 원형'은 '~하기 시작하다'입니다.","x":["empiece: antes de que 뒤 접속법 현재 → 정답 ✓","empieza: 직설법이라 antes de que 뒤에 쓰지 않습니다 ✗","empezase: 접속법 과거라 현재·미래 주절과 맞지 않습니다 ✗","empezará: 직설법 미래라 ✗"]},{"id":"G422","q":"Fui a buscar al niño a la escuela, pero mi marido ya lo ____.","o":["estuvo recogiendo","ha recogido","había recogido","recogía"],"a":2,"k":"과거완료","t":"아이를 데리러 학교에 갔는데, 남편이 이미 데려간 뒤였다.","e":"과거의 한 시점(내가 학교에 갔을 때)보다 먼저 끝난 일은 과거완료(había + 과거분사)로 씁니다. 남편이 데려간 일이 내가 도착하기 전에 일어났으므로 había recogido가 맞습니다. ya(이미)와 자주 함께 씁니다.","x":["estuvo recogiendo: 일정 기간 계속된 행동이라 의미가 맞지 않습니다 ✗","ha recogido: 현재완료라 과거 이야기와 맞지 않습니다 ✗","había recogido: 과거 시점보다 앞선 일 → 정답 ✓","recogía: 불완료과거라 반복·배경 의미가 되어 ✗"]},{"id":"G423","q":"¿Qué es ____ menos te gusta del pueblo en el que vives?","o":["que","lo que","lo cual","el que"],"a":1,"k":"중성 관계사 lo que","t":"네가 사는 마을에서 가장 마음에 안 드는 건 뭐야?","e":"'lo que'는 '~하는 것'이라는 뜻으로 막연한 대상을 가리킵니다. '¿Qué es lo que más/menos te gusta?'는 '가장 좋아하는/싫어하는 게 뭐야?'라고 묻는 아주 흔한 표현입니다.","x":["que: 선행사 없이 '~하는 것'이 되지 못합니다 ✗","lo que: '~하는 것' → 정답 ✓","lo cual: 앞 문장 전체를 받을 때만 쓰며 이 자리에 쓰지 않습니다 ✗","el que: 특정 남성 명사를 가리킬 때 써서 막연한 질문과 맞지 않습니다 ✗"]},{"id":"G424","q":"Tengo que contarte ____ cosa importante.","o":["la","un","una","ø"],"a":2,"k":"부정관사 una","t":"너한테 중요한 걸 하나 말해야 해.","e":"처음 꺼내는 '어떤 하나의' 일이므로 부정관사를 씁니다. cosa(것, 일)는 여성 명사라 una가 됩니다. 예: Tengo una pregunta. (질문이 하나 있어.)","x":["la: 정관사는 이미 아는 특정한 것에 씁니다 ✗","un: 남성형이라 여성 명사 cosa와 맞지 않습니다 ✗","una: 여성 단수 부정관사 → 정답 ✓","ø: 단수 가산명사 앞에 관사가 필요합니다 ✗"]},{"id":"G425","q":"María tiene ____ novio desde hace dos años.","o":["el","uno","al","ø"],"a":3,"k":"tener + 관사 생략","t":"마리아는 2년 전부터 남자친구가 있다.","e":"tener 뒤에 보통 하나만 있는 것(남자친구, 차, 직업 등)이 오면 관사를 생략하는 경우가 많습니다: tener novio, tener coche, tener trabajo. 'desde hace dos años'는 '2년 전부터'라는 뜻입니다.","x":["el: 정관사를 쓰면 '그 남자친구'가 되어 어색합니다 ✗","uno: 명사 앞에서는 un으로 줄여야 하고, 이 표현에서는 보통 관사를 생략합니다 ✗","al: a + el이라 tener 뒤에 맞지 않습니다 ✗","ø: tener novio, 관사 생략 → 정답 ✓"]},{"id":"G426","q":"Ojalá te vaya bien cuando ____ al extranjero.","o":["te vas","irte","te has ido","te vayas"],"a":3,"k":"cuando + 접속법","t":"외국에 나가게 되면 잘 지내길 바라.","e":"cuando가 아직 일어나지 않은 미래의 일을 가리키면 접속법 현재를 씁니다. irse(떠나다)의 접속법 현재 2인칭 단수는 te vayas입니다. 'Ojalá te vaya bien'은 '잘되길 바라'라는 덕담입니다.","x":["te vas: 직설법이라 미래를 가리키는 cuando 뒤에 쓰지 않습니다 ✗","irte: 동사원형이라 cuando 뒤에 올 수 없습니다 ✗","te has ido: 직설법 현재완료라 ✗","te vayas: 접속법 현재 → 정답 ✓"]},{"id":"G427","q":"¿____ es el país más extenso del mundo?","o":["Dónde","Cuál","Qué","Quién"],"a":1,"k":"cuál vs qué","t":"세계에서 가장 넓은 나라는 어디야?","e":"'¿Cuál es ~?'는 여러 개 중 '어느 것'인지를 물을 때 씁니다. 여러 나라 중 하나를 고르는 질문이므로 cuál이 맞습니다. ser 앞에서 qué를 쓰면 '정의(~란 무엇인가)'를 묻는 말이 됩니다(¿Qué es un país?).","x":["Dónde: '어디에'라는 위치 질문이라 ser 구문과 맞지 않습니다 ✗","Cuál: 여러 개 중 '어느 것' → 정답 ✓","Qué: ser 앞에서는 정의를 묻는 질문이 되어 ✗","Quién: 사람을 묻는 '누구'라서 ✗"]},{"id":"G428","q":"Ana y yo nacimos ____ mismo día.","o":["los","la","ø","el"],"a":3,"k":"el mismo día","t":"아나와 나는 같은 날 태어났다.","e":"'같은 ~'는 '정관사 + mismo + 명사'로 표현합니다. día는 -a로 끝나지만 남성 명사라 'el mismo día'가 됩니다. 비슷한 예: el mapa(지도), el problema(문제)도 남성입니다.","x":["los: 복수라 단수 día와 맞지 않습니다 ✗","la: día는 남성 명사이므로 ✗","ø: mismo 앞에는 정관사가 필요합니다 ✗","el: 남성 단수 정관사 → 정답 ✓"]},{"id":"G429","q":"Es una pena que te ____ de tu trabajo. Lo siento.","o":["están despidiendo","han despedido","hayan despedido","habían despedido"],"a":2,"k":"접속법 현재완료","t":"네가 직장에서 해고당했다니 안타깝다. 유감이야.","e":"'Es una pena que ~(~라니 안타깝다)'는 감정 표현이라 접속법을 씁니다. 이미 일어난 일에 대한 현재의 감정이므로 접속법 현재완료(hayan + 과거분사)를 씁니다. 여기서 주어는 막연한 '그들(회사)'입니다.","x":["están despidiendo: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","han despedido: 직설법 현재완료라 ✗","hayan despedido: 접속법 현재완료 → 정답 ✓","habían despedido: 직설법 과거완료라 ✗"]},{"id":"G430","q":"Los chicos ____ quienes conocí el sábado están viajando por España.","o":["de","a","con","por"],"a":1,"k":"전치사 + quienes","t":"내가 토요일에 만난 그 남자애들은 스페인을 여행하고 있다.","e":"'conocer a alguien(누군가를 알게 되다)'처럼 사람 목적어 앞에는 인칭 a가 필요합니다. 관계절에서 이 a가 관계대명사 quienes 앞으로 옵니다. 'a quienes'는 'a los que'로 바꿔 쓸 수도 있습니다.","x":["de: conocer와 함께 쓰지 않습니다 ✗","a: 사람 목적어 앞 인칭 a → 정답 ✓","con: '~와 함께'라서 conocer의 목적어 표시가 아닙니다 ✗","por: 이유·경로를 나타내어 ✗"]},{"id":"G431","q":"No me gusta el jersey verde, prefiero ____ azul.","o":["el","una","lo","un"],"a":0,"k":"명사 생략 el + 형용사","t":"초록색 스웨터는 마음에 안 들어, 파란 게 더 좋아.","e":"앞에 나온 명사(jersey)를 반복하지 않을 때 '관사 + 형용사'로 씁니다. jersey는 남성 명사이고 '그 파란 스웨터'라는 특정한 것이므로 'el azul'이 됩니다. jersey는 스페인식 표현이고, 중남미에서는 suéter를 많이 씁니다.","x":["el: 남성 정관사 + 형용사로 명사 생략 → 정답 ✓","una: 여성형이라 jersey와 맞지 않습니다 ✗","lo: 중성 관사로 '파란 것(일반적인 성질)'이 되어 ✗","un: '파란 것 하나'라 일반적인 선호를 말하기에 어색합니다 ✗"]},{"id":"G432","q":"Tengo mucha ropa negra, pero no me ____ pongo casi nunca.","o":["la","las","lo","los"],"a":0,"k":"직접목적격 la","t":"나는 검은 옷이 많지만, 거의 입지 않는다.","e":"앞에 나온 'ropa negra(검은 옷)'를 다시 가리키는 직접목적격 대명사(~을/를)가 필요합니다. ropa는 여성 단수 명사(옷 전체를 하나로 봄)이므로 la를 씁니다. ponerse는 '(옷을) 입다'입니다.","x":["la: 여성 단수 ropa를 받는 직접목적격 → 정답 ✓","las: 복수라 단수 명사 ropa와 맞지 않습니다 ✗","lo: 남성형이라 ✗","los: 남성 복수라 ✗"]},{"id":"G433","q":"Encontré un cuaderno ____ en el aula de informática.","o":["de ti","tuyo","de tú","el tuyo"],"a":1,"k":"강세형 소유사","t":"컴퓨터실에서 네 공책을 발견했어.","e":"'un cuaderno tuyo'는 '네 공책 중 하나'라는 뜻으로, 명사 뒤에 강세형 소유사를 씁니다. cuaderno가 남성 단수이므로 tuyo가 됩니다. 'tu cuaderno'는 명사 앞에서만 씁니다.","x":["de ti: '너의'를 de ti로 표현하지 않습니다 ✗","tuyo: 명사 뒤 남성 단수 강세형 소유사 → 정답 ✓","de tú: 전치사 뒤에 tú를 쓸 수 없습니다 ✗","el tuyo: 이미 un이 있어 관사가 중복됩니다 ✗"]},{"id":"G434","q":"Es muy probable que ____ tarde.","o":["llegar","llegaremos","lleguemos","llegamos"],"a":2,"k":"es probable que","t":"우리는 늦게 도착할 가능성이 매우 크다.","e":"'Es probable que ~(~할 것 같다)'는 가능성을 나타내므로 뒤에 접속법을 씁니다. llegar의 접속법 현재 1인칭 복수는 lleguemos입니다(g→gu 철자 변화에 주의). 'llegar tarde'는 '늦게 도착하다, 지각하다'입니다.","x":["llegar: 동사원형이라 que 뒤에 올 수 없습니다 ✗","llegaremos: 직설법 미래라 ✗","lleguemos: 접속법 현재 → 정답 ✓","llegamos: 직설법이라 ✗"]},{"id":"G435","q":"Me parece raro que Inma ya no ____ a nuestro lado.","o":["se siente","se ha sentado","se había sentado","se sienta"],"a":0,"k":"감정 + 접속법","t":"인마가 이제 우리 옆에 앉지 않는다니 이상하다.","e":"'Me parece raro que ~(~가 이상하게 느껴진다)'는 평가·감정 표현이라 접속법을 씁니다. sentarse(앉다)의 접속법 현재 3인칭 단수는 se siente입니다. sentirse(느끼다)의 직설법 se siente와 형태가 같으니 문맥으로 구별하세요.","x":["se siente: sentarse(앉다)의 접속법 현재 → 정답 ✓","se ha sentado: 직설법 현재완료라 ✗","se había sentado: 직설법 과거완료라 ✗","se sienta: sentarse의 직설법 현재라 감정 표현 뒤에 쓰지 않습니다 ✗"]},{"id":"G436","q":"¿Cuántas veces por semana te lavas ____ pelo?","o":["el","su","tú","tu"],"a":0,"k":"신체 부위 + 정관사","t":"일주일에 몇 번 머리를 감니?","e":"재귀동사(lavarse)와 함께 신체 부위를 말할 때는 소유사 대신 정관사를 씁니다. 재귀대명사 te가 이미 '네 자신의'라는 뜻을 나타내기 때문입니다. 예: Me duele la cabeza. (머리가 아파.)","x":["el: 신체 부위 앞 정관사 → 정답 ✓","su: 소유사는 쓰지 않고, 3인칭이라 맞지도 않습니다 ✗","tú: 주격 대명사라 명사 앞에 올 수 없습니다 ✗","tu: 재귀동사와 신체 부위에는 소유사 대신 정관사를 씁니다 ✗"]},{"id":"G437","q":"¿____ vas a estas horas de la noche?","o":["Adónde","Donde","De dónde","Adonde"],"a":0,"k":"adónde","t":"이 밤늦은 시간에 어디 가니?","e":"ir처럼 이동 동사와 함께 '어디로'를 물을 때는 의문사 adónde(a + dónde)를 씁니다. 의문사이므로 악센트가 꼭 필요합니다. 악센트 없는 adonde는 관계사(~하는 곳으로)입니다.","x":["Adónde: 방향을 묻는 의문사 → 정답 ✓","Donde: 악센트가 없어 관계사이고, 방향 표시 a도 없습니다 ✗","De dónde: '어디서부터'라서 ir와 맞지 않습니다 ✗","Adonde: 악센트가 없는 관계사라 의문문에 쓰지 않습니다 ✗"]},{"id":"G438","q":"¿____ me hablas como si fuera un niño pequeño?","o":["Porqué","Por que","Por qué","Porque"],"a":2,"k":"por qué","t":"왜 나를 어린애처럼 대하며 말하니?","e":"이유를 묻는 의문사 '왜'는 띄어 쓰고 악센트를 붙인 por qué입니다. 대답할 때 쓰는 porque(~때문에)와 헷갈리지 마세요. 'como si + 접속법 과거'는 '마치 ~인 것처럼'입니다.","x":["Porqué: 명사 '이유'라서 의문사로 쓰지 않습니다 ✗","Por que: 악센트가 없어 의문사가 아닙니다 ✗","Por qué: 의문사 '왜' → 정답 ✓","Porque: 이유 접속사 '~때문에'라서 ✗"]},{"id":"G439","q":"Es una pena que Cristina no ____ asistir a la ceremonia.","o":["pueda","podría","puede","ha podido"],"a":0,"k":"es una pena que","t":"크리스티나가 행사에 참석하지 못한다니 아쉽다.","e":"'Es una pena que ~(~라니 아쉽다)'는 감정 표현이라 뒤에 접속법을 씁니다. 현재·미래의 일이므로 poder의 접속법 현재 pueda를 씁니다. asistir a는 '~에 참석하다'입니다.","x":["pueda: 접속법 현재 → 정답 ✓","podría: 조건법이라 ✗","puede: 직설법이라 감정 표현 뒤에 쓰지 않습니다 ✗","ha podido: 직설법 현재완료라 ✗"]},{"id":"G440","q":"Si estás ____ indignado, ¿por qué no hablas con tu jefa?","o":["tantos","tanto","tanta","tan"],"a":3,"k":"tan + 형용사","t":"그렇게 화가 났으면 상사에게 이야기하지 그래?","e":"형용사 indignado(분개한) 앞에서 '그렇게'라고 할 때는 tan을 씁니다. tanto는 동사 뒤나 명사 앞에서 형태를 바꿔 씁니다. 예: Estás tan cansado. (너 정말 피곤하구나.)","x":["tantos: 남성 복수 명사 앞 형태라 ✗","tanto: 동사 뒤에 쓰는 형태라 형용사 앞에 쓰지 않습니다 ✗","tanta: 여성 단수 명사 앞 형태라 ✗","tan: 형용사 앞의 '그렇게' → 정답 ✓"]},{"id":"G441","q":"¿Me das ____ otro boli? Este no escribe bien.","o":["un","ø","uno","una"],"a":1,"k":"otro 관사 생략","t":"볼펜 하나 더 줄래? 이건 잘 안 나와.","e":"otro(다른, 또 하나의) 앞에는 부정관사 un/una를 쓰지 않습니다. 'un otro boli'는 영어식 표현이라 틀립니다. boli는 bolígrafo(볼펜)의 줄임말로 스페인에서 씁니다.","x":["un: otro 앞에는 부정관사를 쓰지 않습니다 ✗","ø: otro 단독 → 정답 ✓","uno: 같은 이유로 쓰지 않습니다 ✗","una: 여성형이고 otro 앞에 쓰지 않습니다 ✗"]},{"id":"G442","q":"____ cansado, deberías hacer una pausa.","o":["Parecéis","Te pareces","Pareces","Os parecéis"],"a":2,"k":"parecer vs parecerse","t":"피곤해 보여, 좀 쉬는 게 좋겠어.","e":"'parecer + 형용사'는 '~해 보이다'라는 뜻입니다. 재귀형 parecerse는 '(누구와) 닮다'라는 다른 뜻입니다. deberías가 tú 형태이므로 2인칭 단수 pareces를 씁니다.","x":["Parecéis: vosotros 형태라 deberías(tú)와 맞지 않습니다 ✗","Te pareces: parecerse는 '닮다'라는 뜻이라 ✗","Pareces: '너는 ~해 보인다' → 정답 ✓","Os parecéis: '너희는 서로 닮았다'라는 뜻이라 ✗"]},{"id":"G443","q":"Lo que más valoro en la vida es ____ libertad.","o":["el","lo","ø","la"],"a":3,"k":"추상명사 정관사","t":"내가 인생에서 가장 소중히 여기는 것은 자유다.","e":"자유, 사랑, 행복처럼 추상적인 개념을 일반적으로 말할 때는 정관사를 씁니다. libertad(자유)는 -dad로 끝나는 여성 명사라 la를 씁니다. -dad, -tad, -ción으로 끝나는 명사는 대부분 여성입니다.","x":["el: 남성형이라 여성 명사 libertad와 맞지 않습니다 ✗","lo: 중성 관사라 명사 앞에 쓰지 않습니다 ✗","ø: 일반적 개념의 추상명사 앞에는 관사가 필요합니다 ✗","la: 여성 정관사 → 정답 ✓"]},{"id":"G444","q":"El yoga es ____ para la mente y para el cuerpo.","o":["bien","bueno","buen","buena"],"a":1,"k":"bueno vs bien","t":"요가는 정신과 몸에 좋다.","e":"'ser bueno para ~'는 '~에 좋다'라는 뜻으로, ser 뒤에는 형용사 bueno를 씁니다. 주어 el yoga가 남성 단수이므로 bueno입니다. bien은 부사(잘)라서 'estar bien', 'hablar bien'처럼 씁니다.","x":["bien: 부사라 ser 뒤에서 성질을 나타내지 않습니다 ✗","bueno: 남성 단수 형용사 → 정답 ✓","buen: 명사 앞에서만 쓰는 단축형이라 ✗","buena: 여성형이라 남성 주어 el yoga와 맞지 않습니다 ✗"]},{"id":"G445","q":"Hay que lavarse las manos ____ comer.","o":["antes a","antes de","antes","de antes"],"a":1,"k":"antes de + 원형","t":"먹기 전에 손을 씻어야 한다.","e":"'~하기 전에'는 'antes de + 동사원형'으로 씁니다. 주어가 다를 때만 'antes de que + 접속법'을 씁니다. 'hay que'는 '(일반적으로) ~해야 한다'입니다.","x":["antes a: antes는 a와 함께 쓰지 않습니다 ✗","antes de: antes de + 동사원형 → 정답 ✓","antes: 동사원형 앞에 de가 필요합니다 ✗","de antes: '예전의'라는 뜻이라 ✗"]},{"id":"G446","q":"Te he dicho varias veces que no me ____ como si fuera tonto.","o":["estás hablando","hablarías","hables","hablas"],"a":2,"k":"부정 명령 전달","t":"나를 바보 취급하듯 말하지 말라고 여러 번 말했잖아.","e":"decir que가 '말하다(전달)'가 아니라 '~하라고 하다(명령·요청)'의 뜻일 때는 que 뒤에 접속법을 씁니다. 주절 he dicho가 현재완료이므로 접속법 현재 hables가 됩니다. 비교: Te digo que hablas mucho. (너 말이 많다고 하는 거야.)","x":["estás hablando: 직설법이라 명령·요청의 decir que 뒤에 쓰지 않습니다 ✗","hablarías: 조건법이라 ✗","hables: 요청의 decir que 뒤 접속법 현재 → 정답 ✓","hablas: 직설법이라 사실 전달 의미가 되어 ✗"]},{"id":"G447","q":"¡Ojalá nos ____ el primer premio!","o":["toque","tocar","tocaría","tocará"],"a":0,"k":"ojalá + 접속법","t":"우리가 1등상에 당첨되면 좋겠다!","e":"ojalá(~이면 좋겠다) 뒤에는 접속법을 씁니다. 'tocar el premio a alguien'은 '(누구에게) 상이 당첨되다'라는 뜻으로, 상(el primer premio)이 주어라서 3인칭 단수 toque가 됩니다. 복권 이야기에서 자주 씁니다.","x":["toque: 접속법 현재 3인칭 단수 → 정답 ✓","tocar: 동사원형이라 ojalá 뒤에 쓰지 않습니다 ✗","tocaría: 조건법이라 ✗","tocará: 직설법 미래라 ✗"]},{"id":"G448","q":"Comprendemos que tengas miedo ____ volar, pero el avión es bastante seguro.","o":["en","con","a","para"],"a":2,"k":"miedo a","t":"네가 비행기 타는 걸 무서워하는 건 이해해, 하지만 비행기는 꽤 안전해.","e":"'tener miedo a ~'는 '~을 무서워하다'라는 표현입니다. 'miedo de'도 함께 쓰이지만 보기 중에는 a만 있습니다. 예: Tengo miedo a los perros. (나는 개가 무섭다.)","x":["en: miedo와 함께 쓰지 않습니다 ✗","con: miedo와 함께 쓰지 않습니다 ✗","a: tener miedo a → 정답 ✓","para: miedo와 함께 쓰지 않습니다 ✗"]},{"id":"G449","q":"Señora, no puede estacionar aquí, ____ siento.","o":["ø","lo","la","le"],"a":1,"k":"lo siento","t":"부인, 여기에 주차하시면 안 됩니다, 죄송합니다.","e":"'Lo siento'는 '죄송합니다, 유감입니다'라는 고정 표현입니다. lo는 '그 상황'을 가리키는 중성 직접목적격 대명사입니다. estacionar(주차하다)는 중남미에서 많이 쓰고, 스페인에서는 aparcar를 주로 씁니다.","x":["ø: sentir 단독으로는 '느끼다'가 되어 사과 표현이 되지 않습니다 ✗","lo: 'lo siento' 고정 표현 → 정답 ✓","la: 여성형이라 이 표현에 쓰지 않습니다 ✗","le: 간접목적격이라 이 표현에 쓰지 않습니다 ✗"]},{"id":"G450","q":"Nos enseñó Madrid ____ guía muy simpático.","o":["una","el","un","la"],"a":2,"k":"guía 성 구별","t":"아주 친절한 가이드가 우리에게 마드리드를 구경시켜 주었다.","e":"guía(가이드)는 남녀 형태가 같은 명사로 관사로 성별을 나타냅니다(el/la guía). 형용사 simpático가 남성형이므로 남성 가이드이고, 처음 등장하는 사람이라 부정관사 un을 씁니다. 참고로 'la guía'는 '안내서'라는 뜻도 됩니다.","x":["una: 여성형이라 simpático(남성)와 맞지 않습니다 ✗","el: 처음 언급하는 사람이라 정관사는 어색합니다 ✗","un: 남성 단수 부정관사 → 정답 ✓","la: 여성형이라 simpático와 맞지 않습니다 ✗"]},{"id":"G451","q":"A mis compañeros de clase no ____ interesa el ciclismo, prefieren el fútbol.","o":["le","les","los","ø"],"a":1,"k":"interesar 구문","t":"우리 반 친구들은 사이클에 관심이 없고, 축구를 더 좋아한다.","e":"interesar(~에게 관심을 끌다)는 gustar처럼 '관심을 느끼는 사람'을 간접목적격 대명사(~에게)로 씁니다. 'A mis compañeros de clase(내 반 친구들에게)'는 3인칭 복수이므로 les가 필요합니다. 'a + 사람'이 앞에 나와도 대명사 les를 반드시 함께 씁니다.","x":["le: 3인칭 단수 간접목적격(그/그녀에게)이라 복수인 친구들과 맞지 않습니다 ✗","les: 3인칭 복수 간접목적격(그들에게) → 정답 ✓","los: 직접목적격(그들을)이라 interesar 구문에 쓰지 않습니다 ✗","ø: 'a + 사람'이 있어도 interesar 앞의 간접목적격 대명사는 생략할 수 없습니다 ✗"]},{"id":"G452","q":"____ tren une a las dos principales ciudades españolas.","o":["Estos","Esto","Esta","Este"],"a":3,"k":"지시형용사 este","t":"이 기차는 스페인의 두 주요 도시를 연결한다.","e":"tren(기차)은 남성 단수 명사이므로 '이 ~'는 남성 단수 지시형용사 este를 씁니다. 지시형용사는 뒤에 오는 명사의 성·수에 맞춰 este/esta/estos/estas로 바뀝니다.","x":["Estos: 남성 복수(이 ~들)라서 단수인 tren과 맞지 않습니다 ✗","Esto: 중성 지시대명사(이것)로 명사 앞에 쓰지 않습니다 ✗","Esta: 여성 단수라서 남성 명사 tren과 맞지 않습니다 ✗","Este: 남성 단수 지시형용사(이) → 정답 ✓"]},{"id":"G453","q":"¿____ mapas son actuales?","o":["Esta","Estes","Estos","Estas"],"a":2,"k":"지시형용사 estos","t":"이 지도들은 최신 것인가요?","e":"mapa는 -a로 끝나지만 남성 명사(el mapa)입니다. 따라서 복수 mapas 앞에는 남성 복수 지시형용사 estos를 씁니다. -a로 끝나는 남성 명사로는 el día, el problema, el idioma 등도 있으니 함께 기억하세요.","x":["Esta: 여성 단수라서 남성 복수 mapas와 맞지 않습니다 ✗","Estes: 스페인어에 없는 형태입니다 ✗","Estos: 남성 복수 지시형용사(이 ~들) → 정답 ✓","Estas: 여성 복수인데 mapa는 남성 명사입니다 ✗"]},{"id":"G454","q":"Ayer vi a Javier ____ la biblioteca de la universidad.","o":["de","en","a","con"],"a":1,"k":"장소 전치사 en","t":"어제 대학 도서관에서 하비에르를 봤다.","e":"어떤 일이 일어난 장소(~에서)를 나타낼 때는 전치사 en을 씁니다. 'vi a Javier en la biblioteca'는 '도서관에서 하비에르를 봤다'는 뜻입니다. 참고로 'vi a Javier'의 a는 사람이 직접목적어일 때 붙는 a입니다.","x":["de: 출신·소유(~의, ~로부터)를 나타내 장소 표현으로 맞지 않습니다 ✗","en: 장소(~에서, ~안에서)를 나타냄 → 정답 ✓","a: 방향(~로)을 나타내며 '~에서 보다'에는 쓰지 않습니다 ✗","con: 동반(~와 함께)을 나타내 의미가 맞지 않습니다 ✗"]},{"id":"G455","q":"No creo que Fernando ____ ver el partido, no le gusta el fútbol.","o":["querría","quiera","quiere","quería"],"a":1,"k":"no creo que+접속법","t":"페르난도가 경기를 보고 싶어 할 것 같지 않아, 그는 축구를 좋아하지 않거든.","e":"'No creo que(~라고 생각하지 않는다)'처럼 의심·부정을 나타내는 표현 뒤의 que절에는 접속법(바람·의심·감정을 나타내는 동사 형태)을 씁니다. 현재 일에 대한 의심이므로 querer의 접속법 현재 quiera가 맞습니다. 반대로 긍정 'Creo que quiere...'에서는 직설법을 씁니다.","x":["querría: 가정미래(~하고 싶을 텐데)라 no creo que 뒤에 오지 않습니다 ✗","quiera: querer의 접속법 현재 → 정답 ✓","quiere: 직설법 현재로, 부정 no creo que 뒤에는 쓰지 않습니다 ✗","quería: 직설법 불완료과거라 접속법이 필요한 자리에 맞지 않습니다 ✗"]},{"id":"G456","q":"¿____ es tu color favorito?","o":["Qué","Cuál","Cuánto","Quién"],"a":1,"k":"의문사 cuál/qué","t":"네가 가장 좋아하는 색은 뭐야?","e":"ser 동사 앞에서 여러 선택지 중 '어느 것'을 물을 때는 qué가 아니라 cuál을 씁니다. '¿Cuál es tu color favorito?(가장 좋아하는 색이 뭐야?)', '¿Cuál es tu nombre?'처럼 씁니다. qué는 정의를 물을 때(¿Qué es un ornitorrinco? 오리너구리가 뭐야?) 주로 씁니다.","x":["Qué: ser 앞에서 쓰면 정의(그게 무엇인가)를 묻는 뜻이 되어 어색합니다 ✗","Cuál: ser 앞에서 '어느 것/무엇'을 고르게 할 때 → 정답 ✓","Cuánto: 양(얼마나)을 묻는 말이라 색과 맞지 않습니다 ✗","Quién: 사람(누구)을 묻는 말입니다 ✗"]},{"id":"G457","q":"No ____ acuerdo de lo que hice ayer. ¡Qué cabeza!","o":["lo","me","me lo","ø"],"a":1,"k":"재귀동사 acordarse","t":"어제 내가 뭘 했는지 기억이 안 나. 정신머리하고는!","e":"acordarse de(~을 기억하다)는 재귀동사(자기 자신에게 동작이 돌아오는 동사)로, 주어에 맞는 재귀대명사가 필요합니다. 주어가 '나(yo)'이므로 me acuerdo가 됩니다. 기억하는 대상은 de 뒤에 오므로 따로 lo를 붙이지 않습니다.","x":["lo: 직접목적격 대명사(그것을)로, acordarse에는 재귀대명사가 필요합니다 ✗","me: 1인칭 재귀대명사, me acuerdo(나는 기억한다) → 정답 ✓","me lo: 대상이 이미 'de lo que hice'로 나와 있어 lo가 중복됩니다 ✗","ø: acordar 단독은 '합의하다'라는 다른 뜻이 됩니다 ✗"]},{"id":"G458","q":"Me gusta leer ____ noche, cuando está todo en silencio.","o":["por","en","a","de"],"a":3,"k":"de noche 표현","t":"모든 것이 조용한 밤에 책 읽는 것을 좋아한다.","e":"'밤에'라는 막연한 시간대를 말할 때 스페인어에서는 관용적으로 de noche를 씁니다. 같은 방식으로 de día(낮에)도 있습니다. 'por la noche'도 가능하지만 이 경우 정관사 la가 필요하므로 이 문장의 빈칸에는 de가 맞습니다.","x":["por: 'por la noche'처럼 정관사가 있어야 하므로 여기서는 맞지 않습니다 ✗","en: 'en noche'라는 표현은 쓰지 않습니다 ✗","a: 'a noche'라는 표현은 없습니다(시각에는 a las diez처럼 씀) ✗","de: de noche(밤에) 관용 표현 → 정답 ✓"]},{"id":"G459","q":"Si ____ a Laura, decidle que me llame.","o":["veáis","veríais","veréis","veis"],"a":3,"k":"현재 조건문 si","t":"너희가 라우라를 보면, 나한테 전화하라고 전해 줘.","e":"현실적으로 가능한 조건을 말하는 si절(만약 ~하면)에는 직설법 현재를 씁니다. 주절이 명령(decidle 너희가 그녀에게 말해 줘)이고 주어가 vosotros이므로 veis가 맞습니다. 주의: si 바로 뒤에는 접속법 현재나 미래형을 쓰지 않습니다. vosotros는 주로 스페인에서 쓰고, 중남미에서는 ustedes(si ven a Laura, díganle)를 씁니다.","x":["veáis: 접속법 현재로, si 조건절에는 쓰지 않습니다 ✗","veríais: 가정미래로, 현실적인 si 조건절에 맞지 않습니다 ✗","veréis: 직설법 미래로, si 바로 뒤에는 쓰지 않습니다 ✗","veis: ver의 직설법 현재(vosotros) → 정답 ✓"]},{"id":"G460","q":"Lo que más me gusta del verano son ____ vacaciones.","o":["ø","las","los","unas"],"a":1,"k":"정관사 las","t":"여름에서 내가 가장 좋아하는 건 휴가다.","e":"이미 알고 있는 특정한 것(여름의 휴가)을 가리킬 때는 정관사를 씁니다. vacaciones(휴가)는 항상 복수로 쓰는 여성 명사이므로 las vacaciones가 됩니다. 'lo que más me gusta... son las vacaciones'처럼 서술어 자리여도 관사가 필요합니다.","x":["ø: 특정한 대상을 가리키므로 관사를 생략할 수 없습니다 ✗","las: 여성 복수 정관사, las vacaciones → 정답 ✓","los: 남성 복수 정관사인데 vacaciones는 여성 명사입니다 ✗","unas: 부정관사(몇몇의)라 '그 휴가'라는 특정 의미와 맞지 않습니다 ✗"]},{"id":"G461","q":"____ el informe cuando haya recopilado más datos.","o":["Haré","Hago","Estaré haciendo","Haría"],"a":0,"k":"미래형과 cuando","t":"데이터를 더 모으면 보고서를 작성하겠다.","e":"'cuando + 접속법(haya recopilado)'은 미래에 일어날 시점을 나타내고, 주절에는 앞으로 할 일을 나타내는 미래형을 씁니다. 따라서 hacer의 미래형 haré(내가 하겠다)가 맞습니다. 구어에서는 현재형 hago로 미래를 나타내기도 하지만 이 구조에서는 미래형이 가장 자연스럽습니다.","x":["Haré: hacer의 직설법 미래(내가 할 것이다) → 정답 ✓","Hago: 현재형이라 미래 시점의 계획을 말하기엔 덜 적절합니다 ✗","Estaré haciendo: 미래진행(~하고 있을 것이다)으로 특정 시점의 진행 상황을 말할 때 씁니다 ✗","Haría: 가정미래(~할 텐데)로 이 문장의 의미와 맞지 않습니다 ✗"]},{"id":"G462","q":"No conozco a ____ persona que tenga tres casas.","o":["alguna","una","ningún","ninguna"],"a":3,"k":"부정어 ninguna","t":"집이 세 채인 사람은 아무도 모른다.","e":"부정문(No conozco)에서 '어떤 ~도 (없다)'라는 뜻으로 명사 앞에 ningún/ninguna를 씁니다. persona는 여성 명사이므로 ninguna가 맞습니다. 스페인어는 no와 ninguna처럼 부정어를 두 번 써도 부정의 뜻이 유지됩니다.","x":["alguna: 긍정의 '어떤'이라 부정문 no conozco와 어울리지 않습니다 ✗","una: '한 사람'이라는 뜻이 되어 '아무도 없다'는 강한 부정 의미가 약해집니다 ✗","ningún: 남성 단수형이라 여성 명사 persona와 맞지 않습니다 ✗","ninguna: 여성 단수 부정어(어떤 ~도) → 정답 ✓"]},{"id":"G463","q":"Necesito que me ____ tus apuntes de la clase de historia.","o":["pasarás","pasarías","pases","pasas"],"a":2,"k":"necesitar que+접속법","t":"역사 수업 필기를 나한테 넘겨줘야 해.","e":"'Necesito que(~가 ~해 주기를 필요로 한다)'처럼 다른 사람에게 바람·요구를 나타낼 때 que절에는 접속법을 씁니다. 상대방 tú에게 부탁하는 것이므로 pasar의 접속법 현재 pases가 맞습니다.","x":["pasarás: 직설법 미래로, 요구를 나타내는 que절에는 쓰지 않습니다 ✗","pasarías: 가정미래로 이 구조에 맞지 않습니다 ✗","pases: pasar의 접속법 현재(tú) → 정답 ✓","pasas: 직설법 현재로, 요구 표현 뒤에는 접속법이 필요합니다 ✗"]},{"id":"G464","q":"Os he pedido muchas veces que ____ en voz baja.","o":["hablas","habléis","hablad","hablen"],"a":1,"k":"pedir que+접속법","t":"너희에게 작은 목소리로 말하라고 여러 번 부탁했잖아.","e":"pedir que(~해 달라고 부탁하다) 뒤에는 접속법을 씁니다. 'Os(너희에게)'가 부탁받는 사람이므로 vosotros 형태인 habléis가 맞습니다. 주절이 현재완료(he pedido)이므로 접속법 현재를 씁니다. 중남미에서는 'Les he pedido que hablen'이라고 합니다.","x":["hablas: tú의 직설법 현재로 인칭도, 법도 맞지 않습니다 ✗","habléis: hablar의 접속법 현재(vosotros) → 정답 ✓","hablad: vosotros 긍정명령형으로, que절 안에서는 쓰지 않습니다 ✗","hablen: ustedes(또는 ellos)의 접속법인데 os는 vosotros를 가리킵니다 ✗"]},{"id":"G465","q":"Ya no hay ____ cabinas telefónicas en mi ciudad.","o":["las","una","ø","unas"],"a":2,"k":"hay+무관사 복수","t":"우리 도시에는 이제 공중전화 부스가 없다.","e":"hay(~이 있다) 뒤에서 막연한 대상을 말할 때, 특히 부정문에서는 복수 명사에 관사를 붙이지 않습니다. 'No hay cabinas(부스가 없다)'처럼 씁니다. hay 뒤에는 정관사(las)를 쓰지 않는 것도 중요한 규칙입니다.","x":["las: hay 뒤에는 정관사를 쓰지 않습니다 ✗","una: 단수 부정관사라 복수 cabinas와 맞지 않습니다 ✗","ø: 부정문 hay 뒤 복수 명사는 무관사 → 정답 ✓","unas: 부정문 'no hay'와 함께 쓰면 부자연스럽습니다 ✗"]},{"id":"G466","q":"¿Dónde ____ ayer tus padres?","o":["estuvieron","estarían","han estado","estuvieran"],"a":0,"k":"단순과거 estuvieron","t":"어제 네 부모님은 어디에 계셨어?","e":"ayer(어제)처럼 끝난 과거 시점이 분명하면 단순과거(부정과거, 완료된 과거 동작)를 씁니다. 주어 tus padres(너의 부모님)는 3인칭 복수이므로 estar의 단순과거 estuvieron이 맞습니다.","x":["estuvieron: estar의 단순과거(그들은 있었다) → 정답 ✓","estarían: 가정미래(있었을 텐데)로 질문 의미와 맞지 않습니다 ✗","han estado: 현재완료로, 스페인 표준에서는 ayer와 함께 쓰지 않습니다 ✗","estuvieran: 접속법 과거라 일반 의문문에는 쓰지 않습니다 ✗"]},{"id":"G467","q":"¿De quién es ____ lapicero?","o":["eso","esta","esto","este"],"a":3,"k":"지시형용사 este","t":"이 색연필은 누구 거야?","e":"lapicero(연필, 샤프)는 남성 단수 명사이므로 명사 앞에는 남성 단수 지시형용사 este를 씁니다. esto/eso는 중성 지시대명사로 명사 앞에 붙지 않고 '이것/그것' 단독으로만 씁니다.","x":["eso: 중성 지시대명사(그것)라 명사 앞에 쓸 수 없습니다 ✗","esta: 여성 단수인데 lapicero는 남성 명사입니다 ✗","esto: 중성 지시대명사(이것)라 명사 앞에 쓸 수 없습니다 ✗","este: 남성 단수 지시형용사(이) → 정답 ✓"]},{"id":"G468","q":"____ sabe nada de Jorge. Parece que se lo ha tragado la tierra.","o":["Nada","Nadie","Alguien","Ningún"],"a":1,"k":"부정어 nadie","t":"아무도 호르헤 소식을 모른다. 마치 땅이 그를 삼켜 버린 것 같다.","e":"nadie는 '아무도 (~않다)'라는 뜻으로 사람을 가리키는 부정대명사입니다. 동사 앞에 오면 no 없이도 부정문이 됩니다(Nadie sabe = 아무도 모른다). 'se lo ha tragado la tierra'는 '감쪽같이 사라졌다'는 관용 표현입니다.","x":["Nada: '아무것도'로 사물을 가리켜 sabe의 주어(사람)로 맞지 않습니다 ✗","Nadie: '아무도(사람)' → 정답 ✓","Alguien: '누군가'라 'nada'와 함께 쓰면 문맥(소식이 없다)과 어긋납니다 ✗","Ningún: 명사 앞에 붙는 형용사형이라 단독 주어가 될 수 없습니다 ✗"]},{"id":"G469","q":"____ el horario es muy bueno, no voy a aceptar este puesto de trabajo.","o":["Incluso","Aunque","A pesar de","Como"],"a":1,"k":"양보 접속사 aunque","t":"근무 시간이 아주 좋긴 하지만, 나는 이 일자리를 받아들이지 않겠다.","e":"aunque는 '비록 ~이지만'이라는 양보 접속사로, 뒤에 문장(주어+동사)이 옵니다. 실제 사실(근무 시간이 좋다)을 인정할 때는 직설법(es)을 씁니다. a pesar de도 같은 뜻이지만 뒤에 명사나 동사원형, 또는 que가 필요합니다.","x":["Incluso: '~조차도'라는 부사라 두 문장을 연결하지 못합니다 ✗","Aunque: 양보 접속사(~이지만) → 정답 ✓","A pesar de: 뒤에 문장이 오려면 'a pesar de que'가 되어야 합니다 ✗","Como: 문두에서 '~이므로'라는 이유를 나타내 뒤 내용과 모순됩니다 ✗"]},{"id":"G470","q":"Tenemos ____ el viernes para entregar el informe.","o":["para","por","hacia","hasta"],"a":3,"k":"기한 전치사 hasta","t":"보고서 제출 기한은 금요일까지다.","e":"'Tenemos hasta el viernes'는 '금요일까지 (시간이) 있다'라는 뜻으로, 기한의 끝을 나타낼 때 hasta(~까지)를 씁니다. 'para el viernes'도 '금요일까지(마감)'라는 뜻이 있지만 tener와 함께 '시간이 금요일까지 있다'고 할 때는 hasta가 자연스럽습니다.","x":["para: 마감을 나타낼 수 있지만 'tener ____ el viernes' 구조에는 어색합니다 ✗","por: 대략적인 시간(~쯤)을 나타내 기한 의미와 맞지 않습니다 ✗","hacia: '~무렵, ~쪽으로'라는 뜻이라 맞지 않습니다 ✗","hasta: 기한의 끝(~까지) → 정답 ✓"]},{"id":"G471","q":"No me iré de aquí ____ me devuelvan mi dinero.","o":["hasta que","desde que","mientras","antes de"],"a":0,"k":"hasta que+접속법","t":"내 돈을 돌려줄 때까지 나는 여기서 떠나지 않겠다.","e":"hasta que(~할 때까지)가 아직 일어나지 않은 미래 일을 가리키면 뒤에 접속법(devuelvan)을 씁니다. 'No me iré hasta que...'는 '~할 때까지 떠나지 않겠다'는 강한 의지를 나타냅니다.","x":["hasta que: '~할 때까지' → 정답 ✓","desde que: '~한 이후로'라 미래 조건과 맞지 않습니다 ✗","mientras: '~하는 동안'이라 의미가 어색합니다 ✗","antes de: 뒤에 문장이 오려면 'antes de que'가 필요하고 의미도 맞지 않습니다 ✗"]},{"id":"G472","q":"____ dije a José que viniera después del mediodía.","o":["Lo","ø","Les","Le"],"a":3,"k":"간접목적격 le","t":"나는 호세에게 정오 이후에 오라고 말했다.","e":"decir(말하다)에서 '말을 듣는 사람'은 간접목적어(~에게)이므로 간접목적격 대명사를 씁니다. 'a José'는 3인칭 단수이므로 le가 맞습니다. 스페인어에서는 'a + 사람'이 있어도 le를 함께 쓰는 것이 일반적입니다.","x":["Lo: 직접목적격(그를/그것을)이라 '~에게 말하다'에 맞지 않습니다 ✗","ø: 문법적으로 불가능하진 않지만 'a José'가 있으면 le를 함께 쓰는 것이 자연스럽습니다 ✗","Les: 3인칭 복수(그들에게)라 José 한 명과 맞지 않습니다 ✗","Le: 3인칭 단수 간접목적격(그에게) → 정답 ✓"]},{"id":"G473","q":"¿Te ____ que fuéramos de excursión con Alba y Pedro?","o":["gustará","gustara","está gustando","gustaría"],"a":3,"k":"가정미래 gustaría","t":"우리가 알바, 페드로와 함께 소풍 가면 좋겠어?","e":"'¿Te gustaría...?(~하면 좋겠니?)'는 정중하게 제안하거나 바람을 묻는 표현으로 가정미래(조건법)를 씁니다. 주절이 가정미래이므로 que절에는 접속법 과거(fuéramos)가 옵니다.","x":["gustará: 미래형이라 que절의 접속법 과거 fuéramos와 시제가 맞지 않습니다 ✗","gustara: 접속법 과거로 주절 동사로 쓰기엔 어색합니다 ✗","está gustando: 진행형(마음에 들고 있다)이라 제안 의미와 맞지 않습니다 ✗","gustaría: 가정미래(~하면 좋겠다) → 정답 ✓"]},{"id":"G474","q":"Durante muchos años, este programa fue presentado ____ Joaquín Prat.","o":["para","sobre","de","por"],"a":3,"k":"수동태 por","t":"오랫동안 이 프로그램은 호아킨 프랏이 진행했다.","e":"수동태(ser + 과거분사, ~에 의해 ~되다)에서 행위자(누가 했는지)는 전치사 por로 나타냅니다. 'fue presentado por Joaquín Prat'은 '호아킨 프랏에 의해 진행되었다'는 뜻입니다.","x":["para: 목적·대상(~을 위해)을 나타내 행위자 표시에 쓰지 않습니다 ✗","sobre: '~에 대해, ~위에'라는 뜻입니다 ✗","de: 옛 문체에서는 쓰였지만 현대 수동태 행위자로는 쓰지 않습니다 ✗","por: 수동태의 행위자(~에 의해) → 정답 ✓"]},{"id":"G475","q":"Anoche ____ con Marta hasta la una.","o":["hablaba","estuve hablando","estaba hablando","he estado hablando"],"a":1,"k":"과거진행 estuve+ando","t":"어젯밤 나는 마르타와 1시까지 이야기했다.","e":"과거의 특정 기간 동안 계속되다가 끝난 동작(hasta la una 1시까지)은 'estar의 단순과거 + 현재분사'로 표현합니다. estuve hablando는 '(일정 시간 동안) 이야기하고 있었다(그리고 끝났다)'는 뜻입니다. 끝이 정해진 기간에는 불완료과거(estaba hablando)보다 이 형태가 자연스럽습니다.","x":["hablaba: 불완료과거로 배경·습관을 나타내 끝이 명확한 기간과 어울리지 않습니다 ✗","estuve hablando: 끝난 기간 동안의 지속 동작 → 정답 ✓","estaba hablando: 다른 일이 일어난 배경을 나타낼 때 쓰며 hasta la una와 덜 자연스럽습니다 ✗","he estado hablando: 현재완료로, anoche(어젯밤)와 함께 쓰지 않습니다 ✗"]},{"id":"G476","q":"¿Qué ____ cuando llegaron vuestros padres?","o":["habéis hecho","estabais haciendo","estuvisteis haciendo","hacéis"],"a":1,"k":"과거진행 estaba+ando","t":"너희 부모님이 도착했을 때 너희는 뭘 하고 있었어?","e":"과거의 어떤 순간(cuando llegaron 부모님이 도착했을 때)에 진행 중이던 동작은 'estar의 불완료과거 + 현재분사'로 나타냅니다. vosotros에 맞춰 estabais haciendo가 됩니다. 중남미에서는 '¿Qué estaban haciendo (ustedes)?'라고 합니다.","x":["habéis hecho: 현재완료라 과거의 한 순간에 진행 중이던 일을 나타내지 못합니다 ✗","estabais haciendo: 과거 순간에 진행 중이던 동작 → 정답 ✓","estuvisteis haciendo: 끝난 기간의 지속을 나타내며 '~했을 때 하고 있던 일'에는 맞지 않습니다 ✗","hacéis: 현재형이라 과거 상황과 맞지 않습니다 ✗"]},{"id":"G477","q":"Llevo dos años ____ de viaje a ningún sitio.","o":["que no voy","sin yendo","no ir","sin ir"],"a":3,"k":"llevar+기간+sin","t":"나는 2년째 어디에도 여행을 가지 않았다.","e":"'llevar + 기간 + sin + 동사원형'은 '~동안 ~하지 않고 있다'라는 뜻입니다. 'Llevo dos años sin ir'는 '2년째 가지 않고 있다'는 의미입니다. 긍정은 'llevar + 기간 + 현재분사(Llevo dos años estudiando 2년째 공부 중)'를 씁니다.","x":["que no voy: 'Hace dos años que no voy'라면 가능하지만 llevar와는 맞지 않습니다 ✗","sin yendo: sin 뒤에는 현재분사가 아니라 동사원형이 옵니다 ✗","no ir: llevar 구문에서 부정은 sin을 씁니다 ✗","sin ir: llevar+기간+sin+동사원형 → 정답 ✓"]},{"id":"G478","q":"Suspendieron el acto ____ la intensa lluvia.","o":["como","porque","a causa de","ya que"],"a":2,"k":"원인 a causa de","t":"폭우 때문에 행사가 취소되었다.","e":"a causa de(~ 때문에)는 뒤에 명사가 오는 원인 표현입니다. 빈칸 뒤 'la intensa lluvia(강한 비)'는 동사 없는 명사구이므로 a causa de가 맞습니다. porque, ya que, como는 모두 뒤에 문장(주어+동사)이 와야 합니다.","x":["como: 이유를 나타낼 때 문두에 오고 뒤에 문장이 필요합니다 ✗","porque: 접속사라 뒤에 동사가 있는 문장이 와야 합니다 ✗","a causa de: 명사 앞에 쓰는 원인 표현 → 정답 ✓","ya que: 접속사라 뒤에 문장이 와야 합니다 ✗"]},{"id":"G479","q":"A mi marido le encanta el pescado. A mí, ____, no me gusta nada.","o":["además","por eso","por tanto","sin embargo"],"a":3,"k":"대조 sin embargo","t":"내 남편은 생선을 아주 좋아한다. 하지만 나는 전혀 좋아하지 않는다.","e":"sin embargo는 '그러나, 하지만'이라는 뜻으로 앞 내용과 반대되는 내용을 이어 줍니다. 남편은 좋아하지만 나는 싫어한다는 대조이므로 sin embargo가 맞습니다. 문장 중간에 콤마와 함께 삽입해서 쓸 수 있습니다.","x":["además: '게다가'라는 추가 의미로 대조와 맞지 않습니다 ✗","por eso: '그래서'라는 결과 의미입니다 ✗","por tanto: '따라서'라는 결론 의미입니다 ✗","sin embargo: '그러나'라는 대조 → 정답 ✓"]},{"id":"G480","q":"Marisa se puso a trabajar después ____.","o":["de desayunar","desayunar","que desayuna","de que desayune"],"a":0,"k":"después de+동사원형","t":"마리사는 아침을 먹은 후에 일을 시작했다.","e":"'después de + 동사원형'은 '~한 후에'라는 뜻으로, 두 동작의 주어가 같을 때 씁니다. 일을 시작한 사람과 아침을 먹은 사람이 모두 마리사이므로 de desayunar가 맞습니다. 주어가 다르면 'después de que + 접속법/직설법'을 씁니다.","x":["de desayunar: 같은 주어, después de + 동사원형 → 정답 ✓","desayunar: después 뒤에 de가 빠져 틀립니다 ✗","que desayuna: después 뒤에 de가 빠졌고 시제도 맞지 않습니다 ✗","de que desayune: 주어가 같을 때는 que절을 쓰지 않고, 과거 문맥에 접속법 현재도 맞지 않습니다 ✗"]},{"id":"G481","q":"¿____ quién es este lápiz?","o":["Por","En","A","De"],"a":3,"k":"소유 의문 de quién","t":"이 연필은 누구 거야?","e":"'누구의 것인가'라고 소유를 물을 때는 '¿De quién es...?'를 씁니다. 스페인어는 소유를 de(~의)로 나타내므로, 의문사 quién 앞에도 de가 붙습니다. 대답은 'Es de Ana(아나 거야)'처럼 합니다.","x":["Por: '~때문에, ~을 통해'라는 뜻이라 소유 질문에 쓰지 않습니다 ✗","En: '~에서'라는 장소 표현입니다 ✗","A: '~에게'라는 뜻이라 소유를 묻지 못합니다 ✗","De: ¿De quién es? '누구 거야?' → 정답 ✓"]},{"id":"G482","q":"Paloma y Andrés están muy enamorados, por eso ____ llaman constantemente.","o":["se los","se","los","les"],"a":1,"k":"상호 재귀 se","t":"팔로마와 안드레스는 서로 무척 사랑해서, 계속 서로에게 전화한다.","e":"주어가 복수일 때 재귀대명사 se는 '서로'라는 상호의 의미를 가질 수 있습니다. 'se llaman'은 '(두 사람이) 서로 전화한다'는 뜻입니다. 예: Nos escribimos cada día. (우리는 매일 서로 편지를 쓴다.)","x":["se los: 목적어 los가 덧붙어 의미가 성립하지 않습니다 ✗","se: 상호 재귀 '서로' → 정답 ✓","los: '그들을 전화한다'가 되어 주어 자신들끼리라는 의미가 사라집니다 ✗","les: '그들에게 전화한다'는 뜻으로 다른 사람에게 전화하는 의미가 됩니다 ✗"]},{"id":"G483","q":"No ____ molesta que vengas con tus amigos, al contrario.","o":["se","te","me","lo"],"a":2,"k":"molestar 구문","t":"네가 친구들과 함께 와도 나는 전혀 불편하지 않아, 오히려 반가워.","e":"molestar(~를 귀찮게 하다, 불편하게 하다)는 gustar처럼 감정을 느끼는 사람을 간접목적격 대명사로 씁니다. 불편함을 느끼는 사람이 '나'이므로 me가 맞습니다. 감정 표현 뒤 que절에는 접속법(vengas)이 옵니다.","x":["se: 재귀대명사라 '나'에게 불편하지 않다는 뜻을 나타내지 못합니다 ✗","te: '너에게'가 되어 vengas(네가 오다)와 논리가 맞지 않습니다 ✗","me: '나에게' 불편하지 않다 → 정답 ✓","lo: 직접목적격(그를)으로 문맥과 맞지 않습니다 ✗"]},{"id":"G484","q":"¿Cuántas ____ has estado en Argentina?","o":["vezes","vez","veces","de vez"],"a":2,"k":"복수형 veces","t":"너는 아르헨티나에 몇 번 가 봤어?","e":"vez(번, 회)처럼 -z로 끝나는 명사는 복수형에서 z가 c로 바뀌고 -es가 붙습니다: vez → veces. '¿Cuántas veces...?'는 '몇 번 ~했니?'라는 자주 쓰는 표현입니다. 같은 규칙: lápiz → lápices, luz → luces.","x":["vezes: z를 c로 바꾸지 않은 틀린 철자입니다 ✗","vez: 단수형이라 cuántas(몇)와 맞지 않습니다 ✗","veces: vez의 복수형 → 정답 ✓","de vez: 'de vez en cuando(가끔)'의 일부일 뿐 여기 맞지 않습니다 ✗"]},{"id":"G485","q":"Vamos a ordenar la casa antes de que ____ papá y mamá.","o":["vienen","vinieran","vengan","vendrán"],"a":2,"k":"antes de que+접속법","t":"아빠와 엄마가 오시기 전에 집을 정리하자.","e":"antes de que(~하기 전에)는 항상 뒤에 접속법을 씁니다. 주절이 현재·미래(Vamos a ordenar)이므로 venir의 접속법 현재 vengan이 맞습니다. 과거 문맥이었다면 접속법 과거(vinieran)를 씁니다.","x":["vienen: 직설법이라 antes de que 뒤에 올 수 없습니다 ✗","vinieran: 접속법 과거로, 현재·미래 문맥과 시제가 맞지 않습니다 ✗","vengan: venir의 접속법 현재(ellos) → 정답 ✓","vendrán: 미래형은 antes de que 뒤에 쓰지 않습니다 ✗"]},{"id":"G486","q":"Nos fuimos de la fiesta ____ era aburridísima.","o":["aunque","pese a que","por","porque"],"a":3,"k":"이유 porque","t":"파티가 너무 지루해서 우리는 그 자리를 떴다.","e":"porque는 '왜냐하면, ~이기 때문에'라는 뜻으로 뒤에 문장(era aburridísima)이 옵니다. 파티를 떠난 이유가 지루함이므로 porque가 맞습니다. aburridísima는 aburrida(지루한)의 최상급(-ísimo, 매우 ~한)입니다.","x":["aunque: '~이지만'이라는 양보라 이유와 맞지 않습니다 ✗","pese a que: '~임에도 불구하고'라는 양보 표현입니다 ✗","por: 전치사라 뒤에 동사 있는 문장이 올 수 없습니다 ✗","porque: 이유 접속사(~이기 때문에) → 정답 ✓"]},{"id":"G487","q":"¿____ las manos?","o":["Has lavado","Te has lavado","Has te lavado","Tú has lavado"],"a":1,"k":"재귀동사 lavarse","t":"손 씻었어?","e":"자기 몸의 일부를 씻을 때는 재귀동사 lavarse를 씁니다. 현재완료에서 재귀대명사는 haber 앞에 둡니다: te has lavado. 스페인어는 몸의 부위에 소유격 대신 정관사(las manos)를 쓰는 것도 기억하세요.","x":["Has lavado: 재귀대명사가 빠져 '(다른 사람의) 손을 씻겼니'처럼 들립니다 ✗","Te has lavado: 재귀대명사 + haber + 과거분사 → 정답 ✓","Has te lavado: 대명사를 haber와 과거분사 사이에 넣을 수 없습니다 ✗","Tú has lavado: 주어만 있고 재귀대명사가 없어 틀립니다 ✗"]},{"id":"G488","q":"Es raro que ningún alumno ____ ese examen.","o":["había suspendido","ha suspendido","hayan suspendido","haya suspendido"],"a":3,"k":"es raro que+접속법","t":"어떤 학생도 그 시험에 떨어지지 않았다니 이상하다.","e":"'Es raro que(~하다니 이상하다)'처럼 판단·감정을 나타내는 표현 뒤에는 접속법을 씁니다. 이미 일어난 일에 대한 판단이므로 접속법 현재완료 haya suspendido를 씁니다. ningún alumno는 3인칭 단수이므로 haya가 맞습니다.","x":["había suspendido: 직설법 대과거라 es raro que 뒤에 맞지 않습니다 ✗","ha suspendido: 직설법이라 판단 표현 뒤에 쓰지 않습니다 ✗","hayan suspendido: 복수형이라 단수 주어 ningún alumno와 맞지 않습니다 ✗","haya suspendido: 접속법 현재완료(3인칭 단수) → 정답 ✓"]},{"id":"G489","q":"Me da vergüenza ____ hablar en público.","o":["a","ø","de","para"],"a":1,"k":"dar vergüenza+원형","t":"나는 사람들 앞에서 말하는 게 부끄럽다.","e":"'Me da vergüenza(나는 ~가 부끄럽다)' 구문에서 부끄러운 일(동사원형)은 문법상 주어 역할을 하므로 전치사 없이 바로 씁니다. 'Me da miedo volar(나는 비행기 타는 게 무섭다)'도 같은 구조입니다.","x":["a: 동사원형 주어 앞에는 전치사를 쓰지 않습니다 ✗","ø: 전치사 없이 동사원형 → 정답 ✓","de: 'tener vergüenza de'에서는 쓰지만 'dar vergüenza' 뒤에는 쓰지 않습니다 ✗","para: 목적(~하기 위해)의 뜻이라 맞지 않습니다 ✗"]},{"id":"G490","q":"No sé de nadie que ____ malayo.","o":["hables","hablan","hable","habla"],"a":2,"k":"부정 선행사+접속법","t":"말레이어를 하는 사람은 아무도 모른다.","e":"관계절의 선행사가 존재하지 않거나 모르는 대상(nadie 아무도)이면 관계절에 접속법을 씁니다. 3인칭 단수에 맞춰 hablar의 접속법 현재 hable가 됩니다. 실제로 존재하는 사람이면 직설법을 씁니다(Conozco a alguien que habla malayo).","x":["hables: tú 형태라 3인칭인 nadie와 맞지 않습니다 ✗","hablan: 직설법 복수라 법·수 모두 맞지 않습니다 ✗","hable: 접속법 현재(3인칭 단수) → 정답 ✓","habla: 직설법이라 존재하지 않는 선행사 뒤에는 쓰지 않습니다 ✗"]},{"id":"G491","q":"¿Todavía no ____ de leer ese cómic?","o":["estás terminando","terminas","has terminado","terminabas"],"a":2,"k":"todavía no+현재완료","t":"아직도 그 만화책 다 안 읽었어?","e":"'todavía no(아직 ~하지 않았다)'는 지금까지 완료되지 않은 일을 말할 때 현재완료와 잘 어울립니다. 'terminar de + 동사원형'은 '~하는 것을 끝내다'라는 뜻이므로 has terminado de leer는 '다 읽었다'가 됩니다.","x":["estás terminando: 진행형(끝내는 중)이라 todavía no와 의미가 어색합니다 ✗","terminas: 현재형이라 완료 여부를 묻는 문맥에 덜 적절합니다 ✗","has terminado: 현재완료, 지금까지의 완료 여부 → 정답 ✓","terminabas: 불완료과거라 현재 시점의 질문과 맞지 않습니다 ✗"]},{"id":"G492","q":"¡Conocemos a una persona que ____ tres trabajos!","o":["tenga","tendría","tuviera","tiene"],"a":3,"k":"존재 선행사+직설법","t":"우리는 직업이 세 개인 사람을 안다!","e":"관계절의 선행사가 실제로 존재하는 사람(conocemos a una persona 우리가 아는 사람)이면 관계절에 직설법을 씁니다. 따라서 tener의 직설법 현재 tiene가 맞습니다. 존재하지 않거나 막연하면 접속법(No conocemos a nadie que tenga...)을 씁니다.","x":["tenga: 접속법이라 실제로 아는 사람을 묘사하는 데 맞지 않습니다 ✗","tendría: 가정미래(가질 텐데)라 사실 묘사에 맞지 않습니다 ✗","tuviera: 접속법 과거라 현재 사실과 맞지 않습니다 ✗","tiene: 직설법 현재, 실제 존재하는 선행사 → 정답 ✓"]},{"id":"G493","q":"Aquí hay exactamente diez manzanas, ni una más, ____ una menos.","o":["ni","o","y","no"],"a":0,"k":"부정 접속사 ni","t":"여기에는 정확히 사과 열 개가 있다. 하나도 더도 덜도 아니게.","e":"ni는 '~도 아니다'라는 부정 접속사로, 부정의 내용을 나열할 때 씁니다. 'ni una más, ni una menos'는 '하나 더도 하나 덜도 아닌'이라는 고정된 표현입니다. 예: No tengo ni tiempo ni dinero. (나는 시간도 돈도 없다.)","x":["ni: 부정 나열 '~도 아니고' → 정답 ✓","o: '또는'이라는 선택의 뜻이라 부정 나열에 맞지 않습니다 ✗","y: '그리고'라 앞의 ni와 짝이 맞지 않습니다 ✗","no: 접속사로 쓰지 않으며 ni ... ni 짝을 깨뜨립니다 ✗"]},{"id":"G494","q":"Mañana, a esta misma hora, ____ el último examen de este curso.","o":["habíamos hecho","hemos hecho","estaremos haciendo","estemos haciendo"],"a":2,"k":"미래진행형","t":"내일 이 시간쯤이면 우리는 이번 학기 마지막 시험을 보고 있을 것이다.","e":"미래의 특정 시점(mañana a esta misma hora 내일 이 시간)에 진행 중일 동작은 'estar의 미래형 + 현재분사'로 나타냅니다. estaremos haciendo는 '우리가 하고 있을 것이다'라는 뜻입니다.","x":["habíamos hecho: 대과거라 미래 시점과 맞지 않습니다 ✗","hemos hecho: 현재완료라 mañana와 맞지 않습니다 ✗","estaremos haciendo: 미래진행(하고 있을 것이다) → 정답 ✓","estemos haciendo: 접속법이라 독립된 평서문에 쓰지 않습니다 ✗"]},{"id":"G495","q":"¿Por qué ____ de la fiesta sin decir nada?","o":["te fuiste","has ido","ibas","fuiste"],"a":0,"k":"irse 단순과거","t":"왜 아무 말도 없이 파티에서 가 버렸어?","e":"'~에서 떠나다, 가 버리다'는 재귀형 irse de를 씁니다. 과거에 한 번 일어나 끝난 동작이므로 단순과거 te fuiste가 맞습니다. ir만 쓰면 '어디로 가다'라는 뜻이고, irse는 '있던 곳에서 떠나다'에 초점이 있습니다.","x":["te fuiste: irse의 단순과거(tú), 떠났다 → 정답 ✓","has ido: 재귀대명사가 없어 '떠나다'라는 뜻이 되지 않습니다 ✗","ibas: 불완료과거이고 재귀대명사도 없습니다 ✗","fuiste: ir의 단순과거지만 재귀대명사가 없어 'de la fiesta(~에서)'와 맞지 않습니다 ✗"]},{"id":"G496","q":"¿Dónde has comprado ____ cortinas?","o":["esos","ese","esa","esas"],"a":3,"k":"지시형용사 esas","t":"그 커튼들은 어디서 샀어?","e":"cortinas(커튼)는 여성 복수 명사이므로 '그 ~들'은 여성 복수 지시형용사 esas를 씁니다. ese/esa/esos/esas는 듣는 사람 가까이에 있는 것을 가리킵니다.","x":["esos: 남성 복수라 여성 명사 cortinas와 맞지 않습니다 ✗","ese: 남성 단수라 성·수 모두 맞지 않습니다 ✗","esa: 여성 단수라 복수 cortinas와 맞지 않습니다 ✗","esas: 여성 복수 지시형용사(그 ~들) → 정답 ✓"]},{"id":"G497","q":"Todos fueron a la boda menos ____.","o":["de mí","me","yo","mí"],"a":2,"k":"menos+주격 대명사","t":"나만 빼고 모두 결혼식에 갔다.","e":"menos, excepto, salvo(~을 제외하고), según(~에 따르면), entre tú y yo 같은 표현 뒤에는 전치격(mí, ti)이 아니라 주격 대명사(yo, tú)를 씁니다. 그래서 'menos yo(나만 빼고)'가 맞습니다.","x":["de mí: menos 뒤에 de를 쓰지 않습니다 ✗","me: 목적격 대명사라 단독으로 이 자리에 올 수 없습니다 ✗","yo: menos 뒤에는 주격 대명사 → 정답 ✓","mí: 전치격이지만 menos 뒤에는 쓰지 않습니다 ✗"]},{"id":"G498","q":"Si no le cuentas a tu madre lo que ha pasado, ____ contaré yo.","o":["se lo","le lo","le","se"],"a":0,"k":"이중 목적격 se lo","t":"네가 엄마에게 무슨 일이 있었는지 말하지 않으면, 내가 말할게.","e":"간접목적격(le, ~에게)과 직접목적격(lo, 그것을)이 함께 오면 le가 se로 바뀝니다: le + lo → se lo. 여기서 se는 'a tu madre(너의 엄마에게)', lo는 'lo que ha pasado(일어난 일)'를 가리킵니다.","x":["se lo: le+lo → se lo(그녀에게 그것을) → 정답 ✓","le lo: 두 대명사가 연달아 올 때 le는 se로 바뀌어야 합니다 ✗","le: '그것을'에 해당하는 lo가 빠졌습니다 ✗","se: 직접목적어 lo가 빠져 의미가 불완전합니다 ✗"]},{"id":"G499","q":"No ____ los resultados de mi análisis antes del jueves que viene.","o":["recibiré","recibí","había recibido","he recibido"],"a":0,"k":"직설법 미래","t":"다음 주 목요일 전에는 내 검사 결과를 받지 못할 것이다.","e":"'antes del jueves que viene(다음 주 목요일 전)'는 미래 시점이므로 미래형을 씁니다. recibir의 미래형 recibiré는 '내가 받을 것이다'라는 뜻입니다. 미래형은 동사원형에 -é, -ás, -á, -emos, -éis, -án을 붙여 만듭니다.","x":["recibiré: 직설법 미래(받을 것이다) → 정답 ✓","recibí: 단순과거라 미래 시점과 맞지 않습니다 ✗","había recibido: 대과거라 미래 시점과 맞지 않습니다 ✗","he recibido: 현재완료라 다음 주 일을 말할 수 없습니다 ✗"]},{"id":"G500","q":"No hace falta que me ____, pueden irse ya.","o":["esperen","esperan","esperarán","esperarían"],"a":0,"k":"no hace falta que","t":"저를 기다리실 필요 없어요, 이제 가셔도 됩니다.","e":"'No hace falta que(~할 필요 없다)' 뒤에는 접속법을 씁니다. 뒤의 'pueden irse'로 보아 주어는 ustedes(여러분)이므로 esperar의 접속법 현재 esperen이 맞습니다. ustedes는 스페인에서는 존댓말 복수, 중남미에서는 일반 복수 '너희'로도 씁니다.","x":["esperen: esperar의 접속법 현재(ustedes) → 정답 ✓","esperan: 직설법이라 no hace falta que 뒤에 쓰지 않습니다 ✗","esperarán: 미래형이라 이 구문에 맞지 않습니다 ✗","esperarían: 가정미래라 이 구문에 맞지 않습니다 ✗"]},{"id":"G501","q":"Me duelen ____ dos rodillas.","o":["ambas","los","las","mis"],"a":2,"k":"신체 부위와 정관사","t":"나는 두 무릎이 다 아프다.","e":"스페인어에서는 신체 부위를 말할 때 소유격(mis) 대신 정관사를 씁니다. 'Me duelen'의 me가 이미 '나의' 무릎임을 알려 주기 때문입니다. rodillas(무릎들)는 여성 복수이므로 las dos rodillas가 됩니다.","x":["ambas: '양쪽 다'라는 뜻이지만 ambas 뒤에 dos를 또 쓰지 않습니다 ✗","los: 남성 복수 정관사인데 rodillas는 여성 명사입니다 ✗","las: 여성 복수 정관사, 신체 부위 앞 → 정답 ✓","mis: me가 있으므로 소유격을 쓰면 중복되어 부자연스럽습니다 ✗"]},{"id":"G502","q":"¿____ es lo que más te gusta de esta ciudad?","o":["Quién","Cuándo","Qué","Cuál"],"a":2,"k":"qué es lo que","t":"이 도시에서 네가 가장 좋아하는 게 뭐야?","e":"'lo que(~하는 것)'와 함께 '무엇이 ~인가'를 물을 때는 '¿Qué es lo que...?'를 씁니다. 선택지가 정해지지 않은 막연한 '무엇'이기 때문에 cuál보다 qué가 자연스럽습니다. 'Lo que más me gusta es la comida(내가 가장 좋아하는 건 음식이야)'처럼 대답합니다.","x":["Quién: 사람(누구)을 묻는 말이라 'lo que'와 맞지 않습니다 ✗","Cuándo: 시간(언제)을 묻는 말입니다 ✗","Qué: '무엇', ¿Qué es lo que...? → 정답 ✓","Cuál: 'lo que' 앞에서는 보통 qué를 씁니다 ✗"]},{"id":"G503","q":"____ no he visto la última película de mi cineasta favorito.","o":["Todavía","Ya","Mientras","Nunca"],"a":0,"k":"todavía no","t":"나는 아직 내가 가장 좋아하는 감독의 최신 영화를 보지 못했다.","e":"todavía no(아직 ~하지 않았다)는 기대하는 일이 지금까지 일어나지 않았음을 나타냅니다. 'Todavía no he visto'는 '아직 못 봤다'는 뜻이고, 나중에 볼 생각이 있음을 암시합니다. aún no도 같은 뜻입니다.","x":["Todavía: todavía no '아직 ~않다' → 정답 ✓","Ya: 'ya no'는 '더 이상 ~않다'라 현재완료와 의미가 맞지 않습니다 ✗","Mientras: '~하는 동안'이라는 접속사라 문장이 성립하지 않습니다 ✗","Nunca: 'nunca no'처럼 no와 연이어 쓸 수 없습니다 ✗"]},{"id":"G504","q":"¡Ojalá nos ____ pronto!","o":["vemos","veamos","vimos","veríamos"],"a":1,"k":"ojalá+접속법","t":"우리 곧 만날 수 있으면 좋겠다!","e":"ojalá(~하면 좋겠다)는 바람을 나타내는 표현으로 항상 접속법과 함께 씁니다. 앞으로의 바람이므로 ver의 접속법 현재 veamos를 씁니다. 'nos veamos'는 '우리가 서로 보다'라는 상호 재귀입니다.","x":["vemos: 직설법 현재라 ojalá 뒤에 올 수 없습니다 ✗","veamos: ver의 접속법 현재(nosotros) → 정답 ✓","vimos: 직설법 단순과거라 맞지 않습니다 ✗","veríamos: 가정미래라 ojalá 뒤에 쓰지 않습니다 ✗"]},{"id":"G505","q":"____ era muy tarde, decidimos pedir un taxi para volver a casa.","o":["Así que","Pues","Como","Por"],"a":2,"k":"문두 이유 como","t":"너무 늦었기 때문에 우리는 택시를 불러 집에 가기로 했다.","e":"como가 문장 맨 앞에 오면 '~이기 때문에'라는 이유를 나타냅니다. 이유절이 먼저 오는 구조에서는 porque 대신 como를 쓰는 것이 자연스럽습니다. 예: Como llovía, no salimos. (비가 와서 우리는 나가지 않았다.)","x":["Así que: '그래서'라는 결과 표현으로 문두 이유절에 쓰지 않습니다 ✗","Pues: 이 위치에서 이유절을 이끌지 않습니다 ✗","Como: 문두에서 이유(~이므로) → 정답 ✓","Por: 전치사라 뒤에 동사 있는 문장이 올 수 없습니다 ✗"]},{"id":"G506","q":"¿____ qué hospital trabaja tu mamá?","o":["De","En","Por","A"],"a":1,"k":"장소 전치사 en","t":"너희 엄마는 어느 병원에서 일하셔?","e":"'trabajar en(~에서 일하다)'처럼 장소를 나타낼 때는 en을 씁니다. 의문문에서는 전치사가 의문사 앞으로 옵니다: ¿En qué hospital...? 'mamá'는 중남미에서 특히 자주 쓰는 표현이고, 스페인에서는 'madre'나 'mamá' 모두 씁니다.","x":["De: '~에서부터, ~의'라 일하는 장소를 나타내지 못합니다 ✗","En: trabajar en '~에서 일하다' → 정답 ✓","Por: '~을 통해, ~ 근처에서'라 장소 고정 의미와 맞지 않습니다 ✗","A: 방향(~로)을 나타내 맞지 않습니다 ✗"]},{"id":"G507","q":"Según ____, ¿qué deberíamos votar en las próximas elecciones?","o":["a ti","ti","te","tú"],"a":3,"k":"según+주격 대명사","t":"네 생각에 우리는 다음 선거에서 무엇에 투표해야 할까?","e":"según(~에 따르면)은 전치사지만 뒤에 대명사가 올 때는 예외적으로 주격 대명사(yo, tú)를 씁니다. 그래서 'según tú(네 생각에는)', 'según yo'가 됩니다. 'según ti'는 틀린 형태입니다.","x":["a ti: según 뒤에 a를 쓰지 않습니다 ✗","ti: 다른 전치사 뒤에는 ti를 쓰지만 según 뒤에는 쓰지 않습니다 ✗","te: 목적격 대명사라 이 자리에 올 수 없습니다 ✗","tú: según 뒤에는 주격 대명사 → 정답 ✓"]},{"id":"G508","q":"Me dijo ____ que no tenía ganas de ir a la excursión.","o":["a","desde","de","ø"],"a":3,"k":"decir que (전치사X)","t":"그는 소풍에 가고 싶지 않다고 나에게 말했다.","e":"decir(말하다) 뒤에 내용을 전할 때는 바로 que를 씁니다: 'Me dijo que...(나에게 ~라고 말했다)'. 이때 전치사 de를 넣는 'dijo de que'는 흔히 하는 실수(dequeísmo)이므로 주의하세요.","x":["a: decir que 사이에 a를 쓰지 않습니다 ✗","desde: '~부터'라는 뜻이라 맞지 않습니다 ✗","de: 'dijo de que'는 틀린 표현(dequeísmo)입니다 ✗","ø: decir 바로 뒤 que → 정답 ✓"]},{"id":"G509","q":"¿Qué ____ regalaron a José por su cumpleaños?","o":["lo","le","ø","les"],"a":1,"k":"간접목적격 le","t":"호세 생일에 사람들이 그에게 뭘 선물했어?","e":"regalar(선물하다)에서 선물을 받는 사람은 간접목적어(~에게)입니다. 'a José'는 3인칭 단수이므로 le를 씁니다. 'Qué'는 선물한 물건(직접목적어)이므로 따로 lo를 붙이지 않습니다.","x":["lo: 직접목적격(그것을)인데 qué가 이미 그 역할을 합니다 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","ø: a José가 있을 때 le를 함께 쓰는 것이 자연스러운 스페인어입니다 ✗","les: 3인칭 복수라 José 한 명과 맞지 않습니다 ✗"]},{"id":"G510","q":"Dígame ____ sabe sobre el acusado.","o":["todo que","todo lo que","todo","todo el que"],"a":1,"k":"todo lo que","t":"피고인에 대해 알고 계신 것을 모두 말씀해 주세요.","e":"'todo lo que'는 '~하는 모든 것'이라는 뜻입니다. lo que(~하는 것)가 막연한 내용을 가리키고, 앞의 todo가 '모두'를 강조합니다. 'Dígame'는 usted에게 하는 정중한 명령형(저에게 말씀해 주세요)입니다.","x":["todo que: lo가 빠져 틀린 형태입니다 ✗","todo lo que: '~하는 모든 것' → 정답 ✓","todo: 뒤에 동사 sabe를 연결할 관계사가 없습니다 ✗","todo el que: '~하는 모든 사람'이라는 뜻이라 내용(것)과 맞지 않습니다 ✗"]},{"id":"G511","q":"¿____ viste a Teresa por última vez?","o":["Desde cuándo","Cuando","Hasta cuándo","Cuándo"],"a":3,"k":"의문사 cuándo","t":"테레사를 마지막으로 본 게 언제야?","e":"'언제'를 묻는 의문문에서는 악센트가 있는 cuándo를 씁니다. 악센트 없는 cuando는 '~할 때'라는 접속사입니다. 'por última vez(마지막으로)'는 한 시점을 가리키므로 기간을 묻는 desde cuándo(언제부터)나 hasta cuándo(언제까지)는 맞지 않습니다.","x":["Desde cuándo: '언제부터'라 기간의 시작을 묻는 말이라 맞지 않습니다 ✗","Cuando: 악센트가 없으면 접속사(~할 때)라 의문문에 쓰지 않습니다 ✗","Hasta cuándo: '언제까지'라 의미가 맞지 않습니다 ✗","Cuándo: 의문사 '언제' → 정답 ✓"]},{"id":"G512","q":"Cuando ____ todas mis deudas, me sentiré mejor.","o":["pague","pagué","pagaré","pago"],"a":0,"k":"cuando+접속법","t":"빚을 다 갚으면 기분이 나아질 거야.","e":"cuando(~할 때)가 미래에 일어날 일을 가리키면 뒤에 접속법을 씁니다. 주절이 미래형(me sentiré)이므로 cuando절에는 pagar의 접속법 현재 pague가 옵니다. 주의: cuando 뒤에는 미래형(pagaré)을 쓰지 않습니다.","x":["pague: pagar의 접속법 현재(yo), 미래의 때 → 정답 ✓","pagué: 단순과거라 미래 일에 맞지 않습니다 ✗","pagaré: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","pago: 직설법 현재는 습관을 말할 때 쓰며, 미래 일에는 접속법이 필요합니다 ✗"]},{"id":"G513","q":"____ tomarme un té, por eso no quiero otro. Gracias de todas formas.","o":["He dejado de","Acabo de","Me pongo a","Estoy a punto de"],"a":1,"k":"acabar de+원형","t":"방금 차를 한 잔 마셨어요, 그래서 한 잔 더는 괜찮아요. 아무튼 고마워요.","e":"'acabar de + 동사원형'은 '방금 ~했다'라는 뜻으로 아주 가까운 과거를 나타냅니다. 방금 차를 마셔서 더 마시고 싶지 않다는 문맥에 딱 맞습니다. 예: Acabo de llegar. (방금 도착했어.)","x":["He dejado de: '~하는 것을 그만두었다'라 '방금 마셨다'는 문맥과 맞지 않습니다 ✗","Acabo de: '방금 ~했다' → 정답 ✓","Me pongo a: '~하기 시작하다'라 의미가 맞지 않습니다 ✗","Estoy a punto de: '막 ~하려는 참이다'라 아직 안 마셨다는 뜻이 됩니다 ✗"]},{"id":"G514","q":"¿Qué sueles ____ hacer en cuanto llegas a tu casa?","o":["a","por","de","ø"],"a":3,"k":"soler+원형","t":"너는 집에 도착하자마자 보통 뭘 해?","e":"soler(평소에 ~하곤 하다)는 뒤에 전치사 없이 바로 동사원형이 옵니다: suelo leer(나는 보통 책을 읽는다). 'en cuanto(~하자마자)'는 습관을 말할 때 직설법(llegas)과 함께 씁니다.","x":["a: soler 뒤에는 전치사를 쓰지 않습니다 ✗","por: soler 뒤에 por는 오지 않습니다 ✗","de: soler 뒤에 de는 오지 않습니다 ✗","ø: soler + 동사원형 → 정답 ✓"]},{"id":"G515","q":"Javier, ____ la ropa en la lavadora, por favor.","o":["pones","pone","pondrás","pon"],"a":3,"k":"불규칙 명령형 pon","t":"하비에르, 빨래 좀 세탁기에 넣어 줘.","e":"이름을 부르며 친한 상대(tú)에게 부탁하므로 tú 긍정명령형을 씁니다. poner의 tú 긍정명령형은 불규칙형 pon입니다. 같은 불규칙 명령형: ten(tener), ven(venir), sal(salir), haz(hacer), di(decir).","x":["pones: 직설법 현재라 명령이 아닌 서술이 됩니다 ✗","pone: usted/3인칭 직설법 현재입니다 ✗","pondrás: 미래형이라 부탁하는 문맥에 맞지 않습니다 ✗","pon: poner의 tú 긍정명령형 → 정답 ✓"]},{"id":"G516","q":"____ lunes voy a ver a mis abuelos.","o":["Todos","Todas las","Todos los","Todas"],"a":2,"k":"todos los+요일","t":"매주 월요일 나는 할아버지 할머니를 뵈러 간다.","e":"'매주 ~요일'이라는 반복은 'todos los + 요일 복수형'으로 나타냅니다. 요일은 모두 남성 명사이므로 todos los lunes가 됩니다. lunes는 단수와 복수 형태가 같습니다(el lunes / los lunes).","x":["Todos: 정관사 los가 빠져 틀립니다 ✗","Todas las: 여성형인데 요일은 남성 명사입니다 ✗","Todos los: todos los lunes '매주 월요일' → 정답 ✓","Todas: 여성형이고 관사도 빠졌습니다 ✗"]},{"id":"G517","q":"Javier es ____ jardinero.","o":["ø","un","uno","una"],"a":0,"k":"직업 앞 무관사","t":"하비에르는 정원사다.","e":"ser 동사 뒤에 직업·국적·종교를 말할 때는 보통 관사를 쓰지 않습니다: Es jardinero.(정원사다) 다만 형용사가 붙어 묘사하면 관사를 씁니다: Es un jardinero excelente.(훌륭한 정원사다)","x":["ø: ser + 직업은 무관사 → 정답 ✓","un: 형용사 없이 직업만 말할 때는 관사를 쓰지 않습니다 ✗","uno: 명사 앞에서는 un으로 줄여 써야 하고, 여기선 관사도 필요 없습니다 ✗","una: 여성형이라 남성 명사 jardinero와 맞지 않습니다 ✗"]},{"id":"G518","q":"Os ____ vuestra colaboración. Sin vosotros no lo habría conseguido.","o":["agradezco","agradecéis","agradece","agradecido"],"a":0,"k":"agradecer 현재형","t":"너희의 협조에 감사해. 너희가 없었다면 해내지 못했을 거야.","e":"'Os(너희에게)'가 감사를 받는 사람이고, 감사하는 주어는 '나(yo)'입니다. agradecer는 1인칭 단수에서 -zco로 바뀌는 불규칙 동사이므로 agradezco가 됩니다. 같은 유형: conocer → conozco, ofrecer → ofrezco.","x":["agradezco: agradecer의 1인칭 단수 현재 → 정답 ✓","agradecéis: vosotros가 주어인 형태라 '너희가 감사한다'가 됩니다 ✗","agradece: 3인칭 단수 형태라 주어가 맞지 않습니다 ✗","agradecido: 과거분사(감사하는)라 동사 자리에 단독으로 쓸 수 없습니다 ✗"]},{"id":"G519","q":"____ importante es tener salud.","o":["El","De lo","Lo","La"],"a":2,"k":"중성 관사 lo","t":"중요한 것은 건강하다는 것이다.","e":"중성 관사 lo + 형용사는 '~한 것'이라는 추상적인 뜻을 만듭니다. 'Lo importante'는 '중요한 것'이라는 뜻입니다. 예: Lo bueno es que... (좋은 점은 ~라는 것이다)","x":["El: 남성 관사 + 형용사는 구체적인 남성 명사를 가리키게 됩니다 ✗","De lo: 주어 자리에 전치사 de가 올 수 없습니다 ✗","Lo: 중성 관사 lo + 형용사 '~한 것' → 정답 ✓","La: 여성 관사라 추상적인 '것'을 나타내지 못합니다 ✗"]},{"id":"G520","q":"Fui a una tienda y ____ compré un regalo a mi sobrina.","o":["le","la","se","lo"],"a":0,"k":"간접목적격 le","t":"가게에 가서 조카딸에게 선물을 하나 샀다.","e":"comprar algo a alguien(누구에게 무엇을 사 주다)에서 선물을 받는 사람(a mi sobrina)은 간접목적어입니다. 3인칭 단수 간접목적격은 성별과 상관없이 le입니다. 직접목적어는 'un regalo(선물)'입니다.","x":["le: 3인칭 단수 간접목적격(그녀에게) → 정답 ✓","la: 직접목적격(그녀를)이라 '~에게'에 쓰지 않습니다(laísmo 오류) ✗","se: 재귀대명사라 이 문장에 맞지 않습니다 ✗","lo: 직접목적격(그것을/그를)이라 '~에게'에 맞지 않습니다 ✗"]},{"id":"G521","q":"El apartamento de mis abuelos ____ pequeño pero acogedor.","o":["era","ha sido","fue","había sido"],"a":0,"k":"묘사의 불완료과거","t":"할아버지 할머니의 아파트는 작지만 아늑했다.","e":"과거의 사물이나 장소의 모습·특징을 묘사할 때는 불완료과거(과거의 배경·상태를 나타내는 시제)를 씁니다. ser의 불완료과거 3인칭 단수는 era입니다. 'pequeño pero acogedor(작지만 아늑한)'는 지속적인 특징 묘사입니다.","x":["era: ser의 불완료과거, 과거 묘사 → 정답 ✓","ha sido: 현재완료라 과거 묘사에 맞지 않습니다 ✗","fue: 단순과거는 끝난 사건에 쓰며 배경 묘사에는 어색합니다 ✗","había sido: 대과거라 다른 과거보다 앞선 일이 아니므로 맞지 않습니다 ✗"]},{"id":"G522","q":"El gimnasio ____ voy tiene muchas máquinas para entrenar.","o":["que","a quien","al que","a que"],"a":2,"k":"관계사 al que","t":"내가 다니는 헬스장에는 운동 기구가 많다.","e":"ir a(~에 가다)처럼 동사가 전치사 a를 요구하면 관계사 앞에도 그 전치사가 옵니다. 선행사 el gimnasio는 남성 단수이므로 'a + el que = al que'가 됩니다. 'adonde voy'나 'donde voy'라고도 할 수 있습니다.","x":["que: 동사 ir가 요구하는 전치사 a가 빠졌습니다 ✗","a quien: quien은 사람에게만 쓰는데 gimnasio는 장소입니다 ✗","al que: a + el que, ir a에 맞는 관계사 → 정답 ✓","a que: 정관사가 빠져 관계사로 쓸 수 없습니다 ✗"]},{"id":"G523","q":"Isabel se esfuerza cada día ____ a sus hijos no les falte de nada.","o":["para","a que","para que","ya que"],"a":2,"k":"para que+접속법","t":"이사벨은 아이들에게 부족한 것이 없도록 매일 애쓴다.","e":"para que(~하도록, ~하기 위해)는 목적을 나타내며 항상 접속법과 함께 씁니다. 주절 주어(Isabel)와 que절 주어(아이들에게 부족함)가 다르므로 para가 아니라 para que가 필요합니다. 'no falte de nada'는 '아무것도 부족하지 않다'는 뜻입니다.","x":["para: 주어가 다를 때는 que를 붙여야 합니다 ✗","a que: 일부 동사 뒤에서는 쓰지만 esforzarse 뒤 목적 표현으로는 어색합니다 ✗","para que: 목적 '~하도록' + 접속법 → 정답 ✓","ya que: '~이므로'라는 이유 표현이라 의미가 맞지 않습니다 ✗"]},{"id":"G524","q":"¿A qué hora ____ a tus hijos cada mañana?","o":["se despiertan","despiertas","te despiertas","te despiertes"],"a":1,"k":"despertar 타동사","t":"너는 매일 아침 몇 시에 아이들을 깨우니?","e":"despertar(깨우다)는 다른 사람을 깨울 때 재귀대명사 없이 씁니다: despertar a alguien. 스스로 일어날 때만 despertarse(깨다)를 씁니다. 여기서는 '네가 아이들을 깨우다'이므로 despiertas가 맞습니다.","x":["se despiertan: '그들이 깬다'라는 뜻이 되어 a tus hijos와 맞지 않습니다 ✗","despiertas: '네가 (아이들을) 깨운다' → 정답 ✓","te despiertas: '네가 깬다'라 목적어 a tus hijos와 어울리지 않습니다 ✗","te despiertes: 접속법이라 일반 의문문에 쓰지 않습니다 ✗"]},{"id":"G525","q":"Me acosté en cuanto llegué a casa porque la noche anterior no ____ nada.","o":["estaba durmiendo","he dormido","había dormido","estuve durmiendo"],"a":2,"k":"직설법 대과거","t":"나는 집에 도착하자마자 잠자리에 들었다. 전날 밤에 한숨도 못 잤기 때문이다.","e":"과거의 어떤 일(me acosté 잠자리에 들었다)보다 더 이전에 일어난 일은 대과거(había + 과거분사)로 나타냅니다. 'la noche anterior(그 전날 밤)'는 과거 기준점보다 앞선 시간이므로 había dormido가 맞습니다.","x":["estaba dormiendo: 진행 중인 상태라 '전혀 못 잤다'는 의미와 맞지 않습니다 ✗","he dormido: 현재완료라 과거 이야기 속에서 쓰지 않습니다 ✗","había dormido: 과거보다 더 이전의 일, 대과거 → 정답 ✓","estuve durmiendo: '한동안 자고 있었다'는 뜻이라 nada와 어울리지 않습니다 ✗"]},{"id":"G526","q":"¡Qué bebés ____ lindos!","o":["tantas","tanto","tan","tantos"],"a":2,"k":"감탄문 qué+명사+tan","t":"아기들이 정말 귀엽네!","e":"'¡Qué + 명사 + tan/más + 형용사!'는 '정말 ~한 ~이구나!'라는 감탄문입니다. 형용사 앞에는 형태가 변하지 않는 tan을 씁니다. lindo(귀여운, 예쁜)는 중남미에서 특히 자주 쓰고, 스페인에서는 bonito/mono를 더 많이 씁니다.","x":["tantas: 명사 앞에 쓰는 형태(그렇게 많은)이고 성도 맞지 않습니다 ✗","tanto: 동사나 명사와 쓰며 형용사 앞에서는 tan이 됩니다 ✗","tan: 형용사 앞 '그렇게, 정말' → 정답 ✓","tantos: 명사 앞에 쓰는 '그렇게 많은'이라 형용사 앞에 오지 않습니다 ✗"]},{"id":"G527","q":"Nunca he estado ____ Canadá, pero me encantaría ir.","o":["sobre","a","hacia","en"],"a":3,"k":"estar en+장소","t":"캐나다에 가 본 적은 없지만, 정말 가 보고 싶다.","e":"'he estado en + 장소'는 '~에 가 본 적이 있다(~에 있어 본 적이 있다)'는 경험 표현입니다. estar는 위치를 나타내므로 장소 앞에 en을 씁니다. ir(가다)를 쓸 때만 a를 씁니다: Nunca he ido a Canadá.","x":["sobre: '~위에, ~에 대해'라는 뜻이라 맞지 않습니다 ✗","a: 방향(~로)은 ir와 쓰며 estar와는 쓰지 않습니다 ✗","hacia: '~쪽으로'라는 방향 표현이라 맞지 않습니다 ✗","en: estar en + 장소 → 정답 ✓"]},{"id":"G528","q":"No creo que Roberto ____ las condiciones de este contrato.","o":["aceptará","acepte","aceptaría","acepta"],"a":1,"k":"no creo que+접속법","t":"로베르토가 이 계약 조건을 받아들일 것 같지 않다.","e":"'No creo que(~라고 생각하지 않는다)'는 의심을 나타내므로 que절에 접속법을 씁니다. aceptar의 접속법 현재 3인칭 단수는 acepte입니다. -ar 동사의 접속법 현재는 어미가 -e로 바뀝니다.","x":["aceptará: 직설법 미래로, 부정의 creer 뒤에는 접속법이 필요합니다 ✗","acepte: aceptar의 접속법 현재 → 정답 ✓","aceptaría: 가정미래로 이 구조에 맞지 않습니다 ✗","acepta: 직설법 현재라 no creo que 뒤에 쓰지 않습니다 ✗"]},{"id":"G529","q":"Podemos ir ____ quieras, es tu cumpleaños.","o":["adónde","dónde","a dónde","adonde"],"a":3,"k":"관계부사 adonde","t":"네가 원하는 곳으로 가도 돼, 네 생일이니까.","e":"ir(가다)와 함께 '~하는 곳으로'를 말할 때는 관계부사 adonde(악센트 없음)를 씁니다. 의문문이 아닌 관계절이므로 악센트를 붙이지 않습니다. 'quieras'는 정해지지 않은 장소를 말하므로 접속법입니다.","x":["adónde: 악센트가 있으면 의문사(어디로?)라 관계절에 쓰지 않습니다 ✗","dónde: 악센트가 있는 의문사이고 방향의 a도 없습니다 ✗","a dónde: 악센트가 있는 의문사 형태라 관계절에 맞지 않습니다 ✗","adonde: 관계부사 '~하는 곳으로' → 정답 ✓"]},{"id":"G530","q":"El río ____ más caudaloso de España es el Ebro.","o":["del","el","ø","lo"],"a":2,"k":"최상급 구조","t":"스페인에서 수량이 가장 많은 강은 에브로 강이다.","e":"최상급은 '정관사 + 명사 + más + 형용사 + de'로 만듭니다. 이미 'El río'에 정관사가 있으므로 más 앞에 관사를 다시 쓰지 않습니다. caudaloso는 '수량이 풍부한'이라는 뜻입니다.","x":["del: más 앞에 de+el을 넣으면 문장이 성립하지 않습니다 ✗","el: 정관사가 이미 río 앞에 있어 중복됩니다 ✗","ø: El río más caudaloso, 관사 중복 없음 → 정답 ✓","lo: 중성 관사라 명사 río를 꾸밀 수 없습니다 ✗"]},{"id":"G531","q":"No sé por qué no ha llegado Federico todavía. ____ en su trabajo terminando alguna tarea.","o":["Estará","Estaría","Está","Esté"],"a":0,"k":"추측의 미래형","t":"페데리코가 왜 아직 안 왔는지 모르겠어. 아마 회사에서 무슨 일을 마무리하고 있겠지.","e":"스페인어에서 미래형은 '현재에 대한 추측(~이겠지)'을 나타낼 수 있습니다. 지금 이 순간 페데리코가 어디 있는지 추측하므로 estar의 미래형 estará를 씁니다. 과거에 대한 추측이면 가정미래(estaría)를 씁니다.","x":["Estará: 현재 추측의 미래형(~하고 있겠지) → 정답 ✓","Estaría: 가정미래로, 과거 상황을 추측할 때 씁니다 ✗","Está: 직설법 현재라 확신하는 말투가 되어 추측의 뜻이 없습니다 ✗","Esté: 접속법이라 독립된 문장에 단독으로 쓰지 않습니다 ✗"]},{"id":"G532","q":"No recuerdo ____ nada de aquel día.","o":["ø","a","de","por"],"a":0,"k":"recordar 타동사","t":"그날에 대해서는 아무것도 기억나지 않는다.","e":"recordar(기억하다)는 타동사로 목적어를 전치사 없이 바로 받습니다: recordar algo. 'acordarse de'와 혼동하지 마세요. 'No recuerdo nada = No me acuerdo de nada'로 같은 뜻입니다.","x":["ø: recordar + 목적어(전치사 없음) → 정답 ✓","a: 사물 목적어 앞에는 a를 쓰지 않습니다 ✗","de: de는 acordarse와 쓰는 전치사입니다 ✗","por: recordar 뒤에 por는 오지 않습니다 ✗"]},{"id":"G533","q":"No encuentro mi anillo por ninguna parte. Creo que nunca lo ____.","o":["encuentro","encuentre","encontraré","estaré encontrando"],"a":2,"k":"직설법 미래","t":"반지를 아무 데서도 찾을 수가 없어. 영영 못 찾을 것 같아.","e":"'Creo que(~라고 생각한다)'는 긍정이므로 que절에 직설법을 씁니다. 앞으로의 일을 예상하므로 encontrar의 미래형 encontraré가 맞습니다. 'nunca lo encontraré'는 '절대 그것을 찾지 못할 것이다'라는 뜻입니다.","x":["encuentro: 현재형이라 앞으로의 예상을 표현하기엔 약합니다 ✗","encuentre: 접속법인데 긍정 creo que 뒤에는 직설법을 씁니다 ✗","encontraré: 직설법 미래(찾을 것이다) → 정답 ✓","estaré encontrando: 미래진행은 '찾다'처럼 순간적인 동작과 어울리지 않습니다 ✗"]},{"id":"G534","q":"Últimamente no tenemos ____ tiempo libre.","o":["un poco","mucho","muy","tan"],"a":1,"k":"mucho+명사","t":"요즘 우리는 자유 시간이 많지 않다.","e":"명사 앞에서 '많은'은 mucho/mucha/muchos/muchas로, 명사의 성·수에 맞춥니다. tiempo는 남성 단수이므로 mucho tiempo가 됩니다. muy는 형용사·부사 앞에만 씁니다(muy cansado).","x":["un poco: '조금'은 명사 앞에서 'un poco de tiempo'처럼 de가 필요합니다 ✗","mucho: 남성 단수 명사 앞 '많은' → 정답 ✓","muy: 형용사·부사 앞에만 쓰고 명사 앞에는 쓰지 않습니다 ✗","tan: 형용사 앞 '그렇게'라 명사 앞에서는 tanto가 됩니다 ✗"]},{"id":"G535","q":"Déjame dormir un poco más, ____ muy pronto...","o":["están","está","es","son"],"a":2,"k":"시간 표현 ser","t":"조금만 더 자게 해 줘, 아직 너무 이르잖아...","e":"시각이나 '이르다/늦다'를 말할 때는 3인칭 단수 무인칭 ser를 씁니다: Es pronto(이르다), Es tarde(늦다), Son las tres(3시다). 주어가 따로 없으므로 단수 es가 맞습니다.","x":["están: estar 복수형이라 시간 표현에 쓰지 않습니다 ✗","está: estar는 'es pronto/tarde' 같은 시간 표현에 쓰지 않습니다 ✗","es: 시간 표현의 ser(이르다) → 정답 ✓","son: 복수형은 'son las dos'처럼 시각에만 씁니다 ✗"]},{"id":"G536","q":"¿Por qué no ____ has dado la comida al perro todavía?","o":["le","ø","les","lo"],"a":0,"k":"중복 간접목적격 le","t":"왜 아직 개한테 밥을 안 줬어?","e":"dar(주다)에서 받는 쪽(al perro 개에게)은 간접목적어이므로 3인칭 단수 le를 씁니다. 스페인어에서는 'a + 명사'가 뒤에 나와도 대명사 le를 앞에 함께 쓰는 경우가 많습니다. 직접목적어는 'la comida(밥)'입니다.","x":["le: 3인칭 단수 간접목적격(그것에게) → 정답 ✓","ø: 문법적으로 가능하지만 'al perro'와 le를 함께 쓰는 것이 자연스럽습니다 ✗","les: 복수형이라 개 한 마리와 맞지 않습니다 ✗","lo: 직접목적격이라 '~에게'를 나타내지 못합니다 ✗"]},{"id":"G537","q":"Mi color favorito es ____ morado.","o":["un","el","uno","ø"],"a":1,"k":"색 이름과 정관사","t":"내가 가장 좋아하는 색은 보라색이다.","e":"색 이름을 명사로 쓸 때는 남성 명사로 취급하며 정관사 el을 붙입니다: el morado(보라색), el azul(파란색). 'Mi color favorito es el rojo'처럼 씁니다.","x":["un: '어떤 보라색'이라는 뜻이 되어 어색합니다 ✗","el: 색 이름(남성 명사) 앞의 정관사 → 정답 ✓","uno: 명사 앞에서는 un이 되어야 하고 의미도 맞지 않습니다 ✗","ø: 일상 회화에서는 생략도 들리지만 교재 기준 정관사가 필요합니다 ✗"]},{"id":"G538","q":"Pablito quiere ir ____ a la fiesta. ¿Te parece bien?","o":["con te","contigo","con ti","con tú"],"a":1,"k":"contigo","t":"파블리토가 너랑 같이 파티에 가고 싶어 해. 괜찮겠어?","e":"전치사 con + 1·2인칭 대명사는 특별한 형태가 됩니다: con + mí → conmigo, con + ti → contigo. 'con ti', 'con tú'는 틀린 표현입니다. 다른 인칭은 그대로 씁니다: con él, con ella, con usted.","x":["con te: te는 목적격이라 전치사 뒤에 쓰지 않습니다 ✗","contigo: con + ti의 특수형 '너와 함께' → 정답 ✓","con ti: con 뒤에서는 contigo로 바뀌어야 합니다 ✗","con tú: 주격 tú는 con 뒤에 쓰지 않습니다 ✗"]},{"id":"G539","q":"Señor Rodríguez, ____ a la consulta.","o":["pasas","pase","pasa","pasar"],"a":1,"k":"usted 명령형","t":"로드리게스 씨, 진료실로 들어오세요.","e":"'Señor Rodríguez'에게 존댓말(usted)로 말하므로 usted 긍정명령형을 씁니다. usted 명령형은 접속법 현재와 같은 형태라서 pasar → pase가 됩니다. tú에게라면 'pasa'라고 합니다.","x":["pasas: tú의 직설법 현재라 명령이 아닙니다 ✗","pase: usted 긍정명령형(들어오세요) → 정답 ✓","pasa: tú 명령형이라 존댓말 상대에게 맞지 않습니다 ✗","pasar: 동사원형은 이 문장에서 명령으로 쓰지 않습니다 ✗"]},{"id":"G540","q":"¿Puedes hacerme ____ favor?","o":["un","uno","ø","una"],"a":0,"k":"부정관사 un","t":"나 부탁 하나 들어줄 수 있어?","e":"'hacer un favor(부탁을 들어주다)'는 정해진 표현입니다. favor는 남성 명사이므로 부정관사 un을 씁니다. uno는 명사 없이 단독으로 쓸 때의 형태입니다(Tengo uno 하나 있어).","x":["un: 남성 단수 부정관사, hacer un favor → 정답 ✓","uno: 명사 앞에서는 un으로 줄어듭니다 ✗","ø: 'hacer favor'처럼 관사를 빼면 틀립니다 ✗","una: 여성형인데 favor는 남성 명사입니다 ✗"]},{"id":"G541","q":"Cuando fuimos a Mallorca por última vez, ____ en un hotel fantástico.","o":["nos hemos alejado","nos alojábamos","nos alojamos","nos estábamos alojando"],"a":2,"k":"단순과거 alojarse","t":"마지막으로 마요르카에 갔을 때, 우리는 환상적인 호텔에 묵었다.","e":"과거의 특정 여행(cuando fuimos por última vez)에서 있었던, 끝난 일 전체를 말하므로 단순과거를 씁니다. alojarse(묵다, 숙박하다)의 nosotros 단순과거는 nos alojamos입니다. 숙박 기간 전체를 하나의 완결된 사건으로 보는 것입니다.","x":["nos hemos alejado: alejarse(멀어지다)라는 다른 동사이고 현재완료라 맞지 않습니다 ✗","nos alojábamos: 불완료과거는 반복·배경을 나타내 한 번의 여행 이야기엔 어색합니다 ✗","nos alojamos: alojarse의 단순과거(우리는 묵었다) → 정답 ✓","nos estábamos alojando: 다른 사건의 배경일 때 쓰며 여기서는 맞지 않습니다 ✗"]},{"id":"G542","q":"Me gustaría que ____ a mi lado en estos momentos.","o":["estés","seas","estuvieras","fueras"],"a":2,"k":"me gustaría que+접속법과거","t":"이럴 때 네가 내 곁에 있어 주면 좋겠어.","e":"주절이 가정미래(me gustaría ~하면 좋겠다)이면 que절에는 접속법 과거를 씁니다. '곁에 있다'는 위치·상태이므로 ser가 아니라 estar를 써서 estuvieras가 됩니다.","x":["estés: 접속법 현재라 가정미래 주절과 시제가 맞지 않습니다 ✗","seas: ser이고 시제도 맞지 않습니다 ✗","estuvieras: estar의 접속법 과거(tú) → 정답 ✓","fueras: 접속법 과거지만 ser라서 위치 표현에 맞지 않습니다 ✗"]},{"id":"G543","q":"¿Por qué ____ has comido mi trozo de tarta?","o":["tú","ø","ti","te"],"a":3,"k":"강조 재귀 comerse","t":"왜 내 케이크 조각을 (다) 먹어 버렸어?","e":"comer에 재귀대명사를 붙인 comerse는 '먹어 치우다, 다 먹어 버리다'라는 완전한 소비를 강조합니다. 주어가 tú이므로 te has comido가 됩니다. 비슷하게 beberse(다 마셔 버리다)도 있습니다.","x":["tú: 주어 대명사라 문법적으론 가능하지만 '먹어 치웠다'는 재귀 강조가 빠집니다 ✗","ø: 가능은 하지만 특정한 조각을 다 먹은 경우 te를 쓰는 것이 자연스럽습니다 ✗","ti: 전치격이라 동사 앞에 단독으로 올 수 없습니다 ✗","te: comerse의 재귀대명사(tú) → 정답 ✓"]},{"id":"G544","q":"No me gustaría ____ por una situación así.","o":["de pasar","paso","pasar","que paso"],"a":2,"k":"gustar+동사원형","t":"그런 상황은 겪고 싶지 않다.","e":"'me gustaría + 동사원형'은 '(내가) ~하고 싶다'라는 뜻으로, 좋아하는 사람과 행동하는 사람이 같으면 동사원형을 바로 씁니다. 'pasar por una situación'은 '어떤 상황을 겪다'라는 표현입니다.","x":["de pasar: gustar 뒤에 de를 쓰지 않습니다 ✗","paso: 활용형이라 gustar 뒤에 올 수 없습니다 ✗","pasar: 동사원형, me gustaría pasar → 정답 ✓","que paso: 주어가 같으면 que절을 쓰지 않고, que절이라도 접속법이어야 합니다 ✗"]},{"id":"G545","q":"Cuando era pequeño no me ____ las aceitunas, pero ahora me encantan.","o":["gustaron","han gustado","habían gustado","gustaban"],"a":3,"k":"습관의 불완료과거","t":"어렸을 때는 올리브를 좋아하지 않았지만, 지금은 아주 좋아한다.","e":"'Cuando era pequeño(어렸을 때)'처럼 과거의 오랜 기간 동안의 취향·습관은 불완료과거로 나타냅니다. gustar의 주어는 las aceitunas(올리브들, 복수)이므로 gustaban이 맞습니다.","x":["gustaron: 단순과거는 한 번의 경험에 쓰며 어린 시절의 지속적인 취향에는 어색합니다 ✗","han gustado: 현재완료라 과거 어린 시절과 맞지 않습니다 ✗","habían gustado: 대과거라 시간 관계가 맞지 않습니다 ✗","gustaban: gustar의 불완료과거 복수 → 정답 ✓"]},{"id":"G546","q":"Mi hijo, a veces, no hace ____ le digo.","o":["lo que","el que","que","los que"],"a":0,"k":"관계사 lo que","t":"내 아들은 가끔 내가 하는 말을 안 듣는다.","e":"선행사 없이 '~하는 것'이라는 막연한 내용을 가리킬 때는 lo que를 씁니다. 'no hace lo que le digo'는 '내가 그에게 말하는 것을 하지 않는다', 즉 말을 안 듣는다는 뜻입니다.","x":["lo que: '~하는 것' → 정답 ✓","el que: 특정 남성 명사(~하는 그 사람/것)를 가리켜 막연한 내용에는 쓰지 않습니다 ✗","que: 선행사가 없으므로 단독 que로는 안 됩니다 ✗","los que: '~하는 사람들'이라는 복수라 의미가 맞지 않습니다 ✗"]},{"id":"G547","q":"¿A qué hora ____ la conferencia de la que me hablaste?","o":["hay","va a estar","está","es"],"a":3,"k":"행사 장소·시간 ser","t":"네가 말했던 그 강연은 몇 시에 해?","e":"행사·사건(강연, 파티, 회의)이 '언제/어디서 열린다'고 말할 때는 estar가 아니라 ser를 씁니다: La conferencia es a las cinco. (강연은 5시에 있다) 사물의 위치에는 estar를 쓰지만 행사는 예외입니다.","x":["hay: 정관사가 붙은 특정한 대상(la conferencia)에는 hay를 쓰지 않습니다 ✗","va a estar: estar는 행사의 시간 표현에 쓰지 않습니다 ✗","está: 행사의 시간·장소에는 estar를 쓰지 않습니다 ✗","es: 행사의 시간을 말하는 ser → 정답 ✓"]},{"id":"G548","q":"Almudena es ____ jueza.","o":["ø","una","la","un"],"a":0,"k":"직업 앞 무관사","t":"알무데나는 판사다.","e":"ser 뒤에 직업을 말할 때는 보통 관사를 쓰지 않습니다: Es jueza.(판사다) jueza는 juez(판사)의 여성형입니다. 'Es una jueza muy justa(아주 공정한 판사다)'처럼 형용사가 붙으면 관사를 씁니다.","x":["ø: ser + 직업은 무관사 → 정답 ✓","una: 형용사 없이 직업만 말할 때는 관사를 쓰지 않습니다 ✗","la: 특정한 '그 판사'라는 뜻이 되어 맞지 않습니다 ✗","un: 남성형이고 관사도 필요 없습니다 ✗"]},{"id":"G549","q":"¿Qué aficiones teníais cuando ____ niños?","o":["fuisteis","estabais","estuvisteis","erais"],"a":3,"k":"ser 불완료과거","t":"너희는 어렸을 때 어떤 취미가 있었어?","e":"'cuando éramos niños(우리가 어렸을 때)'처럼 과거의 시기·신분을 말할 때는 ser의 불완료과거를 씁니다. 주어가 vosotros이므로 erais가 됩니다. 중남미에서는 'cuando eran niños'라고 합니다.","x":["fuisteis: 단순과거라 어린 시절이라는 배경 묘사에 맞지 않습니다 ✗","estabais: estar는 '어린이다'라는 신분·시기에 쓰지 않습니다 ✗","estuvisteis: estar이고 단순과거라 두 가지 모두 맞지 않습니다 ✗","erais: ser의 불완료과거(vosotros) → 정답 ✓"]},{"id":"G550","q":"¿Es cierto que estás aprendiendo ____ alemán?","o":["lo","el","la","ø"],"a":3,"k":"언어명과 관사","t":"네가 독일어를 배우고 있다는 게 사실이야?","e":"aprender, hablar, estudiar 같은 동사 바로 뒤에서 언어 이름을 쓸 때는 보통 관사를 생략합니다: Hablo español, Aprendo alemán. 반면 언어가 주어일 때는 관사를 씁니다: El alemán es difícil.","x":["lo: 중성 관사라 언어 이름 앞에 쓰지 않습니다 ✗","el: 주어일 때는 쓰지만 aprender 바로 뒤에서는 보통 생략합니다 ✗","la: 여성형인데 언어 이름은 남성 명사입니다 ✗","ø: aprender + 언어명은 무관사 → 정답 ✓"]},{"id":"G551","q":"____ libro está usado, necesito uno nuevo.","o":["Esto","Este","Esta","Estos"],"a":1,"k":"지시형용사 este","t":"이 책은 중고라서 새것이 필요해.","e":"libro(책)는 남성 단수 명사이므로 명사 앞에 남성 단수 지시형용사 este를 씁니다. esto는 중성 대명사(이것)로, 명사 앞에 붙지 않습니다.","x":["Esto: 중성 지시대명사라 명사 앞에 쓸 수 없습니다 ✗","Este: 남성 단수 지시형용사(이) → 정답 ✓","Esta: 여성형이라 남성 명사 libro와 맞지 않습니다 ✗","Estos: 복수형이라 단수 libro와 맞지 않습니다 ✗"]},{"id":"G552","q":"Todavía no ____ si hoy vamos a comer en casa o fuera.","o":["sé","sepa","estoy sabiendo","se"],"a":0,"k":"saber 현재형 sé","t":"오늘 집에서 먹을지 밖에서 먹을지 아직 모르겠어.","e":"saber(알다)의 1인칭 단수 현재형은 불규칙형 sé입니다. 악센트가 없는 se는 재귀대명사이므로 철자에 주의하세요. 'no sé si...'는 '~인지 아닌지 모르겠다'는 뜻으로 si절에는 직설법을 씁니다.","x":["sé: saber의 1인칭 단수 현재 → 정답 ✓","sepa: 접속법이라 단독 평서문에 맞지 않습니다 ✗","estoy sabiendo: saber는 진행형으로 쓰지 않습니다 ✗","se: 악센트가 없으면 재귀대명사가 되어 틀립니다 ✗"]},{"id":"G553","q":"Aunque sean de la misma familia, no ____ parecen ni en el blanco de los ojos.","o":["los","se lo","les","se"],"a":3,"k":"상호 재귀 parecerse","t":"같은 가족이긴 하지만, 그들은 서로 하나도 닮지 않았다.","e":"parecerse(서로 닮다)는 재귀동사로, 주어가 복수이면 se parecen이 '서로 닮았다'라는 뜻이 됩니다. 'no se parecen ni en el blanco de los ojos'는 '전혀 닮지 않았다'는 관용 표현(눈의 흰자위조차 안 닮았다)입니다.","x":["los: 직접목적격이라 재귀 동사 parecerse에 맞지 않습니다 ✗","se lo: 불필요한 lo가 붙어 틀립니다 ✗","les: 'les parecen'이면 '그들에게 ~처럼 보인다'라는 다른 뜻이 됩니다 ✗","se: parecerse, 서로 닮다 → 정답 ✓"]},{"id":"G554","q":"No recuerdo dónde ____ las llaves del coche.","o":["puse","puesto","estuve poniendo","pondría"],"a":0,"k":"단순과거 puse","t":"자동차 열쇠를 어디에 두었는지 기억이 안 난다.","e":"과거에 한 번 한 동작(열쇠를 둔 것)은 단순과거로 나타냅니다. poner(놓다, 두다)의 1인칭 단수 단순과거는 불규칙형 puse입니다. 같은 유형: tener → tuve, poder → pude.","x":["puse: poner의 단순과거(yo) → 정답 ✓","puesto: 과거분사라 haber 없이 단독으로 쓸 수 없습니다 ✗","estuve poniendo: '한동안 놓고 있었다'라 열쇠를 한 번 둔 동작과 맞지 않습니다 ✗","pondría: 가정미래라 과거 사실에 맞지 않습니다 ✗"]},{"id":"G555","q":"¡Qué bien! Hoy no ____ nada.","o":["me duele","me duelo","duelo","me duelen"],"a":0,"k":"doler 구문","t":"좋다! 오늘은 아무 데도 안 아파.","e":"doler(아프다)는 gustar처럼 아픈 사람을 간접목적격(me)으로, 아픈 부위를 주어로 씁니다. 여기서 주어는 nada(아무것도, 단수 취급)이므로 동사는 3인칭 단수 duele가 됩니다.","x":["me duele: 주어 nada가 단수 → 정답 ✓","me duelo: '나 자신이 아프다'는 잘못된 재귀형입니다 ✗","duelo: '내가 아프게 한다'라는 뜻이 되고, 명사로는 '애도'라는 뜻입니다 ✗","me duelen: 복수형이라 단수 nada와 맞지 않습니다 ✗"]},{"id":"G556","q":"Hoy ____ un buen día.","o":["había tenido","he tenido","haya tenido","tenía"],"a":1,"k":"hoy+현재완료","t":"오늘 좋은 하루를 보냈다.","e":"hoy(오늘), esta semana(이번 주)처럼 아직 끝나지 않은 시간 단위 안에서 일어난 일은 스페인 스페인어에서 주로 현재완료를 씁니다. he tenido는 '(오늘) ~을 가졌다/보냈다'는 뜻입니다. 중남미에서는 단순과거(tuve)도 흔히 씁니다.","x":["había tenido: 대과거라 기준이 되는 과거 시점이 없어 맞지 않습니다 ✗","he tenido: hoy와 어울리는 현재완료 → 정답 ✓","haya tenido: 접속법이라 단독 평서문에 쓰지 않습니다 ✗","tenía: 불완료과거라 오늘 하루 전체에 대한 평가로는 어색합니다 ✗"]},{"id":"G557","q":"¿Por qué ____?","o":["te rías","te ríes","ríes","rías"],"a":1,"k":"재귀동사 reírse","t":"왜 웃어?","e":"reírse(웃다)는 보통 재귀형으로 씁니다. 주어가 tú이므로 te ríes가 됩니다. reír의 현재형은 악센트에 주의해야 합니다: me río, te ríes, se ríe. 일반 의문문에는 직설법을 씁니다.","x":["te rías: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","te ríes: reírse의 직설법 현재(tú) → 정답 ✓","ríes: 재귀대명사가 없어 부자연스럽습니다 ✗","rías: 재귀대명사도 없고 접속법이라 틀립니다 ✗"]},{"id":"G558","q":"Puedes venir ____ quieras. Para ti las puertas de mi casa están siempre abiertas.","o":["donde","quien","cuando","como"],"a":2,"k":"cuando+접속법","t":"네가 원할 때 언제든 와도 돼. 너에게 우리 집 문은 항상 열려 있어.","e":"'cuando quieras(네가 원할 때 언제든)'는 정해지지 않은 미래의 때를 가리켜 접속법을 씁니다. 뒷문장 '문이 항상 열려 있다'는 언제든 와도 된다는 시간의 의미와 잘 어울립니다.","x":["donde: '네가 원하는 곳으로'라 venir(오다)와 의미가 어색합니다 ✗","quien: 사람(누구든)을 가리켜 맞지 않습니다 ✗","cuando: '네가 원할 때' → 정답 ✓","como: '네가 원하는 방식으로'라 문맥과 맞지 않습니다 ✗"]},{"id":"G559","q":"Veo a mis antiguos compañeros de trabajo de vez ____ cuando.","o":["para","en","por","a"],"a":1,"k":"de vez en cuando","t":"나는 예전 직장 동료들을 가끔 만난다.","e":"'de vez en cuando'는 '가끔, 때때로'라는 고정 표현입니다. 중간의 전치사는 반드시 en입니다. 비슷한 표현으로 a veces(가끔)가 있습니다.","x":["para: 이 관용 표현에 쓰지 않습니다 ✗","en: de vez en cuando '가끔' → 정답 ✓","por: 이 관용 표현에 쓰지 않습니다 ✗","a: 이 관용 표현에 쓰지 않습니다 ✗"]},{"id":"G560","q":"A todos les encantó la comida de ese restaurante menos ____.","o":["me","a mí","yo","mí"],"a":1,"k":"menos a mí","t":"나만 빼고 모두가 그 식당 음식을 무척 좋아했다.","e":"encantar(무척 좋아하다) 구문에서 좋아하는 사람은 'a + 사람(a todos)'으로 나타납니다. 그래서 '~를 제외하고'라고 비교할 때도 같은 형태 'a mí'를 맞춰 씁니다. 'Todos fueron menos yo'처럼 주어를 비교할 때는 yo를 쓰는 것과 대비해 보세요.","x":["me: 목적격 대명사라 menos 뒤에 단독으로 올 수 없습니다 ✗","a mí: a todos와 같은 형태로 맞춘 'a + 사람' → 정답 ✓","yo: 주격이라 간접목적어 a todos와 짝이 맞지 않습니다 ✗","mí: 전치사 a가 빠졌습니다 ✗"]},{"id":"G561","q":"Rafa y Lorena están pensando en ____ a otro barrio.","o":["mudar","mudarse","se mudar","mudar se"],"a":1,"k":"재귀동사 원형 mudarse","t":"라파와 로레나는 다른 동네로 이사 갈 생각을 하고 있다.","e":"mudarse(이사하다)는 재귀동사로, 동사원형으로 쓸 때 재귀대명사를 끝에 붙입니다. 전치사 en 뒤에는 동사원형이 오므로 'pensando en mudarse'가 됩니다. 주어가 ellos이므로 원형 끝의 se도 3인칭에 맞습니다.","x":["mudar: '바꾸다, 옮기다'라는 타동사라 '이사하다'의 뜻이 되지 않습니다 ✗","mudarse: 재귀동사 원형(이사하다) → 정답 ✓","se mudar: 동사원형 앞에 재귀대명사를 따로 둘 수 없습니다 ✗","mudar se: 원형과 se는 붙여 써야 합니다 ✗"]},{"id":"G562","q":"El autobús al que se refiere no pasa ____ esta calle.","o":["entre","sobre","para","por"],"a":3,"k":"통과의 por","t":"말씀하신 버스는 이 길로 지나가지 않습니다.","e":"pasar por(~을 지나가다)처럼 통과하는 장소를 나타낼 때는 por를 씁니다. 'no pasa por esta calle'는 '이 길을 지나가지 않는다'는 뜻입니다. 'se refiere'는 usted에게 하는 정중한 말투입니다.","x":["entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗","sobre: '~위에'라는 뜻이라 맞지 않습니다 ✗","para: 목적지·목적(~을 향해, ~을 위해)이라 통과 의미와 다릅니다 ✗","por: 통과(~을 지나서) → 정답 ✓"]},{"id":"G563","q":"Perdona, Antonio, ¿____ tu móvil? Es que necesito hacer una llamada.","o":["me dejas","me deja","dejarme","me dejes"],"a":0,"k":"부탁 표현 ¿me dejas?","t":"미안한데, 안토니오, 네 휴대폰 좀 빌려줄래? 전화를 한 통 해야 해서.","e":"친한 사람(tú)에게 부탁할 때 현재형 의문문 '¿Me dejas...?(~ 빌려줄래?)'를 자주 씁니다. Antonio를 tú(tu móvil)로 부르고 있으므로 2인칭 dejas가 맞습니다. 'móvil'은 스페인에서 쓰는 말이고 중남미에서는 'celular'라고 합니다.","x":["me dejas: 2인칭 현재 의문문으로 부탁 → 정답 ✓","me deja: usted 형태인데 tu móvil로 보아 tú로 말하고 있습니다 ✗","dejarme: 동사원형이라 의문문 동사로 쓸 수 없습니다 ✗","me dejes: 접속법이라 단독 의문문에 쓰지 않습니다 ✗"]},{"id":"G564","q":"Tengo un reloj que ____ perfectamente desde hace años.","o":["funcione","funcionase","funcionaría","funciona"],"a":3,"k":"존재 선행사+직설법","t":"나는 몇 년째 완벽하게 잘 가는 시계를 가지고 있다.","e":"관계절의 선행사가 실제로 있는 물건(내가 가진 시계)이면 관계절에 직설법을 씁니다. 'desde hace años(몇 년 전부터)'와 함께 현재까지 계속되는 사실이므로 현재형 funciona가 맞습니다.","x":["funcione: 접속법은 존재하지 않거나 막연한 대상에 씁니다 ✗","funcionase: 접속법 과거라 시제도, 법도 맞지 않습니다 ✗","funcionaría: 가정미래라 사실 묘사에 맞지 않습니다 ✗","funciona: 직설법 현재, 실제 존재하는 선행사 → 정답 ✓"]},{"id":"G565","q":"Es normal que ____ cansados, trabajan muchas horas.","o":["están","son","sean","estén"],"a":3,"k":"es normal que+접속법","t":"그들이 피곤한 것은 당연해, 오랜 시간 일하잖아.","e":"'Es normal que(~하는 것은 당연하다)'처럼 가치 판단을 나타내는 표현 뒤에는 접속법을 씁니다. '피곤하다'는 일시적인 상태이므로 estar를 써서 estén cansados가 됩니다.","x":["están: 직설법이라 판단 표현 뒤에 쓰지 않습니다 ✗","son: ser는 일시적 상태에 맞지 않고 직설법이기도 합니다 ✗","sean: 접속법이지만 ser라 '피곤하다'에 맞지 않습니다 ✗","estén: estar의 접속법 현재(ellos) → 정답 ✓"]},{"id":"G566","q":"Señores, ____ silencio, por favor.","o":["guardes","guarden","guardas","guardáis"],"a":1,"k":"ustedes 명령형","t":"여러분, 조용히 해 주세요.","e":"'Señores(여러분)'에게 정중하게 말하므로 ustedes 명령형을 씁니다. ustedes 명령형은 접속법 현재와 같아 guardar → guarden이 됩니다. 'guardar silencio'는 '침묵을 지키다, 조용히 하다'라는 표현입니다.","x":["guardes: tú의 접속법 현재(부정명령형)입니다 ✗","guarden: ustedes 명령형 → 정답 ✓","guardas: tú 직설법 현재라 명령이 아닙니다 ✗","guardáis: vosotros 직설법 현재라 명령이 아닙니다 ✗"]},{"id":"G567","q":"No hablo ____ idiomas como Rosa.","o":["tantos","tanta","tan","tantas"],"a":0,"k":"비교 tantos...como","t":"나는 로사만큼 많은 언어를 하지 못한다.","e":"명사의 양을 비교하는 동등 비교는 'tanto/tanta/tantos/tantas + 명사 + como'입니다. idiomas는 -a로 끝나지만 남성 복수 명사(el idioma)이므로 tantos가 맞습니다.","x":["tantos: 남성 복수, tantos idiomas como → 정답 ✓","tanta: 여성 단수라 idiomas와 맞지 않습니다 ✗","tan: 형용사·부사 앞에 쓰며 명사 앞에는 쓰지 않습니다 ✗","tantas: 여성 복수인데 idioma는 남성 명사입니다 ✗"]},{"id":"G568","q":"¿Todavía ____? Daos un poco de prisa o llegaremos tarde.","o":["coméis","comíais","estáis comiendo","habéis comido"],"a":2,"k":"현재진행형","t":"아직도 먹고 있어? 좀 서둘러, 안 그러면 늦을 거야.","e":"바로 지금 진행 중인 동작은 'estar + 현재분사'로 나타냅니다. 주어는 vosotros(daos 너희 서둘러)이므로 estáis comiendo가 맞습니다. 중남미에서는 '¿Todavía están comiendo? Apúrense'처럼 ustedes를 씁니다.","x":["coméis: 단순 현재라 '지금 이 순간 진행 중'을 강조하지 못합니다 ✗","comíais: 불완료과거라 지금 상황과 맞지 않습니다 ✗","estáis comiendo: 현재진행(지금 먹고 있다) → 정답 ✓","habéis comido: '다 먹었다'는 완료라 todavía와 의미가 맞지 않습니다 ✗"]},{"id":"G569","q":"Pienso que en el futuro ____ muy pocos vehículos contaminantes.","o":["habría","habrían","habrá","habrán"],"a":2,"k":"haber 미래형 habrá","t":"나는 미래에는 오염을 일으키는 차량이 아주 적을 거라고 생각한다.","e":"존재를 나타내는 hay(~이 있다)는 항상 3인칭 단수로만 씁니다. 미래형도 뒤의 명사가 복수여도 habrá(있을 것이다)입니다. 'Pienso que'는 긍정이므로 직설법을 씁니다. 'habrán vehículos'는 흔한 실수입니다.","x":["habría: 가정미래라 미래 예측보다는 가정의 뜻이 됩니다 ✗","habrían: 가정미래 복수이고, 존재의 haber는 복수로 쓰지 않습니다 ✗","habrá: 존재의 haber 미래형(단수) → 정답 ✓","habrán: 존재의 haber는 복수 명사 앞에서도 단수형을 씁니다 ✗"]},{"id":"G570","q":"Cuando estés mejor, ____ a ese sitio que tanto te gusta.","o":["iríamos","fuéramos","iremos","íbamos"],"a":2,"k":"cuando+접속법/미래","t":"네가 좀 나아지면, 네가 그렇게 좋아하는 그곳에 가자.","e":"'cuando + 접속법(estés)'은 미래의 시점을 나타내고, 주절에는 미래형을 씁니다. ir의 nosotros 미래형은 iremos(우리는 갈 것이다)입니다. 'que tanto te gusta'는 '네가 그토록 좋아하는'이라는 뜻입니다.","x":["iríamos: 가정미래라 cuando + 접속법 현재와 짝이 맞지 않습니다 ✗","fuéramos: 접속법 과거라 주절 동사로 쓸 수 없습니다 ✗","iremos: ir의 미래형(우리는 갈 것이다) → 정답 ✓","íbamos: 불완료과거라 미래 일과 맞지 않습니다 ✗"]},{"id":"G571","q":"Marcos, cada vez que ____, trae regalos para los niños.","o":["vino","viene","venía","había venido"],"a":1,"k":"습관의 현재형","t":"마르코스는 올 때마다 아이들에게 줄 선물을 가져온다.","e":"'cada vez que(~할 때마다)'가 현재의 습관을 나타내면 직설법 현재를 씁니다. 주절(trae 가져온다)이 현재형이므로 venir도 현재형 viene가 맞습니다. 과거 습관이었다면 'cada vez que venía, traía...'가 됩니다.","x":["vino: 단순과거라 현재형 trae와 시제가 맞지 않습니다 ✗","viene: venir의 현재형, 현재 습관 → 정답 ✓","venía: 불완료과거라 현재 습관을 나타내는 trae와 맞지 않습니다 ✗","había venido: 대과거라 시제가 맞지 않습니다 ✗"]},{"id":"G572","q":"¿____ es lo que te preocupa?","o":["Que","Lo qué","Cuál","Qué"],"a":3,"k":"의문사 qué","t":"너를 걱정시키는 게 뭐야?","e":"'¿Qué es lo que...?(~하는 것은 무엇인가?)'는 막연한 내용을 묻는 표현으로 qué를 씁니다. 의문사이므로 반드시 악센트(qué)를 붙입니다. lo que 앞에는 cuál보다 qué가 자연스럽습니다.","x":["Que: 악센트가 없으면 접속사·관계사라 의문사로 쓸 수 없습니다 ✗","Lo qué: 의문사 앞에 lo를 붙이지 않습니다 ✗","Cuál: lo que 앞에서는 qué를 씁니다 ✗","Qué: 의문사 '무엇' → 정답 ✓"]},{"id":"G573","q":"____, se ha dejado su chaqueta en la silla.","o":["Oís","Oyes","Oiga","Oye"],"a":2,"k":"usted 명령형 oiga","t":"저기요, 의자에 재킷을 두고 가셨어요.","e":"모르는 사람의 주의를 끌 때 '여보세요, 저기요'라는 뜻으로 oír의 명령형을 씁니다. 뒷문장의 'su chaqueta(당신의 재킷)'와 'se ha dejado'로 보아 상대는 usted이므로 usted 명령형 oiga가 맞습니다. 친한 사이(tú)라면 oye를 씁니다.","x":["Oís: vosotros 직설법 현재라 명령형이 아닙니다 ✗","Oyes: tú 직설법 현재라 명령형이 아닙니다 ✗","Oiga: usted 명령형 '저기요' → 정답 ✓","Oye: tú 명령형이라 su chaqueta(usted)와 맞지 않습니다 ✗"]},{"id":"G574","q":"En esta casa no ____ ni un solo espejo. ¡Qué raro!","o":["hay","es","esté","está"],"a":0,"k":"hay vs estar","t":"이 집에는 거울이 단 하나도 없다. 정말 이상하네!","e":"어떤 것이 '있다/없다'는 존재 자체를 말할 때는 hay를 씁니다. 특히 부정관사나 수량 표현(un solo espejo 단 하나의 거울)과 함께 쓰입니다. 정해진 특정한 것의 위치를 말할 때는 estar를 씁니다(El espejo está en el baño).","x":["hay: 존재 '~이 있다/없다' → 정답 ✓","es: ser는 존재를 나타내지 않습니다 ✗","esté: 접속법이라 단독 평서문에 쓰지 않습니다 ✗","está: 특정한 것의 위치에 쓰며 막연한 존재에는 쓰지 않습니다 ✗"]},{"id":"G575","q":"Pienso que en España ____ muy bien. Me gusta todo.","o":["se come","comiendo","come","comer"],"a":0,"k":"무인칭 se","t":"스페인에서는 음식이 아주 맛있다고 생각해. 다 마음에 들어.","e":"'se + 3인칭 단수 동사'는 특정 주어 없이 '(사람들이 일반적으로) ~한다'는 무인칭 표현입니다. 'en España se come muy bien'은 '스페인에서는 (사람들이) 아주 잘 먹는다', 즉 음식이 맛있다는 뜻입니다.","x":["se come: 무인칭 se '사람들이 먹는다' → 정답 ✓","comiendo: 현재분사라 활용된 동사 자리에 올 수 없습니다 ✗","come: 주어가 없어서 '누가 먹는지'가 불분명합니다 ✗","comer: 동사원형이라 que절의 동사로 쓸 수 없습니다 ✗"]},{"id":"G576","q":"Somos de Galicia, ____, somos gallegos.","o":["es decir","en cambio","por eso","sin embargo"],"a":0,"k":"설명 표현 es decir","t":"우리는 갈리시아 출신이에요. 즉, 갈리시아 사람이에요.","e":"es decir는 '즉, 다시 말해'라는 뜻으로 앞의 내용을 다른 말로 풀어 설명할 때 씁니다. '갈리시아 출신 = 갈리시아 사람'은 같은 내용을 바꿔 말한 것입니다. 비슷한 표현: o sea(즉, 구어).","x":["es decir: '즉, 다시 말해' → 정답 ✓","en cambio: '반면에'라는 대조 표현입니다 ✗","por eso: '그래서'라는 결과 표현입니다 ✗","sin embargo: '그러나'라는 대조 표현입니다 ✗"]},{"id":"G577","q":"Estoy ____ más preparada para este examen que para los otros.","o":["tan","muy","mucho","mucha"],"a":2,"k":"비교급 강조 mucho","t":"나는 다른 시험보다 이번 시험이 훨씬 더 잘 준비되어 있다.","e":"비교급 más/menos를 강조해 '훨씬 더'라고 할 때는 mucho를 씁니다: mucho más(훨씬 더). 이때 mucho는 부사라서 형태가 변하지 않습니다. muy는 비교급 앞에 쓰지 않습니다.","x":["tan: 'tan más'라는 표현은 없습니다 ✗","muy: 비교급 más 앞에 쓰지 않습니다 ✗","mucho: 비교급 강조 '훨씬 더' → 정답 ✓","mucha: 부사 역할이라 여성형으로 변하지 않습니다 ✗"]},{"id":"G578","q":"Últimamente no tengo tiempo libre, ____ no me dedico a mis aficiones.","o":["por eso","porque","o sea","ya que"],"a":0,"k":"결과 표현 por eso","t":"요즘 자유 시간이 없어서 취미 활동을 하지 못한다.","e":"por eso는 '그래서, 그 때문에'라는 뜻으로 앞 문장(원인)의 결과를 이어 줍니다. 시간이 없다(원인) → 취미 활동을 못 한다(결과)의 순서이므로 por eso가 맞습니다.","x":["por eso: '그래서'라는 결과 → 정답 ✓","porque: 뒤에 이유가 와야 하는데 여기서는 뒤 내용이 결과입니다 ✗","o sea: '즉'이라는 바꿔 말하기라 원인-결과 관계와 맞지 않습니다 ✗","ya que: '~이므로'라는 이유 표현이라 순서가 맞지 않습니다 ✗"]},{"id":"G579","q":"Venimos ____ nos den el dinero que nos deben.","o":["para","por que","que","para que"],"a":3,"k":"para que+접속법","t":"우리는 그들이 우리에게 빚진 돈을 돌려받으려고 왔다.","e":"para que(~하도록)는 목적을 나타내며 뒤에 접속법이 옵니다. 오는 사람(우리)과 돈을 주는 사람(그들)이 다르므로 para가 아니라 para que를 씁니다. den은 dar의 접속법 현재입니다.","x":["para: 주어가 다를 때는 que가 필요합니다 ✗","por que: 'por que'는 이 문맥의 목적 표현으로 쓰지 않습니다 ✗","que: 목적 의미를 나타내려면 para가 필요합니다 ✗","para que: 목적 '~하도록' + 접속법 → 정답 ✓"]},{"id":"G580","q":"No conozco a ese chico ____ la camisa blanca.","o":["de","a","con","en"],"a":0,"k":"특징의 de","t":"나는 흰 셔츠를 입은 그 남자애를 모른다.","e":"사람의 옷차림이나 특징으로 구별할 때 전치사 de를 씁니다: el chico de la camisa blanca(흰 셔츠의 그 남자애). 'la chica de gafas(안경 쓴 여자애)'도 같은 용법입니다. con도 가능하지만 특정 인물을 가리킬 때는 de가 더 자연스럽습니다.","x":["de: 특징으로 사람을 구별하는 de → 정답 ✓","a: '~에게, ~로'라는 뜻이라 맞지 않습니다 ✗","con: 쓸 수는 있지만 정해진 사람을 가리킬 때는 de가 더 일반적입니다 ✗","en: '~안에'라는 장소 의미라 어색합니다 ✗"]},{"id":"G581","q":"A Jorge no ____ interesa el fútbol.","o":["ø","les","lo","le"],"a":3,"k":"interesar 구문","t":"호르헤는 축구에 관심이 없다.","e":"interesar(관심을 끌다)는 관심을 느끼는 사람을 간접목적격 대명사로 씁니다. 'A Jorge'는 3인칭 단수이므로 le가 맞습니다. 'a + 사람'이 문장 앞에 나오면 대명사 le를 반드시 함께 씁니다.","x":["ø: a Jorge가 앞에 나오면 le를 생략할 수 없습니다 ✗","les: 3인칭 복수라 Jorge 한 명과 맞지 않습니다 ✗","lo: 직접목적격이라 interesar 구문에 쓰지 않습니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓"]},{"id":"G582","q":"No sé si Juanito ____ hoy a clase.","o":["venga","viniera","vendrá","está viniendo"],"a":2,"k":"no sé si+직설법","t":"후아니토가 오늘 수업에 올지 모르겠다.","e":"'no sé si(~인지 모르겠다)'의 si절에는 접속법이 아니라 직설법을 씁니다. 앞으로의 일에 대한 불확실함이므로 venir의 미래형 vendrá가 자연스럽습니다. 현재형 viene도 가능하지만 보기에는 없습니다.","x":["venga: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","viniera: 접속법 과거라 이 문장과 맞지 않습니다 ✗","vendrá: venir의 직설법 미래 → 정답 ✓","está viniendo: '지금 오는 중'이라는 뜻이라 'hoy a clase(오늘 수업에)' 문맥에 어색합니다 ✗"]},{"id":"G583","q":"Tienes las manos sucias, ____.","o":["lávatelas","lava te las","lávalas","las lavas"],"a":0,"k":"명령형+대명사","t":"손이 더러워, 씻어.","e":"긍정명령형에서는 대명사를 동사 끝에 붙여 씁니다. 순서는 재귀대명사(te) → 직접목적격(las, 손을)입니다: lava + te + las = lávatelas. 음절이 늘어나 원래 강세를 지키려고 악센트를 찍습니다.","x":["lávatelas: 명령형 + te + las, 붙여 쓰고 악센트 → 정답 ✓","lava te las: 대명사를 띄어 쓰면 틀립니다 ✗","lávalas: 재귀대명사 te가 없어 '자기 손'을 씻는 의미가 약해집니다 ✗","las lavas: 직설법 현재라 명령이 되지 않습니다 ✗"]},{"id":"G584","q":"No es verdad que ____ mayoría de mis amigos esté en paro.","o":["la","un","el","ø"],"a":0,"k":"la mayoría","t":"내 친구들 대부분이 실업 상태라는 건 사실이 아니다.","e":"mayoría(대부분, 다수)는 여성 명사로 정관사 la와 함께 'la mayoría de(~의 대부분)'로 씁니다. 'No es verdad que(~는 사실이 아니다)' 뒤에는 접속법(esté)이 옵니다. 'estar en paro'는 스페인에서 '실직 상태이다'라는 뜻입니다(중남미: estar desempleado).","x":["la: 여성 정관사, la mayoría → 정답 ✓","un: 남성 부정관사인데 mayoría는 여성 명사입니다 ✗","el: 남성 정관사라 맞지 않습니다 ✗","ø: la mayoría는 관사를 빼고 쓰지 않습니다 ✗"]},{"id":"G585","q":"¿____ quién vas a ir a la fiesta?","o":["Para","De","A","Con"],"a":3,"k":"동반 전치사 con","t":"너는 누구랑 파티에 갈 거야?","e":"'누구와 함께'를 물을 때는 동반의 전치사 con을 씁니다. 의문문에서는 전치사가 의문사 앞으로 옵니다: ¿Con quién vas? 대답은 'Voy con Ana(아나랑 가)'처럼 합니다.","x":["Para: '누구를 위해'라는 뜻이라 문맥과 맞지 않습니다 ✗","De: '누구의/누구로부터'라는 뜻이라 맞지 않습니다 ✗","A: '누구에게'라는 뜻이라 맞지 않습니다 ✗","Con: 동반 '누구와 함께' → 정답 ✓"]},{"id":"G586","q":"Sentaos ____ queráis.","o":["dónde","donde","adónde","adonde"],"a":1,"k":"관계부사 donde","t":"너희가 원하는 곳에 앉아.","e":"'~하는 곳에'라는 관계 표현은 악센트 없는 donde를 씁니다. 의문문이 아니므로 악센트를 붙이지 않습니다. sentarse(앉다)는 위치를 나타내므로 방향의 adonde가 아니라 donde가 맞습니다. 'sentaos'는 vosotros 명령형(스페인)이고, 중남미에서는 'siéntense'라고 합니다.","x":["dónde: 악센트가 있으면 의문사(어디?)라 관계절에 쓰지 않습니다 ✗","donde: 관계부사 '~하는 곳에' → 정답 ✓","adónde: 의문사이고 방향(어디로)이라 맞지 않습니다 ✗","adonde: 방향(~로 가는 곳)을 나타내 '앉다'와 어울리지 않습니다 ✗"]},{"id":"G587","q":"¿Cuánto ____ estos tomates?","o":["cuestan","costan","cuesten","cuesta"],"a":0,"k":"costar 어간변화","t":"이 토마토들은 얼마예요?","e":"가격을 물을 때 주어는 '물건'이므로 동사는 물건의 수에 맞춥니다. estos tomates(이 토마토들)는 복수이므로 cuestan입니다. costar는 강세가 오는 o가 ue로 바뀌는 어간변화 동사입니다: cuesta, cuestan.","x":["cuestan: costar의 3인칭 복수 현재 → 정답 ✓","costan: 어간 o가 ue로 바뀌지 않은 틀린 형태입니다 ✗","cuesten: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","cuesta: 단수형이라 복수 tomates와 맞지 않습니다 ✗"]},{"id":"G588","q":"Este es ____ mejor libro que he leído en los últimos tiempos.","o":["el","ø","un","lo"],"a":0,"k":"최상급 el mejor","t":"이 책은 최근에 내가 읽은 책 중 최고의 책이다.","e":"최상급 '가장 좋은'은 '정관사 + mejor + 명사'로 만듭니다. libro는 남성 명사이므로 el mejor libro가 됩니다. 관사를 빼면 단순 비교급(더 좋은)이 되어 버립니다.","x":["el: 최상급 el mejor(가장 좋은) → 정답 ✓","ø: 관사가 없으면 최상급이 되지 않습니다 ✗","un: 'un mejor libro'는 '더 좋은 책 하나'라 최상급이 아닙니다 ✗","lo: 중성 관사라 명사 libro 앞에 쓰지 않습니다 ✗"]},{"id":"G589","q":"Se nota que hoy ____ lleno de energía.","o":["estés","eres","estás","seas"],"a":2,"k":"estar lleno de","t":"오늘 네가 에너지가 넘친다는 게 눈에 보여.","e":"'lleno de energía(에너지로 가득 찬)'는 일시적인 상태이므로 estar를 씁니다. 'Se nota que(~가 티가 나다)'는 사실을 말하므로 que절에 직설법을 씁니다. 따라서 estás가 맞습니다.","x":["estés: 접속법인데 se nota que 뒤에는 직설법을 씁니다 ✗","eres: ser는 일시적 상태(lleno)에 쓰지 않습니다 ✗","estás: estar의 직설법 현재(tú) → 정답 ✓","seas: ser이고 접속법이라 두 가지 모두 맞지 않습니다 ✗"]},{"id":"G590","q":"En la calle ____ vivo hay poquísimos árboles.","o":["donde","de donde","adonde","dónde"],"a":0,"k":"관계부사 donde","t":"내가 사는 거리에는 나무가 아주 적다.","e":"장소 선행사(la calle)를 꾸며 '~하는 곳'을 말할 때는 관계부사 donde를 씁니다. vivir(살다)는 위치를 나타내므로 donde가 맞습니다. 'en la que vivo'로 바꿔 쓸 수도 있습니다.","x":["donde: 관계부사 '~하는 곳' → 정답 ✓","de donde: '~로부터 온 곳'이라 vivir와 맞지 않습니다 ✗","adonde: 방향(~로 가는 곳)이라 vivir와 맞지 않습니다 ✗","dónde: 악센트가 있으면 의문사라 관계절에 쓰지 않습니다 ✗"]},{"id":"G591","q":"Recuerden que la lista de participantes debe estar completada ____ mañana.","o":["a","para","por","entre"],"a":1,"k":"마감의 para","t":"참가자 명단은 내일까지 작성되어 있어야 한다는 것을 기억하세요.","e":"'~까지(마감)'처럼 일이 완료되어야 하는 기한을 나타낼 때 para를 씁니다: para mañana(내일까지). 'Recuerden'은 ustedes 명령형으로 '기억해 주세요'라는 뜻입니다.","x":["a: 기한을 나타내지 않습니다 ✗","para: 마감 기한 '~까지' → 정답 ✓","por: 대략적인 시간(~쯤)을 나타내 마감 의미와 다릅니다 ✗","entre: '~사이에'라는 뜻이라 맞지 않습니다 ✗"]},{"id":"G592","q":"Celebraremos nuestra boda ____ 5 de mayo.","o":["el","a","al","en el"],"a":0,"k":"날짜 앞 정관사 el","t":"우리는 5월 5일에 결혼식을 올릴 것이다.","e":"스페인어로 날짜(며칠에)를 말할 때는 전치사 없이 정관사 el만 씁니다: el 5 de mayo(5월 5일에). 'en el'은 쓰지 않습니다. 요일도 마찬가지입니다: el lunes(월요일에).","x":["el: 날짜 앞 정관사(~일에) → 정답 ✓","a: 날짜 앞에 a를 쓰지 않습니다 ✗","al: a + el이라 날짜 표현에 쓰지 않습니다 ✗","en el: 날짜 앞에는 en을 쓰지 않습니다 ✗"]},{"id":"G593","q":"Aunque nunca ____ en un país hispanohablante, habla muy bien español.","o":["ha vivido","vivía","estaba viviendo","había vivido"],"a":0,"k":"경험의 현재완료","t":"스페인어권 나라에서 산 적이 한 번도 없는데도, 그는 스페인어를 아주 잘한다.","e":"지금까지의 인생 경험(nunca ~한 적 없다)은 현재완료로 나타냅니다. 주절이 현재형(habla)이므로 '지금까지 살아 본 적이 없다'는 ha vivido가 맞습니다. aunque 뒤에 사실을 인정할 때는 직설법을 씁니다.","x":["ha vivido: 현재까지의 경험, 현재완료 → 정답 ✓","vivía: 불완료과거라 경험의 유무를 나타내지 못합니다 ✗","estaba viviendo: 과거진행이라 의미가 맞지 않습니다 ✗","había vivido: 대과거라 현재형 habla와 시제가 맞지 않습니다 ✗"]},{"id":"G594","q":"¿Le ____ más azúcar al café o te gusta así?","o":["eche","echar","echaré","echo"],"a":3,"k":"제안의 현재형","t":"커피에 설탕을 더 넣어 줄까, 아니면 이대로가 좋아?","e":"'¿Le echo...?(내가 ~해 줄까?)'처럼 상대에게 무언가를 해 주겠다고 제안할 때 1인칭 현재형 의문문을 씁니다. 여기서 le는 'al café(커피에)'를 가리킵니다. echar는 '넣다, 붓다'라는 뜻입니다.","x":["eche: 접속법·usted 명령형이라 이 의문문에 맞지 않습니다 ✗","echar: 동사원형이라 활용된 동사 자리에 쓸 수 없습니다 ✗","echaré: 미래형은 이런 즉석 제안에서 잘 쓰지 않습니다 ✗","echo: 1인칭 현재형 의문문, 제안 → 정답 ✓"]},{"id":"G595","q":"Me encanta que ____ para mí.","o":["cocine","cocinará","cocinaría","cocina"],"a":0,"k":"감정 표현+접속법","t":"(그/그녀/당신이) 나를 위해 요리해 주는 게 정말 좋아.","e":"'Me encanta que(~하는 것이 무척 좋다)'처럼 감정을 나타내는 표현 뒤 que절의 주어가 다르면 접속법을 씁니다. 3인칭 단수(그/그녀/usted)에 맞춰 cocinar의 접속법 현재 cocine가 됩니다.","x":["cocine: cocinar의 접속법 현재 → 정답 ✓","cocinará: 미래형이라 감정 표현 뒤에 쓰지 않습니다 ✗","cocinaría: 가정미래라 이 구조에 맞지 않습니다 ✗","cocina: 직설법이라 감정 표현 뒤 que절에 맞지 않습니다 ✗"]},{"id":"G596","q":"Está mal porque no fue ____ al estreno de su obra de teatro.","o":["nadie","alguien","alguno","alguna"],"a":0,"k":"부정어 nadie","t":"그의 연극 초연에 아무도 오지 않아서 그는 기분이 안 좋다.","e":"동사 뒤에서 '아무도'라고 할 때는 'no + 동사 + nadie'로 부정어를 두 번 씁니다. 'no fue nadie'는 '아무도 가지 않았다'는 뜻입니다. alguien(누군가)은 긍정문에서 씁니다.","x":["nadie: no와 함께 '아무도 ~않다' → 정답 ✓","alguien: 긍정의 '누군가'라 no와 함께 쓰지 않습니다 ✗","alguno: 긍정 표현이라 부정문 no와 맞지 않습니다 ✗","alguna: 긍정 표현이고 여성형이라 맞지 않습니다 ✗"]},{"id":"G597","q":"Esa decisión no ____ de mí, sino de todos nosotros.","o":["depende","se depende","dependa","dependen"],"a":0,"k":"depender de","t":"그 결정은 나에게 달린 것이 아니라 우리 모두에게 달려 있다.","e":"depender de(~에 달려 있다)는 재귀형 없이 씁니다. 주어 'esa decisión(그 결정)'은 3인칭 단수이므로 depende가 맞습니다. 'no ~, sino ~'는 '~이 아니라 ~이다'라는 표현입니다.","x":["depende: depender의 3인칭 단수 현재 → 정답 ✓","se depende: depender는 재귀형으로 쓰지 않습니다 ✗","dependa: 접속법이라 단독 평서문에 맞지 않습니다 ✗","dependen: 복수형이라 단수 주어 decisión과 맞지 않습니다 ✗"]},{"id":"G598","q":"Envíame una postal cuando ____ de viaje.","o":["estés","eres","seas","estarías"],"a":0,"k":"cuando+접속법","t":"여행 중일 때 나한테 엽서 한 장 보내 줘.","e":"cuando가 앞으로의 때를 가리키면 접속법을 씁니다. 'estar de viaje(여행 중이다)'는 일시적인 상태라서 estar를 써야 하므로 estés가 맞습니다. 'Envíame'는 tú 긍정명령형 + 대명사입니다.","x":["estés: estar의 접속법 현재(tú) → 정답 ✓","eres: ser이고 직설법이라 맞지 않습니다 ✗","seas: 접속법이지만 'estar de viaje' 표현에는 estar가 필요합니다 ✗","estarías: 가정미래는 cuando 뒤에 쓰지 않습니다 ✗"]},{"id":"G599","q":"Este mes he trabajado más horas ____ mes pasado.","o":["del","que el","como el","que"],"a":1,"k":"비교 más que","t":"이번 달에 나는 지난달보다 더 많은 시간을 일했다.","e":"우등 비교는 'más + (명사) + que + 비교 대상'으로 만듭니다. 비교 대상 'el mes pasado(지난달)'에도 정관사가 필요하므로 que el가 맞습니다. 단, 숫자 앞에서는 'más de'를 씁니다(más de diez horas).","x":["del: 'más de'는 숫자 앞에만 쓰며 비교 대상 앞에는 que를 씁니다 ✗","que el: más ... que + el mes pasado → 정답 ✓","como el: como는 동등 비교(tanto ... como)에 씁니다 ✗","que: 'mes pasado' 앞에 정관사 el이 빠졌습니다 ✗"]},{"id":"G600","q":"A Julia le gusta esta película y ____ también.","o":["a mi","yo","mí","a mí"],"a":3,"k":"a mí también","t":"훌리아는 이 영화를 좋아하고, 나도 좋아한다.","e":"gustar 구문에서 '나도 (좋아한다)'라고 맞장구칠 때는 'a + 사람'의 형태를 맞춰 'a mí también'이라고 합니다. 앞의 'A Julia le gusta'와 같은 구조입니다. mí는 전치격 대명사로 '나'를 뜻하며 악센트가 있습니다(mi는 '나의').","x":["a mi: 악센트가 없는 mi는 소유형용사(나의)라 틀립니다 ✗","yo: 주격이라 gustar 구문의 'a + 사람'과 짝이 맞지 않습니다 ✗","mí: 전치사 a가 빠졌습니다 ✗","a mí: 'a + 전치격 대명사', a mí también → 정답 ✓"]},{"id":"G601","q":"El chico con ____ compartía piso se ha ido a vivir a Finlandia.","o":["que","cual","el que","lo que"],"a":2,"k":"전치사+관계대명사","t":"내가 함께 집을 나눠 쓰던 그 남자는 핀란드로 살러 가 버렸다.","e":"관계절 안에 전치사(con, de, en 등)가 필요할 때는 '전치사 + el/la/los/las que' 형태를 씁니다. 'compartía piso con el chico(그 남자와 집을 같이 썼다)'에서 con이 앞으로 나오고, 선행사 chico가 남성 단수이므로 'con el que'가 됩니다. 'con el cual'도 가능하지만 cual은 반드시 관사와 함께 써야 합니다.","x":["que: 전치사 뒤에서는 보통 관사 없이 que만 쓰지 않습니다 ✗","cual: cual은 관계대명사로 쓸 때 반드시 el/la 등 관사가 붙어야 합니다 ✗","el que: 전치사 con 뒤, 남성 단수 선행사 chico에 맞는 형태 → 정답 ✓","lo que: 사람이 아니라 '~하는 것(내용)'을 가리키는 중성 형태라 ✗"]},{"id":"G602","q":"Cuando ____, te llevaré al mejor restaurante de la ciudad.","o":["vengas","vendrás","vas a venir","vienes"],"a":0,"k":"cuando+접속법","t":"네가 오면 이 도시 최고의 식당에 데려갈게.","e":"cuando(~할 때)가 아직 일어나지 않은 미래의 일을 가리키면, 뒤에 접속법(바람·가정·미확정을 나타내는 동사 형태)을 씁니다. 주절이 미래형 'te llevaré'이므로 '네가 올 때'는 아직 일어나지 않은 일 → venir의 접속법 현재 vengas가 맞습니다. cuando 뒤에는 미래형을 쓰지 않는다는 점이 한국인 학습자가 자주 틀리는 부분입니다.","x":["vengas: venir의 접속법 현재 2인칭 단수, 미래의 미확정 시점 → 정답 ✓","vendrás: 직설법 미래형으로, cuando 뒤에는 쓰지 않습니다 ✗","vas a venir: 근접미래(ir a + 동사원형)도 cuando 뒤 미래 의미에는 쓰지 않습니다 ✗","vienes: 직설법 현재는 습관적인 일(올 때마다)에 쓰므로 여기선 ✗"]},{"id":"G603","q":"Considero que Daniel no ____ razón.","o":["tener","tiene","tienes","tenga"],"a":1,"k":"의견동사+직설법","t":"나는 다니엘이 옳지 않다고 생각한다.","e":"considerar(~라고 여기다), creer, pensar 같은 의견 동사가 긍정문일 때는 que 뒤에 직설법을 씁니다. 주어 Daniel은 3인칭 단수이므로 tener의 직설법 현재 tiene가 맞습니다. 'tener razón'은 '옳다, 말이 맞다'라는 관용 표현입니다. 참고로 'No considero que tenga razón'처럼 주절이 부정이면 접속법을 씁니다.","x":["tener: 동사원형이라 주어가 있는 que절의 동사로 쓸 수 없습니다 ✗","tiene: 3인칭 단수 직설법 현재, 긍정 의견 동사 뒤 → 정답 ✓","tienes: 2인칭 단수(너) 형태라 Daniel과 맞지 않습니다 ✗","tenga: 접속법은 주절이 부정(No considero que...)일 때 씁니다 ✗"]},{"id":"G604","q":"¿Qué es ____ que más os gusta de esta ciudad?","o":["el","la","lo","los"],"a":2,"k":"중성관사 lo","t":"너희가 이 도시에서 가장 좋아하는 것은 무엇이니?","e":"'lo que'는 '~하는 것'이라는 뜻으로, 특정한 명사를 가리키지 않고 막연한 내용·대상을 나타냅니다. 여기서는 '너희가 가장 좋아하는 것'이 무엇인지 묻고 있으므로 중성 관사 lo를 씁니다. 예: Lo que necesito es descansar.(내게 필요한 것은 쉬는 것이다.)","x":["el: 남성 명사가 생략된 경우에 쓰는데, 여기선 특정 명사가 없습니다 ✗","la: 여성 명사를 가리킬 때 쓰므로 ✗","lo: 막연한 '것'을 나타내는 중성 관사 → 정답 ✓","los: 남성 복수 명사를 가리킬 때 쓰므로 ✗"]},{"id":"G605","q":"El protagonista de esa película es ____ actor muy conocido.","o":["el","uno","un","ø"],"a":2,"k":"부정관사 un","t":"그 영화의 주인공은 아주 유명한 배우다.","e":"'ser + 직업 명사'만 올 때는 관사를 생략하지만(Es actor.), 명사 뒤에 'muy conocido' 같은 수식어가 붙으면 부정관사 un/una를 넣습니다. 남성 단수 명사 actor 앞에서 uno는 un으로 줄어듭니다. 예: Es un médico excelente.(그는 훌륭한 의사다.)","x":["el: 정관사는 이미 알려진 특정 대상을 가리켜 '아주 유명한 배우 중 하나'라는 뜻과 맞지 않습니다 ✗","uno: 남성 명사 앞에서는 un으로 줄여 씁니다 ✗","un: 수식어가 붙은 직업 명사 앞의 부정관사 → 정답 ✓","ø: 형용사 수식어(muy conocido)가 있으므로 관사가 필요합니다 ✗"]},{"id":"G606","q":"De pequeña, Mila ____ muy nerviosa. Ahora es una de las personas más tranquilas que conozco.","o":["estaba siendo","era","fue","ha sido"],"a":1,"k":"불완료과거(묘사)","t":"어렸을 때 밀라는 아주 신경질적이었다. 지금은 내가 아는 사람들 중 가장 차분한 사람이다.","e":"'De pequeña(어렸을 때)'처럼 과거의 한 시기 동안의 성격·상태를 묘사할 때는 불완료과거(과거의 배경·습관·묘사를 나타내는 시제)를 씁니다. 따라서 ser의 불완료과거 era가 맞습니다. 단순과거 fue는 끝난 하나의 사건에 씁니다.","x":["estaba siendo: 과거진행형으로, 성격 묘사에는 어색합니다 ✗","era: 과거 한 시기의 성격을 묘사하는 불완료과거 → 정답 ✓","fue: 단순과거는 완결된 사건에 쓰므로 어린 시절 묘사에 맞지 않습니다 ✗","ha sido: 현재완료는 현재까지 이어지는 일에 쓰는데, 지금은 차분하다고 했으므로 ✗"]},{"id":"G607","q":"¿Podrías ____ echarme una mano con los deberes de matemáticas?","o":["de","para","a","ø"],"a":3,"k":"poder+동사원형","t":"수학 숙제 좀 도와줄 수 있니?","e":"poder(~할 수 있다)는 전치사 없이 바로 동사원형을 붙입니다. 따라서 'Podrías echarme una mano'가 맞습니다. 'echar una mano'는 '도와주다(손을 빌려주다)'라는 뜻의 아주 흔한 관용 표현입니다.","x":["de: poder 뒤에 de를 넣지 않습니다(deber de와 혼동 주의) ✗","para: 목적을 나타내는 para는 여기 구조에 맞지 않습니다 ✗","a: ir a, empezar a처럼 a를 쓰는 동사와 달리 poder는 a를 쓰지 않습니다 ✗","ø: poder + 동사원형, 아무것도 넣지 않음 → 정답 ✓"]},{"id":"G608","q":"¿Os habéis lavado ____ manos?","o":["las","vuestros","los","vuestras"],"a":0,"k":"신체부위+정관사","t":"너희 손 씻었니?","e":"스페인어에서는 재귀동사(자기 자신에게 하는 행동을 나타내는 동사)와 함께 신체 부위를 말할 때, 소유가 이미 대명사(os)로 드러나므로 소유형용사 대신 정관사를 씁니다. manos는 여성 복수이므로 las가 맞습니다. 예: Me lavo los dientes.(나는 이를 닦는다.)","x":["las: 여성 복수 명사 manos 앞의 정관사 → 정답 ✓","vuestros: 소유형용사는 쓰지 않고, 게다가 남성형이라 ✗","los: manos는 -o로 끝나지만 여성 명사이므로 ✗","vuestras: 재귀동사와 신체 부위에는 소유형용사를 쓰지 않습니다 ✗"]},{"id":"G609","q":"El agente de policía me preguntó ____ vivía.","o":["adónde","dónde","donde","adonde"],"a":1,"k":"간접의문문 dónde","t":"경찰관이 나에게 어디에 사는지 물었다.","e":"preguntar(묻다) 뒤의 간접의문문에서도 의문사는 악센트를 그대로 유지합니다. vivir(살다)는 위치를 나타내므로 '어디에'인 dónde를 씁니다. adónde는 ir처럼 '어디로' 이동하는 동사와 함께 씁니다.","x":["adónde: '어디로'라는 방향 의미라서 vivir와 맞지 않습니다 ✗","dónde: 악센트가 있는 의문사 '어디에', 간접의문문 → 정답 ✓","donde: 악센트 없는 형태는 관계부사(~하는 곳)라서 질문 내용에는 ✗","adonde: 악센트 없는 관계부사이며 방향 의미라 ✗"]},{"id":"G610","q":"Estoy harta ____ mi jefa. ¡Qué pesada!","o":["a","sobre","de","para"],"a":2,"k":"estar harto de","t":"나 우리 상사한테 질렸어. 정말 귀찮은 사람이야!","e":"'estar harto/a de + 사람/사물/동사원형'은 '~에 질리다, 진저리가 나다'라는 표현으로 항상 전치사 de를 씁니다. 주어가 여성이라 harta가 쓰였습니다. 예: Estoy harto de esperar.(기다리는 데 질렸어.)","x":["a: harto와 함께 쓰지 않는 전치사라 ✗","sobre: '~에 대하여'라는 뜻이라 맞지 않습니다 ✗","de: estar harto de(~에 질리다) → 정답 ✓","para: 목적·방향의 전치사라 이 표현에 쓰지 않습니다 ✗"]},{"id":"G611","q":"Me siento muy bien ____ invierno, me gusta el frío.","o":["en","por","de","a"],"a":0,"k":"계절 앞 전치사 en","t":"나는 겨울에 기분이 아주 좋다. 추운 게 좋다.","e":"계절, 달, 연도 앞에서 '~에'라고 할 때는 전치사 en을 씁니다. 예: en verano(여름에), en marzo(3월에), en 2020(2020년에). 그래서 'en invierno(겨울에)'가 맞습니다.","x":["en: 계절 앞에서 '~에' → 정답 ✓","por: por la mañana처럼 하루의 때에는 쓰지만 계절에는 쓰지 않습니다 ✗","de: de noche처럼 일부 표현에만 쓰고 '겨울에'는 en invierno입니다 ✗","a: 시각(a las tres) 앞에 쓰므로 ✗"]},{"id":"G612","q":"Elisa está locamente enamorada ____.","o":["contigo","para ti","de ti","a ti"],"a":2,"k":"enamorado de","t":"엘리사는 너에게 미친 듯이 빠져 있다.","e":"'estar enamorado/a de + 사람'은 '~를 사랑하고 있다, ~에게 반해 있다'라는 뜻으로 전치사 de를 씁니다. 전치사 뒤 인칭대명사는 ti이므로 'de ti'가 됩니다. 'enamorarse de alguien(누군가에게 반하다)'도 같은 전치사를 씁니다.","x":["contigo: '너와 함께'라는 뜻이라 사랑의 대상을 나타내지 않습니다 ✗","para ti: '너를 위해'라는 뜻이라 ✗","de ti: enamorada de(~에게 반한) + ti → 정답 ✓","a ti: enamorado는 a가 아니라 de와 씁니다 ✗"]},{"id":"G613","q":"Te escribo ____ pedirte un favor.","o":["sobre","para","con","por"],"a":1,"k":"para(목적)","t":"너에게 부탁을 하나 하려고 편지를 쓴다.","e":"'para + 동사원형'은 '~하기 위해서, ~하려고'라는 목적을 나타냅니다. 편지를 쓰는 목적이 부탁하는 것이므로 para가 맞습니다. por는 원인·이유(~때문에)를 나타낼 때 주로 씁니다.","x":["sobre: '~에 대해서'라는 주제 의미로 동사원형 목적 표현과 맞지 않습니다 ✗","para: 목적(~하기 위해) → 정답 ✓","con: '~와 함께, ~로'라는 뜻이라 ✗","por: 원인·이유를 나타내므로 목적 의미에는 ✗"]},{"id":"G614","q":"¿Saben a qué hora ____ el espectáculo?","o":["empecé","empezó","empiece","empiezo"],"a":1,"k":"간접의문문 단순과거","t":"공연이 몇 시에 시작했는지 아세요?","e":"주어는 el espectáculo(공연, 3인칭 단수)이므로 empezar의 3인칭 단수 형태가 필요합니다. 'Saben a qué hora...'처럼 의문사로 시작하는 간접의문문에는 직설법을 쓰므로 단순과거 empezó가 맞습니다.","x":["empecé: 1인칭 단수(나는 시작했다)라 공연과 맞지 않습니다 ✗","empezó: 3인칭 단수 단순과거, 직설법 → 정답 ✓","empiece: 접속법 현재로, 간접의문문에는 쓰지 않습니다 ✗","empiezo: 1인칭 단수 현재라 주어와 맞지 않습니다 ✗"]},{"id":"G615","q":"Es probable ____ luego, llévate el paraguas.","o":["que lloverá","llueva","llover","que llueva"],"a":3,"k":"es probable que","t":"이따가 비가 올 것 같아, 우산 가져가.","e":"'Es probable que(~할 가능성이 있다)'처럼 가능성·추측을 나타내는 표현 뒤에는 que와 접속법을 씁니다. llover의 접속법 현재는 llueva이므로 'que llueva'가 맞습니다. que를 빠뜨리지 않도록 주의하세요.","x":["que lloverá: 직설법 미래라 es probable que 뒤에 쓰지 않습니다 ✗","llueva: 접속법은 맞지만 que가 빠졌습니다 ✗","llover: 동사원형은 'Es probable llover'처럼 쓰지 않습니다 ✗","que llueva: que + 접속법 현재 → 정답 ✓"]},{"id":"G616","q":"Espero que te ____ la beca. Te la mereces.","o":["concederán","concederían","concedan","concedieran"],"a":2,"k":"esperar que+접속법","t":"네가 장학금을 받기를 바라. 너는 받을 자격이 있어.","e":"esperar que(~하기를 바라다)는 바람을 나타내므로 뒤에 접속법을 씁니다. 주절이 현재(Espero)이므로 접속법 현재 concedan을 씁니다. 주어가 막연한 '그들(심사하는 사람들)'이라 3인칭 복수가 쓰였고, 'conceder una beca'는 '장학금을 수여하다'라는 뜻입니다.","x":["concederán: 직설법 미래라 바람 표현 뒤에 쓰지 않습니다 ✗","concederían: 가능법(조건법)이라 ✗","concedan: 현재 바람에 맞는 접속법 현재 → 정답 ✓","concedieran: 접속법 과거는 주절이 과거일 때 씁니다 ✗"]},{"id":"G617","q":"Hacía ____ frío que nos quedamos en casa.","o":["tan","tantos","tanto","tanta"],"a":2,"k":"tanto+명사 que","t":"너무 추워서 우리는 집에 있었다.","e":"'tan/tanto ... que ~'는 '너무 ...해서 ~하다'라는 결과 표현입니다. 명사 앞에서는 tanto/tanta/tantos/tantas를 명사의 성·수에 맞춰 씁니다. 'hacer frío(춥다)'의 frío는 남성 단수 명사이므로 tanto가 맞습니다.","x":["tan: 형용사·부사 앞에 쓰고 명사 앞에는 쓰지 않습니다 ✗","tantos: 남성 복수 명사 앞에 쓰므로 ✗","tanto: 남성 단수 명사 frío 앞 → 정답 ✓","tanta: 여성 단수 명사 앞에 쓰므로 ✗"]},{"id":"G618","q":"¿Sabes ____ que le pasó a Carlos el otro día?","o":["el","lo","al","ø"],"a":1,"k":"lo que","t":"요전에 카를로스에게 무슨 일이 있었는지 아니?","e":"'lo que'는 '~한 것, ~한 일'이라는 뜻으로 막연한 일·내용을 가리킵니다. 'lo que le pasó a Carlos'는 '카를로스에게 일어난 일'이라는 뜻입니다. 이처럼 특정 명사가 없을 때는 중성 lo를 씁니다.","x":["el: 남성 명사를 가리키는데 여기선 '일, 내용' 전체를 가리키므로 ✗","lo: 막연한 일을 가리키는 lo que → 정답 ✓","al: a + el의 결합형이라 문장 구조와 맞지 않습니다 ✗","ø: 'Sabes que...'가 되면 '~라는 걸 아니?'라는 다른 문장이 되어 어색합니다 ✗"]},{"id":"G619","q":"Esa profesora trata muy bien ____ sus alumnos.","o":["ø","en","de","a"],"a":3,"k":"인칭 a","t":"그 선생님은 학생들을 아주 잘 대해 준다.","e":"직접목적어(~을/를)가 사람일 때는 앞에 전치사 a를 붙이는데, 이를 '인칭 a'라고 합니다. tratar(대하다)의 목적어 sus alumnos가 사람이므로 a를 넣습니다. 예: Veo a mi madre.(나는 엄마를 본다.)","x":["ø: 사람 목적어 앞에는 인칭 a가 필요합니다 ✗","en: '~안에'라는 장소 전치사라 ✗","de: 'tratar de'는 '~하려고 애쓰다, ~에 관한 것이다'라는 다른 뜻이라 ✗","a: 사람 직접목적어 앞의 인칭 a → 정답 ✓"]},{"id":"G620","q":"Me pidió que lo ____, pero ese día no podía faltar a mi trabajo.","o":["acompañaría","acompañase","acompañe","acompañaré"],"a":1,"k":"pedir que+접속법과거","t":"그는 나에게 같이 가 달라고 부탁했지만, 그날 나는 직장에 빠질 수 없었다.","e":"pedir que(~해 달라고 부탁하다)는 요청을 나타내므로 뒤에 접속법을 씁니다. 주절이 과거(pidió)이므로 접속법 과거를 써야 하고, acompañar의 접속법 과거는 acompañara 또는 acompañase입니다. -se 형태는 -ra 형태와 뜻이 같으며 스페인에서 더 자주 씁니다.","x":["acompañaría: 가능법(조건법)이라 요청 표현 뒤에 쓰지 않습니다 ✗","acompañase: 과거 주절에 맞는 접속법 과거 → 정답 ✓","acompañe: 접속법 현재는 주절이 현재일 때 씁니다 ✗","acompañaré: 직설법 미래라 ✗"]},{"id":"G621","q":"¿____ quieres tantas manzanas?","o":["Para que","A que","Para qué","De qué"],"a":2,"k":"para qué(목적 의문)","t":"그렇게 많은 사과를 뭐 하려고 원하니?","e":"'¿Para qué...?'는 '무엇을 위해서, 뭐 하려고?'라는 목적을 묻는 의문사입니다. 의문문에서 qué는 반드시 악센트를 붙입니다. 'para que'(악센트 없음)는 '~하도록'이라는 접속사로 뒤에 접속법이 옵니다.","x":["Para que: 악센트 없는 형태는 '~하도록'이라는 접속사라 의문문에 쓰지 않습니다 ✗","A que: '~라는 데 내기할래?' 같은 다른 표현이라 ✗","Para qué: 목적을 묻는 의문사 '뭐 하려고' → 정답 ✓","De qué: '무엇에 대해/무엇으로'라는 뜻이라 문맥에 맞지 않습니다 ✗"]},{"id":"G622","q":"____ una tarta de chocolate para Laura.","o":["Vamos a hacer","Vamos hacer","Estaremos haciendo","Habremos hecho"],"a":0,"k":"ir a+동사원형","t":"우리 라우라를 위해 초콜릿 케이크를 만들 거야.","e":"'ir a + 동사원형'은 '~할 것이다'라는 가까운 미래나 계획을 나타냅니다. 전치사 a를 빼먹으면 안 됩니다. 1인칭 복수이므로 'Vamos a hacer'가 맞습니다.","x":["Vamos a hacer: ir a + 동사원형, 계획된 미래 → 정답 ✓","Vamos hacer: 전치사 a가 빠져 문법적으로 틀립니다 ✗","Estaremos haciendo: 미래진행형(~하고 있을 것이다)이라 계획을 말하기에 어색합니다 ✗","Habremos hecho: 미래완료(~했을 것이다)라 문맥에 맞지 않습니다 ✗"]},{"id":"G623","q":"Antiguamente, había un olivo ____ esa casa.","o":["detrás de","tras de","de detrás","detrás"],"a":0,"k":"detrás de","t":"옛날에 그 집 뒤에 올리브나무가 한 그루 있었다.","e":"'detrás de + 명사'는 '~의 뒤에'라는 장소 표현입니다. 뒤에 명사(esa casa)가 오면 반드시 de를 붙입니다. detrás만 쓰면 '뒤에'라는 부사로, 뒤에 명사가 오지 않습니다. 예: El perro está detrás.(개는 뒤에 있다.)","x":["detrás de: 명사 앞에서 '~의 뒤에' → 정답 ✓","tras de: tras는 de 없이 'tras la casa'로 쓰는 것이 보통이라 ✗","de detrás: '뒤쪽의, 뒤에서'라는 뜻으로 명사 앞에 쓰지 않습니다 ✗","detrás: 명사 앞에서는 de가 필요합니다 ✗"]},{"id":"G624","q":"Os ____ las fechas del próximo examen en cuanto las sepa.","o":["diré","diría","decía","dije"],"a":0,"k":"en cuanto+미래","t":"다음 시험 날짜를 알게 되는 대로 너희에게 말해 줄게.","e":"'en cuanto(~하자마자)' 뒤에 미래의 일이 오면 접속법(sepa)을 쓰고, 주절에는 미래형을 씁니다. 그래서 decir의 미래형 diré가 맞습니다. 'Os las diré'에서 os는 '너희에게', las는 'las fechas(날짜들)'를 받는 대명사입니다.","x":["diré: 미래의 약속을 나타내는 직설법 미래 → 정답 ✓","diría: 가능법(조건법)이라 en cuanto + 접속법 현재와 어울리지 않습니다 ✗","decía: 불완료과거라 미래 약속에 맞지 않습니다 ✗","dije: 단순과거라 아직 일어나지 않은 일에 쓸 수 없습니다 ✗"]},{"id":"G625","q":"Estamos ____ interesados en el proyecto como ellos.","o":["tanto","tan","tantas","tantos"],"a":1,"k":"tan...como 동등비교","t":"우리도 그들만큼 그 프로젝트에 관심이 있다.","e":"'tan + 형용사/부사 + como'는 '~만큼 ...하다'라는 동등 비교입니다. interesados는 형용사(관심 있는)이므로 형용사 앞에 쓰는 tan이 맞습니다. 명사 앞이라면 tanto/a/os/as를 씁니다.","x":["tanto: 동사 뒤나 남성 단수 명사 앞에 쓰고, 형용사 앞에는 쓰지 않습니다 ✗","tan: 형용사 interesados 앞의 동등 비교 → 정답 ✓","tantas: 여성 복수 명사 앞에 쓰므로 ✗","tantos: 남성 복수 명사 앞에 쓰므로 ✗"]},{"id":"G626","q":"¿Es cierto que nos ____ a reducir el sueldo?","o":["van","vayan","vamos","fuesen"],"a":0,"k":"es cierto que","t":"우리 월급을 깎을 거라는 게 사실이야?","e":"'Es cierto que(~는 사실이다)'는 사실을 나타내는 표현이라 긍정문에서는 직설법을 씁니다. 의문문으로 사실 여부를 묻는 경우에도 직설법이 자연스럽습니다. 막연한 '그들(회사 측)'이 주어이므로 'van a reducir'가 맞습니다. 부정 'No es cierto que...'라면 접속법을 씁니다.","x":["van: 3인칭 복수 직설법, ir a + 동사원형 → 정답 ✓","vayan: 접속법은 'No es cierto que'처럼 부정일 때 씁니다 ✗","vamos: '우리가 깎을 것'이라는 뜻이 되어 'nos' 및 문맥과 맞지 않습니다 ✗","fuesen: 접속법 과거라 시제와 법 모두 맞지 않습니다 ✗"]},{"id":"G627","q":"María del Mar ____ cae bien a todo el mundo.","o":["les","los","la","le"],"a":3,"k":"caer bien 구문","t":"마리아 델 마르는 모든 사람에게 호감을 산다.","e":"'caer bien/mal a alguien'은 '~에게 좋은/나쁜 인상을 주다, 호감을 사다'라는 뜻으로 gustar처럼 간접목적격 대명사(~에게)를 씁니다. 'a todo el mundo(모든 사람)'는 문법적으로 3인칭 단수 취급하므로 le가 맞습니다.","x":["les: 3인칭 복수인데 todo el mundo는 단수 취급하므로 ✗","los: 직접목적격(그들을)이라 caer bien 구문에 쓰지 않습니다 ✗","la: 직접목적격(그녀를)이라 ✗","le: 3인칭 단수 간접목적격, todo el mundo에 맞음 → 정답 ✓"]},{"id":"G628","q":"¿____ idiomas habla usted?","o":["Cuantos","Cuantas","Cuántas","Cuántos"],"a":3,"k":"의문사 cuántos","t":"당신은 몇 개 언어를 하십니까?","e":"'¿Cuántos/Cuántas + 명사?'는 '몇 개의 ~?'라는 의문사로, 뒤 명사의 성·수에 맞춥니다. idioma는 -a로 끝나지만 남성 명사(el idioma)이므로 Cuántos를 씁니다. 의문사이므로 악센트(á)가 필요합니다.","x":["Cuantos: 의문문에서는 악센트가 있어야 합니다 ✗","Cuantas: 악센트도 없고 여성형이라 ✗","Cuántas: idiomas는 남성 명사이므로 여성형은 ✗","Cuántos: 남성 복수 명사 idiomas에 맞는 의문사 → 정답 ✓"]},{"id":"G629","q":"Exijo que me ____ una explicación sobre lo ocurrido.","o":["dan","den","darían","dieran"],"a":1,"k":"exigir que+접속법","t":"일어난 일에 대해 나에게 설명해 줄 것을 요구합니다.","e":"exigir que(~할 것을 요구하다)는 명령·요구를 나타내므로 뒤에 접속법을 씁니다. 주절이 현재(Exijo)이므로 dar의 접속법 현재 3인칭 복수 den이 맞습니다. 'lo ocurrido'는 '일어난 일'이라는 뜻입니다.","x":["dan: 직설법 현재라 요구 표현 뒤에 쓰지 않습니다 ✗","den: 현재 주절에 맞는 접속법 현재 → 정답 ✓","darían: 가능법(조건법)이라 ✗","dieran: 접속법 과거는 주절이 과거일 때 씁니다 ✗"]},{"id":"G630","q":"¿Cómo te ____ que fuera tu vida dentro de veinte años?","o":["gustara","gustará","gusta","gustaría"],"a":3,"k":"gustaría que","t":"20년 후 너의 삶이 어떻게 되면 좋겠니?","e":"'me gustaría(~하면 좋겠다)'는 gustar의 가능법(조건법)으로 소망을 부드럽게 나타냅니다. 뒤에 'que + 접속법 과거(fuera)'가 이어지는 것이 시제 일치에 맞습니다. 예: Me gustaría que vinieras.(네가 와 주면 좋겠어.)","x":["gustara: 접속법 과거라 주절 동사로 쓸 수 없습니다 ✗","gustará: 직설법 미래는 뒤의 fuera(접속법 과거)와 시제가 맞지 않습니다 ✗","gusta: 현재형이면 뒤에 접속법 현재(sea)가 와야 하므로 ✗","gustaría: 가능법 + que + 접속법 과거 → 정답 ✓"]},{"id":"G631","q":"¿Qué harías tú si ____ en mi lugar?","o":["estuvieras","estabas","estarías","estarás"],"a":0,"k":"si+접속법 과거","t":"네가 내 입장이라면 너는 어떻게 하겠니?","e":"현재 사실과 반대되거나 일어날 가능성이 낮은 가정은 'si + 접속법 과거, 가능법(조건법)' 구조를 씁니다. 주절이 harías(가능법)이므로 si절에는 estar의 접속법 과거 estuvieras가 와야 합니다. 'estar en mi lugar'는 '내 입장이 되다'라는 뜻입니다.","x":["estuvieras: 비현실 가정의 si절에 쓰는 접속법 과거 → 정답 ✓","estabas: 불완료과거는 비현실 가정의 si절에 쓰지 않습니다 ✗","estarías: si 바로 뒤에는 가능법을 쓰지 않습니다 ✗","estarás: 직설법 미래도 si 뒤에 쓰지 않습니다 ✗"]},{"id":"G632","q":"Para trabajar aquí puedes vestirte ____ quieras, no hay reglas.","o":["como","que","lo que","como que"],"a":0,"k":"como+접속법","t":"여기서 일하려면 네가 원하는 대로 옷을 입어도 돼, 규칙이 없어.","e":"'como + 접속법'은 '~하는 대로, ~하는 방식으로'라는 뜻으로, 아직 정해지지 않은 방식을 말할 때 씁니다. 'como quieras'는 '네가 원하는 대로'라는 아주 흔한 표현입니다. vestirse(옷을 입다)라는 방식을 설명하므로 como가 맞습니다.","x":["como: 방식(~하는 대로) → 정답 ✓","que: 방식을 나타내지 못하고 문장이 성립하지 않습니다 ✗","lo que: '~하는 것'이라 'vestirse lo que quieras'는 어색합니다 ✗","como que: '~인 것처럼, ~라는 듯이'라는 구어 표현이라 ✗"]},{"id":"G633","q":"En cuanto ____ listos, nos iremos.","o":["estaremos","estamos","hemos estado","estemos"],"a":3,"k":"en cuanto+접속법","t":"우리가 준비되는 대로 떠날 거야.","e":"'en cuanto(~하자마자)'가 미래의 일을 가리키면 뒤에 접속법을 씁니다. 주절이 미래형(nos iremos)이므로 '준비가 될 때'는 아직 일어나지 않은 일 → estar의 접속법 현재 estemos가 맞습니다. 'estar listo'는 '준비가 되다'라는 뜻입니다.","x":["estaremos: en cuanto 뒤에는 미래형을 쓰지 않습니다 ✗","estamos: 직설법 현재는 습관적인 일에 쓰므로 여기선 ✗","hemos estado: 현재완료라 미래 시점에 맞지 않습니다 ✗","estemos: 미래 시점의 접속법 현재 → 정답 ✓"]},{"id":"G634","q":"____ estaba cansadísima, se echó una siesta.","o":["Por","Por eso","Aunque","Como"],"a":3,"k":"como(이유)","t":"그녀는 너무 피곤해서 낮잠을 잤다.","e":"문장 맨 앞에서 'Como + 직설법'은 '~이니까, ~해서'라는 이유를 나타냅니다. 이유절이 앞에 오므로 Como가 자연스럽습니다. 'echarse una siesta'는 '낮잠을 자다'라는 뜻이고, cansadísima는 cansada의 최상급(아주 피곤한)입니다.","x":["Por: 전치사라 뒤에 활용된 동사(estaba)가 올 수 없습니다 ✗","Por eso: '그래서'라는 결과 표현이라 의미 순서가 반대가 됩니다 ✗","Aunque: '~에도 불구하고'라는 양보라 피곤해서 낮잠을 잤다는 뜻과 맞지 않습니다 ✗","Como: 문두에서 이유(~해서) → 정답 ✓"]},{"id":"G635","q":"Nuestra vecina nos regañó ____ hacer demasiado ruido.","o":["ya que","debido a que","por","porque"],"a":2,"k":"por+동사원형(이유)","t":"이웃집 여자가 우리가 너무 시끄럽게 한다고 꾸짖었다.","e":"'por + 동사원형'은 '~해서, ~한 이유로'라는 원인을 나타냅니다. 뒤에 동사원형 hacer가 오므로 전치사 por가 맞습니다. ya que, debido a que, porque는 접속사라 뒤에 활용된 동사(hacíamos 등)가 와야 합니다.","x":["ya que: 접속사라 뒤에 활용된 동사가 필요합니다 ✗","debido a que: 접속사구라 동사원형과 쓰지 않습니다 ✗","por: 전치사 + 동사원형으로 이유 표현 → 정답 ✓","porque: 접속사라 'porque hacíamos'처럼 써야 합니다 ✗"]},{"id":"G636","q":"¿Por qué ____ así?","o":["te comportes","comportas","te comportas","comportes"],"a":2,"k":"comportarse","t":"너는 왜 그렇게 행동하니?","e":"comportarse(행동하다, 처신하다)는 재귀대명사(me, te, se 등)와 함께 쓰는 재귀동사입니다. 주어가 tú이므로 te comportas가 됩니다. por qué 의문문에는 직설법을 씁니다.","x":["te comportes: 접속법이라 일반 의문문에 쓰지 않습니다 ✗","comportas: 재귀대명사 te가 빠졌습니다 ✗","te comportas: 재귀대명사 + 직설법 현재 2인칭 단수 → 정답 ✓","comportes: 재귀대명사도 없고 접속법이라 ✗"]},{"id":"G637","q":"Si eres menor ____ 18 años, no puedes entrar ahí.","o":["de","a","en","que"],"a":0,"k":"menor de+숫자","t":"18세 미만이면 거기에 들어갈 수 없어.","e":"'menor de + 나이/숫자'는 '~세 미만'이라는 뜻입니다. 비교급(más, menos, mayor, menor) 뒤에 숫자가 올 때는 que 대신 de를 씁니다. 예: Tiene más de 30 años.(그는 서른 살이 넘었다.)","x":["de: 숫자 앞 비교 menor de → 정답 ✓","a: menor와 함께 쓰지 않는 전치사입니다 ✗","en: 장소·시간의 전치사라 ✗","que: 숫자 앞에서는 que 대신 de를 씁니다 ✗"]},{"id":"G638","q":"Cuando ____ que hablemos, dímelo.","o":["quieras","querrás","quieres","querías"],"a":0,"k":"cuando+접속법","t":"우리가 얘기했으면 할 때 나에게 말해 줘.","e":"cuando 뒤에 아직 일어나지 않은 미래의 일이 오면 접속법을 씁니다. 주절이 명령형(dímelo)이므로 '네가 원할 때'는 미래 시점 → querer의 접속법 현재 quieras가 맞습니다.","x":["quieras: 미래 시점을 나타내는 접속법 현재 → 정답 ✓","querrás: cuando 뒤에 미래형을 쓰지 않습니다 ✗","quieres: 직설법 현재는 습관(원할 때마다)에 쓰므로 명령문과 어울리지 않습니다 ✗","querías: 불완료과거라 시제가 맞지 않습니다 ✗"]},{"id":"G639","q":"Cecilia tiene dos hermanos. Yo tengo ____ más, o sea, tengo tres.","o":["lo","uno","un","el"],"a":1,"k":"대명사 uno","t":"세실리아는 형제가 둘이다. 나는 하나 더 있다, 그러니까 셋이다.","e":"이미 나온 명사(hermano)를 받아 '하나'라고 할 때는 명사 없이 쓰는 대명사 uno를 씁니다. un은 뒤에 남성 명사가 직접 올 때만 씁니다(un hermano). 'o sea'는 '즉, 그러니까'라는 뜻입니다.","x":["lo: 직접목적격 대명사(그것을)라 수를 나타낼 수 없습니다 ✗","uno: 명사를 생략하고 '하나'를 나타내는 대명사 → 정답 ✓","un: 뒤에 명사가 와야 하는 형태라 ✗","el: 정관사 + más는 최상급처럼 되어 의미가 통하지 않습니다 ✗"]},{"id":"G640","q":"Por esa puerta no ____ entrar al edificio.","o":["se poder","se puede","se pueden","se puedes"],"a":1,"k":"무인칭 se","t":"저 문으로는 건물에 들어갈 수 없다.","e":"'se + 3인칭 단수 동사'는 '(일반적으로) ~할 수 있다/없다'처럼 주어를 특정하지 않는 무인칭 표현입니다. 뒤에 동사원형(entrar)이 오므로 poder는 3인칭 단수 se puede가 됩니다. 예: Aquí no se puede fumar.(여기서는 담배를 피울 수 없다.)","x":["se poder: 동사원형이라 활용되지 않아 ✗","se puede: 무인칭 se + 3인칭 단수 → 정답 ✓","se pueden: 뒤에 복수 명사가 올 때 쓰는데, 동사원형 앞이라 ✗","se puedes: 2인칭 형태는 se와 함께 쓸 수 없습니다 ✗"]},{"id":"G641","q":"Cuando ____ con mi familia, compartía el dormitorio con mi hermano.","o":["viviera","viviría","vivía","viva"],"a":2,"k":"불완료과거(습관·배경)","t":"가족과 함께 살 때 나는 형과 방을 같이 썼다.","e":"과거에 일정 기간 계속되던 상황이나 배경은 불완료과거로 나타냅니다. 'Cuando vivía con mi familia'는 '가족과 살던 시절'이라는 과거의 배경이므로 vivía가 맞습니다. 이미 일어난 과거 사실이라 접속법은 쓰지 않습니다.","x":["viviera: 접속법 과거는 가정이나 미확정 일에 쓰므로 ✗","viviría: 가능법(조건법)이라 과거 배경 묘사에 맞지 않습니다 ✗","vivía: 과거의 지속된 상황을 나타내는 불완료과거 → 정답 ✓","viva: 접속법 현재는 미래 시점의 cuando에 씁니다 ✗"]},{"id":"G642","q":"No es verdad que Juana y Alberto ____ divorciados.","o":["estén","están","estando","estarían"],"a":0,"k":"no es verdad","t":"후아나와 알베르토가 이혼했다는 건 사실이 아니다.","e":"'No es verdad que(~는 사실이 아니다)'처럼 사실을 부정하는 표현 뒤에는 접속법을 씁니다. 주어가 Juana y Alberto(3인칭 복수)이므로 estar의 접속법 현재 estén이 맞습니다. 긍정 'Es verdad que están...'이면 직설법을 씁니다.","x":["estén: 사실 부정 뒤의 접속법 현재 → 정답 ✓","están: 직설법은 'Es verdad que'(긍정)일 때 씁니다 ✗","estando: 현재분사라 que절의 동사로 쓸 수 없습니다 ✗","estarían: 가능법(조건법)이라 ✗"]},{"id":"G643","q":"Yo llegué ____ dos horas. ¿Y tú?","o":["desde hace","antes","de hace","hace"],"a":3,"k":"hace+기간(~전)","t":"나는 두 시간 전에 도착했어. 너는?","e":"'hace + 기간'을 단순과거와 함께 쓰면 '~ 전에'라는 뜻입니다. 'llegué hace dos horas'는 '두 시간 전에 도착했다'입니다. 'desde hace'는 '~ 전부터 (지금까지 계속)'라는 뜻으로 현재형과 함께 씁니다.","x":["desde hace: 지속(~전부터)을 나타내므로 한 번 도착한 일과 맞지 않습니다 ✗","antes: 'dos horas antes'처럼 기간 뒤에 와야 하고 '그보다 전에'라는 뜻이라 ✗","de hace: 'el periódico de hace dos días(이틀 전 신문)'처럼 명사를 수식할 때 씁니다 ✗","hace: hace + 기간 = ~ 전에 → 정답 ✓"]},{"id":"G644","q":"Rocío no es nada tímida. Habla con ____.","o":["cualquiera","un cualquiera","cualquier","uno cualquiera"],"a":0,"k":"cualquiera","t":"로시오는 전혀 수줍어하지 않는다. 아무하고나 이야기한다.","e":"cualquiera는 명사 없이 단독으로 쓰면 '누구든지, 아무나'라는 대명사가 됩니다. 명사 앞에서는 cualquier로 줄어듭니다(cualquier persona). 전치사 con 뒤에 명사가 없으므로 cualquiera가 맞습니다.","x":["cualquiera: 단독으로 '아무나'라는 대명사 → 정답 ✓","un cualquiera: '하찮은 사람, 별 볼일 없는 사람'이라는 경멸적인 뜻이라 ✗","cualquier: 뒤에 명사가 올 때만 쓰는 형태라 ✗","uno cualquiera: '아무거나 하나'라는 뜻으로 이미 나온 명사를 받을 때 쓰므로 ✗"]},{"id":"G645","q":"A Elvira todavía no ____ han dado su nuevo horario de trabajo.","o":["le","ø","lo","la"],"a":0,"k":"간접목적어 중복 le","t":"엘비라에게는 아직 새 근무 시간표를 주지 않았다.","e":"dar(주다)는 '누구에게'를 간접목적격 대명사로 받습니다. 'A Elvira'처럼 간접목적어가 동사 앞에 나오면 같은 대상을 가리키는 대명사 le를 반드시 함께 씁니다. 그래서 'A Elvira ... le han dado'가 됩니다.","x":["le: 3인칭 단수 간접목적격(그녀에게) → 정답 ✓","ø: 간접목적어가 앞에 나오면 대명사 중복이 필수입니다 ✗","lo: 직접목적격 남성(그것을/그를)이라 ✗","la: 직접목적격 여성(그녀를)이라 '~에게'를 나타내지 못합니다 ✗"]},{"id":"G646","q":"No sé dónde se ha metido Juan. A lo mejor ____ en un atasco.","o":["esté","estar","estando","está"],"a":3,"k":"a lo mejor+직설법","t":"후안이 어디 있는지 모르겠어. 아마 교통 체증에 걸렸나 봐.","e":"'a lo mejor(아마도)'는 추측을 나타내지만 뒤에 항상 직설법을 씁니다. 그래서 estar의 직설법 현재 está가 맞습니다. 반면 quizás, tal vez는 직설법과 접속법 모두 쓸 수 있습니다.","x":["esté: a lo mejor 뒤에는 접속법을 쓰지 않습니다 ✗","estar: 동사원형이라 주어가 있는 문장의 동사로 쓸 수 없습니다 ✗","estando: 현재분사라 ✗","está: a lo mejor + 직설법 → 정답 ✓"]},{"id":"G647","q":"____ que la semana que viene la escuela estará cerrada, necesito que alguien cuide a mi hijo.","o":["Es","Desde","Dado","Así"],"a":2,"k":"dado que(이유)","t":"다음 주에 학교가 문을 닫으니, 누군가 내 아들을 돌봐 줬으면 해.","e":"'dado que'는 '~이므로, ~이니까'라는 이유 접속사로 뒤에 직설법이 옵니다. 문장 앞에서 이유를 먼저 제시할 때 자주 씁니다. 'necesitar que + 접속법(cuide)'도 함께 기억해 두세요.","x":["Es: 'Es que'는 '사실은 ~해서'라는 변명 표현으로 문장 중간을 이끌기 어려워 ✗","Desde: 'desde que'는 '~한 이후로'라는 시간 표현이라 ✗","Dado: dado que(~이므로) → 정답 ✓","Así: 'así que'는 '그래서'라는 결과 표현이라 앞에 올 수 없습니다 ✗"]},{"id":"G648","q":"Sólo tú sabes que estoy saliendo con Elena. ____ más lo sabe.","o":["Algunos","Alguno","Nadie","Alguien"],"a":2,"k":"부정어 nadie","t":"내가 엘레나와 사귀고 있다는 건 너만 알아. 다른 사람은 아무도 몰라.","e":"nadie는 '아무도 ~않다'라는 부정 대명사입니다. 동사 앞에 오면 no 없이 그 자체로 부정이 됩니다. '오직 너만 안다'는 앞 문장과 이어지므로 'Nadie más lo sabe(그 외엔 아무도 모른다)'가 맞습니다.","x":["Algunos: '몇몇 사람들'이라 '너만 안다'는 내용과 모순됩니다 ✗","Alguno: '어떤 이'라는 뜻으로 의미가 모순됩니다 ✗","Nadie: 아무도(~않다) → 정답 ✓","Alguien: '누군가'라는 긍정 표현이라 의미가 반대가 됩니다 ✗"]},{"id":"G649","q":"Anabel es la mujer ____ simpática que he conocido en mi vida.","o":["mucho más","tan","la más","más"],"a":3,"k":"최상급 정관사+명사+más","t":"아나벨은 내가 살면서 만난 여자 중 가장 다정한 사람이다.","e":"최상급은 '정관사 + 명사 + más + 형용사 (+ que/de ...)' 구조입니다. 이미 명사 앞에 정관사 la가 있으므로 형용사 앞에는 más만 씁니다. 관사를 두 번 쓰지 않도록 주의하세요. 예: el chico más alto de la clase(반에서 가장 키 큰 아이).","x":["mucho más: 비교급 강조(훨씬 더)라 최상급 의미가 되지 않습니다 ✗","tan: 동등 비교(그만큼)라 ✗","la más: 앞에 이미 la가 있어 관사가 중복됩니다 ✗","más: 정관사 la + 명사 + más → 정답 ✓"]},{"id":"G650","q":"Al final no compré ningún vestido porque, de los que vi, no me gustaba ____.","o":["ninguno","alguno","algún","ningún"],"a":0,"k":"부정어 ninguno","t":"결국 나는 아무 원피스도 사지 않았다. 내가 본 것들 중 마음에 드는 게 하나도 없었기 때문이다.","e":"ninguno는 '하나도 ~않다'라는 부정 대명사로, 명사 없이 단독으로 쓰면 ninguno 형태를 유지합니다. 명사 앞에서만 ningún으로 줄어듭니다(ningún vestido). 'no me gustaba ninguno'처럼 동사 뒤에 오면 앞에 no가 함께 쓰입니다.","x":["ninguno: 명사 없이 단독으로 쓰는 부정 대명사 → 정답 ✓","alguno: no와 함께 쓰는 부정 의미로는 ninguno가 자연스럽습니다 ✗","algún: 명사 앞에 쓰는 형태이고 긍정 의미라 ✗","ningún: 뒤에 명사가 올 때만 쓰는 형태라 ✗"]},{"id":"G651","q":"Este bolso es bastante más caro ____ ese.","o":["como","que","a","de"],"a":1,"k":"비교급 más...que","t":"이 가방은 그것보다 꽤 더 비싸다.","e":"우등 비교는 'más + 형용사 + que + 비교 대상'입니다. 'más caro que ese(그것보다 더 비싼)'가 맞습니다. bastante는 '꽤'라는 뜻으로 비교급을 강조합니다.","x":["como: 동등 비교(tan ... como)에 쓰므로 ✗","que: más ... que(~보다 더) → 정답 ✓","a: 'superior a'처럼 일부 형용사에만 쓰므로 ✗","de: 숫자 앞이나 최상급에 쓰고 일반 비교에는 쓰지 않습니다 ✗"]},{"id":"G652","q":"____ de esos hombres trabaja en la misma fábrica que yo.","o":["Un","Unos","Uno","Una"],"a":2,"k":"대명사 uno de","t":"그 남자들 중 한 명이 나와 같은 공장에서 일한다.","e":"'uno de + 복수 명사'는 '~ 중 하나/한 명'이라는 뜻입니다. 명사가 뒤에 바로 붙지 않으므로 un이 아닌 uno를 씁니다. hombres는 남성이므로 una가 아니라 uno이고, 동사도 3인칭 단수(trabaja)입니다.","x":["Un: 바로 뒤에 명사가 와야 하는 형태라 de 앞에는 ✗","Unos: 복수라 단수 동사 trabaja와 맞지 않습니다 ✗","Uno: uno de(~ 중 한 명), 남성 → 정답 ✓","Una: hombres는 남성이라 여성형은 ✗"]},{"id":"G653","q":"Dime ____ ha roto las ventanas.","o":["quién","quien","quienes","quiénes"],"a":0,"k":"간접의문문 quién","t":"누가 창문들을 깼는지 말해 줘.","e":"간접의문문(~인지)에서도 의문사는 악센트를 유지합니다. 동사 ha roto가 단수이므로 단수형 quién이 맞습니다. 'romper(깨다)'의 과거분사는 불규칙형 roto입니다.","x":["quién: 악센트 있는 단수 의문사, 단수 동사와 일치 → 정답 ✓","quien: 악센트 없는 형태는 관계대명사(~하는 사람)라 ✗","quienes: 악센트가 없고 복수형이라 ✗","quiénes: 복수형이라 단수 동사 ha roto와 맞지 않습니다 ✗"]},{"id":"G654","q":"¿Has leído el libro ____ te recomendé?","o":["el que","cual","que","quien"],"a":2,"k":"관계대명사 que","t":"내가 추천해 준 책 읽었니?","e":"전치사 없이 선행사(el libro)를 바로 받는 관계절에서는 가장 기본적인 관계대명사 que를 씁니다. 'el libro que te recomendé'는 '내가 너에게 추천한 책'입니다. 전치사가 없는 제한적 관계절에서 el que를 쓰는 것은 어색합니다.","x":["el que: 전치사가 없을 때는 관사를 넣지 않는 것이 보통입니다 ✗","cual: 관사 없이 단독으로 관계대명사로 쓸 수 없습니다 ✗","que: 기본 관계대명사 → 정답 ✓","quien: 사람을 가리키는 관계대명사라 책에는 ✗"]},{"id":"G655","q":"¿Cómo pudieron sobrevivir en condiciones ____ extremas?","o":["tan","tanta","tantas","tanto"],"a":0,"k":"tan+형용사","t":"그렇게 극한의 조건에서 그들이 어떻게 살아남을 수 있었을까?","e":"'tan + 형용사'는 '그렇게 ~한'이라는 강조 표현입니다. extremas는 형용사(극한의)이므로 tan을 씁니다. tanto/tanta/tantas는 명사 앞에 씁니다.","x":["tan: 형용사 extremas 앞에서 '그렇게' → 정답 ✓","tanta: 여성 단수 명사 앞에 쓰므로 ✗","tantas: 명사 앞에 쓰므로 형용사 앞에는 ✗","tanto: 동사를 꾸미거나 남성 명사 앞에 쓰므로 ✗"]},{"id":"G656","q":"____ martes son los días más aburridos para mí.","o":["El","Los","Unos","ø"],"a":1,"k":"요일 앞 정관사 los","t":"화요일은 나에게 가장 지루한 날이다.","e":"요일을 '매주 ~요일마다'처럼 일반적으로 말할 때는 정관사 복수 los를 씁니다. martes는 단수·복수 형태가 같지만, 동사 son과 'los días'가 복수이므로 Los martes가 맞습니다. 예: Los lunes voy al gimnasio.(월요일마다 헬스장에 간다.)","x":["El: 단수라 특정한 한 화요일을 가리키고 동사 son과도 맞지 않습니다 ✗","Los: 반복되는 요일 일반을 나타내는 복수 정관사 → 정답 ✓","Unos: '몇몇 화요일'이라는 뜻이라 어색합니다 ✗","ø: 주어 자리의 요일에는 관사가 필요합니다 ✗"]},{"id":"G657","q":"____ día seré famosa. ¡Estoy segura!","o":["El","La","Un","Una"],"a":2,"k":"un día(언젠가)","t":"언젠가 나는 유명해질 거야. 확신해!","e":"'un día'는 '언젠가, 어느 날'이라는 표현으로 정해지지 않은 시점을 나타냅니다. día는 -a로 끝나지만 남성 명사(el día)이므로 un을 씁니다. 'algún día(언젠가)'도 같은 뜻으로 자주 씁니다.","x":["El: 특정한 그날을 가리키므로 '언젠가'라는 뜻이 되지 않습니다 ✗","La: día는 남성 명사라 ✗","Un: 불특정한 어느 날(언젠가) → 정답 ✓","Una: día는 남성 명사라 여성형은 ✗"]},{"id":"G658","q":"Llevamos ____ tres semanas trabajando en esta fábrica.","o":["por","ø","de","desde"],"a":1,"k":"llevar+기간+현재분사","t":"우리는 이 공장에서 일한 지 3주 되었다.","e":"'llevar + 기간 + 현재분사'는 '~한 지 (기간)이 되다, ~동안 계속 ~하고 있다'라는 뜻입니다. 기간 앞에 전치사를 넣지 않습니다. 예: Llevo dos años estudiando español.(나는 스페인어를 2년째 공부하고 있다.)","x":["por: llevar 구문에서 기간 앞에 por를 쓰지 않습니다 ✗","ø: llevar + 기간(전치사 없음) + 현재분사 → 정답 ✓","de: 기간 앞에 de를 넣지 않습니다 ✗","desde: 'desde + 시작 시점'이라 기간(tres semanas) 앞에는 ✗"]},{"id":"G659","q":"Suelo ir a la biblioteca de mi facultad ____ estudiar.","o":["sobre","para","por","de"],"a":1,"k":"para(목적)","t":"나는 공부하러 우리 학부 도서관에 자주 간다.","e":"'para + 동사원형'은 '~하기 위해, ~하러'라는 목적을 나타냅니다. 도서관에 가는 목적이 공부이므로 para가 맞습니다. 'soler + 동사원형'은 '~하곤 하다, 자주 ~하다'라는 뜻입니다.","x":["sobre: '~에 관해'라는 뜻이라 ✗","para: 목적(~하러) → 정답 ✓","por: 이유·원인을 나타내므로 목적에는 ✗","de: 목적을 나타내지 않습니다 ✗"]},{"id":"G660","q":"No necesito un diccionario de francés, ya tengo ____.","o":["lo","uno","el","un"],"a":1,"k":"대명사 uno","t":"프랑스어 사전은 필요 없어, 이미 하나 있어.","e":"앞에 나온 명사(un diccionario)를 받아 '하나'를 가리킬 때는 대명사 uno를 씁니다. 명사가 생략되었으므로 un이 아니라 uno가 됩니다. 특정한 그 사전이 아니라 '사전 하나'이므로 lo도 맞지 않습니다.","x":["lo: 특정한 그것을 가리키는 직접목적격이라 '하나'라는 뜻이 아닙니다 ✗","uno: 명사를 생략한 '하나' → 정답 ✓","el: 정관사만으로는 명사를 대신할 수 없습니다 ✗","un: 뒤에 명사가 와야 하는 형태라 ✗"]},{"id":"G661","q":"Aquel día, salí ____ mi apartamento a eso de las once y media.","o":["en","a","por","de"],"a":3,"k":"salir de","t":"그날 나는 11시 반쯤에 내 아파트에서 나왔다.","e":"'salir de + 장소'는 '~에서 나오다/나가다'라는 뜻으로, 출발점을 나타내는 전치사 de를 씁니다. 'a eso de + 시각'은 '~시쯤에'라는 유용한 표현입니다. 예: Salgo de casa a las ocho.(나는 8시에 집을 나선다.)","x":["en: '~안에서'라는 위치라 출발점을 나타내지 못합니다 ✗","a: 'salir a la calle(거리로 나가다)'처럼 목적지를 나타내므로 ✗","por: '~을 통해서'라는 경로라 'salir por la ventana(창문으로 나가다)'에 쓰므로 ✗","de: 출발점(~에서) → 정답 ✓"]},{"id":"G662","q":"En su caso, una operación quirúrgica es ____ única opción para que mejore.","o":["un","una","la","ø"],"a":2,"k":"정관사 la(유일)","t":"그의 경우에는 수술이 그가 나아질 수 있는 유일한 방법이다.","e":"'única(유일한)'처럼 단 하나뿐인 것을 나타내는 명사구 앞에는 정관사를 씁니다. opción은 여성 명사이므로 'la única opción'이 맞습니다. 'para que + 접속법(mejore)'은 '~하도록'이라는 목적 표현입니다.","x":["un: 남성 부정관사이고, opción은 여성이라 ✗","una: '유일한'이라는 뜻과 '여럿 중 하나'인 부정관사가 어울리지 않습니다 ✗","la: 유일한 대상을 나타내는 여성 정관사 → 정답 ✓","ø: 주어 보어 자리의 única opción에는 관사가 필요합니다 ✗"]},{"id":"G663","q":"Alfonso siempre es ____ en llegar a la oficina.","o":["primer","el primer","lo primero","el primero"],"a":3,"k":"el primero en","t":"알폰소는 항상 사무실에 제일 먼저 도착한다.","e":"'ser el primero/la primera en + 동사원형'은 '~하는 첫 번째 사람이다, 제일 먼저 ~하다'라는 표현입니다. 명사 없이 쓰므로 primer로 줄이지 않고 el primero를 씁니다. 예: Ella fue la primera en hablar.(그녀가 제일 먼저 말했다.)","x":["primer: 뒤에 남성 명사가 올 때만 쓰는 줄임 형태라 ✗","el primer: 역시 뒤에 명사가 필요합니다(el primer día) ✗","lo primero: '첫 번째 일/것'이라는 중성 표현이라 사람에게 ✗","el primero: 명사 없이 '첫 번째 사람' → 정답 ✓"]},{"id":"G664","q":"No tengo ____ paciencia como vos.","o":["tanto","tanta","tan","tantos"],"a":1,"k":"tanto+명사+como","t":"나는 너만큼 인내심이 많지 않아.","e":"명사의 동등 비교는 'tanto/tanta/tantos/tantas + 명사 + como'이며, 명사의 성·수에 맞춥니다. paciencia는 여성 단수이므로 tanta가 맞습니다. vos는 아르헨티나·우루과이 등 중남미 일부에서 tú 대신 쓰는 2인칭 대명사로, 'como vos'는 '너처럼'이라는 뜻입니다.","x":["tanto: 남성 단수 명사 앞에 쓰므로 ✗","tanta: 여성 단수 명사 paciencia 앞 → 정답 ✓","tan: 형용사·부사 앞에 쓰므로 명사 앞에는 ✗","tantos: 남성 복수 명사 앞에 쓰므로 ✗"]},{"id":"G665","q":"No creo que sea ____ comer tan rápido.","o":["buena","bueno","bien","buen"],"a":1,"k":"ser bueno+동사원형","t":"그렇게 빨리 먹는 게 좋다고 생각하지 않아.","e":"'ser bueno + 동사원형'은 '~하는 것은 좋다'라는 뜻입니다. 주어가 동사원형(comer)이면 남성 단수 취급하므로 형용사도 bueno가 됩니다. bien은 부사라서 ser 뒤 보어로 쓰지 않고, buen은 명사 앞에서만 씁니다. 'No creo que + 접속법(sea)'도 함께 기억하세요.","x":["buena: 여성형인데 동사원형 주어는 남성 단수 취급이라 ✗","bueno: 동사원형 주어에 맞는 남성 단수 형용사 → 정답 ✓","bien: 부사라 ser의 보어로 쓰지 않습니다 ✗","buen: 명사 앞에서만 쓰는 줄임 형태라 ✗"]},{"id":"G666","q":"Tres más tres es igual ____ seis.","o":["con","a","de","por"],"a":1,"k":"igual a","t":"3 더하기 3은 6이다.","e":"'ser igual a ~'는 '~와 같다'라는 뜻으로 전치사 a를 씁니다. 수학 계산에서 '=(이퀄)'을 말할 때 자주 쓰는 표현입니다. 예: Dos por dos es igual a cuatro.(2 곱하기 2는 4다.)","x":["con: igual과 함께 쓰는 전치사가 아닙니다 ✗","a: igual a(~와 같다) → 정답 ✓","de: 'igual de + 형용사'는 '똑같이 ~한'이라는 다른 뜻이라 ✗","por: 곱셈(por)을 나타내는 말이라 ✗"]},{"id":"G667","q":"He hecho mal la tarea, ____ rehacerla.","o":["voy","hay","tengo que","tengo"],"a":2,"k":"tener que+동사원형","t":"숙제를 잘못했어, 다시 해야 해.","e":"'tener que + 동사원형'은 '~해야 한다'라는 의무를 나타냅니다. 주어가 나(yo)이므로 tengo que가 맞습니다. 'hay que'도 '~해야 한다'이지만 주어 없이 일반적인 의무를 말할 때 쓰고, que가 꼭 필요합니다.","x":["voy: 'voy a rehacerla'처럼 a가 필요해 이대로는 ✗","hay: 'hay que'처럼 que가 빠져 틀립니다 ✗","tengo que: 의무(~해야 한다) → 정답 ✓","tengo: que가 빠져 의무 표현이 되지 않습니다 ✗"]},{"id":"G668","q":"Alfonso, ____ la tarea de la escuela ahora y luego podrás jugar.","o":["haced","hagas","haces","haz"],"a":3,"k":"tú 긍정명령 haz","t":"알폰소, 지금 학교 숙제를 하렴. 그러면 나중에 놀 수 있어.","e":"tú에게 하는 긍정 명령은 대부분 직설법 현재 3인칭 단수 형태와 같지만, hacer는 불규칙으로 haz가 됩니다. 한 사람(Alfonso)에게 말하므로 tú 명령형 haz가 맞습니다. 다른 불규칙: ven(오다), pon(놓다), sal(나가다), di(말하다).","x":["haced: vosotros(너희들)에게 하는 명령형이라 ✗","hagas: 접속법 현재로 부정 명령(No hagas...)에 씁니다 ✗","haces: 직설법 현재(너는 한다)라 명령이 아닙니다 ✗","haz: hacer의 tú 긍정 명령형 → 정답 ✓"]},{"id":"G669","q":"Sin duda Miguel es ____ mejor jugador de su equipo.","o":["lo","ø","el","un"],"a":2,"k":"최상급 el mejor","t":"틀림없이 미겔은 자기 팀에서 최고의 선수다.","e":"최상급 '가장 좋은/최고의'는 '정관사 + mejor + 명사 + de ...' 구조입니다. jugador는 남성 단수이므로 'el mejor jugador de su equipo'가 됩니다. 관사가 없으면 '더 좋은'이라는 비교급 의미가 됩니다.","x":["lo: 중성 관사라 'lo mejor(가장 좋은 점)'처럼 명사 없이 씁니다 ✗","ø: 관사가 없으면 최상급이 되지 않습니다 ✗","el: 남성 단수 최상급 el mejor → 정답 ✓","un: '최고의 선수 중 하나'처럼 들려 'su equipo'의 최상급과 어색합니다 ✗"]},{"id":"G670","q":"____ Sra. Campos no se encuentra en casa en este momento.","o":["ø","La","Una","Las"],"a":1,"k":"호칭 앞 정관사","t":"캄포스 부인은 지금 집에 계시지 않습니다.","e":"señor, señora, doctor 같은 호칭을 넣어 그 사람에 대해 말할 때는 정관사를 씁니다. Sra.(señora)는 여성 단수이므로 La가 맞습니다. 다만 그 사람에게 직접 말을 걸 때는 관사를 쓰지 않습니다. 예: Buenos días, señora Campos.","x":["ø: 3인칭으로 그 사람을 이야기할 때는 관사가 필요합니다 ✗","La: 호칭 앞 여성 단수 정관사 → 정답 ✓","Una: '어떤 캄포스 부인'이 되어 어색합니다 ✗","Las: 복수형이라 한 사람에게 맞지 않습니다 ✗"]},{"id":"G671","q":"____ lunes tendré clases de inglés por las tardes.","o":["A partir del","A partir","Del","Desde"],"a":0,"k":"a partir de","t":"월요일부터 나는 오후에 영어 수업이 있을 거야.","e":"'a partir de + 시점'은 '~부터 (앞으로)'라는 뜻으로, 미래에 무언가가 시작되는 시점을 말할 때 씁니다. de + el = del이므로 'A partir del lunes'가 맞습니다. desde는 주로 과거부터 지금까지 이어지는 시작점에 씁니다.","x":["A partir del: a partir de + el lunes(월요일부터) → 정답 ✓","A partir: de가 빠져 틀립니다 ✗","Del: '월요일의'라는 뜻이 되어 문장이 성립하지 않습니다 ✗","Desde: 관사도 없고, 미래 계획 시작에는 a partir de가 자연스럽습니다 ✗"]},{"id":"G672","q":"____ dos semanas sin tomar bebidas con cafeína y me siento mejor.","o":["Estaba","He estado","Estaría","Estaré"],"a":1,"k":"현재완료(현재까지)","t":"나는 2주 동안 카페인 음료를 마시지 않았는데 기분이 더 좋다.","e":"과거부터 지금까지 이어진 기간의 경험을 말하고 그 결과가 현재(me siento mejor)에 영향을 줄 때는 현재완료(haber + 과거분사)를 씁니다. 'He estado dos semanas sin + 동사원형'은 '2주 동안 ~하지 않고 지냈다'라는 뜻입니다.","x":["Estaba: 불완료과거라 현재와 연결되지 않고 과거 배경이 됩니다 ✗","He estado: 현재까지 이어진 기간, 현재완료 → 정답 ✓","Estaría: 가능법(조건법)이라 실제 경험을 말할 수 없습니다 ✗","Estaré: 미래형이라 이미 기분이 좋아진 현재와 맞지 않습니다 ✗"]},{"id":"G673","q":"El Popocatépetl ____ un volcán activo.","o":["es","sea","hay","está"],"a":0,"k":"ser(본질·정체)","t":"포포카테페틀은 활화산이다.","e":"'A는 B이다'처럼 주어가 무엇인지(정체·분류)를 말할 때는 ser를 씁니다. 뒤에 명사(un volcán activo)가 오므로 ser의 3인칭 단수 es가 맞습니다. estar 뒤에는 명사를 보어로 쓰지 않습니다. 포포카테페틀은 멕시코에 있는 유명한 화산입니다.","x":["es: 정체를 나타내는 ser → 정답 ✓","sea: 접속법이라 단순 사실 진술에 쓰지 않습니다 ✗","hay: '~이 있다'라는 존재 표현이라 주어와 함께 쓸 수 없습니다 ✗","está: estar는 위치·상태를 나타내며 명사 보어와 쓰지 않습니다 ✗"]},{"id":"G674","q":"¿A qué hora habéis quedado con ____ amigos?","o":["vuestros","vos","vosotros","vuestro"],"a":0,"k":"소유형용사 vuestros","t":"너희는 몇 시에 너희 친구들과 만나기로 했니?","e":"주어가 vosotros(너희, 동사 habéis)이므로 소유형용사는 vuestro/a/os/as를 씁니다. amigos가 남성 복수이므로 vuestros가 맞습니다. 'quedar con alguien'은 '누구와 만나기로 하다'라는 뜻입니다. 중남미에서는 vosotros 대신 ustedes를 써서 'sus amigos'라고 합니다.","x":["vuestros: 남성 복수 명사 amigos에 맞는 소유형용사 → 정답 ✓","vos: 중남미 일부의 2인칭 단수 대명사라 명사 앞에 쓰지 않습니다 ✗","vosotros: 주격 대명사라 명사 앞 소유 표현이 되지 않습니다 ✗","vuestro: 단수형이라 복수 명사 amigos와 맞지 않습니다 ✗"]},{"id":"G675","q":"No he visto a Lucía ____ verano pasado.","o":["desde el","del","de","desde"],"a":0,"k":"desde(시작점)","t":"나는 지난 여름 이후로 루시아를 보지 못했다.","e":"'desde + 시점'은 '~부터, ~이후로'라는 뜻으로 어떤 일의 시작점을 나타냅니다. 'el verano pasado(지난 여름)'은 정관사가 필요한 명사구이므로 'desde el verano pasado'가 됩니다.","x":["desde el: 시작점 desde + 정관사 el → 정답 ✓","del: '지난 여름의'라는 소유·소속 의미라 ✗","de: 'de ... a ...' 구조 없이 단독으로 시작점을 나타내지 못합니다 ✗","desde: 이 명사구에는 정관사 el이 필요합니다 ✗"]},{"id":"G676","q":"El frijol es ____ ingrediente estrella de este platillo.","o":["una","la","ø","el"],"a":3,"k":"정관사 el(특정)","t":"강낭콩이 이 요리의 핵심 재료이다.","e":"'ingrediente estrella(대표 재료, 핵심 재료)'처럼 특정하고 유일한 것을 가리킬 때는 정관사를 씁니다. ingrediente는 남성 명사이므로 el이 맞습니다. frijol(강낭콩)과 platillo(요리)는 멕시코 등 중남미에서 많이 쓰는 단어로, 스페인에서는 judía, plato라고 합니다.","x":["una: ingrediente는 남성 명사라 ✗","la: ingrediente는 남성 명사라 ✗","ø: 주어 보어 자리 명사에는 관사가 필요합니다 ✗","el: 특정한 핵심 재료, 남성 정관사 → 정답 ✓"]},{"id":"G677","q":"____ sabe hacer algo así.","o":["Uno cualquiera","Un cualquier","Cualquiera","Cualquier"],"a":2,"k":"cualquiera","t":"그런 건 누구라도 할 줄 안다.","e":"cualquiera는 명사 없이 단독으로 쓰면 '누구든지, 아무나'라는 대명사입니다. 여기서는 주어로 쓰였으므로 cualquiera가 맞습니다. 명사 앞에서는 cualquier로 줄어듭니다(cualquier persona).","x":["Uno cualquiera: '아무거나 하나'라는 뜻으로 이미 나온 명사를 받을 때 씁니다 ✗","Un cualquier: 존재하지 않는 형태입니다 ✗","Cualquiera: 단독 대명사 '누구든지' → 정답 ✓","Cualquier: 뒤에 명사가 필요합니다 ✗"]},{"id":"G678","q":"A Carlos no ____ importa cocinar, es más, le encanta.","o":["se","le","ø","lo"],"a":1,"k":"importar 구문","t":"카를로스는 요리하는 게 싫지 않다. 아니, 오히려 아주 좋아한다.","e":"importar(신경 쓰이다)는 gustar처럼 '누구에게'를 간접목적격 대명사로 씁니다. 'A Carlos'는 3인칭 단수이므로 le가 맞습니다. 'no importar + 동사원형'은 '~하는 게 싫지 않다, 괜찮다'라는 뜻이고 'es más'는 '게다가, 오히려'입니다.","x":["se: 재귀 대명사라 이 구문에 쓰지 않습니다 ✗","le: 3인칭 단수 간접목적격(그에게) → 정답 ✓","ø: 'A Carlos'가 있으면 대명사 le가 반드시 필요합니다 ✗","lo: 직접목적격(그를)이라 ✗"]},{"id":"G679","q":"Mi bolígrafo no tiene tinta. ¿Me dejas ____?","o":["tuyo","la tuya","el tuyo","lo tuyo"],"a":2,"k":"소유대명사 el tuyo","t":"내 볼펜에 잉크가 없어. 네 것 좀 빌려줄래?","e":"소유대명사(~의 것)는 '정관사 + tuyo/tuya/tuyos/tuyas'로, 가리키는 명사의 성·수에 맞춥니다. bolígrafo(볼펜)는 남성 단수이므로 el tuyo가 맞습니다. 'dejar'는 여기서 '빌려주다'라는 뜻입니다.","x":["tuyo: 관사 없이 '네 것'이라는 대명사로 목적어 자리에 쓸 수 없습니다 ✗","la tuya: 여성형이라 bolígrafo와 맞지 않습니다 ✗","el tuyo: 남성 단수 소유대명사 → 정답 ✓","lo tuyo: '너의 일, 너에게 해당하는 것'이라는 추상적 의미라 ✗"]},{"id":"G680","q":"____ una buena posición social es el objetivo de muchas personas.","o":["Teniendo","Tener","Tienen","Al tener"],"a":1,"k":"동사원형 주어","t":"좋은 사회적 지위를 갖는 것은 많은 사람들의 목표이다.","e":"스페인어에서 '~하는 것'이라는 명사 역할을 할 때는 동사원형을 씁니다. 여기서는 'Tener una buena posición social(좋은 사회적 지위를 갖는 것)'이 문장의 주어입니다. 영어처럼 -ing(현재분사)를 주어로 쓰지 않는다는 점에 주의하세요.","x":["Teniendo: 현재분사는 주어로 쓸 수 없습니다 ✗","Tener: 동사원형이 명사처럼 주어 역할 → 정답 ✓","Tienen: 활용 동사라 문장에 동사가 두 개가 되어 ✗","Al tener: '~할 때, ~하므로'라는 부사구라 주어가 될 수 없습니다 ✗"]},{"id":"G681","q":"No me ____ los videojuegos.","o":["interesan","intereso","interesar","interesa"],"a":0,"k":"interesar 구문","t":"나는 비디오 게임에 관심이 없다.","e":"interesar(관심을 끌다)는 gustar처럼 관심 대상이 문법상 주어가 됩니다. 'los videojuegos(비디오 게임들)'가 복수이므로 동사도 3인칭 복수 interesan이 됩니다. me는 '나에게'라는 간접목적격입니다.","x":["interesan: 복수 주어 los videojuegos에 맞는 3인칭 복수 → 정답 ✓","intereso: 1인칭 단수(내가 관심을 끈다)라 ✗","interesar: 동사원형이라 활용되지 않았습니다 ✗","interesa: 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G682","q":"Me gustaría que ____ con nosotros al concierto.","o":["vendrás","vinieras","vengas","vendrías"],"a":1,"k":"gustaría que","t":"네가 우리랑 같이 콘서트에 가면 좋겠어.","e":"'Me gustaría que ~'처럼 주절이 가능법(조건법)일 때는 que 뒤에 접속법 과거를 씁니다. venir의 접속법 과거 2인칭 단수는 vinieras(또는 vinieses)입니다. 바람을 부드럽고 공손하게 말하는 표현입니다.","x":["vendrás: 직설법 미래라 바람 표현 뒤에 쓰지 않습니다 ✗","vinieras: 가능법 주절에 맞는 접속법 과거 → 정답 ✓","vengas: 접속법 현재는 'Me gusta que', 'Quiero que'처럼 현재 주절 뒤에 씁니다 ✗","vendrías: 가능법이라 que절에 쓰지 않습니다 ✗"]},{"id":"G683","q":"____ a ese gimnasio porque me gustan las clases.","o":["Llevo yendo","Tengo que ir","Dejo de ir","Sigo yendo"],"a":3,"k":"seguir+현재분사","t":"수업이 마음에 들어서 나는 그 헬스장에 계속 다니고 있다.","e":"'seguir + 현재분사'는 '계속 ~하고 있다'라는 뜻입니다. 수업이 마음에 든다는 이유와 자연스럽게 이어지므로 'Sigo yendo(계속 다니고 있다)'가 맞습니다. yendo는 ir의 불규칙 현재분사입니다.","x":["Llevo yendo: llevar 구문은 기간(dos años 등)이 함께 와야 합니다 ✗","Tengo que ir: '가야 한다'는 의무라서 '마음에 들어서'라는 이유와 어색합니다 ✗","Dejo de ir: '그만 다닌다'라는 뜻이라 이유와 모순됩니다 ✗","Sigo yendo: seguir + 현재분사(계속 ~하다) → 정답 ✓"]},{"id":"G684","q":"¿Cuántos kilómetros hay desde tu casa ____ tu trabajo?","o":["hasta","en","hacia","de"],"a":0,"k":"desde...hasta","t":"너희 집에서 회사까지 몇 킬로미터니?","e":"'desde A hasta B'는 'A에서 B까지'라는 범위·거리를 나타냅니다. 앞에 desde가 있으므로 짝이 되는 hasta를 씁니다. 비슷한 짝으로 'de A a B'도 있습니다. 예: de lunes a viernes(월요일부터 금요일까지).","x":["hasta: desde와 짝을 이루는 '~까지' → 정답 ✓","en: 장소(~에) 전치사라 범위의 끝을 나타내지 못합니다 ✗","hacia: '~쪽으로'라는 방향이라 정확한 도착점을 나타내지 않습니다 ✗","de: 출발점을 나타내므로 '~까지'가 되지 않습니다 ✗"]},{"id":"G685","q":"____ el brazo izquierdo jugando al baloncesto.","o":["Rompía","Me rompí","Me rompía","Rompí"],"a":1,"k":"romperse(단순과거)","t":"나는 농구하다가 왼팔이 부러졌다.","e":"자기 신체 부위가 다쳤을 때는 재귀 형태 'romperse + 정관사 + 신체 부위'를 씁니다. 과거에 한 번 일어난 사건이므로 단순과거 'me rompí'가 맞습니다. 'Rompí el brazo'라고 하면 '다른 무언가의 팔을 부러뜨렸다'처럼 들립니다.","x":["Rompía: 재귀대명사가 없고 불완료과거라 ✗","Me rompí: 재귀 + 단순과거(한 번 일어난 사고) → 정답 ✓","Me rompía: 불완료과거는 반복·배경에 쓰므로 한 번의 사고에 ✗","Rompí: 재귀대명사가 없어 자기 신체를 다쳤다는 뜻이 되지 않습니다 ✗"]},{"id":"G686","q":"Necesitamos contratar a alguien que ____ español con fluidez.","o":["hable","habla","hablan","hablen"],"a":0,"k":"불특정 선행사+접속법","t":"우리는 스페인어를 유창하게 하는 사람을 고용해야 한다.","e":"관계절의 선행사가 아직 존재가 확인되지 않은(찾고 있는) 대상이면 관계절에 접속법을 씁니다. 'alguien que hable(말할 수 있는 누군가)'은 아직 찾지 못한 사람이므로 hablar의 접속법 현재 3인칭 단수 hable가 맞습니다. 실제 있는 사람이라면 'Conozco a alguien que habla...'처럼 직설법을 씁니다.","x":["hable: 불특정 선행사 + 접속법 현재 3인칭 단수 → 정답 ✓","habla: 직설법은 이미 아는 특정 인물일 때 씁니다 ✗","hablan: 복수 직설법이라 alguien(단수)과 맞지 않습니다 ✗","hablen: 복수형이라 단수 alguien과 맞지 않습니다 ✗"]},{"id":"G687","q":"En esta sala está prohibido ____ fumar.","o":["con","a","de","ø"],"a":3,"k":"está prohibido","t":"이 방에서는 흡연이 금지되어 있다.","e":"'está prohibido + 동사원형'은 '~하는 것이 금지되어 있다'라는 뜻으로, 동사원형이 주어 역할을 하므로 전치사가 필요 없습니다. 비슷한 구조: 'Es necesario estudiar.(공부하는 것이 필요하다.)'","x":["con: 전치사를 넣으면 동사원형이 주어 역할을 하지 못합니다 ✗","a: prohibido 뒤에 a를 넣지 않습니다 ✗","de: prohibido 뒤에 de를 넣지 않습니다 ✗","ø: 전치사 없이 동사원형 → 정답 ✓"]},{"id":"G688","q":"Primero tomé un autobús hacia el centro y, ____, me dirigí a la estación de tren.","o":["por continuación","de continuación","a continuación","continuación"],"a":2,"k":"a continuación","t":"먼저 시내 쪽으로 가는 버스를 탔고, 그다음에 기차역으로 향했다.","e":"'a continuación'은 '이어서, 그다음에'라는 뜻의 고정된 부사구입니다. 순서를 설명할 때 'primero(먼저) ..., a continuación(그다음에) ..., al final(마지막으로)'처럼 자주 씁니다. 전치사는 항상 a입니다.","x":["por continuación: 존재하지 않는 표현입니다 ✗","de continuación: 존재하지 않는 표현입니다 ✗","a continuación: '그다음에'라는 고정 표현 → 정답 ✓","continuación: 전치사 a가 빠져 부사구가 되지 않습니다 ✗"]},{"id":"G689","q":"¿A quién ____ has mandado esa carta?","o":["les","le","se","la"],"a":1,"k":"간접목적격 le","t":"그 편지를 누구에게 보냈니?","e":"mandar(보내다)는 '무엇을'(esa carta)과 '누구에게'(a quién)를 함께 가집니다. '누구에게'에 해당하는 간접목적격 대명사가 필요하고, a quién은 단수이므로 le를 씁니다. 스페인어에서는 간접목적어가 문장에 있어도 le를 함께 쓰는 경우가 많습니다.","x":["les: 복수형이라 단수 quién과 맞지 않습니다 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓","se: le가 lo/la 앞에 올 때 se로 바뀌는데, 여기선 직접목적격 대명사가 없어 ✗","la: 직접목적격(그녀를/그것을)이라 '~에게'를 나타내지 못합니다 ✗"]},{"id":"G690","q":"____ no sé qué trabajo quiero tener cuando sea grande.","o":["Mientras","Todavía","Incluso","Aun"],"a":1,"k":"todavía(아직)","t":"나는 아직 커서 어떤 일을 하고 싶은지 모르겠어.","e":"todavía는 '아직, 여전히'라는 뜻으로 부정문에서 '아직 ~않다'를 나타냅니다. 같은 뜻으로 악센트가 있는 aún도 쓸 수 있습니다. 'cuando sea grande(내가 크면)'는 미래 시점이라 접속법을 씁니다.","x":["Mientras: '~하는 동안'이라는 접속사라 이 문장 구조에 맞지 않습니다 ✗","Todavía: 아직(~않다) → 정답 ✓","Incluso: '심지어'라는 뜻이라 문맥에 맞지 않습니다 ✗","Aun: 악센트 없는 aun은 '심지어'라는 뜻입니다(아직은 aún) ✗"]},{"id":"G691","q":"No empezaremos la clase ____ lleguen todos los alumnos.","o":["a que","antes","hasta","hasta que"],"a":3,"k":"hasta que+접속법","t":"모든 학생이 도착할 때까지 수업을 시작하지 않을 거예요.","e":"'hasta que(~할 때까지)' 뒤에 미래의 일이 오면 접속법을 씁니다. 학생들이 아직 오지 않았으므로 'hasta que lleguen'이 맞습니다. 뒤에 활용된 동사(lleguen)가 오기 때문에 전치사 hasta만으로는 안 되고 접속사 hasta que가 필요합니다.","x":["a que: '~하도록'이라는 뜻으로 일부 동사 뒤에서만 쓰므로 ✗","antes: 'antes de que'가 되어야 하고 의미도 '~하기 전에'라 ✗","hasta: 전치사라 뒤에 활용 동사가 바로 올 수 없습니다 ✗","hasta que: 접속사 '~할 때까지' + 접속법 → 정답 ✓"]},{"id":"G692","q":"El porcentaje de personas que ____ en nuestro país es cada vez más alto.","o":["reciclarían","reciclan","reciclaban","reciclen"],"a":1,"k":"관계절 직설법","t":"우리나라에서 재활용하는 사람들의 비율은 점점 높아지고 있다.","e":"관계절이 실제로 존재하는 사람들(재활용하는 사람들)을 설명하는 사실이면 직설법을 씁니다. 주절이 현재(es cada vez más alto)이므로 직설법 현재 3인칭 복수 reciclan이 맞습니다. 'cada vez más'는 '점점 더'라는 뜻입니다.","x":["reciclarían: 가능법(조건법)이라 사실 진술에 맞지 않습니다 ✗","reciclan: 현재 사실을 나타내는 직설법 현재 → 정답 ✓","reciclaban: 불완료과거라 현재 상황(es)과 시제가 맞지 않습니다 ✗","reciclen: 접속법은 불특정·가정의 선행사일 때 씁니다 ✗"]},{"id":"G693","q":"No sé cuándo ____ a poner esa serie de televisión.","o":["vuelvan","volverán","volver","volvieran"],"a":1,"k":"간접의문문 미래","t":"그 TV 시리즈를 언제 다시 방영할지 모르겠다.","e":"'No sé cuándo ~(언제 ~할지 모르겠다)'처럼 의문사로 시작하는 간접의문문에는 직설법을 씁니다. 미래의 일이므로 직설법 미래 volverán이 맞습니다. 'volver a + 동사원형'은 '다시 ~하다', 'poner una serie'는 '시리즈를 방영하다'라는 뜻입니다.","x":["vuelvan: 접속법은 간접의문문(cuándo)에 쓰지 않습니다 ✗","volverán: 간접의문문 속 직설법 미래 → 정답 ✓","volver: 동사원형이라 주어(막연한 그들)가 있는 절에 맞지 않습니다 ✗","volvieran: 접속법 과거라 ✗"]},{"id":"G694","q":"Me preguntaron ____ quería participar en el concurso y les dije que sí.","o":["por qué","si","como","que"],"a":1,"k":"간접의문 si","t":"그들은 나에게 대회에 참가하고 싶은지 물었고, 나는 그렇다고 했다.","e":"'예/아니오'로 답하는 질문을 간접적으로 전할 때는 si(~인지 아닌지)를 씁니다. 원래 질문은 '¿Quieres participar?'이고 대답이 sí(예)이므로 'Me preguntaron si quería...'가 맞습니다. 이때 si에는 악센트가 없습니다.","x":["por qué: '왜'를 물었다면 대답이 sí가 될 수 없습니다 ✗","si: 예/아니오 간접의문(~인지) → 정답 ✓","como: 방식을 묻는 의문사라면 악센트(cómo)가 필요하고 의미도 맞지 않습니다 ✗","que: '~라고'라는 접속사라 질문 내용을 전하지 못합니다 ✗"]},{"id":"G695","q":"Anteayer ____ durante unas tres horas.","o":["conducía","conducí","conduje","he conducido"],"a":2,"k":"conducir 단순과거","t":"그저께 나는 세 시간쯤 운전했다.","e":"'anteayer(그저께)'처럼 끝난 과거 시점의 사건은 단순과거로 나타냅니다. conducir는 -ducir로 끝나는 불규칙 동사로 단순과거가 conduje, condujiste, condujo...가 됩니다. 같은 패턴: traducir → traduje, producir → produje.","x":["conducía: 불완료과거로 배경·습관에 쓰므로 정해진 기간의 완결된 행동에 ✗","conducí: 존재하지 않는 형태입니다(불규칙 conduje) ✗","conduje: conducir의 불규칙 단순과거 1인칭 단수 → 정답 ✓","he conducido: 현재완료는 anteayer 같은 끝난 과거 시점과 잘 쓰지 않습니다 ✗"]},{"id":"G696","q":"____ come mucho, no engorda.","o":["Como","Aunque","Puesto que","Debido a que"],"a":1,"k":"aunque(양보)","t":"그는 많이 먹지만 살이 찌지 않는다.","e":"aunque는 '~에도 불구하고, ~이지만'이라는 양보를 나타냅니다. 많이 먹는다는 사실과 살이 찌지 않는다는 결과가 서로 반대되므로 aunque가 맞습니다. 사실을 말할 때는 aunque 뒤에 직설법(come)을 씁니다.","x":["Como: '~이니까'라는 이유라 의미가 맞지 않습니다 ✗","Aunque: 양보(~이지만) → 정답 ✓","Puesto que: '~이므로'라는 이유라 ✗","Debido a que: '~때문에'라는 이유라 ✗"]},{"id":"G697","q":"¿Me ayudas a poner los platos y los cubiertos ____ la mesa?","o":["a","con","en","entre"],"a":2,"k":"poner en","t":"식탁에 접시랑 수저 놓는 거 좀 도와줄래?","e":"'poner algo en + 장소'는 '~을 ...에 놓다'라는 뜻으로 놓이는 위치를 en으로 나타냅니다. 'poner la mesa'만 쓰면 '상을 차리다'라는 관용 표현이 됩니다. 'ayudar a + 동사원형(~하는 것을 돕다)'도 함께 기억하세요.","x":["a: 'a la mesa'는 '식탁으로(식사하러)'처럼 방향 의미라 놓는 위치에 ✗","con: '~와 함께'라는 뜻이라 ✗","en: 놓는 장소(~위에/~에) → 정답 ✓","entre: '~사이에'라는 뜻이라 ✗"]},{"id":"G698","q":"Cuando ____ adolescente, era muy rebelde.","o":["fuera","era","estaba","estuviera"],"a":1,"k":"ser 불완료과거","t":"청소년이었을 때 나는 아주 반항적이었다.","e":"'adolescente(청소년)'는 명사로 그 사람이 어떤 시기의 누구였는지를 말하므로 ser를 씁니다. 과거의 한 시기를 배경으로 묘사하므로 불완료과거 era가 맞습니다. 이미 일어난 과거 사실이라 cuando 뒤에 접속법을 쓰지 않습니다.","x":["fuera: 접속법 과거라 과거 사실을 묘사할 때 쓰지 않습니다 ✗","era: ser의 불완료과거, 과거 시기의 배경 → 정답 ✓","estaba: estar는 명사(adolescente)를 보어로 쓰지 않습니다 ✗","estuviera: estar의 접속법 과거라 ✗"]},{"id":"G699","q":"Posiblemente ____ a Lituania en agosto.","o":["hemos ido","fuéramos","estamos yendo","vayamos"],"a":3,"k":"posiblemente","t":"아마 우리는 8월에 리투아니아에 갈 것 같다.","e":"'posiblemente, probablemente, quizás, tal vez'가 동사 앞에 오면 불확실함을 나타내기 위해 접속법을 쓸 수 있습니다. 8월이라는 미래의 불확실한 계획이므로 ir의 접속법 현재 vayamos가 맞습니다. 확신이 클 때는 직설법(iremos)도 가능합니다.","x":["hemos ido: 현재완료라 미래 시점 en agosto와 맞지 않습니다 ✗","fuéramos: 접속법 과거는 과거나 가정에 쓰므로 미래 계획에는 ✗","estamos yendo: 현재진행형이라 '지금 가는 중'이 되어 ✗","vayamos: 불확실한 미래를 나타내는 접속법 현재 → 정답 ✓"]},{"id":"G700","q":"No ____ el diccionario, por favor, nosotros también lo necesitamos.","o":["llevas","te llevas","te lleves","lleves"],"a":2,"k":"부정명령 llevarse","t":"사전 가져가지 마, 제발. 우리도 필요해.","e":"'llevarse'는 '(어디론가) 가져가 버리다'라는 뜻의 재귀 형태입니다. tú에게 하는 부정 명령은 'no + 접속법 현재'이고, 대명사는 동사 앞에 둡니다. 그래서 'No te lleves'가 맞습니다. 긍정 명령이라면 'Llévatelo'가 됩니다.","x":["llevas: 직설법 현재라 명령이 되지 않습니다 ✗","te llevas: 직설법 현재(너는 가져간다)라 부정 명령이 아닙니다 ✗","te lleves: no + te + 접속법 현재(가져가지 마) → 정답 ✓","lleves: '가져가 버리다'라는 뜻을 위해 재귀대명사 te가 필요합니다 ✗"]},{"id":"G701","q":"Será mejor que les hagas tus preguntas a las personas ____ están organizando el viaje.","o":["las que","quien","que","quienes"],"a":2,"k":"관계대명사 que","t":"여행을 준비하고 있는 사람들에게 질문하는 게 나을 거야.","e":"전치사 없이 선행사(las personas)를 받는 제한적 관계절에서는 que를 씁니다. 'las personas que están organizando...'는 '...를 준비하고 있는 사람들'이라는 뜻입니다. quien/quienes는 쉼표가 있는 설명적 관계절이나 전치사 뒤에서 주로 씁니다.","x":["las que: 선행사가 있고 전치사도 없을 때는 관사를 넣지 않습니다 ✗","quien: 단수형이고 쉼표 없는 제한적 관계절에서는 쓰지 않습니다 ✗","que: 기본 관계대명사 → 정답 ✓","quienes: 쉼표 없는 제한적 관계절의 주어로는 쓰지 않습니다 ✗"]},{"id":"G702","q":"Tengo que estar en el hospital a ____ hora de la mañana.","o":["la primera","primero","primera","primer"],"a":2,"k":"서수 primera","t":"나는 아침 첫 시간에 병원에 가 있어야 한다.","e":"'a primera hora (de la mañana)'는 '(아침) 이른 시간에, 첫 시간에'라는 고정 표현으로 관사 없이 씁니다. hora가 여성 명사이므로 primera가 됩니다. primer는 남성 명사 앞에서만 씁니다(el primer día).","x":["la primera: 이 관용 표현에는 관사를 넣지 않습니다 ✗","primero: 남성형이고 명사 앞에서는 primer로 줄어 ✗","primera: a primera hora(이른 시간에) → 정답 ✓","primer: 남성 명사 앞 형태라 여성 명사 hora와 맞지 않습니다 ✗"]},{"id":"G703","q":"Claro que ____ arrepiento de lo que le dije a Samuel.","o":["ø","se me","se","me"],"a":3,"k":"arrepentirse","t":"물론 나는 사무엘에게 한 말을 후회해.","e":"arrepentirse(후회하다)는 항상 재귀대명사와 함께 쓰는 재귀동사입니다. 주어가 yo(arrepiento)이므로 재귀대명사 me를 씁니다. 'arrepentirse de algo'는 '~을 후회하다'라는 뜻입니다.","x":["ø: 재귀대명사가 꼭 필요한 동사라 ✗","se me: 의도치 않은 일(se me olvidó 등)에 쓰는 구조라 ✗","se: 3인칭 재귀대명사라 1인칭 arrepiento와 맞지 않습니다 ✗","me: 1인칭 재귀대명사 → 정답 ✓"]},{"id":"G704","q":"¿Han pillado ____ al ladrón?","o":["todavía","ya","aún","casi"],"a":1,"k":"ya(벌써/이미)","t":"도둑을 벌써 잡았대?","e":"ya는 '벌써, 이미'라는 뜻으로 어떤 일이 이미 일어났는지 물을 때 현재완료와 함께 자주 씁니다. pillar는 스페인 구어로 '잡다'라는 뜻입니다. todavía/aún은 주로 부정문에서 '아직 ~않다'에 씁니다.","x":["todavía: 긍정 의문문에서는 '아직도 잡고 있니?'처럼 어색해집니다 ✗","ya: 이미/벌써 → 정답 ✓","aún: todavía와 같은 뜻이라 여기선 어색합니다 ✗","casi: '거의'라는 뜻이라 의문문 의미가 이상해집니다 ✗"]},{"id":"G705","q":"Celia es ____ pediatra de mis dos hijos.","o":["un","el","una","la"],"a":3,"k":"정관사 la(특정)","t":"셀리아는 내 두 아이의 소아과 의사이다.","e":"'de mis dos hijos(내 두 아이의)'로 특정한 의사를 가리키므로 정관사를 씁니다. pediatra는 남녀 모두 같은 형태인 명사로, 여성인 Celia를 가리키므로 la가 맞습니다.","x":["un: 남성형이고 부정관사라 특정 인물에 맞지 않습니다 ✗","el: 남성형이라 여성인 Celia와 맞지 않습니다 ✗","una: '여러 의사 중 하나'라는 뜻이 되어 특정성과 어긋납니다 ✗","la: 특정 인물, 여성 정관사 → 정답 ✓"]},{"id":"G706","q":"¿Me pasas ____ tenedor, por favor?","o":["otro","un otro","otra","una otra"],"a":0,"k":"otro(관사 없음)","t":"포크 하나 더 건네줄래?","e":"otro/otra(다른, 또 하나의)는 앞에 부정관사 un/una를 붙이지 않습니다. 'un otro'는 영어 'another'를 그대로 옮긴 흔한 실수입니다. tenedor(포크)는 남성 명사이므로 otro가 맞습니다.","x":["otro: 남성 명사 tenedor 앞, 관사 없이 → 정답 ✓","un otro: otro 앞에는 부정관사를 쓰지 않습니다 ✗","otra: 여성형이라 tenedor와 맞지 않습니다 ✗","una otra: 부정관사를 쓰지 않고 성도 맞지 않습니다 ✗"]},{"id":"G707","q":"Tenemos más huevos ____ los que necesitamos para una tortilla.","o":["con","a","de","que"],"a":2,"k":"más de los que","t":"우리는 토르티야 하나 만드는 데 필요한 것보다 더 많은 달걀을 가지고 있다.","e":"비교 대상이 명사가 아니라 '~하는 양(los que + 동사)'일 때는 que 대신 de를 써서 'más ... de lo/los/las que'라고 합니다. huevos가 남성 복수이므로 'de los que necesitamos'가 됩니다. 예: Gasté más dinero del que tenía.(가진 것보다 더 많은 돈을 썼다.)","x":["con: 비교 표현에 쓰지 않습니다 ✗","a: 비교 표현에 쓰지 않습니다 ✗","de: más ... de los que(~하는 것보다 더) → 정답 ✓","que: 'que los que'는 문법적으로 어색하며, 관계절 앞에서는 de를 씁니다 ✗"]},{"id":"G708","q":"Por favor, no ____ la puerta.","o":["cierra","cerrás","cierres","cierras"],"a":2,"k":"tú 부정명령","t":"제발 문 닫지 마.","e":"tú에게 하는 부정 명령은 'no + 접속법 현재'입니다. cerrar는 e→ie 어간 변화 동사로 접속법 현재 tú 형태가 cierres입니다. 긍정 명령은 'Cierra la puerta.(문 닫아.)'입니다.","x":["cierra: 긍정 명령형이라 no와 함께 쓰지 않습니다 ✗","cerrás: vos(중남미 일부)의 직설법 현재라 명령이 아닙니다 ✗","cierres: no + 접속법 현재(부정 명령) → 정답 ✓","cierras: 직설법 현재(너는 닫는다)라 ✗"]},{"id":"G709","q":"¿Por qué ____ enfadas con nosotros?","o":["le","te","ø","se"],"a":1,"k":"재귀동사 enfadarse","t":"너는 왜 우리한테 화를 내니?","e":"enfadarse(화를 내다)는 재귀동사로, 주어에 맞는 재귀대명사가 필요합니다. 동사 enfadas가 tú 형태이므로 te가 맞습니다. 'enfadarse con alguien'은 '~에게 화내다'입니다. 중남미에서는 enojarse를 더 많이 씁니다.","x":["le: 간접목적격이라 재귀 표현이 되지 않습니다 ✗","te: tú의 재귀대명사 → 정답 ✓","ø: '화를 내다'라는 뜻에는 재귀대명사가 필요합니다 ✗","se: 3인칭 재귀대명사라 tú 형태 enfadas와 맞지 않습니다 ✗"]},{"id":"G710","q":"____ me siento más estresada que de costumbre.","o":["Por último","Últimamente","Por fin","Finalmente"],"a":1,"k":"últimamente(최근)","t":"요즘 나는 평소보다 더 스트레스를 받는다.","e":"últimamente는 '최근에, 요즘'이라는 뜻으로 최근 한동안 이어지는 상태를 말할 때 현재형이나 현재완료와 씁니다. 'de costumbre'는 '평소, 보통'이라는 뜻이라 'más que de costumbre'는 '평소보다 더'입니다.","x":["Por último: '마지막으로'라는 순서 표현이라 ✗","Últimamente: 최근에, 요즘 → 정답 ✓","Por fin: '드디어'라는 뜻이라 ✗","Finalmente: '결국, 마지막으로'라는 뜻이라 ✗"]},{"id":"G711","q":"¿Qué ____ los chicos cuando llegasteis?","o":["hicieran","han hecho","estaban haciendo","estuvieron haciendo"],"a":2,"k":"과거진행 vs 단순과거","t":"너희가 도착했을 때 아이들은 뭘 하고 있었니?","e":"과거의 어떤 순간(너희가 도착했을 때)에 진행 중이던 행동은 'estar의 불완료과거 + 현재분사'인 과거진행형으로 나타냅니다. 도착(llegasteis)은 단순과거로 한 번 일어난 사건이고, 아이들이 하던 일은 그 배경입니다.","x":["hicieran: 접속법 과거라 일반 의문문에 쓰지 않습니다 ✗","han hecho: 현재완료라 과거 특정 순간의 진행 상황을 나타내지 못합니다 ✗","estaban haciendo: 과거 특정 순간에 진행 중이던 일 → 정답 ✓","estuvieron haciendo: 단순과거 진행형은 끝난 기간 전체를 말할 때 써서 ✗"]},{"id":"G712","q":"¿Qué ____ el restaurante al que fuimos?","o":["pareció","te pareció","pareció a ti","parecía"],"a":1,"k":"parecer 구문","t":"우리가 갔던 그 식당 어땠어?","e":"'¿Qué te parece/pareció ...?'는 '~가 어때/어땠어?'라고 의견을 묻는 표현입니다. parecer는 gustar처럼 '누구에게'를 간접목적격 대명사(te)로 나타냅니다. 이미 다녀온 식당에 대한 의견이라 단순과거 pareció를 씁니다.","x":["pareció: '너에게'를 나타내는 대명사가 빠졌습니다 ✗","te pareció: 간접목적격 te + 단순과거 → 정답 ✓","pareció a ti: 대명사 te 없이 'a ti'만 쓰는 것은 틀립니다 ✗","parecía: 대명사가 없고 불완료과거라 ✗"]},{"id":"G713","q":"La dinamita ____ por Alfred Nobel.","o":["estuvo inventada","ha sido inventada","era inventada","fue inventada"],"a":3,"k":"수동태 ser+과거분사","t":"다이너마이트는 알프레드 노벨에 의해 발명되었다.","e":"'ser + 과거분사 + por + 행위자'는 수동태(~에 의해 ~되다)입니다. 과거에 한 번 일어난 사건이므로 ser의 단순과거 fue를 쓰고, 과거분사는 주어 la dinamita(여성 단수)에 맞춰 inventada가 됩니다. 수동태에는 estar가 아니라 ser를 씁니다.","x":["estuvo inventada: estar + 과거분사는 결과 상태를 나타내며 행위 수동태에 쓰지 않습니다 ✗","ha sido inventada: 현재완료는 오래전 역사적 사건에 어색합니다 ✗","era inventada: 불완료과거는 반복·배경이라 한 번의 발명에 ✗","fue inventada: 단순과거 수동태 → 정답 ✓"]},{"id":"G714","q":"Ana prefiere ____ de vacaciones a la costa.","o":["va","ir","a ir","de ir"],"a":1,"k":"preferir+동사원형","t":"아나는 해변으로 휴가 가는 것을 더 좋아한다.","e":"preferir(~을 더 좋아하다)는 전치사 없이 바로 동사원형을 씁니다. 그래서 'prefiere ir'가 맞습니다. querer, poder, saber, necesitar도 같은 구조입니다. 'ir de vacaciones'는 '휴가를 가다'라는 표현입니다.","x":["va: 활용된 동사라 preferir 뒤에 바로 올 수 없습니다 ✗","ir: preferir + 동사원형 → 정답 ✓","a ir: preferir 뒤에 a를 넣지 않습니다 ✗","de ir: preferir 뒤에 de를 넣지 않습니다 ✗"]},{"id":"G715","q":"Ya he visto ____ episodios de esta serie.","o":["veintiuno","veinte y un","veinte y uno","veintiún"],"a":3,"k":"숫자 veintiún","t":"나는 이 시리즈를 벌써 21편 봤다.","e":"21은 한 단어로 veintiuno라고 쓰며, 남성 명사 앞에서는 끝의 -o가 빠지고 악센트가 붙어 veintiún이 됩니다. episodios는 남성 복수이므로 veintiún episodios가 맞습니다. 여성 명사 앞이라면 veintiuna(veintiuna páginas)가 됩니다.","x":["veintiuno: 명사 앞에서는 -o를 생략합니다 ✗","veinte y un: 16~29는 한 단어로 붙여 씁니다 ✗","veinte y uno: 붙여 써야 하고 명사 앞 형태도 아닙니다 ✗","veintiún: 남성 명사 앞의 21 → 정답 ✓"]},{"id":"G716","q":"Estamos hasta la coronilla de tus mentiras. ____ la verdad ahora mismo.","o":["Decidnos","Díganos","Dinos","Di nos"],"a":2,"k":"tú 명령+대명사","t":"우리는 네 거짓말에 진절머리가 나. 지금 당장 우리에게 사실을 말해.","e":"'tus mentiras(너의 거짓말)'로 보아 상대는 tú입니다. decir의 tú 긍정 명령은 불규칙형 di이고, 긍정 명령에서는 대명사를 동사 뒤에 붙여 씁니다. 그래서 'Dinos(우리에게 말해)'가 됩니다. 'estar hasta la coronilla de'는 '~에 진절머리가 나다'라는 관용 표현입니다.","x":["Decidnos: vosotros(너희) 명령형이라 tus와 맞지 않습니다 ✗","Díganos: usted(당신) 명령형이라 tus와 맞지 않습니다 ✗","Dinos: tú 명령 di + nos를 붙여 씀 → 정답 ✓","Di nos: 긍정 명령에서는 대명사를 띄어 쓰지 않고 붙입니다 ✗"]},{"id":"G717","q":"____ tema me resulta indiferente.","o":["Esa","Ese","Eso","Esos"],"a":1,"k":"지시형용사 ese","t":"그 주제는 나에게 아무래도 상관없다.","e":"지시형용사는 뒤 명사의 성·수에 맞춥니다. tema는 -a로 끝나지만 그리스어에서 온 남성 명사(el tema)이므로 ese를 씁니다. 같은 예: el problema, el sistema, el idioma. 'resultar indiferente'는 '관심 없다, 상관없다'라는 뜻입니다.","x":["Esa: tema는 남성 명사라 여성형은 ✗","Ese: 남성 단수 명사 tema 앞 지시형용사 → 정답 ✓","Eso: 중성 지시대명사라 명사 앞에 쓰지 않습니다 ✗","Esos: 복수형이라 단수 tema와 맞지 않습니다 ✗"]},{"id":"G718","q":"¿Saben que el desierto de Atacama es uno de ____ más áridos del mundo?","o":["los","el","ø","lo"],"a":0,"k":"uno de los+최상급","t":"아타카마 사막이 세계에서 가장 건조한 곳 중 하나라는 거 아세요?","e":"'uno de los + (명사) + más + 형용사'는 '가장 ~한 것들 중 하나'라는 표현입니다. 생략된 명사 desiertos가 남성 복수이므로 los를 씁니다. 아타카마 사막은 칠레 북부에 있으며 세계에서 가장 건조한 곳 중 하나로 유명합니다.","x":["los: 생략된 남성 복수 명사(desiertos)를 받는 정관사 → 정답 ✓","el: 단수형이라 'uno de(~ 중 하나)' 뒤에 맞지 않습니다 ✗","ø: 최상급에는 정관사가 필요합니다 ✗","lo: 중성 관사라 구체적 명사(사막들)를 받지 못합니다 ✗"]},{"id":"G719","q":"¿____ estudiantes franceses tienes este año?","o":["Cuántos","Cuánta","Cuántas","Cuánto"],"a":0,"k":"의문사 cuántos","t":"올해 프랑스 학생이 몇 명 있니?","e":"'¿Cuántos/Cuántas + 명사?'는 '몇 명/몇 개의 ~?'라는 뜻으로 명사의 성·수에 맞춥니다. estudiantes는 남녀 모두 같은 형태지만 franceses(남성 복수)로 보아 남성 복수로 쓰였으므로 Cuántos가 맞습니다.","x":["Cuántos: 남성 복수 명사에 맞는 의문사 → 정답 ✓","Cuánta: 여성 단수라 셀 수 없는 여성 명사 앞에 씁니다 ✗","Cuántas: 여성 복수라 franceses(남성)와 맞지 않습니다 ✗","Cuánto: 남성 단수라 셀 수 없는 명사 앞에 씁니다 ✗"]},{"id":"G720","q":"Pasar o no este examen depende ____.","o":["por ti","contigo","a ti","de ti"],"a":3,"k":"depender de","t":"이 시험에 붙을지 말지는 너에게 달려 있다.","e":"depender(~에 달려 있다)는 항상 전치사 de와 함께 씁니다. 전치사 뒤 인칭대명사는 ti이므로 'depende de ti'가 됩니다. 예: Depende del tiempo.(날씨에 달려 있다.)","x":["por ti: '너 때문에/너를 위해'라는 뜻이라 ✗","contigo: '너와 함께'라는 뜻이라 ✗","a ti: depender는 a와 쓰지 않습니다 ✗","de ti: depender de(~에 달려 있다) → 정답 ✓"]},{"id":"G721","q":"¿Cuánto tiempo ____ viniendo a esta academia de idiomas?","o":["andas","sigues","llevas","estás"],"a":2,"k":"llevar+현재분사","t":"너는 이 어학원에 다닌 지 얼마나 됐니?","e":"'¿Cuánto tiempo llevas + 현재분사?'는 '~한 지 얼마나 됐니?'라고 지속 기간을 묻는 표현입니다. llevar는 여기서 '(시간을) 보내다'라는 의미로, 기간과 현재분사(viniendo)를 함께 씁니다. 대답 예: Llevo seis meses viniendo.(6개월째 다니고 있어.)","x":["andas: 'andar + 현재분사'는 '~하며 돌아다니다'라는 뜻으로 기간 질문에 쓰지 않습니다 ✗","sigues: '계속 ~하다'라는 뜻이라 'Cuánto tiempo'와 어울리지 않습니다 ✗","llevas: llevar + 기간 + 현재분사 → 정답 ✓","estás: 현재진행형은 지속 기간을 묻는 표현이 되지 않습니다 ✗"]},{"id":"G722","q":"Álvaro dice que ____ harto de aguantar a sus vecinos.","o":["esté","está","estaría","estará"],"a":1,"k":"간접화법 직설법","t":"알바로는 이웃들을 참는 데 진절머리가 났다고 말한다.","e":"'decir que ~(~라고 말하다)'로 다른 사람의 말을 전할 때는 que 뒤에 직설법을 씁니다. 주절이 현재(dice)이므로 원래 말의 시제 그대로 estar의 직설법 현재 está를 씁니다. 'estar harto de + 동사원형'은 '~하는 데 질리다', aguantar는 '참다, 견디다'입니다.","x":["esté: decir가 '전달'의 뜻일 때는 접속법을 쓰지 않습니다(명령 전달일 때만 접속법) ✗","está: 말 전달 + 직설법 현재 → 정답 ✓","estaría: 가능법이라 현재 상태 전달에 맞지 않습니다 ✗","estará: 미래형이라 지금 질려 있다는 뜻과 맞지 않습니다 ✗"]},{"id":"G723","q":"Si ____ hambre, puedo prepararte un bocadillo ahora mismo.","o":["tengas","tienes","tendrías","tenías"],"a":1,"k":"si+직설법 현재","t":"배고프면 지금 바로 샌드위치를 만들어 줄 수 있어.","e":"실제로 일어날 수 있는 조건을 말할 때는 'si + 직설법 현재, 직설법 현재/미래/명령'을 씁니다. 그래서 tener의 직설법 현재 tienes가 맞습니다. si 바로 뒤에는 접속법 현재나 미래형을 쓰지 않는다는 점을 꼭 기억하세요. bocadillo는 스페인에서 바게트 샌드위치를 뜻합니다.","x":["tengas: si 뒤에는 접속법 현재를 쓰지 않습니다 ✗","tienes: 현실 조건의 직설법 현재 → 정답 ✓","tendrías: si 뒤에는 가능법을 쓰지 않습니다 ✗","tenías: 불완료과거라 주절의 현재 제안(puedo)과 맞지 않습니다 ✗"]},{"id":"G724","q":"A usted ____ encanta el mate, ¿verdad?","o":["le","te","os","se"],"a":0,"k":"encantar 구문","t":"당신은 마테차를 아주 좋아하시죠, 그렇죠?","e":"encantar(아주 좋아하다)는 gustar처럼 좋아하는 사람을 간접목적격 대명사로 나타냅니다. usted(당신)는 문법상 3인칭으로 취급하므로 le를 씁니다. 마테(mate)는 아르헨티나·우루과이·파라과이 등에서 즐겨 마시는 전통 차입니다.","x":["le: usted에 맞는 3인칭 단수 간접목적격 → 정답 ✓","te: tú(너)에게 쓰는 대명사라 usted와 맞지 않습니다 ✗","os: vosotros(너희)에게 쓰는 대명사라 ✗","se: 재귀대명사라 encantar 구문에 쓰지 않습니다 ✗"]},{"id":"G725","q":"¿____ piensas de lo que te he contado?","o":["Cual","Qué","Cuál","Que"],"a":1,"k":"의문사 qué","t":"내가 너한테 이야기한 것에 대해 어떻게 생각해?","e":"'¿Qué piensas de ...?'는 '~에 대해 어떻게 생각해?'라고 의견을 묻는 표현입니다. 의견의 내용(무엇을 생각하는지)을 묻으므로 의문사 qué를 쓰고, 의문사이므로 악센트를 붙입니다. cuál은 여러 개 중 '어느 것'을 고를 때 씁니다.","x":["Cual: 악센트가 없고 의미도 맞지 않습니다 ✗","Qué: 생각의 내용을 묻는 의문사 → 정답 ✓","Cuál: '어느 것'을 고르는 의문사라 의견 질문에 ✗","Que: 악센트가 없으면 의문사가 아닌 접속사·관계사입니다 ✗"]},{"id":"G726","q":"____ un año que no veo a mi mejor amiga.","o":["De hace","Hace","Hasta hace","Desde hace"],"a":1,"k":"hace+기간+que","t":"가장 친한 친구를 못 본 지 1년이 됐다.","e":"'Hace + 기간 + que + 동사'는 '~한 지 (기간)이 되다'라는 표현입니다. 'Hace un año que no veo...'는 '못 본 지 1년이 되었다'입니다. 같은 뜻으로 'No veo a mi mejor amiga desde hace un año.'라고도 할 수 있습니다.","x":["De hace: 명사를 꾸미는 표현(~ 전의)이라 문장 맨 앞에서 쓰지 않습니다 ✗","Hace: hace + 기간 + que → 정답 ✓","Hasta hace: '~ 전까지'라는 뜻이라 que절과 어울리지 않습니다 ✗","Desde hace: 동사 뒤에 쓰는 표현이라 'que'와 함께 문두에 오지 않습니다 ✗"]},{"id":"G727","q":"Algunos estudiantes serán ____ por su mal comportamiento.","o":["castigados","castigadas","castigos","castigado"],"a":0,"k":"수동태 과거분사 일치","t":"일부 학생들은 나쁜 행동 때문에 벌을 받을 것이다.","e":"수동태 'ser + 과거분사'에서 과거분사는 주어의 성·수에 맞춰 변합니다. 주어 'Algunos estudiantes'는 남성 복수이므로 castigados가 맞습니다. 'por su mal comportamiento'는 '나쁜 행동 때문에'라는 이유입니다.","x":["castigados: 남성 복수 주어에 맞는 과거분사 → 정답 ✓","castigadas: 여성 복수라 Algunos(남성)와 맞지 않습니다 ✗","castigos: '벌'이라는 명사라 수동태가 되지 않습니다 ✗","castigado: 단수형이라 복수 주어와 맞지 않습니다 ✗"]},{"id":"G728","q":"Cuando ____ en periodo de exámenes, siempre me pongo nerviosísimo.","o":["sea","esté","soy","estoy"],"a":3,"k":"cuando 습관+직설법","t":"시험 기간이면 나는 항상 엄청 긴장한다.","e":"cuando가 '~할 때마다'처럼 반복되는 습관을 나타내면 직설법을 씁니다. siempre(항상)가 있으므로 습관이고, '시험 기간 중에 있다'는 상황이므로 estar를 써서 estoy가 맞습니다. 'estar en periodo de exámenes'는 '시험 기간이다'라는 뜻입니다.","x":["sea: 접속법이고 ser라서 ✗","esté: 접속법은 미래의 일에 쓰는데 여기는 반복되는 습관이라 ✗","soy: ser는 상황(~중에 있다)을 나타내지 않습니다 ✗","estoy: 습관을 나타내는 직설법 + 상황의 estar → 정답 ✓"]},{"id":"G729","q":"¿____ qué fin hicieron eso?","o":["De","Sobre","Con","A"],"a":2,"k":"con qué fin","t":"그들은 무슨 목적으로 그 일을 했을까?","e":"'¿Con qué fin ...?'은 '무슨 목적으로?'라는 고정 표현으로, fin(목적)과 전치사 con을 함께 씁니다. 같은 뜻으로 '¿Para qué...?'를 쓸 수 있습니다. 'con el fin de + 동사원형(~할 목적으로)'도 자주 쓰는 표현입니다.","x":["De: 'de qué fin'은 쓰지 않는 표현입니다 ✗","Sobre: '~에 대해'라는 주제 의미라 ✗","Con: con qué fin(무슨 목적으로) → 정답 ✓","A: 'a qué fin'은 쓰지 않는 표현입니다 ✗"]},{"id":"G730","q":"____ con Margarita a las 7 de la tarde. Vamos a ir a un bar nuevo.","o":["He quedado","Me he quedado","Me quedo","Voy a quedarme"],"a":0,"k":"quedar con","t":"오후 7시에 마르가리타와 만나기로 했어. 새로 생긴 바에 갈 거야.","e":"'quedar con alguien'은 '~와 만나기로 약속하다'라는 뜻으로 재귀대명사 없이 씁니다. 이미 약속을 잡아 둔 상태이므로 현재완료 'He quedado'가 자연스럽습니다. 'quedarse'(재귀형)는 '머무르다, 남다'라는 다른 뜻입니다. 이 표현은 주로 스페인에서 씁니다.","x":["He quedado: quedar con(만나기로 하다) + 현재완료 → 정답 ✓","Me he quedado: quedarse는 '머물렀다, 남았다'라는 뜻이라 ✗","Me quedo: '나는 남는다/머문다'라는 뜻이라 ✗","Voy a quedarme: '나는 머무를 것이다'라는 뜻이라 ✗"]},{"id":"G731","q":"Compré todas estas cosas ____ solo 10 dólares.","o":["de","entre","para","por"],"a":3,"k":"por(가격·교환)","t":"나는 이 물건들을 전부 겨우 10달러에 샀다.","e":"전치사 por는 가격이나 교환(~을 주고, ~에)을 나타냅니다. 'comprar algo por + 가격'은 '~에 사다'라는 뜻입니다. 예: Lo vendí por 50 euros.(나는 그것을 50유로에 팔았다.)","x":["de: 'un billete de 10 dólares(10달러짜리 지폐)'처럼 명사 수식에 쓰므로 ✗","entre: '~사이에'라는 뜻이라 ✗","para: 목적·용도(~을 위해)를 나타내므로 가격에 ✗","por: 가격·교환 → 정답 ✓"]},{"id":"G732","q":"____ semana ha sido muy productiva. He trabajado mucho.","o":["Ese","Aquella","Esta","Esa"],"a":2,"k":"지시형용사 esta","t":"이번 주는 아주 생산적이었다. 나는 일을 많이 했다.","e":"현재완료(ha sido)와 함께 '지금 포함된 시간'을 가리킬 때는 este/esta(이)를 씁니다. semana는 여성 명사이므로 esta semana(이번 주)가 맞습니다. 지난 시간이라면 'esa/aquella semana(그 주)'와 단순과거를 씁니다.","x":["Ese: 남성형이라 semana와 맞지 않습니다 ✗","Aquella: '저/그때의' 먼 과거라 현재완료와 어울리지 않습니다 ✗","Esta: 현재를 포함하는 '이번' 주 → 정답 ✓","Esa: '그 주'라 현재를 포함하는 기간이 아니므로 ✗"]},{"id":"G733","q":"No te preocupes, te aviso ____ tenga los resultados de tu examen.","o":["nada más","tan pronto como","mientras","al"],"a":1,"k":"tan pronto como","t":"걱정하지 마, 네 시험 결과가 나오는 대로 바로 알려 줄게.","e":"'tan pronto como(~하자마자)'는 시간 접속사로, 미래의 일이면 뒤에 접속법(tenga)을 씁니다. 결과를 받는 즉시 알려 준다는 뜻이므로 tan pronto como가 맞습니다. 같은 뜻으로 en cuanto도 있습니다.","x":["nada más: 'nada más + 동사원형'으로 써서 활용 동사 tenga와 맞지 않습니다 ✗","tan pronto como: ~하자마자 + 접속법 → 정답 ✓","mientras: '~하는 동안'이라는 뜻이라 문맥에 맞지 않습니다 ✗","al: 'al + 동사원형'으로 써서 ✗"]},{"id":"G734","q":"Aquí no hay ____ gente como en la otra sala.","o":["tantas","tan","tanta","tanto"],"a":2,"k":"tanta+명사+como","t":"여기에는 다른 방만큼 사람이 많지 않다.","e":"명사의 동등 비교는 'tanto/a/os/as + 명사 + como'입니다. gente(사람들)는 뜻은 복수지만 문법상 여성 단수 명사이므로 tanta를 씁니다. 동사도 단수로 씁니다(La gente es amable).","x":["tantas: gente는 단수 명사라 복수형은 ✗","tan: 형용사·부사 앞에 쓰므로 명사 앞에는 ✗","tanta: 여성 단수 명사 gente 앞 → 정답 ✓","tanto: 남성형이라 gente와 맞지 않습니다 ✗"]},{"id":"G735","q":"Nos dijo que no ____ dónde estaba el director del instituto.","o":["ha sabido","supiera","sabía","sepa"],"a":2,"k":"간접화법 불완료과거","t":"그는 우리에게 고등학교 교장 선생님이 어디 계신지 모른다고 말했다.","e":"과거에 들은 말을 전할 때(dijo que)는 원래 현재형(No sé)이 불완료과거(no sabía)로 바뀝니다. 사실을 전달하는 것이므로 직설법을 씁니다. instituto는 스페인에서 '고등학교(중등학교)'를 뜻합니다.","x":["ha sabido: 현재완료라 과거 간접화법의 시제 일치에 맞지 않습니다 ✗","supiera: 접속법은 명령·요청을 전할 때 쓰므로 ✗","sabía: 과거 간접화법, 직설법 불완료과거 → 정답 ✓","sepa: 접속법 현재라 시제와 법 모두 맞지 않습니다 ✗"]},{"id":"G736","q":"____ me gustaría más que estar ahora de vacaciones.","o":["Ninguna","Ninguno","Nadie","Nada"],"a":3,"k":"부정대명사 nada","t":"지금 휴가 중인 것보다 더 좋은 건 아무것도 없을 거야.","e":"nada는 '아무것도 (~않다)'라는 부정 대명사로 사물·일에 씁니다. 'Nada me gustaría más que ~'는 '~보다 더 좋은 건 없을 거야', 즉 '~하면 정말 좋겠다'라는 뜻입니다. 사람이라면 nadie를 씁니다.","x":["Ninguna: 특정 여성 명사를 받는 '하나도'라서 앞에 받는 명사가 없어 ✗","Ninguno: 특정 남성 명사를 받는 '하나도'라서 ✗","Nadie: '아무도'라는 사람 표현이라 ✗","Nada: 아무것도(사물·일) → 정답 ✓"]},{"id":"G737","q":"¿Con quién ____ la otra noche?","o":["has discutido","discutieses","discutiste","has estado discutiendo"],"a":2,"k":"단순과거(끝난 시점)","t":"그날 밤 누구와 말다툼했니?","e":"'la otra noche(요전 날 밤)'처럼 이미 끝난 특정 과거 시점의 사건은 단순과거로 나타냅니다. 그래서 discutir의 단순과거 2인칭 단수 discutiste가 맞습니다. discutir는 '말다툼하다, 토론하다'라는 뜻입니다.","x":["has discutido: 현재완료는 현재와 연결된 시간(hoy, esta semana)에 주로 씁니다 ✗","discutieses: 접속법 과거라 일반 의문문에 쓰지 않습니다 ✗","discutiste: 끝난 과거 시점의 단순과거 → 정답 ✓","has estado discutiendo: 현재완료진행은 지금까지 이어진 행동이라 ✗"]},{"id":"G738","q":"Suelo ver el telediario ____ ceno.","o":["después de","mientras","nada más","hasta"],"a":1,"k":"mientras(동시)","t":"나는 저녁을 먹으면서 TV 뉴스를 보곤 한다.","e":"mientras는 '~하는 동안, ~하면서'라는 뜻으로 두 행동이 동시에 일어날 때 씁니다. 뒤에 활용된 동사(ceno)가 오므로 접속사 mientras가 맞습니다. telediario는 스페인에서 TV 뉴스를 뜻합니다.","x":["después de: 전치사구라 뒤에 동사원형(cenar)이 와야 합니다 ✗","mientras: 동시 동작(~하면서) → 정답 ✓","nada más: 'nada más + 동사원형'으로 쓰므로 ✗","hasta: 전치사라 활용 동사가 오려면 hasta que가 필요합니다 ✗"]},{"id":"G739","q":"Nadie sabe ____ se ha metido el gato.","o":["dónde","donde","adonde","adónde"],"a":0,"k":"간접의문문 dónde","t":"고양이가 어디로 숨어 들어갔는지 아무도 모른다.","e":"'meterse'는 '(어딘가에) 들어가 있다, 숨어 있다'라는 뜻으로, 결과적으로 머문 위치를 묻기 때문에 dónde를 씁니다. 'saber' 뒤의 간접의문문에서도 의문사는 악센트를 유지합니다. 예: ¿Dónde te has metido?(너 어디 있었어?)","x":["dónde: 악센트 있는 의문사, 위치 → 정답 ✓","donde: 악센트가 없으면 관계부사(~하는 곳)라 ✗","adonde: 악센트 없는 관계부사이며 방향 의미라 ✗","adónde: 방향(어디로)을 강조하는 의문사로 meterse에는 dónde가 일반적입니다 ✗"]},{"id":"G740","q":"Mi madre me dijo que no ____ comprase más caramelos a mi hermano.","o":["lo","les","los","le"],"a":3,"k":"간접목적격 le","t":"엄마는 나에게 동생에게 사탕을 더 사 주지 말라고 했다.","e":"comprar algo a alguien(누군가에게 ~을 사 주다)에서 '누구에게'는 간접목적격 대명사로 나타냅니다. 'a mi hermano'가 3인칭 단수이므로 le를 씁니다. 스페인어에서는 간접목적어(a mi hermano)가 있어도 le를 함께 쓰는 것이 자연스럽습니다.","x":["lo: 직접목적격(그를/그것을)이라 ✗","les: 복수형이라 단수 mi hermano와 맞지 않습니다 ✗","los: 직접목적격 복수라 ✗","le: 3인칭 단수 간접목적격 → 정답 ✓"]},{"id":"G741","q":"Pienso que en el futuro los robots lo ____ casi todo en nuestras viviendas.","o":["hacen","harían","hará","harán"],"a":3,"k":"미래형(예측)","t":"나는 미래에는 로봇이 우리 집에서 거의 모든 일을 할 거라고 생각한다.","e":"미래에 대한 예측은 직설법 미래로 나타냅니다. 주어가 los robots(3인칭 복수)이므로 hacer의 불규칙 미래형 harán이 맞습니다. 'Pienso que'는 긍정 의견이라 직설법을 씁니다.","x":["hacen: 현재형이라 en el futuro와 맞지 않습니다 ✗","harían: 가능법(조건법)이라 가정의 의미가 되어 ✗","hará: 3인칭 단수라 복수 주어 los robots와 맞지 않습니다 ✗","harán: 3인칭 복수 미래형 → 정답 ✓"]},{"id":"G742","q":"Patricia está locamente enamorada ____ Ricardo.","o":["con","de","por","a"],"a":1,"k":"enamorado de","t":"파트리시아는 리카르도에게 미친 듯이 빠져 있다.","e":"'estar enamorado/a de + 사람'은 '~를 사랑하고 있다, ~에게 반해 있다'라는 뜻으로 항상 전치사 de를 씁니다. 영어 'in love with'를 직역해 con을 쓰는 실수가 많으니 주의하세요.","x":["con: 영어 with를 직역한 실수입니다 ✗","de: enamorada de(~에게 반한) → 정답 ✓","por: 'loco por'처럼 다른 형용사와는 쓰지만 enamorado에는 쓰지 않습니다 ✗","a: enamorado와 함께 쓰지 않습니다 ✗"]},{"id":"G743","q":"El restaurante en el que cenamos anoche ____ lleno.","o":["estuvo","ha estado","estaba","estaría"],"a":2,"k":"estar 불완료과거(묘사)","t":"어젯밤 우리가 저녁을 먹은 식당은 꽉 차 있었다.","e":"과거 장면의 상태(가득 찬 상태)를 묘사할 때는 불완료과거를 씁니다. 'lleno(가득 찬)'는 상태이므로 estar를 써서 estaba가 맞습니다. 저녁을 먹은 사건(cenamos)은 단순과거, 그때의 배경은 불완료과거입니다.","x":["estuvo: 단순과거는 정해진 기간 전체를 말할 때 써서 배경 묘사에 ✗","ha estado: 현재완료라 anoche(어젯밤)와 맞지 않습니다 ✗","estaba: 과거 상태 묘사의 불완료과거 → 정답 ✓","estaría: 가능법이라 추측 의미가 되어 ✗"]},{"id":"G744","q":"Ven cuando ____, necesito tu ayuda.","o":["podrás","puedas","pudieras","puedes"],"a":1,"k":"cuando+접속법","t":"시간 될 때 와 줘, 네 도움이 필요해.","e":"주절이 명령형(Ven)이고 cuando 뒤가 아직 일어나지 않은 미래의 일이면 접속법을 씁니다. 그래서 poder의 접속법 현재 puedas가 맞습니다. 'cuando puedas'는 '네가 가능할 때, 시간 날 때'라는 아주 흔한 표현입니다.","x":["podrás: cuando 뒤에는 미래형을 쓰지 않습니다 ✗","puedas: 미래 시점의 접속법 현재 → 정답 ✓","pudieras: 접속법 과거라 현재 명령문과 시제가 맞지 않습니다 ✗","puedes: 직설법은 습관에 쓰므로 명령문 뒤 미래 시점에 ✗"]},{"id":"G745","q":"No vi ____ libro interesante en la librería.","o":["algún","un","ningún","ninguno"],"a":2,"k":"부정형용사 ningún","t":"나는 서점에서 흥미로운 책을 하나도 보지 못했다.","e":"부정문에서 '하나도 ~않다'는 ninguno를 쓰고, 남성 단수 명사 앞에서는 ningún으로 줄어듭니다. 동사 앞에 no가 있으므로 이중 부정(no ... ningún)이 스페인어에서는 정상입니다. 예: No tengo ningún problema.(아무 문제도 없어.)","x":["algún: 긍정 의미 '어떤'이라 부정문에서 '하나도'를 나타내지 못합니다 ✗","un: '책 한 권을 못 봤다'로 의미가 약해지고 부정 강조가 되지 않습니다 ✗","ningún: 남성 단수 명사 앞 부정형용사 → 정답 ✓","ninguno: 명사 앞에서는 ningún으로 줄여 씁니다 ✗"]},{"id":"G746","q":"No ____ todavía, quédate un ratito más.","o":["vas","te vayas","te vas","irte"],"a":1,"k":"부정명령 irse","t":"아직 가지 마, 조금만 더 있어.","e":"irse(떠나다, 가 버리다)의 tú 부정 명령은 'no + te + 접속법 현재'로 'No te vayas'입니다. 부정 명령에서는 대명사를 동사 앞에 둡니다. 긍정 명령은 'Vete'입니다. 'quédate'는 quedarse(머무르다)의 긍정 명령입니다.","x":["vas: 직설법 현재라 명령이 아니고 재귀대명사도 없습니다 ✗","te vayas: no + te + 접속법 현재(가지 마) → 정답 ✓","te vas: 직설법 현재(너는 간다)라 부정 명령이 아닙니다 ✗","irte: 동사원형이라 명령형으로 쓸 수 없습니다 ✗"]},{"id":"G747","q":"Os dije que el examen ____ fácil y no me equivoqué.","o":["habría sido","será","ha sido","sería"],"a":3,"k":"과거 속 미래(가능법)","t":"내가 너희에게 시험이 쉬울 거라고 했지, 내 말이 틀리지 않았어.","e":"과거 시점에서 본 미래(~할 거라고 말했다)는 가능법(조건법)으로 나타냅니다. 'Os dije que el examen sería fácil'은 원래 'El examen será fácil'을 과거 간접화법으로 바꾼 것입니다. 시험은 이미 끝났지만, 말했을 당시 기준으로 미래였으므로 sería를 씁니다.","x":["habría sido: 가능법 완료라 '쉬웠을 것이다'라는 과거 추측이 되어 ✗","será: 과거 간접화법(dije)에서는 미래형이 가능법으로 바뀝니다 ✗","ha sido: 현재완료라 말한 시점의 예측을 나타내지 못합니다 ✗","sería: 과거에서 본 미래, 가능법 → 정답 ✓"]},{"id":"G748","q":"Eso no ____ dije yo, sino Jordi.","o":["lo","la","los","le"],"a":0,"k":"중성 대명사 lo","t":"그 말은 내가 한 게 아니라 조르디가 한 거야.","e":"eso(그것, 그 말)처럼 중성 지시대명사나 문장 전체를 받는 직접목적어는 중성 대명사 lo로 받습니다. 목적어(Eso)가 동사 앞에 나왔으므로 같은 것을 가리키는 lo를 함께 씁니다. 'no A sino B'는 'A가 아니라 B'라는 뜻입니다.","x":["lo: 중성 eso를 받는 직접목적격 → 정답 ✓","la: 여성 명사를 받을 때 쓰므로 ✗","los: 남성 복수 명사를 받을 때 쓰므로 ✗","le: 간접목적격(~에게)이라 '그 말을'에 맞지 않습니다 ✗"]},{"id":"G749","q":"El sábado mi hermana y yo fuimos de ____ compras a ese centro comercial.","o":["las","ø","la","unas"],"a":1,"k":"ir de compras","t":"토요일에 언니와 나는 그 쇼핑몰에 쇼핑하러 갔다.","e":"'ir de compras'는 '쇼핑하러 가다'라는 고정 표현으로 관사를 넣지 않습니다. 'hacer la compra(장을 보다)'와는 다른 표현입니다. 비슷한 표현: ir de vacaciones(휴가 가다), ir de viaje(여행 가다).","x":["las: 고정 표현이라 관사를 넣지 않습니다 ✗","ø: ir de compras(관사 없음) → 정답 ✓","la: compras는 복수인 데다 관사를 넣지 않습니다 ✗","unas: 고정 표현에 부정관사를 넣지 않습니다 ✗"]},{"id":"G750","q":"____ de aquí. ¡No quiero volver a verte!","o":["Ve","Te vayas","Vayas","Vete"],"a":3,"k":"irse 긍정명령","t":"여기서 나가! 다시는 너를 보고 싶지 않아!","e":"irse(떠나다)의 tú 긍정 명령은 불규칙형 ve에 재귀대명사 te를 붙인 vete입니다. 긍정 명령에서는 대명사를 동사 뒤에 붙여 씁니다. 부정 명령은 'No te vayas.(가지 마.)'입니다.","x":["Ve: '가라'라는 뜻이지만 '여기서 떠나'라는 뜻의 재귀대명사 te가 빠졌습니다 ✗","Te vayas: no 없이 접속법만 쓰면 명령이 되지 않습니다 ✗","Vayas: 접속법 현재라 긍정 명령으로 쓸 수 없습니다 ✗","Vete: irse의 tú 긍정 명령 → 정답 ✓"]}];